def get_user_menu_data(request):
    if not request.session.get('staffid'):
        return {}
    staff_id = request.session['staffid']
    # Retrieve role assignments for the staff
    role_assignments = Roleassign.objects.filter(Staff=staff_id)
    # Get the role IDs
    role_ids = role_assignments.values_list('roleid', flat=True)
    # Retrieve menu management entries based on the user's roles
    menu_management_entries = menumanagement.objects.filter(roleid__in=role_ids)
    # Prepare menu data to be sent to the template
    menu_data = {}
    for entry in menu_management_entries:
        menu = entry.menuid
        heading = menu.menuheadingname.menuheadingname
        if heading not in menu_data:
            menu_data[heading] = []
        # Append menu item details to the respective heading
        menu_data[heading].append({
            'menu': menu,
            'menumanagement_id': entry.id,
            'icon': menu.icon,
            'view': entry.view == '1',
            'add': entry.add == '1',
            'edit': entry.edit == '1',
            'delete': entry.delete == '1',
           
        })
    return {'menu_data': menu_data}


def index(request):
    st=request.session.get('loginstaff')
    if not st:
        return redirect("staff_login")
    staff_branch=Staffallocation.objects.get(id=st)
    staffbranchid=staff_branch.Branch_Name_id
    # room_count = Room_details.objects.count()
    staff_count=Staffallocation.objects.filter(Branch_Name_id=staffbranchid).count()
    patient_count=Patient_details.objects.filter(Branch_Name_id=staffbranchid).count()
    today_date =  date.today()
    # datetime.date.today()
    today_appointments_count = Appointments.objects.filter(Appointment_date=today_date,Branch_id=staffbranchid).count()
    stdesign = request.session.get('loginstaffdesign')
    room=Room_details.objects.all()
    current_date = date.today()
    staff_id = request.session.get('staffid')
    # Calculate the date 6 months from now
    six_months_from_now = current_date + timedelta(days=30*6)
    # Find medicines with expiry dates within the next 6 months
    expiring_within_six_months = Physicalstockdetails.objects.filter(Expiry_date__lte=six_months_from_now)
    # If you want to find medicines that are expiring within the next 6 months but not expired yet
    # Filter out medicines that have already expired
    not_expired_yet = expiring_within_six_months.filter(Expiry_date__gt=current_date)
    # Calculate the count of expiring medicines
    expiring_medicines_count = not_expired_yet.count()
    today_enq_count = enquiry.objects.filter(currentdate=today_date).count()
    branch_id = request.session['branchid']
    # Query to count enquiries where callormsg is "Call" and follow-up is done today
    call_count = followupcalldetails.objects.filter(
        callorstatus__iexact="Call",  # Match "Call" exactly, case-insensitive
        currentdate=today_date
    ).distinct().count()
    # count of treatment Allocate for today
    todaytratmentlist=nextreatmentdetailschild.objects.filter(treatment_date=current_date)
    todaytreatmentcount=todaytratmentlist.count()
   # Reorder Level Calculation (Out-of-Stock + Low Stock)
    reorder_levels = {
        (reorder.itemname_id, reorder.companyid_id): int(reorder.qty)
        for reorder in reorderleveldetails.objects.all()
    }
    out_of_stock_count = 0
    low_stock_count = 0
    for stock in Physicalstockdetails.objects.all():
        stock_qty = int(stock.qty)
        key = (stock.itemnm_id, stock.Comapany_name_id)
        reorder_qty = reorder_levels.get(key, 0)  # Default to 0 if not found
        if stock_qty == 0:
            out_of_stock_count += 1
        elif stock_qty < reorder_qty:
            low_stock_count += 1
    reorder_count = out_of_stock_count + low_stock_count
    six_months_from_now = current_date + timedelta(days=30*6)
    #Find medicines with expiry dates within the next 6 months
    expiring_within_six_months = Physicalstockdetails.objects.filter(Expiry_date__lte=six_months_from_now,qty__gt=0,stockbranch=branch_id)
    # If you want to find medicines that are expiring within the next 6 months but not expired yet
    # Filter out medicines that have already expired
    not_expired_yet = expiring_within_six_months.filter(Expiry_date__gt=current_date)
    countofnotexpiredyet=not_expired_yet.count()
    followups = followup.objects.filter(
        remainderdate=current_date,
        enqid__status__in=["Pending", "Re-contact", "Recontact2","Priority"],
        enqid__branch_id=branch_id
    )
    followup_count = followups.count() 
    mddt=clairvedaCaseHistory.objects.filter(follow_up_date=current_date,prepairedby_id__staffallocation__Branch_Name_id=staffbranchid)
    flwcount=mddt.count()
    # filter(branchidrm_id=staffbranchid)
    if stdesign==9:
        today_appointments_count = Appointments.objects.filter(Appointment_date=today_date,Branch_id=staffbranchid).count()
    else:
        today_appointments_count = Appointments.objects.filter(Appointment_date=today_date,Branch_id=staffbranchid).count()    
    # Get the dashboard items assigned to this role
    todaytreatmentinvcount=treatmentinvoicemaster.objects.filter(currentdate=today_date,branch_id=staffbranchid).count()
    todaypharmacyinvcount=invoicemaster.objects.filter(currentdate=today_date,branch_id=staffbranchid).count()
    treatmntbkkcount=oppatienttreamentroombooking.objects.filter(bookingdate=today_date,bookingstatus=True).count()
    count_mapping ={
         "invlist":todaypharmacyinvcount,
         "treatmentlist":todaytreatmentinvcount,
         "todaymedicalfollowup":flwcount,
         "treatmentlistrecord":todaytreatmentcount,
         "todayremaindertable":followup_count,
          "currentreorderlist":reorder_count,
          "todayappointment": today_appointments_count,
          "staff_count": staff_count,
          "adminpatientdetailtable": patient_count,
          "expiredmedicine": expiring_medicines_count,
          "enquirycalldetails": call_count,
          "treatment_booking_list":treatmntbkkcount
    }
    role_id =request.session.get('roleid')
    allocated_dashboard_items = dashboardallocation.objects.filter(roleid_id=role_id)
    # Create a list of dashboard items to send to the template
    dashboard_data = [
        {
            # Dynamically fetch data using `linkname`
            "label": dashboard.dashboardid.dashboardname,
            "count": count_mapping.get(dashboard.dashboardid.linkname, 0),  # Fetch count dynamically
            "url": dashboard.dashboardid.linkname,
            "color": dashboard.dashboardid.color,
            "icon": "ion ion-stats-bars",  # You can add an icon field in `dashboardesign` if needed
        }
        for dashboard in allocated_dashboard_items
    ]
    context = {
        "stdesign":stdesign,
        "dashboard_data":dashboard_data,
        "room":room,
        "staffbranchid":staffbranchid
     
    }
    return render(request,"index.html",context)
