def get_booking_dates(request):
    if request.method == 'GET':
        room_id = request.GET.get('room_id')
      
        bookings = ippatientroombooking.objects.filter(roomdt_id=room_id,bookingcancel=False)
        if bookings.exists():
            booking_ranges = []
            for booking in bookings:
                booking_start_date = booking.Admission_Date
                booking_end_date = booking.admissionenddate
                patient_name = booking.MR_Number.Patient_Name  # Get patient name associated with the booking
                patient_phno = booking.MR_Number.contactno  # Get patient phone number associated with the booking
               
                booking_ranges.append({'start_date': booking_start_date, 'end_date': booking_end_date,'patient_name': patient_name,
                    'patient_phno': patient_phno, 'booking_id': booking.id, })
            
            return JsonResponse({'booking_ranges': booking_ranges})
        else:
            return JsonResponse({'error': 'No bookings found for the selected room'}, status=400)
    else:
        return JsonResponse({'error': 'Invalid request'}, status=400)

