from django.http import JsonResponse
from django.db.models import Q

def searching_mrno(request):
    query = request.GET.get('query', '').strip()
    if not query:
        return JsonResponse([], safe=False)

    staff_id = request.session.get('loginstaff')
    staff_design_id = request.session.get('loginstaffdesign')

    if not staff_id or not staff_design_id:
        return JsonResponse({'error': 'Not authenticated'}, status=403)

    try:
        designation = Designation.objects.get(id=staff_design_id)
        designation_name = designation.Designation_Name.lower()
    except Designation.DoesNotExist:
        return JsonResponse({'error': 'Designation not found'}, status=403)

    # 🔹 BASE FILTER (ONLINE CONSULTATION ONLY)
    base_filter = Q(
        consultation_type='online',
        deleted=False
    ) & (
        Q(Medical_Record_Number__icontains=query) |
        Q(contactno__icontains=query) |
        Q(Patient_Name__icontains=query)
    )

    if designation_name == "superadmin":
        # 🔓 Superadmin → all online patients
        patients = Patient_details.objects.filter(
            base_filter
        ).values(
            'id',
            'Medical_Record_Number',
            'Patient_Name',
            'contactno',
            'Gender',
            'Age',
            'address',
            'district'
        )[:10]

    else:
        try:
            staff_branch = Staffallocation.objects.get(id=staff_id).Branch_Name_id
        except Staffallocation.DoesNotExist:
            return JsonResponse({'error': 'Staff branch not found'}, status=403)

        # 🔒 Normal staff → online patients in their branch
        patients = Patient_details.objects.filter(
            base_filter,
            Branch_Name_id=staff_branch
        ).values(
            'id',
            'Medical_Record_Number',
            'Patient_Name',
            'contactno',
            'Gender',
            'Age',
            'address',
            'district'
        )[:10]

    return JsonResponse(list(patients), safe=False)




from datetime import date, datetime, timedelta

@login_required
def online_appointment(request):
    idmngmnt = request.GET.get('menumanagement_id')
    request.session['onlineappmngid'] = idmngmnt
    # Also store in the regular key as a fallback for backward compatibility
    request.session['appmngid'] = idmngmnt

    if not idmngmnt:
        messages.error(request, "Unable to retrieve Menu Management details.")
        return redirect('error_page')

    mangmntobj = get_object_or_404(menumanagement, id=idmngmnt)

    # ==========================================================
    # POST : SAVE ONLINE APPOINTMENT
    # ==========================================================
    if request.method == 'POST':
        try:
            addmrnumber = request.POST.get('mrnum')
            addbranch = request.POST.get('branch')
            adddocname = request.POST.get('docname')
            addappoinmentdate = request.POST.get('apntdate')
            addremarks = request.POST.get('remarks')
            addcontactnumber = request.POST.get('contactnum')
            addstatus = request.POST.get('status', 'zoho online consultation')
            
            # Get fee from database based on branch, doctor, and status
            branch_id = int(addbranch)
            doctor_id = int(adddocname)
            
            fee_obj = AppointmentFee.objects.filter(
                branch_id=branch_id,
                doctor_id=doctor_id,
                visit_type=addstatus,
                is_active=True
            ).first()
            
            if fee_obj:
                fee = float(fee_obj.fee_amount)
            else:
                # Fallback to default rates if no fee found in database
                fee_mapping = {
                    'zoho online consultation': 600,
                    'zoho online revisit': 0,
                    'whatsapp': 600,
                    'whatsapp revisit': 0
                }
                fee = fee_mapping.get(addstatus.lower(), 0)

            visit_start_time = request.POST.get('visit_start_time')
            visit_duration = int(request.POST.get('visit_duration', 30))

            if not addmrnumber or not addbranch or not adddocname:
                messages.error(request, "Patient, Branch and Doctor are required.")
                return redirect(f"{reverse('online_appointment')}?menumanagement_id={idmngmnt}")

            today = date.today()
            todate = today.strftime("%Y%m%d")

            patient_obj = Patient_details.objects.filter(id=addmrnumber).first()
            if not patient_obj:
                messages.error(request, "Patient details not found.")
                return redirect(f"{reverse('online_appointment')}?menumanagement_id={idmngmnt}")

            # ==========================================================
            # TIME SLOT VALIDATION (9:00 AM – 9:30 PM)
            # ==========================================================
            appointment_date_obj = datetime.strptime(
                addappoinmentdate, "%Y-%m-%d"
            ).date()

            if visit_start_time:
                try:
                    start_time_obj = datetime.strptime(
                        visit_start_time, "%H:%M"
                    ).time()

                    # ⛔ Hard time boundary validation
                    if start_time_obj < time(9, 0) or start_time_obj > time(21, 30):
                        messages.error(
                            request,
                            "Visit time must be between 9:00 AM and 9:30 PM."
                        )
                        return redirect(
                            f"{reverse('online_appointment')}?menumanagement_id={idmngmnt}"
                        )

                    start_datetime = datetime.combine(
                        appointment_date_obj, start_time_obj
                    )
                    end_datetime = start_datetime + timedelta(minutes=visit_duration)
                    end_time_obj = end_datetime.time()

                    # Overlap check
                    overlapping_appointments = Appointments.objects.filter(
                        Doctor_Name_id=doctor_id,
                        Appointment_date=appointment_date_obj,
                        visit_start_time__isnull=False,
                        visit_end_time__isnull=False
                    ).exclude(status__in=['Cancelled', 'Completed'])

                    for appt in overlapping_appointments:
                        appt_start = datetime.combine(
                            appointment_date_obj, appt.visit_start_time
                        )
                        appt_end = datetime.combine(
                            appointment_date_obj, appt.visit_end_time
                        )

                        if start_datetime < appt_end and end_datetime > appt_start:
                            messages.error(
                                request,
                                f"Doctor already has an appointment from "
                                f"{appt.visit_start_time} to {appt.visit_end_time}."
                            )
                            return redirect(
                                f"{reverse('online_appointment')}?menumanagement_id={idmngmnt}"
                            )

                except ValueError:
                    messages.error(request, "Invalid time format. Please use HH:MM.")
                    return redirect(f"{reverse('online_appointment')}?menumanagement_id={idmngmnt}")

            # ==========================================================
            # TOKEN GENERATION (ATOMIC)
            # ==========================================================
            with transaction.atomic():
                # Get last token based on status
                last_entry = Appointments.objects.select_for_update().filter(
                    Current_Date=today,
                    Branch_id=branch_id
                ).order_by('-id').first()

                if last_entry and last_entry.Tokenno:
                    last_seq = int(last_entry.Tokenno[-3:])
                    refnid = last_seq + 1
                else:
                    refnid = 1

                # Generate token prefix based on selected status
                status_lower = addstatus.lower()
                if 'zoho online consultation' in status_lower:
                    token_prefix = "ZO"
                elif 'zoho online revisit' in status_lower:
                    token_prefix = "ZR"
                elif 'whatsapp' in status_lower and 'revisit' in status_lower:
                    token_prefix = "WR"
                elif 'whatsapp' in status_lower:
                    token_prefix = "WA"
                else:
                    token_prefix = "ONL"  # Fallback for other statuses

                token_no = f"{token_prefix}{todate}{refnid:03d}"

                appointment_data = {
                    'Tokenno': token_no,
                    'MR_Number_id': addmrnumber,
                    'Branch_id': branch_id,
                    'Doctor_Name_id': doctor_id,
                    'Appointment_date': appointment_date_obj,
                    'contactno': addcontactnumber,
                    'status': addstatus,
                    'Fee': str(fee),  # Use the fee based on status
                    'Remark': addremarks,
                    'Current_Date': today,
                }

                if visit_start_time:
                    appointment_data.update({
                        'visit_start_time': start_time_obj,
                        'visit_end_time': end_time_obj,
                        'visit_duration': visit_duration
                    })

                # Save appointment
                appointment = Appointments.objects.create(**appointment_data)

                # ==========================================================
                # CREATE INVOICE (same as regular appointment)
                # ==========================================================
                # Fetch Hospital details
                hospital_obj = Hospitaldetails.objects.first()
                if not hospital_obj:
                    messages.error(request, "Hospital details not found. Please add hospital information.")
                    return redirect('error_page')

                # Get staff ID from session
                staff_id = request.session.get("staff_id")
                
                # Patient name and phone
                patient_name = patient_obj.Patient_Name
                patient_phone = patient_obj.contactno or addcontactnumber

                # Create Invoice Entry
                invoice = appointmentinvoicemaster.objects.create(
                    hospitalname=hospital_obj,
                    branch_id=branch_id,
                    Mrno_id=addmrnumber,
                    treatmentInvoicenumber=token_no,  # using token number as invoice number
                    currentdate=appointment_date_obj,
                    subtotal=float(fee),
                    tax=0,
                    shipping=0,
                    total=float(fee),
                    patientname=patient_name,
                    patientphno=patient_phone,
                    discount="0",
                    preparedby_id=staff_id,
                    consultationfee=str(fee),
                    consultationfeecumregfee=str(fee),
                    cancelstatus=False,
                    payementmode="Online",  # Payment mode is Online
                )

            # Success message with status-specific wording
            status_display = addstatus.title()
            fee_display = f" (₹{fee})" if fee > 0 else " (Free)"
            messages.success(
                request,
                f"{status_display} appointment booked successfully! Token Number: {token_no}{fee_display}"
            )
            
            # Redirect to invoice page
            return redirect(f"{reverse('appointmentinvoice')}?invoice_id={invoice.id}")

        except Exception as e:
            messages.error(request, f"Error booking appointment: {e}")
            return redirect('error_page')

    # ==========================================================
    # GET : LOAD FORM
    # ==========================================================
    try:
        today = date.today()
        todate = today.strftime("%Y%m%d")

        staff_alloc_id = request.session.get('loginstaff')
        if not staff_alloc_id:
            messages.error(request, "Staff session expired.")
            return redirect('staff_login')

        staff_allocation = Staffallocation.objects.get(id=staff_alloc_id)
        staff_branch_id = staff_allocation.Branch_Name_id

        # Get last token (for display only)
        last_entry = Appointments.objects.filter(
            Current_Date=today,
            Branch_id=staff_branch_id
        ).order_by('-id').first()

        refnid = int(last_entry.Tokenno[-3:]) + 1 if last_entry else 1
        tk_id = f"ONL{todate}{refnid:03d}"  # Default token for display

        branchobj = Branch.objects.filter(inactive=False)
        
        # ✅ Fetch appointment fees from database
        appointment_fees = []
        fees = AppointmentFee.objects.filter(
            is_active=True
        ).select_related('doctor', 'branch')
        
        for fee in fees:
            appointment_fees.append({
                'branch_id': fee.branch.id if fee.branch else None,
                'doctor_id': fee.doctor.id if fee.doctor else None,
                'visit_type': fee.visit_type,
                'fee_amount': float(fee.fee_amount)
            })

        request.session['onlinemngadd'] = mangmntobj.add
        request.session['onlinemngview'] = mangmntobj.view
        request.session['onlinemngedit'] = mangmntobj.edit
        request.session['onlinemngdelete'] = mangmntobj.delete
        
        # Also store in regular keys as fallback
        request.session['mngadd'] = mangmntobj.add
        request.session['mngview'] = mangmntobj.view
        request.session['mngedit'] = mangmntobj.edit
        request.session['mngdelete'] = mangmntobj.delete

        context = {
            'idmngmnt': idmngmnt,
            'tk_id': tk_id,
            'branchobj': branchobj,
            'onlmngview': mangmntobj.view,
            'onlmngadd': mangmntobj.add,
            'onlmngedit': mangmntobj.edit,
            'onlmngdelete': mangmntobj.delete,
            'brnmae': staff_branch_id,
            'is_online_page': True,
            'appointment_fees_json': json.dumps(appointment_fees)  # Add this line
        }

        return render(request, "online_appointment.html", context)

    except Exception as e:
        messages.error(request, f"Error loading page: {e}")
        return redirect('error_page')

def get_doctor_booked_slots(request):
    """Get doctor's booked time slots for a specific date"""
    doctor_id = request.GET.get('doctor_id')
    appointment_date = request.GET.get('appointment_date')
    
    if not doctor_id or not appointment_date:
        return JsonResponse({'booked_slots': []})
    
    try:
        # Get all appointments for the doctor on the given date
        appointments = Appointments.objects.filter(
            Doctor_Name_id=doctor_id,
            Appointment_date=appointment_date,
            visit_start_time__isnull=False,
            visit_end_time__isnull=False
        ).exclude(status__in=['Cancelled', 'Completed']).order_by('visit_start_time')
        
        booked_slots = []
        for appointment in appointments:
            booked_slots.append({
                'start_time': appointment.visit_start_time.strftime('%H:%M'),
                'end_time': appointment.visit_end_time.strftime('%H:%M'),
                'patient': str(appointment.MR_Number),
                'token': appointment.Tokenno,
                'status': appointment.status
            })
        
        return JsonResponse({'booked_slots': booked_slots})
        
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)


def get_doctors_by_branch(request):    
    branch_id = request.GET.get('branch')
    
    if not branch_id:
        return JsonResponse({'doctors': []})   
    try:
        # Get doctors allocated to this branch with designation 2 (CMO) or 3 (Associate Doctor)
        # and status is Active
        staff_allocations = Staffallocation.objects.filter(
            Branch_Name_id=branch_id,
            Designation_Name_id__in=[2, 3 ,13],  # Only CMO (2) and Associate Doctors (3)
            Status='Active'
        ).select_related('Staff', 'Department_Name', 'Designation_Name')
        
        doctors = []
        for allocation in staff_allocations:
            doctors.append({
                'id': allocation.Staff.id,
                'name': f"{allocation.Staff.Staff_firstname} {allocation.Staff.Staff_lastname}",
                'department': allocation.Department_Name.Department_Name if allocation.Department_Name else '',
                'designation': allocation.Designation_Name.Designation_Name if allocation.Designation_Name else '',
                'designation_id': allocation.Designation_Name_id
            })
        
        return JsonResponse({'doctors': doctors})
    
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)



@login_required
def todayappointment(request):  
    today = date.today() 
    stdesign = request.session.get('loginstaffdesign')
    st = request.session['loginstaff']
    staff_branch = Staffallocation.objects.get(id=st)
    staffbranchid = staff_branch.Branch_Name_id

    # All today's appointments for this branch with related patient data
    tdyappointment = Appointments.objects.filter(
        Appointment_date=today,
        Branch_id=staffbranchid
    ).select_related('MR_Number')  # Optimize by selecting related patient data

    consulted_patients = set()

    # Collect patient IDs from different models where today's records exist
    prescriptions = Prescriptionnew.objects.filter(prescriptiondate=today).values_list("patient_id", flat=True)
    notes = casehistorydoctorsnote.objects.filter(created_at=today).values_list("patient_id", flat=True)
    treatmentplans = casehistorytreatmentplan.objects.filter(created_at=today).values_list("patient_id", flat=True)
    dietplans = casehistorydietplan.objects.filter(created_at=today).values_list("patient_id", flat=True)
    labresults = casehistorylabresult.objects.filter(created_at__date=today).values_list("patient_id", flat=True)
    labtests = casehistorylabtestrequisition.objects.filter(created_at=today).values_list("patient_id", flat=True)
    medhistory = casehistorymedicalandsurgicalhistory.objects.filter(created_at=today).values_list("patient_id", flat=True)

    # Merge all patient IDs
    consulted_patients.update(prescriptions)
    consulted_patients.update(notes)
    consulted_patients.update(treatmentplans)
    consulted_patients.update(dietplans)
    consulted_patients.update(labresults)
    consulted_patients.update(labtests)
    consulted_patients.update(medhistory)

    # Annotate appointment queryset with consultation status and consultation type
    appointments_with_status = []
    for appt in tdyappointment:
        patient_id = appt.MR_Number_id
        is_consulted = patient_id in consulted_patients
        
        # Determine consultation type from patient details
        consultation_type = appt.MR_Number.consultation_type if appt.MR_Number else 'offline'
        
        appointments_with_status.append({
            "appointment": appt,
            "consulted": is_consulted,
            "consultation_type": consultation_type  # Add consultation type to context
        })

    context = {
        "stdesign": stdesign,
        "appointments": appointments_with_status
    }
    return render(request, "todayappnt.html", context)




@login_required
def appointmenttable(request):
    idmngmnt = request.GET.get('menumanagement_id')
    mangmntobj = get_object_or_404(menumanagement, id=idmngmnt)
    mngadd = mangmntobj.add
    mngview = mangmntobj.view
    mngedit = mangmntobj.edit
    mngdelete = mangmntobj.delete
    
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        messages.error(request, "You are not logged in.")
        return redirect('staff_login')
    
    st = request.session.get('loginstaff')
    if not st:
        messages.error(request, "You are not logged in.")
        return redirect('staff_login')
    
    # Retrieve the staff branch
    try:
        staff_branch = Staffallocation.objects.get(id=st)
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff allocation details not found.")
        return redirect('staff_login')
    
    stdesign_id = request.session.get('loginstaffdesign')
    if not stdesign_id:
        messages.error(request, "You are not logged in.")
        return redirect('staff_login')
    
    staffbranchid = staff_branch.Branch_Name_id
    
    try:
        designation_obj = Designation.objects.get(id=stdesign_id)
        designation_name = designation_obj.Designation_Name.lower()
    except Designation.DoesNotExist:
        designation_name = ''

    objappointmentdetailstable = Appointments.objects.all()
    # Calculate 1 week ago from today (7 days)
    one_week_ago = timezone.now() - timedelta(days=7)
    today = timezone.now().date()
        
    # Optional: Add date filter via GET parameters
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')
    
    if start_date and end_date:
        try:
            start_date_obj = datetime.strptime(start_date, '%Y-%m-%d').date()
            end_date_obj = datetime.strptime(end_date, '%Y-%m-%d').date()
            objappointmentdetailstable = objappointmentdetailstable.filter(
                Appointment_date__range=[start_date_obj, end_date_obj]
            )
            default_start_date=start_date_obj
            default_end_date=end_date_obj
        except ValueError:
            messages.error(request, "Invalid date format. Use YYYY-MM-DD.")
    else:
        if designation_name == "superadmin":
            # Filter appointments from last 1 week only
            objappointmentdetailstable = Appointments.objects.filter(
            Appointment_date__gte=one_week_ago.date()
        ).order_by('-Appointment_date', '-id')
        else:
            # Filter appointments from last 1 week only for staff branch
            objappointmentdetailstable = Appointments.objects.filter(
            Branch_id=staffbranchid,
            Appointment_date__gte=one_week_ago.date()
        ).order_by('-Appointment_date', '-id')
        default_start_date=one_week_ago.date()
        default_end_date=today
    
    context = {
        'objappointmentdetailstable': objappointmentdetailstable,
        'stdesign': stdesign,
        'mngview': mngview,
        'mngadd': mngadd,
        'mngedit': mngedit,
        'mngdelete': mngdelete,
        'idmngmnt': idmngmnt,
        'default_start_date':default_start_date,
        'default_end_date': default_end_date,
        'today': today,  # Add today to context for template
    }
    return render(request, "appointmentdetailstable.html", context)

@login_required
def editappointment(request):
    if request.method == 'POST':
        try:
            # ----------------------------
            # Fetch appointment
            # ----------------------------
            idappo = request.POST.get('appoinid')
            objappointment = get_object_or_404(Appointments, id=idappo)

            # ----------------------------
            # Save original values (AUDIT)
            # ----------------------------
            original_data = {
                'doctor_id': objappointment.Doctor_Name_id,
                'appointment_date': objappointment.Appointment_date,
                'contactno': objappointment.contactno,
                'status': objappointment.status,
                'token_no': objappointment.Tokenno,
                'branch_id': objappointment.Branch_id,
            }

            # ----------------------------
            # Allowed POST data ONLY
            # ----------------------------
            adddocname = request.POST.get('docname')
            addappoinmentdate = request.POST.get('apntdate')
            addcontactnumber = request.POST.get('contactnum')
            addbranch = request.POST.get('branch')
            addremarks = request.POST.get('remarks')
            addappointmenttime = request.POST.get('apnttime')
            if addappointmenttime:
                addappointmenttime = datetime.strptime(
                addappointmenttime,
                "%H:%M"
            ).time()
            # ----------------------------
            # Appointment Date validation
            # ----------------------------
            if addappoinmentdate:
                new_date = datetime.strptime(addappoinmentdate, '%Y-%m-%d').date()
                if new_date < timezone.now().date():
                    messages.error(request, "Appointment date cannot be in the past.")
                    return redirect(request.META.get('HTTP_REFERER', 'appointmenttable'))

            # ----------------------------
            # Validate doctor belongs to selected branch
            # ----------------------------
            branch_to_check = addbranch if addbranch else objappointment.Branch_id
            if adddocname and branch_to_check:
                doctor_allocation = Staffallocation.objects.filter(
                    Branch_Name_id=branch_to_check,
                    Staff_id=adddocname,
                    Designation_Name_id__in=[2, 3,13],  # CMO and Associate Doctors only
                    Status='Active'
                ).exists()
                
                if not doctor_allocation:
                    messages.error(request, "Selected doctor is not available in the selected branch or is not a CMO/Associate Doctor.")
                    return redirect(request.META.get('HTTP_REFERER', 'appointmenttable'))

            # ----------------------------
            # UPDATE ONLY ALLOWED FIELDS
            # ----------------------------
            if adddocname:
                objappointment.Doctor_Name_id = adddocname
            
            if addappoinmentdate:
                objappointment.Appointment_date = addappoinmentdate
            
            if addappointmenttime:
                objappointment.visit_start_time = addappointmenttime
         
            # FIXED: Allow empty string or any format for contact number
            if addcontactnumber is not None:  # This will accept empty string as well
                objappointment.contactno = addcontactnumber
            
            # Update branch if changed
            if addbranch:
                objappointment.Branch_id = addbranch
            
            # Update remarks if provided
            if addremarks is not None:
                objappointment.Remark = addremarks

            objappointment.save()         
            # ----------------------------
            # LOG EDIT
            # ----------------------------
            try:
                staff = None
                st = request.session.get('loginstaff')
                if st:
                    staff_alloc = Staffallocation.objects.filter(id=st).first()
                    staff = staff_alloc.Staff if staff_alloc else None

                AppointmentEditLog.objects.create(
                    appointment=objappointment,
                    action="EDIT",

                    original_doctor_id=original_data['doctor_id'],
                    original_appointment_date=original_data['appointment_date'],
                    original_contactno=original_data['contactno'],
                    original_status=original_data['status'],
                    original_token_no=original_data['token_no'],
                    original_branch_id=original_data['branch_id'],

                    new_doctor_id=adddocname if adddocname else original_data['doctor_id'],
                    new_appointment_date=addappoinmentdate if addappoinmentdate else original_data['appointment_date'],
                    # FIXED: Handle contact number properly in log
                    new_contactno=addcontactnumber if addcontactnumber is not None else original_data['contactno'],
                    new_status=objappointment.status,
                    new_branch_id=addbranch if addbranch else original_data['branch_id'],

                    staff=staff,
                    branch=objappointment.Branch,
                    action_date=timezone.now().date(),
                    action_time=timezone.now().time(),
                )
            except Exception as e:
                print("Appointment edit log error:", e)

            messages.success(request, "Appointment updated successfully.")
            
            #    ===== Determine which table to redirect to based on appointment type =====
            if objappointment.status and ('zoho' in objappointment.status.lower() or 'whatsapp' in objappointment.status.lower()):
                # Online appointment - use onlineappmngid
                idmngmnt = request.session.get('onlineappmngid')
                if not idmngmnt:
                    idmngmnt = request.session.get('appmngid')  # Fallback
                return redirect(f"{reverse('appointmenttable')}?menumanagement_id={idmngmnt}")
            else:
                # Regular appointment - use appmngid
                idmngmnt = request.session.get('appmngid')
                if not idmngmnt:
                    idmngmnt = request.session.get('onlineappmngid')  # Fallback
                return redirect(f"{reverse('appointmenttable')}?menumanagement_id={idmngmnt}")

        except ObjectDoesNotExist:
            messages.error(request, "Appointment not found.")
            return redirect('error_page')

        except Exception as e:
            messages.error(request, f"Unexpected error: {e}")
            return redirect('error_page')

    # ----------------------------
    # GET METHOD
    # ----------------------------
    try:
        idenq = request.GET.get('ids')
        if not idenq:
            messages.error(request, "No appointment ID provided.")
            return redirect('appointmenttable')
            
        objedappo = get_object_or_404(Appointments, id=idenq)

        # Determine if this is an online appointment
        is_online_appointment = False
        if objedappo.status:
            status_lower = objedappo.status.lower()
            is_online_appointment = 'zoho' in status_lower or 'whatsapp' in status_lower

        # Get current user info
        st = request.session.get('loginstaff')
        staff_alloc = None
        if st:
            staff_alloc = Staffallocation.objects.filter(id=st).select_related('Staff', 'Branch_Name', 'Designation_Name').first()
        
        # Check if user is superadmin
        is_superadmin = False
        staff_design_id = request.session.get('loginstaffdesign')
        if staff_design_id:
            designation = Designation.objects.filter(id=staff_design_id).first()
            is_superadmin = designation and designation.Designation_Name and designation.Designation_Name.lower() == "superadmin"
        
        # Get branches based on user role
        if is_superadmin:
            branches = Branch.objects.filter(inactive=False).order_by('Branch_Name')
        else:
            if staff_alloc and staff_alloc.Branch_Name:
                branches = Branch.objects.filter(id=staff_alloc.Branch_Name_id, inactive=False)
            else:
                branches = Branch.objects.none()
        
        # Get doctors for the current branch (ONLY CMO and Associate Doctors)
        current_doctors = []
        doctor_designation = None
        
        if objedappo.Branch_id:
            # Get all active CMO and Associate Doctors for this branch
            allocations = Staffallocation.objects.filter(
                Branch_Name_id=objedappo.Branch_id,
                Designation_Name_id__in=[2, 3,13],  # CMO (2) and Associate Doctors (3) only
                Status='Active'
            ).select_related('Staff', 'Designation_Name', 'Department_Name').order_by(
                'Designation_Name_id',  # CMO first (2), then Associate (3)
                'Staff__Staff_firstname'
            )
            
            for a in allocations:
                doctor_data = {
                    'id': a.Staff_id,
                    'first_name': a.Staff.Staff_firstname,
                    'last_name': a.Staff.Staff_lastname,
                    'name': f"{a.Staff.Staff_firstname} {a.Staff.Staff_lastname}",
                    'designation': a.Designation_Name.Designation_Name if a.Designation_Name else '',
                    'designation_id': a.Designation_Name_id,
                    'department': a.Department_Name.Department_Name if a.Department_Name else '',
                }
                current_doctors.append(doctor_data)
            
            # Get current doctor's designation for display
            if objedappo.Doctor_Name:
                doctor_allocation = Staffallocation.objects.filter(
                    Staff_id=objedappo.Doctor_Name_id,
                    Branch_Name_id=objedappo.Branch_id,
                    Status='Active'
                ).select_related('Department_Name','Designation_Name').first()
                
                if doctor_allocation and doctor_allocation.Designation_Name:
                    doctor_designation = doctor_allocation.Designation_Name
        
        # First try to get from both session keys
        idmngmnt = request.session.get('appmngid') or request.session.get('onlineappmngid')
        
        # Get permissions based on appointment type
        if is_online_appointment:
            mgnview = request.session.get('onlinemngview')
            mgnedit = request.session.get('onlinemngedit')
            mgnadd = request.session.get('onlinemngadd')
            mngdelete = request.session.get('onlinemngdelete')
        else:
            mgnview = request.session.get('mngview')
            mgnedit = request.session.get('mngedit')
            mgnadd = request.session.get('mngadd')
            mngdelete = request.session.get('mngdelete')
        
        # If specific permissions not found, fallback to generic ones
        if mgnview is None:
            mgnview = request.session.get('mngview')
        if mgnedit is None:
            mgnedit = request.session.get('mngedit')
        
        if doctor_allocation:
            doctor_department_id = doctor_allocation.Department_Name_id
            doctor_designation_id = doctor_allocation.Designation_Name_id
            doctor_allocation_exists = True
        context = {
            'departmentobj': Department.objects.filter(flag=1,id__in=[4,8, 15, 16, 17, 18, 19, 20]),  # Active departments
            'designobj': Designation.objects.filter(id__in=[2,3,13,15]), 
            'objedappo': objedappo,
            'doctors': current_doctors,
            'branches': branches,
            'is_superadmin': is_superadmin,
            'doctor_department_id': doctor_department_id,      # ADD THIS
            'doctor_designation_id': doctor_designation_id,    # ADD THIS
            'doctor_allocation_exists': doctor_allocation_exists,
            'doctor_designation': doctor_designation,
            'today': timezone.now().date(),
            'idmngmnt': idmngmnt,
            'mgn': mgnview, 
            'mgnedit': mgnedit,
            'mgnadd': mgnadd,
            'mngdelete': mngdelete,
            'stdesign': request.session.get('loginstaffdesign'),
            'is_online_appointment': is_online_appointment,
        }

        return render(request, "appointmentedit.html", context)

    except ObjectDoesNotExist:
        messages.error(request, "Appointment not found.")
        return redirect('appointmenttable')
        
    except Exception as e:
        messages.error(request, f"Error loading appointment: {str(e)}")
        return redirect('error_page')



@login_required
def delappointment(request):
    idenq = request.GET.get('ids')
    try:
        appointment = Appointments.objects.get(id=idenq)
        
        # Store appointment data for logging before deletion
        appointment_data = {
            'token_no': appointment.Tokenno,
            'doctor_id': appointment.Doctor_Name_id,
            'appointment_date': appointment.Appointment_date,
            'status': appointment.status,
            'contactno': appointment.contactno,
            'remark': appointment.Remark,
            'fee': appointment.Fee,
            'branch_id': appointment.Branch_id,
            'mr_number_id': appointment.MR_Number_id if appointment.MR_Number else None,
        }
        
        # Log the delete action before actual deletion
        try:
            # Get staff info from session
            st = request.session.get('loginstaff')
            staff_allocation = None
            staff = None
            
            if st:
                try:
                    staff_allocation = Staffallocation.objects.get(id=st)
                    staff = staff_allocation.Staff
                except (Staffallocation.DoesNotExist, Staffdetails.DoesNotExist):
                    pass
            
            # Create log entry
            AppointmentEditLog.objects.create(
                appointment=appointment,  # This will become None when appointment is deleted
                action="DELETE",
                
                # Original data (all we have since it's a delete)
                original_token_no=appointment_data['token_no'],
                original_doctor_id=appointment_data['doctor_id'],
                original_appointment_date=appointment_data['appointment_date'],
                original_status=appointment_data['status'],
                original_contactno=appointment_data['contactno'],
                original_remark=appointment_data['remark'],
                original_fee=appointment_data['fee'],
                
                # Log metadata
                staff=staff,
                branch_id=appointment_data['branch_id'],
                action_date=timezone.now().date(),
                action_time=timezone.now().time(),
            )
        except Exception as log_error:
            # Don't fail the main operation if logging fails
            print(f"Error logging appointment delete: {log_error}")
        
        # Now delete the appointment
        appointment.delete()
        
        messages.success(request, "Appointment deleted successfully!")
        
    except Appointments.DoesNotExist:
        messages.error(request, "Appointment not found.")
    except Exception as e:
        messages.error(request, f"An error occurred while deleting: {e}")
    
    idmngmnt = request.session.get('appmngid')
    return redirect(f"{reverse('appointment')}?menumanagement_id={idmngmnt}")




