@login_required
def editcompanymaster(request):
    if request.method == 'POST':
        try:
            # Retrieve Menu Management ID from session
            idmngmnt = request.session.get('compmntobjid')
            if not idmngmnt:
                messages.error(request, "Menu Management ID not provided for redirect.")
                return redirect('error_page')

            # Get the company name and company ID from the request
            addcompany = request.POST.get('companyname')
            idcmpnymaster = request.POST.get('cmpnyid')
            if Comapany.objects.filter(
                Comapany_name__iexact=addcompany
            ).exclude(id=idcmpnymaster).exists():
                messages.warning(request, f"Company '{addcompany}' already exists. Please choose a different name.")
                return redirect(f"{reverse('editcompanymaster')}?ids={idcmpnymaster}")

            # Ensure company ID is provided
            if not idcmpnymaster:
                messages.error(request, "Company ID not provided.")
                return redirect(f"{reverse('Companymaster')}?menumanagement_id={idmngmnt}")

            # Attempt to get the company object
            objcompany = Comapany.objects.get(id=idcmpnymaster)
            # Update and save the company name
            objcompany.Comapany_name = addcompany
            objcompany.save()

            messages.success(request, "Company edited successfully.")
            return redirect(f"{reverse('Companymaster')}?menumanagement_id={idmngmnt}")

        except Comapany.DoesNotExist:
            messages.error(request, "Company not found.")
            return redirect(f"{reverse('Companymaster')}?menumanagement_id={idmngmnt}")
        except Exception as e:
            messages.error(request, f"An error occurred: {str(e)}")
            return redirect(f"{reverse('Companymaster')}?menumanagement_id={idmngmnt}")

    # Handling GET requests
    idenq = request.GET.get('ids')
    if not idenq:
        messages.error(request, "Company ID is required.")
        return redirect('companymaster')

    try:
        objedcommastr = Comapany.objects.get(id=idenq)
    except Comapany.DoesNotExist:
        messages.error(request, "Company not found.")
        return redirect('companymaster')
    
    

    # Prepare context
    menu_management_id = request.session.get('compmntobjid')
    stdesign = request.session.get('loginstaffdesign')
    
    if not stdesign:
        return redirect('staff_login')

    context = {
        'objedcommastr': objedcommastr,
        'stdesign': stdesign,
        'menu_management_id': menu_management_id,
        'cmmgmntedit': request.session.get('compmntobjedit'),
        'cmmgmntview': request.session.get('compmntobjview'),
    }

    return render(request, "companymasteredit.html", context)
