@login_required
def dailytreatment(request):
    if request.method == 'POST':
        addstaff = request.POST.get('staffname')
        addmrnumber = request.POST.get('mrno')
        addpatientname = request.POST.get('patientname')
        addcurrentdate = request.POST.get('currentdate')
        # Accessing dynamic treatment and medicine values
        treatment_values = []
        medicine_values = []
        treatment_counter = 1
        while request.POST.get(f'treatment{treatment_counter}'):
            treatment_values.append(request.POST.get(f'treatment{treatment_counter}'))
            medicine_values.append(request.POST.get(f'medicine{treatment_counter}'))
            treatment_counter += 1
        for treatment, medicine in zip(treatment_values, medicine_values):
            DailyTreatmentdetails.objects.create(
                Staff_name_id=addstaff,
                MR_Number_id=addmrnumber,
                Patient_Name_id=addpatientname,
                Current_date=addcurrentdate,
                Treatment_name=treatment,
                Medicinename=medicine
            )
        # Pass values to the template
        stdesign = request.session.get('loginstaffdesign')
        context = {
            'addstaff': addstaff,
            'addmrnumber': addmrnumber,
            'addpatientname': addpatientname,
            'addcurrentdate': addcurrentdate,
            'stdesign':stdesign ,
            'treatment_and_medicine': zip(treatment_values, medicine_values)
        }
    staffobj = Staffdetails.objects.all()
    mrnumobj = Patient_details.objects.all()
    patientobj = Patient_details.objects.all()
    currentdate = timezone.now().date()
    treatments=Treatment_master.objects.all()
    medicines=Itemaster.objects.all()
    stdesign = request.session.get('loginstaffdesign')
    context={
    'stdesign':stdesign,
    'staffobj':staffobj,
    'mrnumobj':mrnumobj,
    'patientobj':patientobj,
    'currentdate': currentdate,
    'treatments':treatments,
    'medicines':medicines,
    }
    return render(request,"dailytreatement.html",context)
