@login_required
def hospital(request):
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')

    # Check if a hospital record already exists
    hospital_instance = Hospitaldetails.objects.first()  # Get the first (and only) instance, if it exists

    if request.method == 'POST':
        addhospitalnme = request.POST.get('hospitalname')
        addaddress = request.POST.get('address')
        addlogo = request.FILES.get('inputfile')  # Use .get() to handle cases where the file is not uploaded
        addregnumber = request.POST.get('regnumber')
        addgst = request.POST.get('gst')
        addmanagernme = request.POST.get('managername')
        addcontactnum = request.POST.get('contactnumber')
        addemail = request.POST.get('email')

        # If a record already exists, update it; otherwise, create a new one
        if hospital_instance:
            # Update existing record
            hospital_instance.Name = addhospitalnme
            hospital_instance.Address = addaddress
            hospital_instance.Register_no = addregnumber
            hospital_instance.GST = addgst
            hospital_instance.Manager_name = addmanagernme
            hospital_instance.Contact_no = addcontactnum
            hospital_instance.Email = addemail

            # Only update the logo if a new file is uploaded
            if addlogo:
                hospital_instance.Logo = addlogo

            hospital_instance.save()
        else:
            # Create a new record
            hospital_instance = Hospitaldetails(
                Name=addhospitalnme,
                Address=addaddress,
                Logo=addlogo,
                Register_no=addregnumber,
                GST=addgst,
                Manager_name=addmanagernme,
                Contact_no=addcontactnum,
                Email=addemail
            )
            hospital_instance.save()

        return redirect('hospital')

    # Pass the existing hospital details to the template if they exist
    context = {
        'stdesign': stdesign,
        'hospital': hospital_instance
    }
    return render(request, "hospital.html", context)

