def edithospital(request):
    stdesign = request.session.get('loginstaffdesign')  # Retrieve staff designation from session
    if request.method == 'POST':
        # Get form data
        hospital_id = request.POST.get('hospitalid')
        hospital_name = request.POST.get('hospitalname')
        address = request.POST.get('address')
        register_no = request.POST.get('regnumber')
        gst = request.POST.get('gst')
        manager_name = request.POST.get('managername')
        contact_no = request.POST.get('contactnumber')
        email = request.POST.get('email')
        logo = request.FILES.get('logo')  # Get the uploaded logo file
        # Retrieve the hospital object or return 404 if not found
        hospital = get_object_or_404(Hospitaldetails, id=hospital_id)
        # Update fields
        hospital.Name = hospital_name
        hospital.Address = address
        hospital.Register_no = register_no
        hospital.GST = gst
        hospital.Manager_name = manager_name
        hospital.Contact_no = contact_no
        hospital.Email = email
        # If a new logo is uploaded, replace the old one
        if logo:
            # Delete the old logo if it exists
            if hospital.Logo:
                if os.path.isfile(hospital.Logo.path):
                    os.remove(hospital.Logo.path)
            hospital.Logo = logo

        # Save the updated hospital information
        hospital.save()

        # Success message
        messages.success(request, "Hospital details have been updated successfully.")
        
        # Redirect to a list page or another page to prevent duplicate submissions
        return redirect('hospital_list_view')  # Replace with your list view URL

    # For GET request, load the existing data into the form
    hospital_id = request.GET.get('ids')
    hospital =Hospitaldetails.objects.get(id=hospital_id)
    
    context = {
        'hospital': hospital,
        'stdesign': stdesign
    }
    return render(request, "hospital_edit.html", context)
           
