from django.views.decorators.http import require_POST
from django.views.decorators.csrf import csrf_exempt
@csrf_exempt
@require_POST
def check_patient_exists(request):
    patientname = request.POST.get('patientname', '').strip()
    contactnumber = request.POST.get('contactnumber', '').strip()

    exists = Patient_details.objects.filter(
        Patient_Name__iexact=patientname,
        contactno=contactnumber
    ).exists()

    return JsonResponse({'exists': exists})   


@login_required
def patientdetails(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')

        # Retrieve POST data
        addpatientname = request.POST.get('patientname').strip()
        addage = request.POST.get('age')
        addgender = request.POST.get('gender')
        addemail = request.POST.get('email')
        addcontactnumber = request.POST.get('contactnumber').strip()
        addcountry = request.POST.get('country')
        addstate = request.POST.get('state')
        adddistrict = request.POST.get('district')
        addaddress = request.POST.get('address')
        addpatientdate = request.POST.get('patient_date')
        addconsultation = request.POST.get('consultation_type') or 'offline'
        addreg_Fee= request.POST.get('reg_Fee')
        if Patient_details.objects.filter(Patient_Name__iexact=addpatientname, contactno=addcontactnumber,deleted=False).exists():
            messages.warning(request, "A patient with the same name and contact number is already registered.")
            return redirect(f"{reverse('patientdetails')}?menumanagement_id={idmngmnt}")
        todate = timezone.now().strftime("%Y%m%d")

        with transaction.atomic():  # Ensures thread safety
            last_entry = Patient_details.objects.filter(Entry_Date=todate).select_for_update().order_by('-id').first()
            refnid = 1
            if last_entry and last_entry.Medical_Record_Number:
                refnid = int(last_entry.Medical_Record_Number[12:]) + 1
            mrn_id = f"MRNO{todate}{refnid}"

            # Get the logged-in staff branch
            st = request.session.get('loginstaff')
            if not st:
                return redirect('staff_login')

            staff_branch = Staffallocation.objects.get(id=st)
            if not staff_branch:
                raise ValueError("Contact Admin To Allocate Staff.")
            staffbranchid = staff_branch.Branch_Name_id  
			
            # Save patient details
            try:
                objpatientdetails = Patient_details(
                    Patient_Name=addpatientname,
                    Entry_Date=todate,
                    Medical_Record_Number=mrn_id,
                    Age=addage,
                    Gender=addgender,
                    Email=addemail,
                    contactno=addcontactnumber,
                    country_id=addcountry,
                    state_id=addstate,
                    district=adddistrict,
                    Date=addpatientdate,
                    Branch_Name_id=staffbranchid,
                    address =addaddress,
                    consultation_type=addconsultation,
                    reg_Fee =addreg_Fee if addreg_Fee else 0
                )
                objpatientdetails.save()
                 
                current_time = timezone.now()
                PatientAuditLog.objects.create(
                    mrno=mrn_id,
                    patientid_id=objpatientdetails.id,
                    action="INSERT",
                    staff_id=request.session.get('staffid'),
                    branch_id=request.session.get('branchid'),
                    action_date=current_time.date(),
                    action_time=current_time.time(),  # ✅ Fix: Properly formatted time
                )
                messages.success(request, "Patient details saved successfully.")
                if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                    # ✅ Return JSON response for AJAX
                    return JsonResponse({
                        'success': True,
                        'patient_id': objpatientdetails.id,
                        'reg_fee': float(addreg_Fee) if addreg_Fee else 0,
                        'message': 'Patient saved successfully'
                    })
                
                # ✅ Regular form submission - redirect based on reg_fee
                if addreg_Fee and float(addreg_Fee) > 0:
                    return redirect(f"{reverse('registration_fee_invoice')}?patient_id={objpatientdetails.id}")
                else:
                    return redirect(f"{reverse('patientdetails')}?menumanagement_id={idmngmnt}")
                # if addreg_Fee and float(addreg_Fee) > 0:
                #     return redirect(f"{reverse('registration_fee_invoice')}?patient_id={objpatientdetails.id}")
                # else:
                #     return redirect(f"{reverse('patientdetails')}?menumanagement_id={idmngmnt}")
            except Exception as e:
                messages.error(request, f"An error occurred while saving patient details: {str(e)}. Please contact the admin.")
                return redirect('error_page')

    else:
        # Handle GET requests
        try:
            idmngmnt = request.GET.get('menumanagement_id')
            if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin.")
                return redirect('error_page')

            ptdtobj = get_object_or_404(menumanagement, id=idmngmnt)
            # Storing menu management permissions in session
            request.session['ptdtobjmngid'] =idmngmnt
            request.session['ptdtobjadd'] = ptdtobj.add
            request.session['ptdtobjview'] = ptdtobj.view
            request.session['ptdtobjedit'] = ptdtobj.edit
            request.session['ptdtobjdelete'] = ptdtobj.delete
            request.session['ptafterobjmngid'] = idmngmnt
            ptafregobj = get_object_or_404(menumanagement, id=idmngmnt)
            request.session['ptafterobjmngadd'] = ptafregobj.add
            request.session['ptafterobjmngview'] = ptafregobj.view
            request.session['ptafterobjmngedit'] = ptafregobj.edit
            request.session['ptafterobjmngdelete'] = ptafregobj.delete
            countryobj = Country.objects.all()
            stateobj = State.objects.all()
            districtobj = District.objects.all()
            cityobj = City.objects.all()
            stdesign = request.session.get('loginstaffdesign')
             
            context = {
                'countryobj': countryobj,
                'stateobj': stateobj,
                'districtobj': districtobj,
                'cityobj': cityobj,
                'stdesign': stdesign,
                'ptdtmngview': request.session.get('ptdtobjview'),
                'ptdtmngadd': request.session.get('ptdtobjadd'),
                'ptdtmngedit': request.session.get('ptdtobjedit'),
                'ptdtmngdelete': request.session.get('ptdtobjdelete'),
                'idmngmnt': idmngmnt
            }
            
            return render(request, "patientdetails.html", context)

        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')
        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin.")
            return redirect('error_page')


