@login_required
def patientdetailtable_data(request):

    staff_id = request.session.get('loginstaff')
    stdesign_id = request.session.get('loginstaffdesign')

    if not staff_id or not stdesign_id:
        return JsonResponse({'error': 'Unauthorized'}, status=401)

    staff_branch = Staffallocation.objects.select_related(
        'Branch_Name'
    ).filter(id=staff_id).first()

    if not staff_branch:
        return JsonResponse({'error': 'Staff not found'}, status=404)

    # Get designation name safely
    try:
        designation = Designation.objects.get(id=stdesign_id)
        designation_name = designation.Designation_Name.lower()
    except Designation.DoesNotExist:
        designation_name = ''

    # Superadmin sees all
    if designation_name == "superadmin":
        qs = Patient_details.objects.select_related(
            'Branch_Name', 'country', 'state'
        ).filter(deleted=False).order_by('-id')
    else:
        qs = Patient_details.objects.select_related(
            'Branch_Name', 'country', 'state'
        ).filter(
            Branch_Name_id=staff_branch.Branch_Name_id,
            deleted=False
        ).order_by('-id')


    # DataTables parameters
    draw = int(request.GET.get('draw', 1))
    start = int(request.GET.get('start', 0))
    length = int(request.GET.get('length', 20))
    search_value = request.GET.get('search[value]', '').strip()

    total_count = qs.count()

    # 🔍 Search filter
    if search_value:
        qs = qs.filter(
            Q(Medical_Record_Number__icontains=search_value) |
            Q(Patient_Name__icontains=search_value) |
            Q(Age__icontains=search_value) |
            Q(Gender__icontains=search_value) |
            Q(address__icontains=search_value) |
            Q(country__Country_Name__icontains=search_value) |
            Q(state__State_Name__icontains=search_value) |
            Q(district__icontains=search_value) |
            Q(contactno__icontains=search_value) |
            Q(consultation_type__icontains=search_value)
        )

    filtered_count = qs.count()
    page_qs = qs[start:start + length]

    data = []

    for idx, obj in enumerate(page_qs, start=start + 1):

        view_url = reverse('casehistory_view') + f"?ids={obj.id}"
        edit_url = reverse('editpatientdetails') + f"?ids={obj.id}"

        # Consultation badge
        consultation_badge = (
            '<span class="badge badge-success">Offline</span>'
            if obj.consultation_type == 'offline'
            else '<span class="badge badge-primary">Online</span>'
        )

        data.append({
            'sl_no': idx,
            'Medical_Record_Number': obj.Medical_Record_Number,
            'Patient_Name': obj.Patient_Name,
            'Age': obj.Age or "",
            'Gender': obj.Gender,
            'address': obj.address or "",
            'branch': obj.Branch_Name.Branch_Name if obj.Branch_Name else "",
            'Country_Name': obj.country.Country_Name if obj.country else "",
            'State_Name': obj.state.State_Name if obj.state else "",
            'district': obj.district or "",
            'contactno': obj.contactno,
            'consultation_type': consultation_badge,
            'Date': obj.Date.strftime("%Y-%m-%d") if obj.Date else "",
            'action': (
                f'<a href="{view_url}" title="View">'
                f'<i class="fas fa-eye mr-2 text-info"></i></a>'
                f'<a href="{edit_url}" title="Edit">'
                f'<i class="fas fa-edit text-primary"></i></a>'
            )
        })

    return JsonResponse({
        'draw': draw,
        'recordsTotal': total_count,
        'recordsFiltered': filtered_count,
        'data': data
    })
    
    
    

