@login_required
def treatmentplan(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Menu Management ID not provided.")
            return redirect('error_page')
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')
        mr_number_id = request.POST.get('mrnumber')
        treatment_plan = request.POST.get('treatmentplan')
        notes = request.POST.get('notes')
        currentdate = timezone.now().date()
        try:
            # Create and save Plan model instance
            if treatment_plan:
                plan_instance = Plan.objects.create(
                    MR_Number_id=mr_number_id,
                    Treatment_Plan=treatment_plan,
                    Notes=notes,
                    currentdate=currentdate
                )
            def parse_date(date_str):
                try:
                    return datetime.strptime(date_str, '%Y-%m-%d').date()
                except ValueError:
                    return None
            # Extract and save Record Sheet data
            record_sheet_data = request.POST.getlist('adddate')
            addbp_data = request.POST.getlist('addbp')
            addpr_data = request.POST.getlist('addpr')
            addspo2_data = request.POST.getlist('addspo2')
            addtemp_data = request.POST.getlist('addtemp')
            addfbsppbs_data = request.POST.getlist('addfbsppbs')

            min_length = min(len(record_sheet_data), len(addbp_data), len(addpr_data), len(addspo2_data), len(addtemp_data), len(addfbsppbs_data))
            for i in range(min_length):
                date = parse_date(record_sheet_data[i])
                if not date:
                    continue  # Skip invalid date entries
                bp = addbp_data[i]
                pr_rr = addpr_data[i]
                spo2 = addspo2_data[i]
                temp = addtemp_data[i]
                fps_ppbs = addfbsppbs_data[i]
                Record_Sheet.objects.create(
                    MR_Number_id=mr_number_id,
                    Date=date,
                    Bp=bp,
                    PR_RR=pr_rr,
                    SPO2=spo2,
                    TEMP=temp,
                    FPS_PPBS=fps_ppbs
                )

            # Extract and save Treatment Chart data
            treatment_chart_data = request.POST.getlist('date')
            em_data = request.POST.getlist('em')
            mrng_data = request.POST.getlist('mrng')
            aftn_data = request.POST.getlist('aftn')
            evng_data = request.POST.getlist('evng')
            night_data = request.POST.getlist('night')

            min_length = min(len(treatment_chart_data), len(em_data), len(mrng_data), len(aftn_data), len(evng_data), len(night_data))
            for i in range(min_length):
                date = parse_date(treatment_chart_data[i])
                if not date:
                    continue  # Skip invalid date entries
                em = em_data[i]
                morning = mrng_data[i]
                afternoon = aftn_data[i]
                evening = evng_data[i]
                night = night_data[i]

                Treatment_Chart.objects.create(
                    MR_Number_id=mr_number_id,
                    Date=date,
                    EM=em,
                    Morning=morning,
                    Afternoon=afternoon,
                    Evening=evening,
                    Night=night
                )

            # Extract and save Diet Chart data
            diet_chart_data = request.POST.getlist('date')
            six_fifteen_data = request.POST.getlist('6_15')
            eight_thirty_data = request.POST.getlist('8_30')
            eleven_data = request.POST.getlist('11')
            twelve_thirty_data = request.POST.getlist('12_30')
            four_data = request.POST.getlist('4')
            six_thirty_data = request.POST.getlist('6_30')
            bed_time_data = request.POST.getlist('bedtime')

            min_length = min(len(diet_chart_data), len(six_fifteen_data), len(eight_thirty_data), len(eleven_data), len(twelve_thirty_data), len(four_data), len(six_thirty_data), len(bed_time_data))
            for i in range(min_length):
                date = parse_date(diet_chart_data[i])
                if not date:
                    continue  # Skip invalid date entries
                six_fifteen = six_fifteen_data[i]
                eight_thirty = eight_thirty_data[i]
                eleven = eleven_data[i]
                twelve_thirty = twelve_thirty_data[i]
                four = four_data[i]
                six_thirty = six_thirty_data[i]
                bed_time = bed_time_data[i]

                Diet_Chart.objects.create(
                    MR_Number_id=mr_number_id,
                    Date=date,
                    six_fifteen=six_fifteen,
                    eight_thirty=eight_thirty,
                    eleven=eleven,
                    twelve_thirty=twelve_thirty,
                    four=four,
                    six_thirty=six_thirty,
                    bed_time=bed_time
                )

            return redirect(f"{reverse('treatmentplan')}?menumanagement_id={idmngmnt}")

        except Exception as e:
            messages.error(request, f"An error occurred while saving room details: {str(e)}. Please contact the admin.")
            return redirect('error_page')

    else:
        try:
            idmngmnt = request.GET.get('menumanagement_id')
            if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
                return redirect('error_page')
            trtplnobj = get_object_or_404(menumanagement, id=idmngmnt)
            request.session['trtplnid'] = idmngmnt
            request.session['trtplnobjadd'] = trtplnobj.add
            request.session['trtplnobjview'] = trtplnobj.view
            request.session['trtplnobjedit'] = trtplnobj.edit
            request.session['trtplnobjdelete'] = trtplnobj.delete

            mrnumobj = Patient_details.objects.all()
            stdesign = request.session.get('loginstaffdesign')
            if not stdesign:
                return redirect('staff_login')
                
            context = {
                'idmngmnt': idmngmnt,
                'mrnumobj': mrnumobj,
                'stdesign': stdesign,
                'mntrtadd': trtplnobj.add,
                'mntrtview': trtplnobj.view,
                'mntrtdelete': trtplnobj.delete,
                'mntrtedit': trtplnobj.edit
            }
            return render(request, "treatmentplan.html", context)
        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')
        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin for assistance.")
            return redirect('error_page')
