from itertools import zip_longest
@login_required
def discharge(request):
    """Handles patient discharge, updates admission status, and releases room allocation."""
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Menu Management ID not provided.")
        return redirect('error_page')

    stdesign = request.session.get('loginstaffdesign')
    st_id = request.session.get('loginstaff')
    if not stdesign or not st_id:
        return redirect('staff_login')

    if request.method == 'POST':
        try:
            ipno = request.POST.get('ipno')
            if not ipno:
                messages.error(request, "Patient admission ID is required.")
                return redirect(f"{reverse('discharge')}?menumanagement_id={idmngmnt}")

            if PatientDischarge.objects.filter(ipptno_id=ipno).exists():
                messages.error(request, "This patient has already been discharged.")
                return redirect(f"{reverse('discharge')}?menumanagement_id={idmngmnt}")

            admission = get_object_or_404(ippatientadmission, id=ipno, Admittedstatus=True)

            # Safely parse dates
            try:
                discharged_date = datetime.strptime(request.POST.get('dischargeddate'), "%Y-%m-%d").date()
            except (ValueError, TypeError):
                discharged_date = timezone.now().date()

            try:
                next_checkup_date = datetime.strptime(request.POST.get('nxtchkupdate'), "%Y-%m-%d").date()
            except (ValueError, TypeError):
                next_checkup_date = None

            # Create discharge record
            objdischarge = PatientDischarge.objects.create(
                ipptno=admission,
                treatment_summary=request.POST.get('treatmentsum', ''),
                discharged_date=discharged_date,
                next_checkup_date=next_checkup_date,
                additional_notes=request.POST.get('additional', ''),
                sfirst_name=request.POST.get('firstname1', ''),
                dischargedstaff_id=st_id,
                discharge_summary_notes =request.POST.get('discharge_summary_note'),
                condition_on_discharge=request.POST.get('condtnondischarge', ''),
                physical_examinations=request.POST.get('condtnondischarge', ''),
                accomadationtype=request.POST.get('accommodation_typeid', ''),
                bedno=request.POST.get('bedid', ''),
                floorno=request.POST.get('floorid', ''),
                roomno=request.POST.get('roomid', ''),
              
            )
            # Save dynamic advice fields
            for advice in request.POST.getlist('advice_on_discharge[]'):
                if advice.strip():
                    AdviceOnDischarge.objects.create(discharge=objdischarge, advice_text=advice.strip())

            # Save internal meds and procedures (handles uneven lists)
            internal_medications = request.POST.getlist('internal_medications[]')
            treatment_procedures = request.POST.getlist('treatment_procedures[]')

            for med, proc in zip_longest(internal_medications, treatment_procedures, fillvalue=''):
                if med.strip() or proc.strip():
                    DischargeMedicationProcedure.objects.create(
                        discharge=objdischarge,
                        internal_medication=med.strip(),
                        treatment_procedure=proc.strip()
                    )

            # Update admission status
            admission.Admittedstatus = False
            admission.end_date = discharged_date
            admission.save()
            # Release room/bed
            room_booking = ippatientroombooking.objects.filter(ipno=admission).first()
            if room_booking:
                if room_booking.room_number:
                    room_booking.room_number.is_available = True
                    room_booking.room_number.save()
                if room_booking.bed_number:
                    room_booking.bed_number.is_available = True
                    room_booking.bed_number.save()

            messages.success(request, "Patient discharged successfully!")
            
            return redirect(f"{reverse('discharge_summary')}?ids={objdischarge.id}")

        except Exception as e:
            messages.error(request, f"Error while saving discharge details: {str(e)}")
            return redirect('error_page')

    else:
        try:
            dischrgobj = get_object_or_404(menumanagement, id=idmngmnt)
            request.session['dischrgobjid'] = dischrgobj.id
            request.session['dischrgobjadd'] = dischrgobj.add
            request.session['dischrgobjview'] = dischrgobj.view
            request.session['dischrgobjedit'] = dischrgobj.edit
            request.session['dischrgobjdelete'] = dischrgobj.delete

            context = {
                'mrnumobj': ippatientadmission.objects.filter(Admittedstatus=True),
                'countryobj': Country.objects.all(),
                'stateobj': State.objects.all(),
                'districtobj': District.objects.all(),
                'cityobj': City.objects.all(),
                'stdesign': stdesign,
                'idmngmnt': idmngmnt,
                'dischrgadd': dischrgobj.add,
                'dischrgedit': dischrgobj.edit,
                'dischrgview': dischrgobj.view,
                'dischrgdelete': dischrgobj.delete,
            }

            return render(request, "discharge.html", context)

        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found.")
            return redirect('error_page')

        except Exception as e:
            messages.error(request, f"Unexpected error: {str(e)}")
            return redirect('error_page')
    # except Exception as e:
