@login_required
def dischargetable(request):
   
    dischrgadd = request.session.get('dischrgobjadd')
    dischrgview = request.session.get('dischrgobjview')
    dischrgdelete = request.session.get('dischrgobjdelete')
    discharge=PatientDischarge.objects.all()
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Menu Management ID not provided.")
        return redirect('error_page')
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')  
  
    dischrgedit = request.session.get('dischrgobjedit')                 
    context={
        'idmngmnt':idmngmnt,
        'dischrgadd':dischrgadd,
        'dischrgview':dischrgview,
        'dischrgdelete':dischrgdelete,
        'discharge':discharge,
        'stdesign':stdesign,
       'dischrgedit': dischrgedit,
    }
    return render(request,'dischargetable.html',context)

@login_required
def invoice(request):

    un=unitdt.objects.all()
    objhospt=Hospitaldetails.objects.all()
    m=Physicalstockdetails.objects.all()
    today = date.today()
    todateinv = timezone.now().strftime("%Y%m%d")
    todate = timezone.now().strftime("%Y/%m/%d")
    mrnoobj=Patient_details.objects.all()
    stdesign= request.session['loginstaffdesign']
    st_id= request.session['loginstaff'] 
    staff_branch=Staffallocation.objects.get(id=st_id)
    stbtachid=staff_branch.Branch_Name_id
    # mrnoobj = Patientadmission.objects.filter(Branch_Name_id=stbtachid)
    brname = Branch.objects.filter(id=stbtachid)
    last_entry = invoicemaster.objects.filter(currentdate=today).order_by('-id').first()
    if last_entry:
            last_refid = last_entry.Invoicenumber
            if last_refid:
                # Extract the numeric part after "INVNO" and increment it by 1
                refnid = int(last_refid[13:]) + 1
            else:
                refnid = 1
    else:
            refnid = 1
    inv_id = f"INVNO{todateinv}{refnid}"
    context={
        'm':m,
        'un':un,
        'st_id':st_id,
        'objhospt':objhospt,
        'today':today,
        'todate':todate,
        'mrnoobj':mrnoobj,
        'stdesign':stdesign,
        'brname':brname,
        'inv_id':inv_id  
          }
    return render(request,"invoice.html",context)
from django.db.models import F
@login_required
def saveinvoice(request):
    if request.method == 'POST':
        try:
            with transaction.atomic():  # Ensures that either all DB operations succeed, or none do
                # Invoice data processing
                ptname = request.POST.get('ptname')
                ptphno = request.POST.get('ptphno')
                hosptname_id = request.POST.get('hosptname')
                branchname_id = request.POST.get('branchname')
                mrnum_id = request.POST.get('mrnum')
                invno = request.POST.get('invno')
                current_date = date.today()
                totsubtoal = request.POST.get('totsubtoal')
                taxperc = request.POST.get('taxperc') or 0.0
                discount = request.POST.get('discount')
                shipping = request.POST.get('shipping') or 0 
                totalIncludingTax = request.POST.get('totalIncludingTax')
                confee = request.POST.get('cfee')
                rgfee = request.POST.get('rgfee')
                st_id = request.session.get('loginstaff')
                if not st_id:
                    return redirect('staff_login') 
                # Get hospital and branch
                hospital = Hospitaldetails.objects.get(id=hosptname_id)
                branch = int(branchname_id)
                # Create the invoice master record
                invoicemaster_obj = invoicemaster.objects.create(
                    hospitalname=hospital,
                    branch_id=branch,
                    patientname=ptname,
                    patientphno=ptphno,
                    Invoicenumber=invno,
                    currentdate=current_date,
                    subtotal=totsubtoal,
                    tax=taxperc,
                    shipping=shipping,
                    total=totalIncludingTax,
                    discount=discount,
                    preparedby_id=st_id,
                    consultationfee=confee,
                    consultationfeecumregfee=rgfee
                )
                # Process invoicechild records
                for i in range(1, int(request.POST.get('record_count')) + 1):
                    particulars = request.POST.get(f'particular{i}')
                    exp = request.POST.get(f'exp{i}')
                    qty = request.POST.get(f'quantity{i}')
                    amount = request.POST.get(f'amount{i}')
                    subtotal = request.POST.get(f'subtotal{i}')
                    batch = request.POST.get(f'batch{i}')
                    unit = request.POST.get(f'un{i}')
                    mfg = request.POST.get(f'mfg{i}')
                    sup = request.POST.get(f'sup{i}')
                    hsn = request.POST.get(f'hsn{i}')
                    # Try to get the stock details; if not found, log an error
                    try:
                        itemaster_obj = Physicalstockdetails.objects.get(itemnm__itemnm=particulars, Batch_no=batch, suppliernm_id=sup)
                    except Physicalstockdetails.DoesNotExist:
                        # Log the error for missing stock details
                        InvoiceErrorLog.objects.create(
                            error_message=f"Physical stock details not found for item: {particulars}, batch: {batch}, supplier: {sup}",
                            related_invoice=invno,
                            staff_id=st_id
                        )
                        continue  # Skip this record and move to the next one
                    # Create invoicechild record
                    invoicechild.objects.create(
                        quantity=qty,
                        particulars=particulars,
                        batchno=batch,
                        amount=amount,
                        sutotal=subtotal,
                        patientname=ptname,
                        patientphno=ptphno,
                        invoiceno=invno,
                        currentdate=current_date,
                        expirydate=exp,
                        description="test",
                        invmasterid_id=invoicemaster_obj.id,
                        mfg=mfg,
                        unt=unit,
                        hsncode=hsn,
                        suppid_id=sup
                    )
                    # Update stock quantity
                    itemaster_obj.qty = F('qty') - int(qty)
                    itemaster_obj.save()
            return redirect('invprint')
        except Exception as e:
            # Catch all exceptions and log them
            error_message = str(e)
            InvoiceErrorLog.objects.create(
                error_message=error_message,
                related_invoice=invno if 'invno' in locals() else None,
                staff_id=request.session.get('loginstaff')
            )
            # Show a generic error message to the user
            return render(request, "error_page.html", {"error_message": "System is engaged. Please try again later."})

    # If it's a GET request, handle as before
    medname = medicinemaster.objects.all()  
    objhospt = Hospitaldetails.objects.all()
    today = date.today()
    todateinv = now().strftime("%Y%m%d")
    todate = now().strftime("%Y/%m/%d")
    mrnoobj = Patient_details.objects.all()
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    st_id = request.session.get('loginstaff')
    if not st_id:
        return redirect('staff_login')
    staff_branch = Staffallocation.objects.get(id=st_id)
    stbtachid = staff_branch.Branch_Name_id 
    brname = Branch.objects.filter(id=stbtachid)
    last_entry = invoicemaster.objects.filter(currentdate=today).order_by('-id').first()
    if last_entry:
        last_refid = last_entry.Invoicenumber
        refnid = int(last_refid[13:]) + 1 if last_refid else 1
    else:
        refnid = 1
    inv_id = f"INVNO{todateinv}{refnid}"
    context = {
        'medname': medname,
        'st_id': st_id,
        'objhospt': objhospt,
        'today': today,
        'todate': todate,
        'mrnoobj': mrnoobj,
        'stdesign': stdesign,
        'brname': brname,
        'inv_id': inv_id  
    }
    return render(request, "invoicenew.html", context)
