from django.http import JsonResponse
from django.views.decorators.http import require_GET
from django.utils.dateparse import parse_date
from .models import Physicalstockdetails

@require_GET
def search_medicine(request):
    
    search_term = request.GET.get('term', '').strip()
    if search_term:
        current_date = date.today()
        try:
            expired_medicines = Physicalstockdetails.objects.filter(
                itemnm__itemnm__icontains=search_term,
                Expiry_date__gte=current_date,qty__gt=0
            )
            data = []
            for medicine in expired_medicines:
                medicine_data = {
                    'item_id': medicine.itemnm.id,
                    'unit': medicine.unt.unitname,
                    'item_name': medicine.itemnm.itemnm,
                    'batchno': medicine.Batch_no,
                    'compid': medicine.Comapany_name_id,
                    'currentstock': medicine.qty,
                    'supplier_name': medicine.suppliernm_id if medicine.suppliernm_id else None
                }
                data.append(medicine_data)
            return JsonResponse(data, safe=False)
        except Exception as e:
            # Log the exception to the console or a log file
            print(f"Error: {e}")
            return JsonResponse({'error': 'Server error occurred'}, status=500)
    return JsonResponse({'error': 'Invalid search term'}, status=400)
