def get_medicine_data(post_data, diet_type):
    medicine_data = []
    counter = 1  

    while True:
        medicine_name_key = f'{diet_type}{counter}'
        quantity_key = f'{diet_type}{counter}qty'

        medicine_name = post_data.get(medicine_name_key)
        quantity = post_data.get(quantity_key)

        if not medicine_name or not quantity:
            break

        medicine_data.append({
            'name': medicine_name,
            'quantity': quantity,
        })

        counter += 1

    return medicine_data

def get_admission_details(request, selected_date):
    try:
       
        admission_details = Patientadmission.objects.filter(Booking_Date=selected_date)
        serialized_data = [
            {'student_name': admission.Bystandername}
            for admission in admission_details
        ]

        response_data = {
            'admission_count': len(serialized_data),
            'admission_details': serialized_data
        }

        return JsonResponse(response_data, status=200)

    except ValueError:
        return JsonResponse({'error': 'Invalid date format'}, status=400)

@login_required
def get_booking_details(request, selected_date):
    try:
        
      
        bookings = Patientadmission.objects.filter(Roomno_id=selected_date)
        if bookings.exists():
            booking_ranges = []
            for booking in bookings:
                booking_start_date = booking.Booking_Date
                booking_end_date = booking.Bookingend_Date
                booking_ranges.append({'start_date': booking_start_date, 'end_date': booking_end_date})
            
            return JsonResponse({'booking_ranges': booking_ranges})
        else:
            return JsonResponse({'error': 'No bookings found for the selected room'}, status=400)
    except ValueError:
        return JsonResponse({'error': 'Invalid date format'}, status=400)

