from django.contrib.auth.hashers import check_password
from django.contrib.auth import logout

def staff_login(request):
    if request.method == 'POST':
        username = request.POST.get('username')
        password = request.POST.get('password')
        # Check if the credentials match a staff account
        try:
            staff_allocation = Staffallocation.objects.get(Username=username, Password=password, Status='active')
            request.session['loginstaff'] = staff_allocation.id
            request.session['loginstaffdesign'] = staff_allocation.Designation_Name_id
            request.session['staffid'] = staff_allocation.Staff_id
            request.session['branchid']=staff_allocation.Branch_Name_id
            # room_count = Room_details.objects.count()                                                                         
            # If no previous URL, redirect to the default page
            # staff_count = Staffdetails.objects.count()
            # patient_count = Patient_details.objects.count()
            # today_date = datetime.date.today()
            # today_appointments_count = Appointments.objects.filter(Appointment_date=today_date).count()
            st = request.session['loginstaff']
            staff_branch = Staffallocation.objects.get(id=st)

            # Fetch staff_id from Staffallocation
            staff_id = staff_branch.Staff_id
            # Get staff details
            staff_details = Staffdetails.objects.get(id=staff_id)
            staff_name = f"{staff_details.Staff_firstname} {staff_details.Staff_lastname}"

            # Get branch name
            branch = Branch.objects.get(id=staff_branch.Branch_Name_id)
            branch_name = branch.Branch_Name

            # Store in session
            request.session['loginstaff_name1'] = staff_name
            request.session['branch_name1'] = branch_name
            request.session['branch_id']=branch.id

            stdesign = request.session['loginstaffdesign']
            staff_branch=Staffallocation.objects.get(id=st)
            staffbranchid=staff_branch.Branch_Name_id
            staff_id= request.session.get('staffid')
            staff_count=Staffallocation.objects.filter(Branch_Name_id=staffbranchid).count()
            patient_count=Patient_details.objects.filter(Branch_Name_id=staffbranchid).count()
            # today_date = datetime.date.today()
            today_date = date.today()
            today_appointments_count = Appointments.objects.filter(Appointment_date=today_date,Branch_id=staffbranchid).count()
            # room=Room_details.objects.filter(branchidrm_id=staffbranchid)
            try:
                staff_roles = Roleassign.objects.filter(Staff_id=staff_id)
                if staff_roles.exists():
                    # If you want the first role (or implement logic to choose one)
                    staff_role = staff_roles.first()
                    request.session['roleid'] = staff_role.roleid_id
                    
                    # Optional: Store multiple roles if needed
                    request.session['roleids'] = list(staff_roles.values_list('roleid_id', flat=True))
                else:
                    messages.error(request, f"Staff role not found for Staff ID {staff_id}. Please register in the Roleassign table.")
                    return render(request, 'login.html')
            except Exception as e:
                messages.error(request, f"Error retrieving staff role: {str(e)}")
                return render(request, 'login.html')   
            context = {
                 'staff_id':staff_id,
                # 'room':room,
                'stdesign': stdesign,
                'st': st,
                # 'room_count': room_count,
                'staff_count': staff_count,
                'patient_count': patient_count,
                'today_appointments_count': today_appointments_count
            }
            return render(request, 'home.html', context)

        except Staffallocation.DoesNotExist:
            messages.error(request, 'Invalid login credentials or inactive account.')
            return render(request, 'login.html')

    return render(request, 'login.html')
    
    
