from django.contrib.auth import logout
@login_required
def logout_view(request):
    if 'loginstaff' in request.session:
        del request.session['loginstaff']
    # Clear requested URL stored for redirection
    if 'requested_url' in request.session:
        del request.session['requested_url']
  # Clear the requested URL if it exists
    request.session.clear()  # Clear all session data
    logout(request)  # Log out the user
    return redirect('staff_login')
    
