def getmrdetails(request):
    # Get the value of 'mrNumber' from the GET parameters
    mr_number = request.GET.get('mrNumber')
    
    # Check if 'mrNumber' is provided
    if mr_number:
        # Query the patientadmission table to get the corresponding patient admission record
        try:
            patient_details=Patient_details.objects.get(id=mr_number)
            # Getappointmentafterreg patient name and address
            patient_name = patient_details.Patient_Name
            # patient_address = patient_details.address
            patient_email = patient_details.Email
            patient_contactno = patient_details.contactno
            # patient_Pincode = patient_details.Pincode
            age=patient_details.Age
            gender=patient_details.Gender
            # place=patient_details.city
            data = {
                'Medical_Record_Number': mr_number,
                'Patient_Name': patient_name,
                # 'Housename': patient_address,
                'phno':patient_contactno,
                'patient_email':patient_email,
                # 'pincode':patient_Pincode,
                'age':age,
                'gender':gender,
                # 'place':place,
            }
            
            # Return the data in a JSON response
            return JsonResponse(data)
        except Patient_details.DoesNotExist:
            # If no patient with the given MR number is found, return an error message
            return JsonResponse({'error': 'Patient with MR number {} not found.'.format(mr_number)}, status=404)
        # except Patientadmission.DoesNotExist:
        #     # If no admission record with the given MR number is found, return an error message
        #     return JsonResponse({'error': 'No admission record found for MR number {}.'.format(mr_number)}, status=404)
    else:
        # If 'mrNumber' is not provided, return an error message
        return JsonResponse({'error': 'MR number not provided.'}, status=400)
