@login_required
def enquiryedit(request):
    if request.method == 'POST':
        enquiername=request.POST.get('enqname')
        age=request.POST.get('age')
        phno=request.POST.get('phno')
        des=request.POST.get('desc')
        langs=request.POST.get('langs')
       
        callormsg=request.POST.get('callormsg')
        sourcedt=request.POST.get('sourcedt')
        cdate=timezone.now().strftime("%Y-%m-%d")
        enq_id=request.POST.get('enqid')
        st_id= request.session['loginstaff'] 
        staff_branch=Staffallocation.objects.get(id=st_id)
        stbtachid=staff_branch.Branch_Name_id
        if not enq_id:
                messages.error(request, "Enquiry Id Not Found. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')
        idmngmnt = request.session.get('enqobjmngid')
        if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
                    return redirect('staff_login') 
        try:
            objenq=enquiry.objects.get(id=enq_id)
            objenq.name=enquiername
            objenq.age=age
            objenq.Phone_number=phno
            objenq.complaint=des
            objenq.currentdate=cdate
            objenq.callormsg=callormsg
            objenq.sourrcdts_id=sourcedt
            objenq.preparedby_id=request.session.get('loginstaff'),
            objenq.branch_id=stbtachid
            objenq.language=langs
            objenq.save()
            return redirect(f"{reverse('displayenquiry')}?menumanagement_id={idmngmnt}")
        except ObjectDoesNotExist:
            messages.error(request, "Enquiry not found.")
        except ValueError:
            messages.error(request, "Invalid Enquiry ID.")
        except Exception as e:
            messages.error(request, f"An error occurred: {str(e)}")
        return redirect(f"{reverse('displayenquiry')}?menumanagement_id={idmngmnt}")
    else:
        idmngmnt = request.session.get('enqobjmngid')
        if not idmngmnt:
            messages.error(request, "Menu Management ID not provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
                    return redirect('staff_login') 
        idenq = request.GET.get('ids')
        if not idenq:
            messages.error(request, "Enquiry ID is missing.")
            return redirect('error_page')
        try:
            enq=enquiry.objects.filter(id=idenq)
        except ObjectDoesNotExist:
            messages.error(request, "Enquiry not found.")
            return redirect(f"{reverse('displayenquiry')}?menumanagement_id={idmngmnt}")
        sourcedt=sourcedetails.objects.filter(status="1")
        context={
        'sourcedt':sourcedt,
        'idmngmnt':idmngmnt,
        'enq':enq,
        'stdesign':stdesign,
        'enqedit': request.session.get('enqobjmngedit'),
        'enqobjmngview':request.session.get('enqobjmngview')
        }
        return render(request,"enquiryedit.html",context)
    
  
@login_required
def delenquiry(request):
        enquiry_id = request.GET.get('ids')
        if enquiry_id:
            try:
                enquiry_instance = enquiry.objects.get(id=enquiry_id)
                if enquiry_instance.status != 'Pending' and enquiry_instance.status != 'Dropped':
                    messages.error(request, "This enquiry cannot be deleted as it is not 'Pending'.")
                else:
                    enquiry_instance.deleted = True
                    enquiry_instance.deleted_date = timezone.now()
                    enquiry_instance.save() 
                    messages.success(request, "Enquiry moved to trash successfully.")
            except enquiry.DoesNotExist:
                messages.error(request, "Enquiry not found.")
        idmngmnt = request.session.get('enqobjmngid')
        if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')
        return redirect(f"{reverse('displayenquiry')}?menumanagement_id={idmngmnt}")
        
         
@login_required
def trash_enquiries(request):
    staff_design_id = request.session.get('loginstaffdesign')
    staff_id = request.session.get('loginstaff')
    if not staff_design_id or not staff_id:
            return redirect('staff_login')

        # Get staff branch
    try:
            staff_branch = Staffallocation.objects.get(id=staff_id)
            branch_id = staff_branch.Branch_Name_id
    except Staffallocation.DoesNotExist:
            messages.error(request, "Staff allocation not found.")
            return redirect('staff_login')
    # Get designation
    try:
        designation = Designation.objects.get(id=staff_design_id)
        designation_name = designation.Designation_Name.lower()
    except Designation.DoesNotExist:
        designation_name = ''
    two_weeks_ago = timezone.now() - timedelta(weeks=2)
    # Fetch only soft-deleted enquiries within the past two weeks
    if designation_name != 'superadmin':
        trashed_enquiries = enquiry.objects.filter(deleted=True,branch_id=branch_id, deleted_date__gte=two_weeks_ago)
    else:
        trashed_enquiries = enquiry.objects.filter(deleted=True, deleted_date__gte=two_weeks_ago)
    context = {
        'trashed_enquiries': trashed_enquiries,
    }
    return render(request, "trash.html", context)
@login_required
def restore_enquiry(request, enquiry_id):
    try:
        enquiry_instance = enquiry.objects.get(id=enquiry_id, deleted=True)
        enquiry_instance.deleted = False
        enquiry_instance.deleted_date = None
        enquiry_instance.save()
        messages.success(request, "Enquiry restored successfully.")
    except enquiry.DoesNotExist:
        messages.error(request, "Enquiry not found in trash.")
    return redirect('trash_enquiries')

@login_required
def permanent_delete_enquiry(request, enquiry_id):
    try:
        # Find the enquiry in the trash and delete it permanently
        enquiry_instance = enquiry.objects.get(id=enquiry_id, deleted=True)
        enquiry_instance.delete()  # Permanently deletes the entry from the database
        messages.success(request, "Enquiry permanently deleted.")
    except enquiry.DoesNotExist:
        messages.error(request, "Enquiry not found in trash.")
    return redirect('trash_enquiries')
