        if status == 'Converted':  # If status is closed, set remainderdate to null
            objfl.remainderdate = None
        elif status== 'Dropped':  # If status is closed, set remainderdate to null
            objfl.remainderdate = None
        else:
            objfl.remainderdate = remaindate

        objfl.save()
        if status:
            enq = enquiry.objects.get(id=enqid)
            enq.name=enqname
            enq.age=age
            enq.status = status
            enq.save()
            flw=followupcalldetails()
            flw.callorstatus=enq.callormsg
            flw.status=status
            flw.followedby_id=followedbystaff
            flw.enqid_id=enq.id
            flw.branch=brid
            flw.currentdate=currentdate
            flw.save()
        idmngmnt = request.session.get('follwupobjmngid')
        if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')
