@login_required
def followuptable(request):
    status_order = Case(
        When(enqid__status="Pending", then=Value(1)),
        When(enqid__status="Recontact", then=Value(2)),
        When(enqid__status="Recontact 2", then=Value(3)),
        When(enqid__status="Priority", then=Value(4)),
        When(enqid__status="Converted", then=Value(5)),
        When(enqid__status="Dropped", then=Value(6)),
        output_field=IntegerField()
        )
    stdesign= request.session['loginstaffdesign']
    fltb=followup.objects.all().order_by(status_order, 'remainderdate')
    context={
        'fltb':fltb,
        'stdesign':stdesign,
    }
    return render(request,"followuptable.html",context)

import calendar   
# Helper function to get bookings for a specific room and month
def get_bookings_for_room(room, month_only):
    # Get all bookings for the room with status=1 and non-null admitted dates
    bookings = Patientadmission.objects.filter(Roomno_id=room.id, status=1).exclude(Admitted_Date__isnull=True)
    
    # Filter bookings where the month of Booking_Date or Bookingend_Date matches the selected month
    bookings_for_month = []
    for booking in bookings:
        booking_date = datetime.strptime(booking.Booking_Date, '%Y-%m-%d')
        booking_end_date = datetime.strptime(booking.Bookingend_Date, '%Y-%m-%d')
        
        if booking_date.month == int(month_only) or booking_end_date.month == int(month_only):
            bookings_for_month.append(booking)
    
    # Sort the bookings by Booking_Date
    bookings_for_month.sort(key=lambda x: datetime.strptime(x.Booking_Date, '%Y-%m-%d'))
    return bookings_for_month

