@login_required
def physicaltable(request):
    
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Menu Management ID not provided. Please contact the admin to grant you the necessary menu permissions.")
        return redirect('error_page')

    staff_design_id = request.session.get('loginstaffdesign')
    staff_id = request.session.get('loginstaff')

    if not staff_design_id or not staff_id:
        return redirect('staff_login')

    # Get staff branch
    try:
        staff_branch = Staffallocation.objects.get(id=staff_id)
        branch_id = staff_branch.Branch_Name_id
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff allocation not found.")
        return redirect('staff_login')

    # Get designation
    try:
        designation = Designation.objects.get(id=staff_design_id)
        designation_name = designation.Designation_Name.strip().lower()
    except Designation.DoesNotExist:
        designation_name = ''

    # Fetch reference data
    stornm = storedetails.objects.all()
    un = unitdt.objects.all()
    itmdt = medicinemaster.objects.all()
    reorderlevel = reorderleveldetails.objects.all()
    stdesign = request.session['loginstaffdesign']

    # Filter physical stock details
    if designation_name == 'superadmin':
        physical_stock_details = Physicalstockdetails.objects.filter(deleted=False).order_by('itemnm__itemnm')
    else:
        physical_stock_details = Physicalstockdetails.objects.filter(
            deleted=False,
            stockbranch_id=branch_id  # Assuming this is the correct field
        ).order_by('itemnm__itemnm')

    # Calculate reorder levels
    reorder_levels = {
        (r.itemname_id, r.companyid_id): int(r.qty)
        for r in reorderlevel
    }

    # Prepare stock status
    stock_with_status = []
    for stock_detail in physical_stock_details:
        stock_qty = int(stock_detail.qty)
        key = (stock_detail.itemnm_id, stock_detail.Comapany_name_id)
        reorder_qty = reorder_levels.get(key, 0)
        is_out_of_stock = stock_qty == 0
        is_low_stock = 0 < stock_qty < reorder_qty
        stock_with_status.append((stock_detail, is_low_stock, is_out_of_stock))

    context = {
        'stornm': stornm,
        'un': un,
        'itmdt': itmdt,
        'reorderlevel': reorderlevel,
        'stdesign': stdesign,
        'physt': physical_stock_details,
        'stock_with_status': stock_with_status,
        'storeadd': request.session.get('storeobjmngadd'),
        'storeview': request.session.get('storeobjmngview'),
        'stckmgmntdelete': request.session.get('stockobjdelete'),
        'idmngmnt': idmngmnt
    }
    return render(request, "physicalstocktable.html", context)

