@login_required
def medicinemasterdt(request):
    try:
        if request.method == 'POST':
            itmcode = request.POST.get('itmcode')
            itmnm = request.POST.get('itmnm')
            # Check if the medicine with the given item name already exists
            if medicinemaster.objects.filter(itemnm=itmnm).exists():
                # Prepare the alert message
                alert_message = f"This medicine '{itmnm}' is already in the list."
                # Render the alert message as JavaScript code
                return render(request, 'alert_script.html', {'alert_message': alert_message})
            genericname = request.POST.get('genericname')
            bsunt = request.POST.get('bsunt')
            sbcat = request.POST.get('sbcategory')
            rackno = request.POST.get('rackno')
            sideeffect = request.POST.get('sideeffect')
            hsn = request.POST.get('hsn')
            taxpg = request.POST.get('taxpg')
            
            # Create and save the new medicine entry
            objmdms = medicinemaster(
                itemcode=itmcode,
                itemnm=itmnm,
                Generic_name=genericname,
                bsuntid_id=bsunt,
                Subcategory_name_id=sbcat,
                racknumber=rackno,
                Sideeffect=sideeffect,
                hsncode=hsn,
                taxpercentage_id=taxpg
            )
            objmdms.save()
            # return redirect('medicinemasterdt')
        stornm = storedetails.objects.all()
        objcompanymastertable = Comapany.objects.all()
        un = baseunit.objects.all()
        tx=Taxmaster.objects.all()
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
                return redirect('error_page')
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
                return redirect('staff_login')
        subcategoryobj = ItemSubcategory.objects.all()
        context = {
             'tx':tx,
            'idmngmnt':idmngmnt,
            'subcategoryobj': subcategoryobj,
            'stdesign': stdesign,
            'stornm': stornm,
            'un': un,
            'objcompanymastertable': objcompanymastertable
        }
        # Fetching menu management details
        try:
            idmngmnt = request.GET.get('menumanagement_id')
            if not idmngmnt:
                    messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
                    return redirect('error_page')
            stdesign = request.session.get('loginstaffdesign')
            if not stdesign:
                    return redirect('staff_login')
            if idmngmnt:
                mangmntobj = get_object_or_404(menumanagement, id=idmngmnt)
                request.session['medmngid'] = idmngmnt
                request.session['medmngadd'] = mangmntobj.add
                request.session['medmngview'] = mangmntobj.view
                request.session['medmngedit'] = mangmntobj.edit
                request.session['medmngdelete'] = mangmntobj.delete
                context.update({
                    'idmngmnt': idmngmnt,
                    'medmngview': mangmntobj.view,
                    'medmngadd': mangmntobj.add,
                    'medmngedit': mangmntobj.edit,
                    'medmngdelete': mangmntobj.delete,
                })
        except Exception as e: 
            messages.error(request,"Contact admin to allow the role to you. ")
            return redirect('error_page')
        return render(request, "medicinemaster.html", context)
    except Exception as e:
        # Log the exception (you might want to use logging)
        print(f"An error occurred:{e}")
        # Render an error page or return an appropriate response
        return render(request, 'error_page.html',{'error_message': 'An unexpected error occurred. Please try again later.'})

