            print("Excel Data Loaded:", excel_data.head())  # Debugging

            for index, row in excel_data.iterrows():
                company_name = row.get('Company_name')

                if company_name:
                    print(f"Processing: {company_name}")  # Debug

                    if not Comapany.objects.filter(Comapany_name=company_name).exists():
                        Comapany.objects.create(Comapany_name=company_name)
                        print(f"Inserted: {company_name}")  # Debug
