def insert_medicinemaster_data(request):
    if request.method == 'POST':
        excel_file = request.FILES.get('excel_file')

        if not excel_file or not excel_file.name.endswith('.xlsx'):
            return HttpResponse('Please upload a valid Excel file.')

        try:
            excel_data = pd.read_excel(excel_file)

            inserted_medicines = []  # Store inserted medicine names
            failed_medicines = []  # Store failed medicine names

            for index, row in excel_data.iterrows():
                try:
                    base_unit_value = str(row['BaseUnit']).strip()  # Remove spaces
                    baseunit_instance = baseunit.objects.get(unit__iexact=base_unit_value)  # Case-insensitive match

                    medicine_instance = medicinemaster(
                        itemnm=row['Medicine'],
                        bsuntid=baseunit_instance,
                        taxpercentage=None  # Adjust as needed
                    )
                    medicine_instance.save()
                    inserted_medicines.append(row['Medicine'])

                except baseunit.DoesNotExist:
                    failed_medicines.append(row['Medicine'])
                    continue  # Skip this row and continue

            # Prepare response message
            message = "Data inserted successfully!<br>"
            if inserted_medicines:
                message += "<b>Inserted Medicines:</b><br> - " + "<br> - ".join(inserted_medicines) + "<br>"
            if failed_medicines:
                message += "<b>Failed Medicines (Base Unit Not Found):</b><br> - " + "<br> - ".join(failed_medicines)

            return HttpResponse(message)

        except Exception as e:
            return HttpResponse(f'Error occurred: {str(e)}')

    return render(request, 'upload_excel.html')
