import datetime
def parse_date(date_str):
    formats = ['%Y-%m-%d', '%d/%m/%Y']  # Add more formats if needed
    for format_str in formats:
        try:
            return datetime.datetime.strptime(date_str, format_str).date()
        except ValueError:
            pass
    return None

def insert_item_data(request):
    if request.method == 'POST':
        excel_file = request.FILES.get('excel_file')
        if excel_file and excel_file.name.endswith('.xlsx'):
            try:
                default_category_name = 'Default Category'  # Define your default category name
                default_category_instance, _ = ItemCategory.objects.get_or_create(Category_name=default_category_name)
            
                excel_data = pd.read_excel(excel_file)
                for index, row in excel_data.iterrows():
                    c = str(row['Company_name']).strip().lower()
                    company_instance = Comapany.objects.get(Comapany_name=c)

                    medname = str(row['Medicinename']).strip().lower()
                    med_instance = medicinemaster.objects.get(itemnm=medname)
                    dm = str(row['Subcategory_name']).strip().lower()
                    subcategory_instance, _ = ItemSubcategory.objects.get_or_create(
                    Category_name=default_category_instance, 
                    Subcategory_name=dm
                    )
                    # dm = str(row['Subcategory_name']).strip().lower()
                    # subcategory_instance = ItemSubcategory.objects.get(Subcategory_name=dm)
                    # sbcat = subcategory_instance.id
                     # Parse manufacturer date if available
                    manufacturer_date_str = str(row.get('Manufacture_date', '')).strip().split()[0]
                    manufacturer_date = parse_date(manufacturer_date_str) if manufacturer_date_str else None
                    expiry_date_str = str(row.get('Expiry_date', '')).strip().split()[0]
                    expiry_date = parse_date(expiry_date_str) if expiry_date_str else None
                    item_instance = Itemaster(
                        Purchase_Invoice_no=row['Purchase_Invoice_no'],
                        Medicinename=med_instance,
                        Generic_name=row['Generic_name'],
                        Comapany_name=company_instance,
                        Subcategory_name=subcategory_instance,
                        Manufacturer_date=manufacturer_date,
                        Expiry_date=expiry_date,
                        Sideeffect=row['Sideeffect'],
                        Quantity=row['Quantity'],
                        Batch_no=row['Batch_no'],
                        Rate=row['Rate'],
                        Suppliername=row['Suppliername'],
                        racknumber=row['Rack_number']
                    )
                    item_instance.save()
                    
                return HttpResponse('Data inserted successfully!')
            except pd.errors.EmptyDataError:
                return HttpResponse('Error: The uploaded file is empty.')
            except KeyError as e:
                return HttpResponse(f'Error: Missing column - {e}')
            except Comapany.DoesNotExist:
                return HttpResponse(f'Error: Company not found.')
            except ItemSubcategory.DoesNotExist:
                return HttpResponse(f'Error: Subcategory not found.')
            except Exception as e:
                return HttpResponse(f'Error occurred: {str(e)}')
        else:
            return HttpResponse('Please upload a valid Excel file (with .xlsx extension).')
    else:
        return render(request, 'upload_excel.html')
    
    
import pandas as pd

def insert_stock_data(request):
    if request.method == 'POST':
        excel_file = request.FILES.get('excel_file')
        
        if excel_file and excel_file.name.endswith('.xlsx'):
            try:
                default_category_name = 'Default Category'
                default_category_instance, _ = ItemCategory.objects.get_or_create(Category_name=default_category_name)

                excel_data = pd.read_excel(excel_file)

                for index, row in excel_data.iterrows():
                    batch = str(row['Batch_no']).strip().lower()

                    # Handle Company
                    company_name = str(row.get('Company_name', '')).strip()
                    company_instance, _ = Comapany.objects.get_or_create(Comapany_name=company_name) if company_name and company_name != "nan" else (None, None)

                    # Handle Unit (Fetch unitdt first, then get related baseunit)
                    try:
                        unit_instance = unitdt.objects.get(unitname=str(row['unit']).strip().lower())  
                        baseunitinstance = unit_instance.bsuntid  # Get the corresponding baseunit
                    except ObjectDoesNotExist:
                        return HttpResponse(f'Error: Unit "{row["unit"]}" not found.')

                    # Handle Medicine with different base units
                    try:
                        med_instance = medicinemaster.objects.get(
                            itemnm=str(row['Medicinename']).strip().lower(), 
                            bsuntid=baseunitinstance  # Pass baseunit, not unitdt
                        )
                    except ObjectDoesNotExist:
                        return HttpResponse(f'Error: Medicine "{row["Medicinename"]}" with unit "{row["unit"]}" not found.')

                    # Handle Supplier
                    supp_name = str(row.get('Suppliername', '')).strip()
                    supp_instance, _ = supplier.objects.get_or_create(shopname=supp_name) if supp_name and supp_name != "nan" else (None, None)

                    # Handle Dates
                    manufacturer_date = pd.to_datetime(row.get('Manufacture_date', None))
                    expiry_date = pd.to_datetime(row.get('Expiry_date', None))

                    manufacturer_date = manufacturer_date.date() if not pd.isna(manufacturer_date) else None
                    expiry_date = expiry_date.date() if not pd.isna(expiry_date) else None

                    # Prevent duplicate stock entry
                    if not Physicalstockdetails.objects.filter(
                        itemnm=med_instance, Batch_no=batch, unt=unit_instance  # ✅ Corrected here
                    ).exists():
                        item_instance = Physicalstockdetails(
                            storenm=storedetails.objects.get(id=1),  # Assuming store ID = 1
                            itemnm=med_instance,
                            Comapany_name=company_instance,
                            Manufacturer_date=manufacturer_date,
                            Expiry_date=expiry_date,
                            qty=row['Quantity'],
                            Batch_no=batch,
                            Rate=row['Rate'],
                            suppliernm=supp_instance,
                            unt=unit_instance,  # ✅ Corrected here, using unitdt instead of baseunit
                            insertedstaffid=Staffdetails.objects.get(id=1),  # Assuming default staff ID = 1
                        )
                        item_instance.save()
                    else:
                        return HttpResponse(f'Duplicate entry for Medicine "{row["Medicinename"]}" with batch "{batch}" and unit "{row["unit"]}".')

                return HttpResponse('Data inserted successfully!')
            
            except pd.errors.EmptyDataError:
                return HttpResponse('Error: The uploaded file is empty.')
            except KeyError as e:
                return HttpResponse(f'Error: Missing column - {e}')
            except Exception as e:
                return HttpResponse(f'Error occurred: {str(e)}')
        else:
            return HttpResponse('Please upload a valid Excel file (with .xlsx extension).')
    
    return render(request, 'upload_excel.html')
@login_required
def storestockentry(request):
    stdesign = request.session.get('loginstaffdesign')
    stff = request.session.get('staffid')

    if not stdesign or not stff:
        return redirect('staff_login')

    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Menu Management ID not provided. Please contact the admin.")
        return redirect('error_page')

    # Get staff's branch
    try:
        staff_alloc = Staffallocation.objects.get(Staff_id=stff)
        staff_branch = staff_alloc.Branch_Name
        staff_branch_id = staff_alloc.Branch_Name.id
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff branch allocation not found.")
        return redirect('error_page')

    if request.method == 'POST':
        try:
            # ✅ Get the list of all rows from the form
            stores = request.POST.getlist('store[]')
            suppliers = request.POST.getlist('spname[]')
            companies = request.POST.getlist('mdcompany[]')
            items = request.POST.getlist('item[]')
            units = request.POST.getlist('bsunty[]')
            batches = request.POST.getlist('btchno[]')
            mfg_dates = request.POST.getlist('mdate[]')
            expiry_dates = request.POST.getlist('edate[]')
            purchase_rates = request.POST.getlist('purchase_rate[]')
            wholesale_rates = request.POST.getlist('wholesale_rate[]')
            retail_rates = request.POST.getlist('retail_rate[]')
            quantities = request.POST.getlist('qnty[]')

            # ✅ Helper function to safely get values
            def get_value(list_obj, index, default=''):
                try:
                    return list_obj[index] if index < len(list_obj) else default
                except (IndexError, TypeError):
                    return default

            # ✅ Determine the maximum length to find total rows
            max_rows = max(
                len(stores), len(suppliers), len(companies), len(items),
                len(units), len(batches), len(mfg_dates), len(expiry_dates),
                len(purchase_rates), len(wholesale_rates), len(retail_rates),
                len(quantities)
            )

            # ✅ Process each row
            for i in range(max_rows):
                try:
                    # ✅ Safely get values
                    storedt = get_value(stores, i)
                    spname = get_value(suppliers, i)
                    mdcompany = get_value(companies, i)
                    medname_id = get_value(items, i)
                    bsunty = get_value(units, i)
                    btchno = get_value(batches, i)
                    mdate = get_value(mfg_dates, i)
                    edate = get_value(expiry_dates, i)
                    purchase_rate_str = get_value(purchase_rates, i)
                    wholesale_rate_str = get_value(wholesale_rates, i)
                    retail_rate_str = get_value(retail_rates, i)
                    qty_str = get_value(quantities, i)

                    # ✅ Skip empty rows (where no item is selected)
                    if not medname_id or medname_id == '':
                        continue

                    # ✅ Validate required fields
                    if not storedt or storedt == '':
                        messages.error(request, f"Row {i+1}: Store is required.")
                        continue
                    if not spname or spname == '':
                        messages.error(request, f"Row {i+1}: Supplier is required.")
                        continue
                    if not mdcompany or mdcompany == '':
                        messages.error(request, f"Row {i+1}: Company is required.")
                        continue
                    if not medname_id or medname_id == '':
                        messages.error(request, f"Row {i+1}: Item/Medicine is required.")
                        continue
                    if not bsunty or bsunty == '':
                        messages.error(request, f"Row {i+1}: Unit is required.")
                        continue
                    if not btchno or btchno == '':
                        messages.error(request, f"Row {i+1}: Batch number is required.")
                        continue
                    if not edate or edate == '':
                        messages.error(request, f"Row {i+1}: Expiry date is required.")
                        continue

                    # ✅ Convert IDs to integers
                    try:
                        medname_id = int(medname_id)
                    except (ValueError, TypeError):
                        messages.error(request, f"Row {i+1}: Invalid item ID.")
                        continue

                    try:
                        storedt = int(storedt)
                    except (ValueError, TypeError):
                        messages.error(request, f"Row {i+1}: Invalid store ID.")
                        continue

                    try:
                        spname = int(spname)
                    except (ValueError, TypeError):
                        messages.error(request, f"Row {i+1}: Invalid supplier ID.")
                        continue

                    try:
                        mdcompany = int(mdcompany)
                    except (ValueError, TypeError):
                        messages.error(request, f"Row {i+1}: Invalid company ID.")
                        continue

                    try:
                        bsunty = int(bsunty) if bsunty else None
                    except (ValueError, TypeError):
                        bsunty = None

                    # ✅ Convert rates
                    purchase_rate = 0.0
                    wholesale_rate = 0.0
                    retail_rate = 0.0
                    
                    try:
                        if purchase_rate_str and purchase_rate_str != '':
                            purchase_rate = round(float(purchase_rate_str), 2)
                    except (ValueError, TypeError):
                        purchase_rate = 0.0
                        
                    try:
                        if wholesale_rate_str and wholesale_rate_str != '':
                            wholesale_rate = round(float(wholesale_rate_str), 2)
                    except (ValueError, TypeError):
                        wholesale_rate = 0.0
                        
                    try:
                        if retail_rate_str and retail_rate_str != '':
                            retail_rate = round(float(retail_rate_str), 2)
                    except (ValueError, TypeError):
                        retail_rate = 0.0

                    # ✅ Convert quantity
                    try:
                        qnty = int(qty_str) if qty_str and qty_str != '' else 0
                    except (ValueError, TypeError):
                        qnty = 0

                    if qnty <= 0:
                        messages.error(request, f"Row {i+1}: Quantity must be greater than 0.")
                        continue

                    lastupdate = timezone.now().date()

                    # ✅ Convert expiry date from "YYYY-MM" to first day of that month
                    try:
                        expiry_date_obj = datetime.strptime(edate, '%Y-%m').date()
                    except ValueError:
                        messages.error(request, f"Row {i+1}: Invalid expiry date format. Please use YYYY-MM.")
                        continue

                    # ✅ Convert mfg date if provided
                    mfg_date_obj = None
                    if mdate and mdate != '':
                        try:
                            mfg_date_obj = datetime.strptime(mdate, '%Y-%m').date()
                        except ValueError:
                            try:
                                mfg_date_obj = datetime.strptime(mdate, '%Y-%m-%d').date()
                            except ValueError:
                                messages.warning(request, f"Row {i+1}: Invalid manufacturing date format. Skipping.")
                                mfg_date_obj = None

                    # ✅ Validate rates
                    staff_branch_ids_allowed = [10, 30, 31]
                    if staff_branch_id in staff_branch_ids_allowed:
                        if purchase_rate <= 0:
                            messages.error(request, f"Row {i+1}: Purchase rate must be greater than 0")
                            continue
                        if wholesale_rate <= 0:
                            messages.error(request, f"Row {i+1}: Wholesale rate must be greater than 0")
                            continue
                        if wholesale_rate < purchase_rate:
                            messages.warning(request, f"Row {i+1}: Wholesale rate is less than purchase rate!")
                        if retail_rate < wholesale_rate:
                            messages.warning(request, f"Row {i+1}: Retail rate is less than wholesale rate!")
                    else:
                        if retail_rate <= 0:
                            messages.error(request, f"Row {i+1}: Retail rate must be greater than 0")
                            continue
                        if purchase_rate == 0 and wholesale_rate == 0:
                            wholesale_rate = retail_rate
                            purchase_rate = 0

                    # ✅ Calculate base values
                    # base_quantity = qty * (1 unit) - you can adjust based on your unit conversion
                    base_quantity = qnty  # Assuming 1 unit = 1 base unit
                    base_rate = purchase_rate if purchase_rate > 0 else retail_rate
                    total_base_quantity = base_quantity * base_rate

                    # ✅ Check if identical stock already exists (excluding soft-deleted)
                    try:
                        stock_item = Physicalstockdetails.objects.filter(
                            itemnm_id=medname_id,
                            Batch_no=btchno,
                            Comapany_name_id=mdcompany,
                            Expiry_date=expiry_date_obj,
                            unt_id=bsunty,
                            suppliernm_id=spname,
                            stockbranch=staff_branch,
                            deleted=False  # ✅ Only check active stock
                        ).first()

                        if stock_item:
                            old_qty = stock_item.qty
                            
                            # ✅ Update existing stock
                            stock_item.qty = (stock_item.qty or 0) + qnty
                            stock_item.lastupdatedate = lastupdate
                            stock_item.insertedstaffid_id = stff
                            stock_item.purchase_rate = purchase_rate
                            stock_item.wholesale_rate = wholesale_rate
                            stock_item.Rate = str(retail_rate)  # Store as string
                            
                            # ✅ Update base values
                            stock_item.base_quantity = base_quantity
                            stock_item.base_rate = base_rate
                            stock_item.total_base_quantity = total_base_quantity
                            
                            stock_item.save()
                            
                            # ✅ Create audit log for update
                            StockAuditLog.objects.create(
                                stock=stock_item,
                                action="UPDATE",
                                staff=Staffdetails.objects.get(id=stff),
                                branch=staff_branch,
                                store=storedetails.objects.get(id=storedt),
                                item=medicinemaster.objects.get(id=medname_id),
                                qty=qnty,
                                action_date=timezone.now().date(),
                                action_time=timezone.now().time(),
                            )
                            
                            messages.success(request, f"Row {i+1}: Stock quantity updated successfully from {old_qty} to {stock_item.qty}.")
                        else:
                            # ✅ Create new stock entry
                            new_stock = Physicalstockdetails.objects.create(
                                storenm_id=storedt,
                                itemnm_id=medname_id,
                                unt_id=bsunty,
                                suppliernm_id=spname,
                                Comapany_name_id=mdcompany,
                                Manufacturer_date=mfg_date_obj,
                                Expiry_date=expiry_date_obj,
                                Batch_no=btchno,
                                Rate=str(retail_rate),  # Store as string
                                purchase_rate=purchase_rate,
                                wholesale_rate=wholesale_rate,
                                qty=qnty,
                                lastupdatedate=lastupdate,
                                insertedstaffid_id=stff,
                                stockbranch=staff_branch,
                                base_rate=base_rate,
                                deleted=False
                            )
                            
                            # ✅ Create audit log for new stock
                            StockAuditLog.objects.create(
                                stock=new_stock,
                                action="CREATE",
                                staff=Staffdetails.objects.get(id=stff),
                                branch=staff_branch,
                                store=storedetails.objects.get(id=storedt),
                                item=medicinemaster.objects.get(id=medname_id),
                                qty=qnty,
                                action_date=timezone.now().date(),
                                action_time=timezone.now().time(),
                            )
                            
                            messages.success(request, f"Row {i+1}: New stock entry created successfully.")

                    except Physicalstockdetails.DoesNotExist:
                        # ✅ Create new stock entry (fallback)
                        new_stock = Physicalstockdetails.objects.create(
                            storenm_id=storedt,
                            itemnm_id=medname_id,
                            unt_id=bsunty,
                            suppliernm_id=spname,
                            Comapany_name_id=mdcompany,
                            Manufacturer_date=mfg_date_obj,
                            Expiry_date=expiry_date_obj,
                            Batch_no=btchno,
                            Rate=str(retail_rate),
                            purchase_rate=purchase_rate,
                            wholesale_rate=wholesale_rate,
                            qty=qnty,
                            lastupdatedate=lastupdate,
                            insertedstaffid_id=stff,
                            stockbranch=staff_branch,
                            base_rate=base_rate,
                            deleted=False
                        )
                        
                        # ✅ Create audit log
                        StockAuditLog.objects.create(
                            stock=new_stock,
                            action="CREATE",
                            staff=Staffdetails.objects.get(id=stff),
                            branch=staff_branch,
                            store=storedetails.objects.get(id=storedt),
                            item=medicinemaster.objects.get(id=medname_id),
                            qty=qnty,
                            action_date=timezone.now().date(),
                            action_time=timezone.now().time(),
                        )
                        
                        messages.success(request, f"Row {i+1}: New stock entry created successfully.")

                    except Exception as e:
                        messages.error(request, f"Row {i+1}: Error saving stock - {str(e)}")
                        continue

                except Exception as e:
                    messages.error(request, f"Row {i+1}: Error processing - {str(e)}")
                    continue

            return redirect(f"{reverse('storestockentry')}?menumanagement_id={idmngmnt}")

        except Exception as e:
            messages.error(request, f"Error processing stock entries: {str(e)}")
            return redirect(f"{reverse('storestockentry')}?menumanagement_id={idmngmnt}")

    # GET request – load stock entry form
    try:
        stockobj = get_object_or_404(menumanagement, id=idmngmnt)
        request.session['stockobjid'] = idmngmnt
        request.session['stockobjadd'] = stockobj.add
        request.session['stockobjview'] = stockobj.view
        request.session['stockobjedit'] = stockobj.edit
        request.session['stockobjdelete'] = stockobj.delete
    except Exception as e:
        messages.error(request, f"Error loading menu access: {str(e)}")
        return redirect('error_page')

    context = {
        'unit': unitdt.objects.all(),
        'supplerdt': supplier.objects.all().order_by('shopname'),
        'mdnm': medicinemaster.objects.all().order_by('itemnm'),
        'stornm': storedetails.objects.all(),
        'companym': Comapany.objects.all().order_by('Comapany_name'),
        'stdesign': stdesign,
        'stckmgmntadd': request.session.get('stockobjadd'),
        'stckmgmntview': request.session.get('stockobjview'),
        'stckmgmntdelete': request.session.get('stockobjdelete'),
        'stckmgmntedit': request.session.get('stockobjedit'),
        'idmngmnt': idmngmnt,
        'staff_branch_id': staff_branch_id,
    }

    return render(request, "storestockentry1.html", context)

def delstockdetls(request):
    # 🔐 Session check
    stdesign = request.session.get('loginstaffdesign')
    stff = request.session.get('loginstaff')
    session_staff_id = request.session.get('loginstaff')

    staff_alloc = Staffallocation.objects.get(id=session_staff_id)

    staffdetails_id = staff_alloc.Staff_id   # ✅ correct

    if not stdesign or not stff:
        return redirect('staff_login')

    stock_id = request.GET.get('ids')
    if not stock_id:
        messages.error(request, "Invalid stock ID.")
        return redirect('physicaltable')
    try:
        dep = Physicalstockdetails.objects.get(id=stock_id)
    except Physicalstockdetails.DoesNotExist:
        messages.error(request, "Stock record not found.")
        return redirect('physicaltable')
    # 🧾 Soft delete
    dep.deleted = True
    dep.deleted_date = timezone.now()
    dep.save()
    # 📝 Audit log
    StockAuditLog.objects.create(
        stock=dep,
        action="DELETE",
        # staff_id=stff,
        staff_id=staffdetails_id,
        branch=dep.stockbranch,
        store=dep.storenm,
        item=dep.itemnm,
        qty=dep.qty,
        action_date=timezone.now().date(),
        action_time=datetime.now().time(),
    )
    messages.success(request, "Stock deleted successfully.")
    idmngmnt = request.session.get('stockobjid')
    return redirect(f"{reverse('physicaltable')}?menumanagement_id={idmngmnt}")

    
