from django.utils import timezone
from django.contrib import messages
  # Import the necessary models
from django.urls import reverse


@login_required
def editstock(request):
    stff = request.session.get('staffid')
    stdesign_id = request.session.get('loginstaffdesign')
    if not stff or not stdesign_id:
        messages.error(request, "Session expired. Please log in again.")
        return redirect('staff_login')
    
    # Determine if staff is admin
    try:
        designation = Designation.objects.get(id=stdesign_id)
        is_admin = designation.Designation_Name.lower() == 'admin'
    except Designation.DoesNotExist:
        is_admin = False
    
    # Get staff's branch
    staff_branch = None
    try:
        staff_branch = Staffallocation.objects.get(Staff_id=stff).Branch_Name
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff branch information not found.")
        return redirect('error_page')
    
    if request.method == 'POST':
        try:
            idstock = request.POST.get('stid')
            if not idstock:
                messages.error(request, "Stock ID is missing.")
                return redirect('error_page')
            
            stock_record = get_object_or_404(Physicalstockdetails, id=idstock)
            
            # Non-admins can only edit their own branch
            if not is_admin and stock_record.stockbranch != staff_branch:
                messages.error(request, "Unauthorized: You can only edit stock from your own branch.")
                return redirect('error_page')
            
            # Extract and validate form fields
            medname_id = int(request.POST.get('item'))
            storedt = request.POST.get('store')
            spname = request.POST.get('spname')
            mdcompany = request.POST.get('mdcompany')
            btchno = request.POST.get('btchno')
            rate = round(float(request.POST.get('rate')), 2)
            purchase_rate = round(float(request.POST.get('purchase_rate', 0)), 2) if request.POST.get('purchase_rate') else 0.0
            wholesale_rate = round(float(request.POST.get('wholesale_rate', 0)), 2) if request.POST.get('wholesale_rate') else 0.0
            mdate = request.POST.get('mdate')
            edate = request.POST.get('edate')
            qnty = int(request.POST.get('qnty'))
            bsunty = request.POST.get('bsunty')
            lastupdate = timezone.now().date()
            idmngmnt = request.session.get('stockobjid')
            
            # ✅ Check if identical stock already exists (excluding current record)
            try:
                existing_item = Physicalstockdetails.objects.get(
                    itemnm_id=medname_id,
                    Batch_no=btchno,
                    Comapany_name_id=mdcompany,
                    Manufacturer_date=mdate,
                    Expiry_date=edate,
                    unt_id=bsunty,
                    suppliernm_id=spname,
                    Rate=rate,
                    purchase_rate = purchase_rate,
                    wholesale_rate = wholesale_rate,
                    stockbranch=stock_record.stockbranch,
                    deleted=False  # ✅ Only check non-deleted items
                )
                
                # ✅ If found and it's a DIFFERENT record (not the one being edited)
                if existing_item.id != stock_record.id:
                    # ✅ Update the existing item's quantity
                    quantity_before = existing_item.qty or 0
                    existing_item.qty = (existing_item.qty or 0) + qnty
                    existing_item.lastupdatedate = lastupdate
                    existing_item.insertedstaffid_id = stff
                    existing_item.save()
                    
                    # ✅ Soft delete the edited record
                    stock_record.deleted = True
                    stock_record.deleted_date = timezone.now()
                    stock_record.save()
                    
                    # ✅ Log the action
                    StockEditLogtabl.objects.create(
                        editstaffno_id=stff,
                        item_id=existing_item.id,
                        quantity_before=quantity_before,
                        quantity_after=existing_item.qty,
                        current_date=timezone.now().date()
                    )
                    
                    messages.success(request, f"Stock merged with existing entry. Quantity updated to {existing_item.qty}.")
                    return redirect(f"{reverse('storestockentry')}?menumanagement_id={idmngmnt}")
                else:
                    # ✅ Same record - just update it normally
                    quantity_before = stock_record.qty or 0
                    stock_record.storenm_id = storedt
                    stock_record.itemnm_id = medname_id
                    stock_record.unt_id = bsunty
                    stock_record.qty = qnty
                    stock_record.Batch_no = btchno
                    stock_record.Comapany_name_id = mdcompany
                    stock_record.Manufacturer_date = mdate
                    stock_record.Expiry_date = edate
                    stock_record.Rate = rate
                    stock_record.purchase_rate = purchase_rate
                    stock_record.wholesale_rate = wholesale_rate
                    stock_record.suppliernm_id = spname
                    stock_record.lastupdatedate = lastupdate
                    stock_record.insertedstaffid_id = stff
                    stock_record.save()
                    
                    StockEditLogtabl.objects.create(
                        editstaffno_id=stff,
                        item_id=stock_record.id,
                        quantity_before=quantity_before,
                        quantity_after=stock_record.qty,
                        current_date=timezone.now().date()
                    )
                    
                    messages.success(request, "Stock updated successfully.")
                    return redirect(f"{reverse('storestockentry')}?menumanagement_id={idmngmnt}")
                    
            except Physicalstockdetails.DoesNotExist:
                # ✅ No existing item found - update normally
                quantity_before = stock_record.qty or 0
                stock_record.storenm_id = storedt
                stock_record.itemnm_id = medname_id
                stock_record.unt_id = bsunty
                stock_record.qty = qnty
                stock_record.Batch_no = btchno
                stock_record.Comapany_name_id = mdcompany
                stock_record.Manufacturer_date = mdate
                stock_record.Expiry_date = edate
                stock_record.Rate = rate
                stock_record.purchase_rate = purchase_rate
                stock_record.wholesale_rate = wholesale_rate
                stock_record.suppliernm_id = spname
                stock_record.lastupdatedate = lastupdate
                stock_record.insertedstaffid_id = stff
                stock_record.save()
                
                StockEditLogtabl.objects.create(
                    editstaffno_id=stff,
                    item_id=stock_record.id,
                    quantity_before=quantity_before,
                    quantity_after=stock_record.qty,
                    current_date=timezone.now().date()
                )
                
                messages.success(request, "Stock updated successfully.")
                return redirect(f"{reverse('storestockentry')}?menumanagement_id={idmngmnt}")
                
        except Exception as e:
            messages.error(request, f"An error occurred: {str(e)}")
            return redirect(f"{reverse('storestockentry')}?menumanagement_id={request.session.get('stockobjid', '')}")
    
    else:
        idmngmnt = request.session.get('stockobjid')
        idstock = request.GET.get('ids')
        if not idmngmnt or not idstock:
            messages.error(request, "Required parameters missing.")
            return redirect('error_page')
        
        try:
            objstock = Physicalstockdetails.objects.get(id=idstock)
            if not is_admin and objstock.stockbranch != staff_branch:
                messages.error(request, "Unauthorized access to stock from another branch.")
                return redirect('error_page')
        except Physicalstockdetails.DoesNotExist:
            messages.error(request, "Stock details not found.")
            return redirect('error_page')
        
        context = {
            'idmngmnt': idmngmnt,
            'objstock': objstock,
            'unit': unitdt.objects.all(),
            'supplerdt': supplier.objects.all().order_by('shopname'),
            'mdnm': medicinemaster.objects.all().order_by('itemnm'),
            'stornm': storedetails.objects.all(),
            'companym': Comapany.objects.all().order_by('Comapany_name'),
            'stdesign': stdesign_id,
        }
        return render(request, "editstock.html", context)

