@login_required   
def find_quantity(request):
    if request.method == 'POST':
        # Get the medicine name entered by the user from the POST data
        medicine_master_id = request.GET.get('medicine_master_id')
        itemasters = Itemaster.objects.filter(Medicinename_id=medicine_master_id)
        
        # Serialize the data into JSON format
        data = [{'particulars_id': item.Medicinename_id, 'quantity': item.Quantity} for item in itemasters]
        
        # Return JSON response
        return JsonResponse(data, safe=False) 
