@login_required
def supplierdetails(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')
        spcode=request.POST.get('spcode')
        spname=request.POST.get('spname')
        addrs=request.POST.get('addrs')
        cno=request.POST.get('cno')
        email=request.POST.get('email')
        if supplier.objects.filter(shopname__iexact=spname).exists():
            messages.warning(request, f"Supplier '{spname}' already exists. Please use a different name.")
            return redirect(f"{reverse('supplierdetails')}?menumanagement_id={idmngmnt}")
        
        if spcode and supplier.objects.filter(suppliercode__iexact=spcode).exists():
            messages.warning(request, f"Supplier code '{spcode}' already exists. Please use a different code.")
            return redirect(f"{reverse('supplierdetails')}?menumanagement_id={idmngmnt}")
        try:
            objmdms=supplier()
            objmdms.suppliercode=spcode
            objmdms.shopname=spname
            objmdms.address=addrs
            objmdms.contactnumber=cno
            objmdms.email=email
            objmdms.save()
            messages.success(request, "Supplier Details saved successfully.")
            return redirect(f"{reverse('supplierdetails')}?menumanagement_id={idmngmnt}")
        except Exception as e:
            messages.error(request, f"An error occurred while saving room details: {str(e)}. Please contact the admin.")
            return redirect('error_page')

    else:
        try:
            idmngmnt = request.GET.get('menumanagement_id')
            if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
                return redirect('error_page')
            suppobj = get_object_or_404(menumanagement, id=idmngmnt)
            # Store menu management permissions in session
            request.session['suppobjmngid'] = idmngmnt
            request.session['suppobjmngadd'] = suppobj.add
            request.session['suppobjmngview'] = suppobj.view
            request.session['suppobjmngedit'] = suppobj.edit
            request.session['suppobjmngdelete'] = suppobj.delete
            # Check if user is logged in
            stdesign = request.session.get('loginstaffdesign')
            if not stdesign:
                return redirect('staff_login')
            branchobj = Branch.objects.all()
            context = {
                'branchobj': branchobj,
                'idmngmnt': idmngmnt,
                'stdesign': stdesign,
                'suppadd': request.session.get('suppobjmngadd'),
                'suppview': request.session.get('suppobjmngview'),
            }
            return render(request, "supplier.html", context)
        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')
        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin for assistance.")
            return redirect('error_page')
            return redirect('supplierdetails')
    
