@login_required
def editsupplier(request):
    if request.method == 'POST':
        spcode=request.POST.get('spcode')
        spname=request.POST.get('spname')
        addrs=request.POST.get('addrs')
        cno=request.POST.get('cno')
        email=request.POST.get('email')
        idrm = request.POST.get('id')

        if not idrm:
            messages.error(request, "Supplier ID is missing.")
            return redirect('error_page')

        idmngmnt = request.session.get('suppobjmngid')

        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')
        
        if supplier.objects.filter(shopname__iexact=spname).exclude(id=idrm).exists():
            messages.warning(request, f"Supplier '{spname}' already exists. Please use a different name.")
            return redirect(f"{reverse('editsupplier')}?ids={idrm}")

        # ✅ Check if supplier code already exists (excluding current)
        if spcode and supplier.objects.filter(suppliercode__iexact=spcode).exclude(id=idrm).exists():
            messages.warning(request, f"Supplier code '{spcode}' already exists. Please use a different code.")
            return redirect(f"{reverse('editsupplier')}?ids={idrm}")
        try:
            objmdms=supplier.objects.get(id=idrm)
            objmdms.suppliercode=spcode
            objmdms.shopname=spname
            objmdms.address=addrs
            objmdms.contactnumber=cno
            objmdms.email=email
            objmdms.save()
            messages.success(request, "Supplier Details edited successfully!")
            return redirect(f"{reverse('supplierdetails')}?menumanagement_id={idmngmnt}")
        except ObjectDoesNotExist:
            messages.error(request, "Supplier Details not found.")
        except ValueError:
            messages.error(request, "Invalid Supplier  ID.")
        except Exception as e:
            messages.error(request, f"An error occurred: {str(e)}")
        return redirect(f"{reverse('supplierdetails')}?menumanagement_id={idmngmnt}")
    else:
        idmngmnt = request.session.get('suppobjmngid')
        if not idmngmnt:
            messages.error(request, "Menu Management ID not provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')
        idenq = request.GET.get('ids')
        if not idenq:
            messages.error(request, "Supplier Details ID is missing.")
            return redirect('error_page')
        try:
            objsupp = supplier.objects.get(id=idenq)
        except ObjectDoesNotExist:
            messages.error(request, "Supplier Details not found.")
            return redirect(f"{reverse('supplierdetails')}?menumanagement_id={idmngmnt}")
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')
        context = {
            'idmngmnt': idmngmnt,
            'objsupp': objsupp,
            'stdesign': stdesign,
             'suppview': request.session.get('suppobjmngview'),
            'suppedit': request.session.get('suppobjmngedit'),   
        }
        return render(request, "suppleredit.html", context)
from datetime import datetime
@login_required
def purchaseorderdetails(request):
    if request.method == 'POST':
        
        prchno = request.POST.get('prchno')
        suppliernm_id = request.POST.get('spname')
        suppliercontactnumber = request.POST.get('cno')
        idmngmnt = request.GET.get('menumanagement_id')
        mdate_str = request.POST.get('mdate')
        today=date.today()
        # Parse the string into a datetime object
        mdate_obj = datetime.strptime(mdate_str, '%d-%m-%Y')
        staffid= request.session.get('loginstaff')
        staffbranch=   request.session.get('branchid')
        # Extract the date part
        orderdate = mdate_obj.date()
        purchaseordhdobj=purchaseorderheader.objects.create(
                putrchaseorderno=prchno,
            	orderdate=orderdate,
                suppliernm_id=suppliernm_id,
                preparedby_id=staffid,
              branch_id=staffbranch,
                currentdate=today
        )
        item_code_list = request.POST.getlist('item_code[]')
        unit_list = request.POST.getlist('Unit[]')
        quantity_list = request.POST.getlist('Quantity[]')
        company_list = request.POST.getlist('medcom[]')
        # Iterate over the lists to create purchaseorder instances for each item
        for item_code, unit, quantity,com in zip(item_code_list, unit_list, quantity_list,company_list):
            purchaseorderchild.objects.create(
                putrchaseorderno=prchno,
                suppliernm_id=suppliernm_id,
                suppliercontactnumber=suppliercontactnumber,
                orderdate=orderdate,
                itemname_id=item_code,
                itemunit_id=unit,
                itemquantity=quantity,
                itemcompany_id=com,
                purchaseorderhid_id=purchaseordhdobj.id,
               preparedby_id=staffid,
              branch_id=staffbranch,
                balance=quantity,

                
            )
        
        return redirect(f"{reverse('purchaseorderdetails')}?menumanagement_id={idmngmnt}")
    last_order=purchaseorderheader.objects.order_by('-id').first()
   
    if last_order:
            last_order_number = last_order.id
    else:
            last_order_number = 0
    staffbranch=   request.session.get('branchid')
    new_order_number = last_order_number + 1
    current_date = timezone.now().strftime('%Y%m%d')
    purchaseorderno=current_date+str(new_order_number)
    objsp=supplier.objects.all().order_by('shopname')
    comp=Comapany.objects.all()
    item=medicinemaster.objects.order_by('itemnm')
    unit=baseunit.objects.all()
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')  
    # Get menu management ID from the request
    menu_management_id = request.GET.get('menumanagement_id')
    if menu_management_id:
        try:
            prchobj = get_object_or_404(menumanagement, id=menu_management_id)
            request.session['prchobjadd'] = prchobj.add
            request.session['prchobjview'] = prchobj.view
            request.session['prchobjedit'] = prchobj.edit
            request.session['prchobjdelete'] = prchobj.delete       
        except Exception as e:
            messages.error(request, f'Error retrieving menu management details: {e}')
            return redirect('error_page')  
        # Redirect to an error page or handle as needed
    else:
        messages.error(request, 'Menu management ID is required.')
        return redirect('error_page') 
    prchmgmntadd= request.session.get('prchobjadd')
    prchmgmntview= request.session.get('prchobjview')
    prchmgmntdelete= request.session.get('prchobjdelete')
    prchmgmntedit= request.session.get('prchobjedit')
    context={
        'idmngmnt':menu_management_id,
        'staffbranch':staffbranch,
        'purchaseorderno':purchaseorderno,
        'comp':comp,
        'item':item,
        'unit':unit,
       'objsp':objsp,
       'stdesign':stdesign,
       'prchmgmntadd':prchmgmntadd,
       'prchmgmntview':prchmgmntview,
       'prchmgmntdelete':prchmgmntdelete,
       'prchmgmntedit':prchmgmntedit,
    }
    return render(request,"purchaseorder.html",context)


from django.http import JsonResponse

def purchase_order_items(request):
    if request.method == 'GET':
        purchase_order_number = request.GET.get('purchase_order_number')

        if purchase_order_number:
            items_queryset = purchaseorderchild.objects.filter(
                purchaseorderhid_id=purchase_order_number
            )

            if items_queryset.exists():
                first_item = items_queryset.first()

                supplier_contact_number = first_item.suppliernm_id
                supplier_shop_name = first_item.suppliernm.shopname

                # ✅ ITEMS
                items_data = [{
                    'itemid': item.itemname_id,
                    'unitid': item.itemunit_id,
                    'itemname': item.itemname.itemnm,
                    'itemunit': item.itemunit.unitname,
                    'itemquantity': item.itemquantity,
                    'comid': item.itemcompany_id,
                    'comname': item.itemcompany.Comapany_name,
                    'balance': item.balance,
                    'prhid': item.purchaseorderhid_id
                } for item in items_queryset]

                # ✅ ADD STORES
                stores = list(storedetails.objects.values('id', 'storename'))

                return JsonResponse({
                    'supplier_contact_number': supplier_contact_number,
                    'shop_name': supplier_shop_name,
                    'items': items_data,
                    'stores': stores   # 👈 IMPORTANT
                })

            else:
                return JsonResponse({'error': 'No items found for the given purchase order number'})
        else:
            return JsonResponse({'error': 'Invalid purchase order number'})
    else:
        return JsonResponse({'error': 'Invalid request'})


def grn_details(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')
        try:
            grn_no = request.POST.get('grnno')
            grn_date = request.POST.get('mdate')
            purchase_order_number = request.POST.get('prchno')
            supplier_id = request.POST.get('supid')
            order_status = request.POST.get('order_status')
            prepared_by_id = request.session.get('loginstaff')
            staffid= request.session.get('staffid')
            branch_id = request.session.get('branchid')
            current_date = date.today()
            
            # Initialize variables for items received in the form
            items = request.POST.getlist('itemid[]')
            quantities = request.POST.getlist('quantity[]')
            companies = request.POST.getlist('compid[]')
            units = request.POST.getlist('unitid[]')
            mdates = request.POST.getlist('mndate[]')
            edates = request.POST.getlist('exdate[]')
            batchnos = request.POST.getlist('batchno[]')
            rates = request.POST.getlist('rate[]')
            purchase_rates = request.POST.getlist('purchase_rate[]')     
            store_ids = request.POST.getlist('store[]')  # 👈 GET STORE VALUES AS LIST
            
            # Save GRN Header
            grn_header = grnheader.objects.create(
                grnno=grn_no,
                grndate=grn_date if grn_date else None,
                prchaseorderno=purchase_order_number,
                suppliernm_id=supplier_id,
                currentdate=current_date,
                preparedby_id=prepared_by_id,
                branch_id=branch_id,
                purchaseorderhid_id=purchase_order_number
            )
            
            # Save GRN Child items and update Purchase Order Child balance
            length = min(len(items), len(quantities), len(purchase_rates), len(store_ids))
            
            # Debug print to check values
            print(f"Items: {items}")
            print(f"Quantities: {quantities}")
            print(f"Store IDs: {store_ids}")
            
            for idx in range(length):
                item = items[idx] if idx < len(items) else None
                qty = quantities[idx] if idx < len(quantities) else 0
                comp = companies[idx] if idx < len(companies) else None
                unit = units[idx] if idx < len(units) else None
                mdate = mdates[idx] if idx < len(mdates) else None
                edate = edates[idx] if idx < len(edates) else None
                batch = batchnos[idx] if idx < len(batchnos) else None
                rate = rates[idx] if idx < len(rates) else 0
                prate = purchase_rates[idx] if idx < len(purchase_rates) else 0
                store_id = store_ids[idx] if idx < len(store_ids) else None  # 👈 GET EACH STORE ID
                
                if item and qty:
                    received_qty = int(qty) if qty else 0
                    
                    mdate_obj = datetime.strptime(mdate, '%Y-%m-%d').date() if mdate else None
                    edate_obj = datetime.strptime(edate, '%Y-%m-%d').date() if edate else None
                    
                    rate_val = float(rate) if rate else 0
                    purchase_rate_val = float(prate) if prate else 0
                    
                    # INSERT GRN CHILD
                    grn_child = grnchild.objects.create(
                        grnhid=grn_header,
                        suppliernm_id=supplier_id,
                        orderdate=current_date,
                        itemname_id=item,
                        itemunit_id=unit,
                        grnnumber=grn_no,
                        purchaseorderitemqty=qty,
                        receivedqty=received_qty,
                        mdate=mdate_obj,
                        exdate=edate_obj,
                        itemcompany_id=comp,
                        batchno=batch,
                        rate=rate_val,
                        purchase_rate=purchase_rate_val,
                        close=True if order_status == 'Closed' else False,
                        preparedby_id=prepared_by_id,
                        branch_id=branch_id
                    )
                    
                    # Update or create Physicalstockdetails
                    physical_stock_filter = Physicalstockdetails.objects.filter(
                        storenm_id=store_id, 
                        stockbranch_id=branch_id,
                        itemnm_id=item,
                        Batch_no=batch,
                        Expiry_date=edate_obj,
                        Manufacturer_date=mdate_obj,
                        unt_id=unit,
                        Rate=rate_val,
                        suppliernm_id=supplier_id,
                        Comapany_name_id=comp
                    )
                    
                    if physical_stock_filter.exists():
                        physical_stock_detail = physical_stock_filter.first()
                        physical_stock_detail.purchase_rate = purchase_rate_val
                        physical_stock_detail.qty = int(physical_stock_detail.qty) + received_qty
                        physical_stock_detail.insertedstaffid_id =staffid
                        
                        physical_stock_detail.save()
                    else:
                        Physicalstockdetails.objects.create(
                            storenm_id=store_id,
                            stockbranch_id=branch_id,
                            itemnm_id=item,
                            Batch_no=batch,
                            Expiry_date=edate_obj,
                            Manufacturer_date=mdate_obj,
                            unt_id=unit,
                            Rate=rate_val,
                            purchase_rate=purchase_rate_val,
                            suppliernm_id=supplier_id,
                            Comapany_name_id=comp,
                            insertedstaffid_id=staffid,
                            qty=received_qty
                        )
                    
                    # Update Purchase Order Child balance
                    purchase_order_child = purchaseorderchild.objects.get(
                        purchaseorderhid_id=purchase_order_number,
                        itemname_id=item
                    )
                    
                    current_balance = int(purchase_order_child.balance)
                    new_balance = current_balance - received_qty
                    
                    if new_balance < 0:
                        extra_qty = abs(new_balance)
                        new_balance = 0
                        purchase_order_child.extraqty = str(int(purchase_order_child.extraqty) + extra_qty)
                    
                    purchase_order_child.balance = str(new_balance)
                    purchase_order_child.save()
            
            # Update Purchase Order Header status if needed
            if order_status == 'Closed':
                purchase_order_header = purchaseorderheader.objects.get(putrchaseorderno=purchase_order_number)
                purchase_order_header.purchaseorderclose = True
                purchase_order_header.save()
            messages.success(request, "GRN Saved Successfully ✅")
            return redirect(f"{reverse('grndetails')}?menumanagement_id={idmngmnt}")
            
        except ValueError as e:
            return JsonResponse({'error': str(e)}, status=400)
        except IndexError:
            return JsonResponse({'error': 'Index out of range error'}, status=400)
    else:
        idmngmnt = request.GET.get('menumanagement_id')
        stores = storedetails.objects.all()
        unique_purchase_orders = purchaseorderheader.objects.all()
        
        return render(request, 'purchaseorder.html', {
            'stores': stores,
            'unique_purchase_orders': unique_purchase_orders,
            'idmngmnt': idmngmnt,
            'inv_id': "AUTO",
            'grnadd': '1'
        })
   
