def get_units(request):
    if request.method == 'GET':
        item_id = request.GET.get('item_id')  # Get the selected item ID from the request

        # Query the medicinemaster model to get the item based on the provided ID
        try:
            item = medicinemaster.objects.get(pk=item_id)
        except medicinemaster.DoesNotExist:
            return JsonResponse({'error': 'Item not found'}, status=404)

        # Retrieve the associated units for the item
        units = unitdt.objects.filter(bsuntid=item.bsuntid)

        # Prepare the units data to be sent in JSON format
        units_data = [{'id': unit.id, 'unitname': unit.unitname,'basequantity':unit.basequantity} for unit in units]

        return JsonResponse(units_data, safe=False)  # Return JSON response with units data
    else:
        return JsonResponse({'error': 'Method not allowed'}, status=405)

