def fetch_name_by_id(request):
    selected_id = request.GET.get('id')
    batchid = request.GET.get('batchid')
    unid = request.GET.get('unid')
    selectedsppId = request.GET.get('selectedsppId')
    selectedcomId_id = request.GET.get('compid')
    
    try:
        your_model_instance = medicinemaster.objects.get(id=selected_id)
        phystockobj = Physicalstockdetails.objects.get(itemnm_id=selected_id,Batch_no=batchid,suppliernm_id=selectedsppId,Comapany_name_id=selectedcomId_id)
        expirydate = phystockobj.Expiry_date
        unitname = unitdt.objects.get(id=unid)
        un_name = unitname.unitname
        spn=phystockobj.suppliernm_id
        currentstock=phystockobj.qty
        # Check if the medicine has the specified unit type
        if not Physicalstockdetails.objects.filter(Batch_no=batchid, itemnm_id=selected_id, unt_id=unid,Comapany_name_id=selectedcomId_id).exists():
            return JsonResponse({'error': 'Medicine does not have this unit type'}, status=400)
        medrate = Physicalstockdetails.objects.get(Batch_no=batchid, itemnm_id=selected_id, unt_id=unid,suppliernm_id=selectedsppId,Comapany_name_id=selectedcomId_id)
        medid=medrate.id
        rate = medrate.Rate
        comname=medrate.Comapany_name.Comapany_name
        comid=medrate.Comapany_name_id
        name = your_model_instance.itemnm
        hsncode=your_model_instance.hsncode
        txpercg=your_model_instance.taxpercentage.taxrate
       
        return JsonResponse({'name': name, 'expirydate': expirydate, 'rate': rate, 'un_name': un_name,'comname':comname,'spn':spn,'hsncode':hsncode,'comid':comid,'currentstock':currentstock,'id':medid,'txpercg':txpercg})
    except medicinemaster.DoesNotExist:
        return JsonResponse({'error': 'Medicine not found'}, status=404)
    except Physicalstockdetails.DoesNotExist:
        return JsonResponse({'error': 'Physical stock details not found'}, status=404)
    except unitdt.DoesNotExist:
        return JsonResponse({'error': 'Unit details not found'}, status=404)
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)
    

