@login_required
def reorderlevel(request):
    if request.method == 'POST':
        mdcompany = request.POST.get('mdcompany')
        item = request.POST.get('item')
        qty = request.POST.get('qty')
        
        # Check if an entry with the same medicine and company exists
        existing_entry = reorderleveldetails.objects.filter(companyid_id=mdcompany, itemname_id=item).first()
        if existing_entry:
            # If it exists, update the quantity
            existing_entry.qty = qty
            existing_entry.save()
        else:
            # If it doesn't exist, create a new entry
            objrclv = reorderleveldetails()
            objrclv.companyid_id = mdcompany
            objrclv.itemname_id = item
            objrclv.qty = qty
            objrclv.save()
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')  
    # Get menu management ID from the request
    menu_management_id = request.GET.get('menumanagement_id')
    if menu_management_id:
        try:
            reordobj = get_object_or_404(menumanagement, id=menu_management_id)
            request.session['reordid'] = menu_management_id  
            request.session['reordobjadd'] = reordobj.add
            request.session['reordobjview'] = reordobj.view
            request.session['reordobjedit'] = reordobj.edit
            request.session['reordobjdelete'] = reordobj.delete       
        except Exception as e:
            messages.error(request, f'Error retrieving menu management details: {e}')
            return redirect('error_page')  
        # Redirect to an error page or handle as needed
    else:
        messages.error(request, 'Menu management ID is required.')
        return redirect('error_page') 
    rordmgmntadd= request.session.get('reordobjadd')
    rordmgmntview= request.session.get('reordobjview')
    rordmgmntdelete= request.session.get('reordobjdelete')
    rordmgmntedit= request.session.get('reordobjedit')
    comp=Comapany.objects.all()
    item=medicinemaster.objects.all()
    context={
        'idmngmnt':menu_management_id,
        'stdesign':stdesign,
        'comp':comp,
        'item':item,
        'rordmgmntadd':rordmgmntadd,
        'rordmgmntview':rordmgmntview,
        'rordmgmntdelete':rordmgmntdelete,
        'rordmgmntedit':rordmgmntedit
    }
    return render(request,"reorderlevel.html",context)
