@login_required
def get_reorder_level(request):
    med_id = request.GET.get('med_id')
    quantity = int(request.GET.get('quantity', 0))
    batchId = request.GET.get('batchId')
    compid = request.GET.get('compid')
    stockbranch = request.GET.get('stockbranch')
    selectedsupid = request.GET.get('selectedsupid')

    # 🧩 Get total stock for matching entries
    qs = Physicalstockdetails.objects.filter(
        itemnm_id=med_id,
        Batch_no=batchId,
        Comapany_name_id=compid,
        suppliernm_id=selectedsupid,
        stockbranch_id=stockbranch
    )

    total_qty = qs.aggregate(total=Sum('qty'))['total'] or 0
    if total_qty == 0:
        return JsonResponse({'stock_status': 'Out Of Stock', 'available_stock': 0})

    # 🧩 Get reorder level (default 10)
    reorder_detail = reorderleveldetails.objects.filter(
        itemname_id=med_id,
        companyid_id=compid
    ).first()
    reorder_level = int(reorder_detail.qty) if reorder_detail else 10

    available_stock = total_qty - quantity

    if available_stock < 0:
        status = 'Stock depleted'
    elif available_stock < reorder_level:
        status = 'Stock below reorder level'
    else:
        status = 'Stock available'

    return JsonResponse({'stock_status': status, 'available_stock': total_qty})


@login_required   
def  expiredmedicine(request):
    current_date = date.today()
    #Calculate the date 6 months from now
    six_months_from_now = current_date + timedelta(days=30*6)
    #Find medicines with expiry dates within the next 6 months
    expiring_within_six_months = Physicalstockdetails.objects.filter(Expiry_date__lte=six_months_from_now,qty__gt=0)
    # If you want to find medicines that are expiring within the next 6 months but not expired yet
    # Filter out medicines that have already expired
    not_expired_yet = expiring_within_six_months.filter(Expiry_date__gt=current_date)
    # Pass the queryset to the template for rendering
    stdesign= request.session['loginstaffdesign']
    context={
        'expiring_medicines': not_expired_yet,
        'stdesign':stdesign,
    }
    return render(request,"expiremedicinedetails.html",context)
from django.db.models import Sum
@login_required
def invlist(request):
    total_amount = None  # Initialize total amount
    sdate = None  # Initialize start date
    edate = None  # Initialize end date
    payment_mode = None
    if request.method == 'POST':
        sdate = request.POST.get('sdate')
        edate = request.POST.get('edate')
        payment_mode = request.POST.get('payment_mode')

        if sdate and edate:  # Check if both start and end dates are provided
            inv = newInvoiceMaster.objects.filter(currentdate__range=[sdate, edate],restockstatus='1').order_by('-Invoicenumber')
            total_amount = inv.aggregate(total_amount=Sum('total'))['total_amount']
        else:
            inv = newInvoiceMaster.objects.all().order_by('-Invoicenumber')
            invst=newInvoiceMaster.objects.filter(restockstatus=1).order_by('-Invoicenumber')
            total_amount = invst.aggregate(total_amount=Sum('total'))['total_amount']

        if payment_mode:
            inv = newInvoiceMaster.objects.filter(payementmode__iexact=payment_mode,restockstatus='1').order_by('-Invoicenumber')
            total_amount = inv.aggregate(total_amount=Sum('total'))['total_amount']
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')
        context = {
            'sdate':sdate,
            'edate':edate,
            'inv': inv,
            'stdesign': stdesign,
            'total_amount': total_amount
        }
        return render(request, "invoicelist.html", context)
    objhospt = Hospitaldetails.objects.all()
    stdesign = request.session['loginstaffdesign']
    if not sdate and not edate:  # If no date range is provided, calculate total amount for all invoices
       invst=newInvoiceMaster.objects.filter(restockstatus='1').order_by('-Invoicenumber')
       total_amount = invst.aggregate(total_amount=Sum('total'))['total_amount']
    inv = newInvoiceMaster.objects.all().order_by('-Invoicenumber')
    context = {
        'objhospt': objhospt,
        'stdesign': stdesign,
        'inv': inv,
        'total_amount': total_amount, 
    } 
    return render(request, "invoicelist.html", context)
