@login_required
def insert_reorder_data(request):
    if request.method == 'POST':
        excel_file = request.FILES['excel_file']
        if excel_file.name.endswith('.xlsx'):
            try:
                
                excel_data = pd.read_excel(excel_file)

                for index, row in excel_data.iterrows():
                     
                    med_instance = medicinemaster.objects.get(itemnm=row['Medicinename'].strip().lower())
                    company_name = row['Company_name'].strip().lower()
                    if company_name:
                        try:
                            company_instance = Comapany.objects.get(Comapany_name=company_name)
                        except Comapany.DoesNotExist:
                            company_instance = None
                    else:
                        company_instance = None
                    reorderleveldetails_instance = reorderleveldetails(
                        
                        itemname=med_instance,
                        qty=row['qty'],
                        companyid=company_instance
                        
                       
                    )
                    reorderleveldetails_instance.save()

                return HttpResponse('Data inserted successfully!')
            except Exception as e:
                return HttpResponse('Error occurred: {}'.format(str(e)))
        else:
            return HttpResponse('Please upload a valid Excel file.')
    else:
        return render(request, 'upload_excel.html')
    
