@login_required
def restock_items(request, invoice_id):
    try:
        # Ensure invoice_id is a valid integer
        invoice_id = int(invoice_id)
        
        # Retrieve the invoice object
        invoice = newInvoiceMaster.objects.get(id=invoice_id)
        stff_id=request.session.get('branchid')
        # Retrieve all items associated with the invoice
        invoice_items = newInvoiceChild.objects.filter(invmasterid=invoice)

        if request.method == 'POST':
            for item in invoice_items:
                try:
                    # Find the corresponding entry in Physicalstockdetails
                    physical_stock_item = Physicalstockdetails.objects.get(
                        itemnm__itemnm=item.particulars,  # Assuming item.particulars is the medicine name
                        Batch_no=item.batchno,
                        suppliernm=item.suppid_id,
                        Expiry_date=item.expirydate,
                        Comapany_name__Comapany_name=item.mfg,
                        deleted=False,
                        stockbranch=stff_id
                    )
                    
                    # Update the quantity in Physicalstockdetails by adding the quantity from the invoice item
                    physical_stock_item.qty = int(physical_stock_item.qty) + int(item.quantity)
                    physical_stock_item.save()
   
                except Physicalstockdetails.DoesNotExist:
                    # Handle the case where the corresponding item in Physicalstockdetails doesn't exist
                    pass
            invoice.restockstatus = False  
            invoice.save()
            return redirect('invlist')
            # Redirect to the invoice detail page after restocking
            # return render(request,"upload_excel.html")
    except (ValueError, invoicemaster.DoesNotExist):
        # Handle cases where invoice_id is not a valid integer or the invoice does not exist
        pass

        # Redirect back to the invoice page or a success page

