@login_required 
def saveprescription(request):
    if request.method == 'POST':
    	
        record_count = int(request.POST.get('record_count'))
        errors = []

        try:
            for i in range(1, record_count + 1):
                current_date = date.today()
                mr_number_id = request.POST.get('mrnum')
                if not mr_number_id or mr_number_id == 'Select':
                    mr_number = None
                else:
                    mr_number = Patient_details.objects.get(id=mr_number_id)

                name = request.POST.get('ptname')
                medicinename_id = request.POST.get(f'medicineid{i}')
                if not medicinename_id or medicinename_id == 'Select':
                    # Skip processing this row
                    continue

                try:
                    medicinename = medicinemaster.objects.get(id=medicinename_id)
                except medicinemaster.DoesNotExist:
                    errors.append(f"Medicine with ID {medicinename_id} does not exist for record {i}")
                    continue

                dosage = request.POST.get(f'dosage{i}')
                direction = request.POST.get(f'direction{i}')

                prescription = doctorprescription(
                    Current_Date=current_date,
                    MR_Number=mr_number,
                    name=name,
                    medicinename=medicinename,
                    dosage=dosage,
                    direction=direction
                )
                prescription.save()

        except Exception as e:
            errors.append(str(e))

        if errors:
            return JsonResponse({'status': 'error', 'errors': errors}, status=400)
		
        idmngmnt = request.GET.get('menumanagement_id')
        return redirect(f"{reverse('doctorprescriptions')}?menumanagement_id={idmngmnt}")
	
    return redirect('doctorprescriptions')

@login_required
def view_previous_prescriptions(request):
    if request.method == 'GET' and 'mrNumber' in request.GET:
        mr_number = request.GET.get('mrNumber')
        if not mr_number:
            return HttpResponseBadRequest("MR Number cannot be empty.")
        
        try:
            previous_prescriptions = (doctorprescription.objects
                                       .filter(MR_Number__id=mr_number)  # Assuming MR_Number is a ForeignKey to PatientDetails
                                       .values_list('Current_Date', flat=True)
                                       .distinct())

            if not previous_prescriptions:
                return render(request, 'previous_prescriptions.html', {'message': 'No prescriptions found for this MR Number.'})
            
            return render(request, 'previous_prescriptions.html', {'previous_prescriptions': previous_prescriptions, 'mr_number': mr_number})
        
        except doctorprescription.DoesNotExist:
            return render(request, 'previous_prescriptions.html', {'message': 'No prescriptions found for this MR Number.'})
        except Exception as e:
            return HttpResponseBadRequest(f"An error occurred: {e}")
    else:
        return HttpResponseBadRequest("MR Number is missing in the request.")


def get_prescription_details(request):
    if request.method == 'GET':
        prescription_id = request.GET.get('prescription_id')
        try:
            # Convert to integer to ensure it's a number
            prescription_id = int(prescription_id)
            prescription = Prescriptionnew.objects.get(id=prescription_id)
            data = {
                'id': prescription.id,
                'case_history_id': prescription.case_history_id,
                'medicine_name': prescription.medicine_name,
                'medicine_id': prescription.medicine_id if hasattr(prescription, 'medicine_id') else None,
                'physicalstock_id': prescription.physicalstock_id if prescription.physicalstock else None,
                'noofdays': prescription.noofdays,
                'moringtime': prescription.moringtime,
                'noontime': prescription.noontime,
                'nighttime': prescription.nighttime,
                'beforeorafterdiet': prescription.beforeorafterdiet,
                'medicineguideline': prescription.medicineguideline,
                'qtyprescriped': prescription.qtyprescriped,
            }
            return JsonResponse({'success': True, 'prescription': data})
        except (Prescriptionnew.DoesNotExist, ValueError):
            return JsonResponse({'success': False, 'error': 'Prescription not found'})
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
    
    return JsonResponse({'success': False, 'error': 'Invalid request method'})



@require_GET
def get_dailyreport_details(request):
    if request.method == 'GET':
        mr_number = request.GET.get('mrNumber')
        try:
            prescription_details_list = []
            dailymedicinehistory_details_list = []
            # Query daily report for OP
            prescriptions = dailyreportforop.objects.filter(Mrno_id=mr_number)
            for prescription in prescriptions:
                prescription_details = {
                    'mr_number': prescription.Mrno_id,
                    'current_date': prescription.currentdate.strftime("%Y-%m-%d"),
                    'name': prescription.particular,
                    'value':prescription.value,
                    'normal_value': prescription.normal_value,
                     'iporopstatus':prescription.iporopstatus
                }
                prescription_details_list.append(prescription_details)
            dailymedicinehistorys = dailymedicinehistory.objects.filter(Mrno_id=mr_number)
            for md in dailymedicinehistorys:
                md_details = {
                    'mr_number': md.Mrno_id,
                    'current_date': md.currentdate.strftime("%Y-%m-%d"),
                    'name': md.medname.itemnm.itemnm,
                    'qty': md.qty,
                   'time':md.time
                }
                dailymedicinehistory_details_list.append(md_details)
            # Check if either list is empty
            if not prescription_details_list and not dailymedicinehistory_details_list:
                return JsonResponse({'error': 'No data found for the selected MR number.'}, status=404)
            elif not prescription_details_list:
                return render(request, 'viewreport.html', {'dailymedicinehistory_details_list': dailymedicinehistory_details_list})
            elif not dailymedicinehistory_details_list:
                return render(request, 'viewreport.html', {'prescription_details_list': prescription_details_list})
            else:
                return render(request, 'viewreport.html', {'prescription_details_list': prescription_details_list, 'dailymedicinehistory_details_list': dailymedicinehistory_details_list})
        except dailyreportforop.DoesNotExist:
            return JsonResponse({'error': 'Daily report for OP not found.'}, status=404)
        except dailymedicinehistory.DoesNotExist:
            return JsonResponse({'error': 'Daily medicine history not found.'}, status=404)
    else:
        return JsonResponse({'error': 'Invalid request.'}, status=400)
def get_unique_prescription_dates(request):
    if request.method == 'GET' and 'mrNumber' in request.GET:
        mr_number = request.GET['mrNumber']
        unique_dates = doctorprescription.objects.filter(
            MR_Number__Medical_Record_Number=mr_number
        ).values_list('Current_Date', flat=True).distinct()
        return JsonResponse({'dates': list(unique_dates)})
    else:
        return JsonResponse({'error': 'MR Number is missing in the request.'}, status=400)                                 
def get_prescriptions_by_date(request):
    if request.method == 'GET' and 'mrNumber' in request.GET and 'date' in request.GET:
        mr_number = request.GET['mrNumber']
        date = request.GET['date']
        prescriptions = doctorprescription.objects.filter(
            MR_Number__Medical_Record_Number=mr_number, Current_Date=date
        )
        prescription_list = [{
            'name': prescription.name,
            'medicinename': prescription.medicinename.itemnm,
            'medicinecompany': prescription.medicinecompany.Comapany_name,
            'dosage': prescription.dosage,
            'direction': prescription.direction                                                                                                                                            
        } for prescription in prescriptions]
        return JsonResponse({'prescriptions': prescription_list})
    else:
        return JsonResponse({'error': 'MR Number or date is missing in the request.'},status=400)
