@login_required
def get_currentstock(request):
    if request.method == 'GET':
        item_id = request.GET.get('id')
        batch_id = request.GET.get('batchid')
        unit_id = request.GET.get('unid')
        supplier_id = request.GET.get('selectedsppId')
        company_id = request.GET.get('compid')
        try:
            # Fetch the physical stock details object based on the provided parameters
            stock_details = Physicalstockdetails.objects.get(itemnm=item_id, Batch_no=batch_id, unt=unit_id, suppliernm=supplier_id, Comapany_name=company_id)
            current_stock = stock_details.qty  # Assuming 'qty' represents the current stock
            return JsonResponse({'currentStock': current_stock})
        except Physicalstockdetails.DoesNotExist:
            return JsonResponse({'error': 'Stock details not found'}, status=404)
        except Exception as e:
            return JsonResponse({'error': str(e)}, status=500)
    else:
        return JsonResponse({'error': 'Invalid request method'}, status=400)                               

@login_required
def treatmentlist(request):
    total_amount = None  # Initialize total amount
    sdate = None  # Initialize start date
    edate = None  # Initialize end date
    if request.method == 'POST':
        sdate = request.POST.get('sdate')
        edate = request.POST.get('edate')
        if sdate and edate:  # Check if both start and end dates are provided
            inv = treatmentinvoicemaster.objects.filter(currentdate__range=[sdate, edate]).exclude(cancelstatus='1')
        else:
            inv = treatmentinvoicemaster.objects.exclude(cancelstatus='1')
        total_amount = inv.aggregate(total_amount=Sum('total'))['total_amount']
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')
        context = {
            'sdate':sdate,
            'edate':edate,
            'inv': inv,
            'stdesign': stdesign,
            'total_amount': total_amount
        }
        return render(request, "treatmentlist.html", context)

    objhospt = Hospitaldetails.objects.all()
    stdesign = request.session['loginstaffdesign']
    if not sdate and not edate: 
        tot= treatmentinvoicemaster.objects.exclude(cancelstatus='1')
        total_amount = tot.aggregate(total_amount=Sum('total'))['total_amount']
    inv = treatmentinvoicemaster.objects.all().order_by('-currentdate')
    context = {
        'objhospt': objhospt,
        'stdesign': stdesign,
        'inv': inv,
        'total_amount': total_amount  # Pass total amount to template
    }
    return render(request, "treatmentlist.html", context)

