from django.template.loader import render_to_string
@login_required
def treatmentview(request):
    try:
        stdesign = request.session['loginstaffdesign']
        idenq = request.GET.get('ids')
        if idenq is None or idenq == '':
            raise ValueError("No 'ids' parameter provided or it is empty")
        objinv = treatmentinvoicemaster.objects.get(treatmentInvoicenumber=idenq)
        objhospt = Hospitaldetails.objects.all()
        lsinvoice = treatmentinvoicemaster.objects.get(treatmentInvoicenumber=idenq)
        chinvoice = treatmentinvoicechild.objects.filter(invmasterid=lsinvoice.id)
        stff = lsinvoice.preparedby_id
        staffn = Staffallocation.objects.get(id=stff)
        context = {
            'staffn': staffn,
            'chinvoice': chinvoice,
            'lsinvoice': lsinvoice,
            'objhospt': objhospt,
            'objinv': objinv,
            'stdesign': stdesign
        }
        return render(request, "treatmentlistview.html", context)
    except (ObjectDoesNotExist, MultipleObjectsReturned) as e:
        error_message = str(e)
        error_html = render_to_string('error_page.html', {'error_message': error_message})
        if isinstance(e, MultipleObjectsReturned):
            return HttpResponseBadRequest(error_html)
        else:
            return HttpResponseServerError(error_html)
    except KeyError as e:
        error_message = "KeyError: {}".format(e)
        error_html = render_to_string('error_page.html', {'error_message': error_message})
        return HttpResponseServerError(error_html)
    except ValueError as e:
        error_message = "ValueError: {}".format(e)
        error_html = render_to_string('error_page.html', {'error_message': error_message})
        return HttpResponseBadRequest(error_html)
    except Exception as e:
        error_message = "An unexpected error occurred: {}".format(e)
        error_html = render_to_string('error_page.html', {'error_message': error_message})
        return HttpResponseServerError(error_html)
@login_required  
def currentreorderlist(request):
   
    stornm = storedetails.objects.all()
    un = unitdt.objects.all()
    itmdt = medicinemaster.objects.all()
    reorderlevel = reorderleveldetails.objects.all()
    stdesign = request.session.get('loginstaffdesign')
    physt = Physicalstockdetails.objects.all().order_by('itemnm__itemnm')
    physical_stock_details = Physicalstockdetails.objects.all()

    # Create a dictionary to store reorder levels for each medicine and company combination
    reorder_levels = {}
    for reorder in reorderleveldetails.objects.all():
        key = (reorder.itemname_id, reorder.companyid_id)
        reorder_levels[key] = int(reorder.qty)

    # Prepare stock data with low stock and out of stock status
    stock_with_status = []
    out_of_stock_items = []
    low_stock_items = []

    for stock_detail in physical_stock_details:
        stock_qty = int(stock_detail.qty)
        key = (stock_detail.itemnm_id, stock_detail.Comapany_name_id)
        reorder_qty = reorder_levels.get(key, 10)  # Default to 0 if not found
        is_out_of_stock = stock_qty == 0
        is_low_stock = stock_qty < reorder_qty and not is_out_of_stock
        stock_with_status.append((stock_detail, is_low_stock, is_out_of_stock))

        if is_out_of_stock:
            out_of_stock_items.append(stock_detail)

        if is_low_stock:
            low_stock_items.append(stock_detail)
    context = {
        'stornm': stornm,
        'un': un,
        'itmdt': itmdt,
        'reorderlevel': reorderlevel,
        'stdesign': stdesign,
        'physt': physt,
        'stock_with_status': stock_with_status,
        'out_of_stock_items': out_of_stock_items,
        'low_stock_items': low_stock_items,
    }
    return render(request, 'currentreorderlist.html', context)
def menuheading(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
