@login_required
def fetch_permissions(request):
    role_id = request.GET.get('role_id')
    if not role_id:
        return JsonResponse({'error': 'Role ID not provided'}, status=400)

    try:
        permissions = menumanagement.objects.filter(roleid_id=role_id)
    except menumanagement.DoesNotExist:
        return JsonResponse({'error': 'No permissions found for this role'}, status=404)

    # Collect permissions in a structured format
    permissions_data = {
        'menu_items': [
            {
                'menu_id': permission.menuid_id,
                'view': permission.view,
                'add': permission.add,
                'edit': permission.edit,
                'delete': permission.delete,
            } for permission in permissions
        ]
    }

    return JsonResponse(permissions_data)
@login_required
def menumanagements(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
            return redirect('error_page')

        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')

        role_id = request.POST.get('rolename')
        menu_ids = request.POST.getlist('link[]')

        # Permissions dictionary
        permissions = {
            'add': request.POST.getlist('add[]'),
            'view': request.POST.getlist('view[]'),
            'edit': request.POST.getlist('edit[]'),
            'delete': request.POST.getlist('delete[]'),
        }

        # Delete existing permissions for the role
        menumanagement.objects.filter(roleid_id=role_id).delete()

        # Iterate over menu_ids and create new menumanagement objects
        for menu_id in menu_ids:
            permission_values = {perm: '1' if menu_id in ids else '0' for perm, ids in permissions.items()}
            try:
                menumanagement.objects.create(
                    roleid_id=role_id,
                    menuid_id=menu_id,
                    **permission_values
                )
            except Exception as e:
                messages.error(request, f"Error creating menu management for menu ID {menu_id}: {e}")

        return redirect(f"{reverse('menu_list')}?menumanagement_id={idmngmnt}")

    else:
        try:
            idmngmnt = request.GET.get('menumanagement_id')
            if not idmngmnt:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')

            stdesign = request.session.get('loginstaffdesign')
            if not stdesign:
                return redirect('staff_login')

            menuallobj = get_object_or_404(menumanagement, id=idmngmnt)

            # Set session variables
            request.session['menuallobjmgmntobjid'] = idmngmnt
            request.session['menuallobjmgmntobjadd'] = menuallobj.add
            request.session['menuallobjmgmntobjview'] = menuallobj.view
            request.session['menuallobjmgmntobjedit'] = menuallobj.edit
            request.session['menuallobjmgmntobjdelete'] = menuallobj.delete

            return menu_list(request)

        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')

        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {e}. Please contact the admin for assistance.")
            return redirect('error_page')
           
