def medicines_sold_on_date(request):
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
            return redirect('staff_login')
    selected_date = request.GET.get('date')
    medicines = []

    if selected_date:
        try:
            # Query to filter medicines sold on the selected date and aggregate quantities
            medicines = invoicechild.objects.filter(currentdate=selected_date) \
                .values('particulars') \
                .annotate(total_quantity=Sum('quantity')) \
                .order_by('particulars')
        except ValueError:
            # Handle invalid date format
            return render(request, 'medicines_sold_on_date.html', {
                'error': 'Invalid date format. Please use YYYY-MM-DD format.'
            })

    context = {
         'stdesign':stdesign,
        'selected_date': selected_date,
        'medicines': medicines,
    }
    return render(request, 'medicines_sold_on_date.html', context)
