def process_return(request):
    if request.method == 'POST':
        selected_items = request.POST.getlist('items')
        qty_list = request.POST.getlist('qty')
        
        for item_id, return_qty in zip(selected_items, qty_list):
            try:
                item = invoicechild.objects.get(id=item_id)
                
                if return_qty.strip():  # Check if return_qty is not empty or whitespace
                    return_qty = int(return_qty)
                else:
                    return_qty = 0
                
                if return_qty > item.quantity:
                    messages.error(request, f'Return quantity for {item.particulars} exceeds available quantity.')
                    return redirect('salereturn')
                
                item.sales_return = True
                item.return_quantity = return_qty
                item.save()
                
                # Update physical stock if return_qty is greater than 0
                if return_qty > 0:
                    item_name = medicinemaster.objects.get(itemnm=item.particulars)
                    company_name =Comapany.objects.get(Comapany_name=item.mfg)
                    supplier_name = get_object_or_404(supplier, id=item.suppid_id)
                    
                    physical_stock_item = Physicalstockdetails.objects.get(
                        itemnm=item_name,
                        Batch_no=item.batchno,
                        Comapany_name_id=company_name,
                        suppliernm_id=supplier_name
                    )
                    physical_stock_item.qty = str(float(physical_stock_item.qty) + return_qty)
                    physical_stock_item.save()
            
            except invoicechild.DoesNotExist:
                messages.error(request, f'Invoice item with ID {item_id} does not exist.')
                return redirect('salereturn')
            
            except Exception as e:
                messages.error(request, f'An error occurred while processing item {item_id}: {str(e)}')
                return redirect('salereturn')

        messages.success(request, 'Selected items returned successfully.')
        return redirect('salereturn')
    
    invid = invoicemaster.objects.all()
    invchild = invoicechild.objects.filter(invmasterid__in=invid)
    context = {
        'invid': invid,
        'invchild': invchild
    }
    return render(request, 'salereturn.html', context)
   
