def get_staff_by_department(request):
    department_id = request.GET.get('department_id')
    if department_id:
        staff_allocations = Staffallocation.objects.filter(Department_Name_id=department_id, Status='active').select_related('Staff')
        staff_data = [
            {
                'Staff_id': staff_allocation.Staff.id,
                'Staff_firstname': staff_allocation.Staff.Staff_firstname,
                'Staff_lastname': staff_allocation.Staff.Staff_lastname,
                'desgn':staff_allocation.Designation_Name.Designation_Name
            }
            for staff_allocation in staff_allocations
        ]
        return JsonResponse(staff_data, safe=False)
    return JsonResponse([], safe=False)

