def dailytreatmentdetails(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Menu Management ID not provided.")
            return redirect('error_page')

        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')

        mrnum = request.POST.get('mrDropdowndt')
        adid = request.POST.get('adminttedid')
        
        if not adid:
            messages.error(request, "Admission ID is missing.")
            return redirect(f"{reverse('dailytreatmentrecord')}?menumanagement_id={idmngmnt}")

        # Verify that the admission ID exists in the ipconvert table
        #try:
        #    ipconvert.objects.get(id=adid)
       # except ipconvert.DoesNotExist:
        #    messages.error(request, "Invalid Admission ID.")
         #   return redirect(f"{reverse('dailytreatmentrecord')}?menumanagement_id={idmngmnt}")
        today = date.today()
        stff_id = request.session.get('loginstaff')
        dailyrecord_count = int(request.POST.get('dailyrecord_count'))
        for i in range(1, dailyrecord_count + 1):
            datetr = request.POST.get(f'date_{i}')
            treatmentname = request.POST.get(f'trid_{i}')
            staffNames = request.POST.get(f'staffNames_{i}')
            time = request.POST.get(f'time_{i}')
            if not all([datetr, treatmentname, staffNames, time, mrnum, adid]):
                messages.error(request, "Missing required fields.")
                return redirect(f"{reverse('dailytreatmentrecord')}?menumanagement_id={idmngmnt}")
            try:
                dailytreatmentforip_obj = dailytreatmentdetailsforip.objects.create(
                    Current_date=today,
                    treatmentdate=datetr,
                    MRNumber_id=mrnum,
                    Treatment_name_id=treatmentname,
                    staffname=staffNames,
                    time=time,
                    admitteddt_id=adid
                )
            except Exception as e:
                messages.error(request, f"Error saving treatment details: {str(e)}")
                return redirect(f"{reverse('dailytreatmentrecord')}?menumanagement_id={idmngmnt}")
           
        return redirect(f"{reverse('dailytreatmentrecord')}?menumanagement_id={idmngmnt}")
