from django.db import transaction
def ipconvertion(request):
    try:
        # Ensure a valid Menu Management ID is provided
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
            return redirect('error_page')

        # Ensure the staff is logged in
        st = request.session.get('loginstaff')
        if not st:
            return redirect('staff_login')

        # Ensure the staff design is in the session
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')

        if request.method == 'POST':
            mrnum = request.POST.get('mrnum')
            branch = request.session.get('branchid')
            if not branch:
                messages.error(request, "Logged staff are not allocated to any branch. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')

            admtdate = request.POST.get('admtdate')
            iporop = request.POST.get('iporop')
            currentdate = date.today()

            try:
                # Check if the patient is already admitted on the given date
                if ipconvert.objects.filter(mrno_id=mrnum, admitteddate=admtdate).exists():
                    messages.error(request, f"Patient with Medical Record Number: {mrnum} is already admitted on {admtdate}.")
                    return redirect(f"{reverse('ipconvertion')}?menumanagement_id={idmngmnt}")

                # Update the Patient_details status to 'ip'
                with transaction.atomic():
                    patient = Patient_details.objects.select_for_update().get(id=mrnum)
                    patient.Status = 'ip'
                    patient.save()

                    # Save the ipconvert object
                    ip_convert_obj = ipconvert(
                        currentdate=currentdate,
                        mrno_id=mrnum,
                        preparedby_id=st,
                        ip=iporop,
                        admitteddate=admtdate,
                        Branch_id_id=branch
                    )
                    ip_convert_obj.save()

                return redirect(f"{reverse('ipconvertion')}?menumanagement_id={idmngmnt}")

            except Patient_details.DoesNotExist:
                messages.error(request, f"No patient found with Medical Record Number: {mrnum}")
                return redirect('error_page')
            except Exception as e:
                messages.error(request, f"An error occurred while saving room details: {str(e)}. Please contact the admin.")
                return redirect('error_page')

        else:
            # Handle GET request logic
            currentdate = date.today()
            ipobj = get_object_or_404(menumanagement, id=idmngmnt)

            # Store menu management permissions in session
            request.session['ipobjmngid'] = idmngmnt
            request.session['ipobjmngadd'] = ipobj.add
            request.session['ipobjmngview'] = ipobj.view
            request.session['ipobjmngedit'] = ipobj.edit
            request.session['ipobjmngdelete'] = ipobj.delete

            branchobj = Branch.objects.all()

            context = {
                'idmngmnt': idmngmnt,
                'stdesign': stdesign,
                'currentdate': currentdate,
                'ipmngadd': request.session.get('ipobjmngadd'),
                'ipmngview': request.session.get('ipobjmngview'),
                'branchobj': branchobj,
                'st': st
            }
            return render(request, "ipconversion.html", context)

    except ObjectDoesNotExist:
        messages.error(request, "Menu Management details not found. Please contact the admin.")
        return redirect('error_page')
    except Exception as e:
        messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin for assistance.")
        return redirect('error_page')

from collections import defaultdict
from django.http import JsonResponse
from datetime import datetime

def getipbillmrdetails(request):
    mr_number = request.GET.get('mrNumber')
    if not mr_number:
        return JsonResponse({'error': 'MR number not provided.'}, status=400)

    try:
        print(f"Searching for MR number: {mr_number}")
        patient_details = Patient_details.objects.get(id=mr_number)
        print(f"Found patient details: {patient_details}")

        # Get the latest admission record for this patient
        patient_admission = Patientadmission.objects.filter(MR_No=patient_details).latest('Admitted_Date')
        print(f"Found patient admission details: {patient_admission}")

        # Extract relevant dates and admission ID
        admitted_date = patient_admission.Admitted_Date
        booking_end_date = patient_admission.Bookingend_Date
        adid = patient_admission.id

        # Get all treatments associated with the latest admission
        treatment_details = dailytreatmentdetailsforip.objects.filter(admitteddt_id=adid)
        
        # Calculate the sum of all treatment costs
        total_treatment_charges = sum(float(detail.Treatment_name.Rate) for detail in treatment_details)

        if not admitted_date or not booking_end_date:
            return JsonResponse({'error': 'Admitted date or booking end date is missing.'}, status=500)

        # Ensure dates are in correct format
        if isinstance(admitted_date, str):
            admitted_date = datetime.strptime(admitted_date, '%Y-%m-%d').date()
        if isinstance(booking_end_date, str):
            booking_end_date = datetime.strptime(booking_end_date, '%Y-%m-%d').date()

        if booking_end_date < admitted_date:
            return JsonResponse({'error': 'Booking end date cannot be before admitted date.'}, status=400)
        days_stayed = (booking_end_date - admitted_date).days
        # Prepare the response data
        data = {
            'adid': adid,
            'Medical_Record_Number': patient_details.Medical_Record_Number,
            'Patient_Name': patient_details.Patient_Name,
            'Housename': patient_details.Housename,
            'phno': patient_details.contactno,
            'patient_email': patient_details.Email,
            'pincode': patient_details.Pincode,
            'age': patient_details.Age,
            'gender': patient_details.Gender,
            'place': patient_details.city,
            'admitted_date': admitted_date.strftime('%Y-%m-%d'),
            'days_stayed': days_stayed,
            'room_no': patient_admission.Roomno.Roomno,
            'rate': patient_admission.Roomno.rate,
            'department_name': patient_admission.Department_Name.Department_Name,
            'branch_name': patient_admission.Branch_Name.Branch_Name,
            'total_treatment_charges': total_treatment_charges,  # Total treatment charges included
        }
        return JsonResponse(data)
    except Patient_details.DoesNotExist:
        print(f"Patient with MR number {mr_number} not found.")
        return JsonResponse({'error': f'Patient with MR number {mr_number} not found.'}, status=404)
    except Patientadmission.DoesNotExist:
        print(f"No admission record found for MR number {mr_number}.")
        return JsonResponse({'error': f'No admission record found for MR number {mr_number}.'}, status=404)
    except Exception as e:
        print(f"Unexpected error: {str(e)}")
        return JsonResponse({'error': f'An unexpected error occurred: {str(e)}'}, status=500)
    
def search_patient(request):
    query = request.GET.get('q', '')  # Get search term
    search_type = request.GET.get('search_type', '')  # Get the type of search (name, contactno, or mrn)
    results = []
    if query:
        if search_type == 'name':
            results = Patient_details.objects.filter(Patient_Name__icontains=query)
        elif search_type == 'contactno':
            results = Patient_details.objects.filter(contactno__icontains=query)
        elif search_type == 'mrn':
            results = Patient_details.objects.filter(Medical_Record_Number__icontains=query)

    return render(request, 'search_patient.html', {'query': query, 'search_type': search_type, 'results': results})
# View to handle the search (limit results)
def search_patient_limited(request):
    query = request.GET.get('q', '')
    results = []

    if query:
        # Use Q objects for combined OR queries, and then apply limit at the end
        results = Patient_details.objects.filter(
            Q(Patient_Name__icontains=query) |
            Q(contactno__icontains=query) |
            Q(Medical_Record_Number__icontains=query)
        )[:10]  # Apply LIMIT here

    # Return limited patient information (id, name, MRN)
    patients_data = [
        {
            'id': patient.id,
            'Patient_Name': patient.Patient_Name,
            'Medical_Record_Number': patient.Medical_Record_Number
        } for patient in results
    ]
    
    return JsonResponse(patients_data, safe=False)


