from django.core.files.storage import FileSystemStorage
import os
    
def savemedicalreport(request):
    if request.method == 'POST':
        # Extract form data with error checking
        ptid = request.POST.get('ptid')
        drugHistory = request.POST.get('drugHistory')
        historyofpresentcomplaint = request.POST.get('historyofpresentcomplaint')
        finaldiagnosis = request.POST.get('finaldiagnosis')
        testneeded = request.POST.get('testneeded')
        idmngmnt = request.session.get('savecshsrtobjmngid')
        logger.debug(f"Received POST request with ptid: {ptid}, drugHistory: {drugHistory}")
        
        if not ptid or not drugHistory or not finaldiagnosis:
            logger.warning("Required fields are missing.")
            return JsonResponse({'error': 'Required fields are missing'}, status=400)

        ptdt = get_object_or_404(Patient_details, id=ptid)

        report = casemedicalreport(
            mrno=ptdt, 
            drugHistory=drugHistory,
            historyofpresentcomplaint=historyofpresentcomplaint,
            finaldiagnosis=finaldiagnosis,
            testneeded=testneeded
        )
        report.save()
        logger.info(f"Created medical report for patient {ptid}")

        uploaded_files = request.FILES.getlist('uploaded_files[]')
        for file in uploaded_files:
            try:
                MedicalReportFile.objects.create(report=report, file=file)
                logger.info(f"Uploaded file: {file.name} for report {report.id}")
            except Exception as e:
                report.delete()
                logger.error(f"File upload failed: {str(e)}")
                return JsonResponse({'error': f'File upload failed: {str(e)}'}, status=500)

        return JsonResponse({
            'success': True,
            'redirect_url': f"{reverse('savecasehistory')}?menumanagement_id={idmngmnt}"
        })
    idmngmnt = request.session.get('savecshsrtobjmngid')
    ptid = request.GET.get('mrno')
    ptdt=Patient_details.objects.get(id= ptid)
    mrno=ptdt.Medical_Record_Number
    context = {
        'ptid': ptid,
        'mrno':mrno,
        'idmngmnt':idmngmnt
    }
    return render(request,"medicalreport.html",context)

