@login_required 
def savedoctorprescription(request):
    if request.method == 'POST':
        record_count = int(request.POST.get('record_count'))
        errors = []
        try:
            for i in range(1, record_count + 1):
                current_date = date.today()
                mr_number_id = request.POST.get('mrnum')
                if not mr_number_id or mr_number_id == 'Select':
                    mr_number = None
                else:
                    mr_number = Patient_details.objects.get(id=mr_number_id)
                name = request.POST.get('ptname')
                chief_complaint = request.POST.get('chief_complaint')
                diet = request.POST.get('diet')
                note = request.POST.get('note')
                medicinename_id = request.POST.get(f'medicineid{i}')
                if not medicinename_id or medicinename_id == 'Select':
                    continue
                try:
                    medicinename = medicinemaster.objects.get(id=medicinename_id)
                except medicinemaster.DoesNotExist:
                    errors.append(f"Medicine with ID {medicinename_id} does not exist for record {i}")
                    continue
                dosage = request.POST.get(f'dosage{i}')
                direction = request.POST.get(f'direction{i}')
                prescription = nexdoctorprescription(
                    Current_Date=current_date,
                    MR_Number=mr_number,
                    name=name,
                    medicinename=medicinename,
                    dosage=dosage,
                    direction=direction,
                    diet=diet,
                    note=note,
                   complaint= chief_complaint
                )
                prescription.save()
        except Exception as e:
            errors.append(str(e))

        if errors:
            return JsonResponse({'status': 'error', 'errors': errors}, status=400)
        
		# return redirect('savedoctorprescription')
        # idmngmnt = request.GET.get('menumanagement_id')
        # return redirect(f"{reverse('savedoctorprescription')}?menumanagement_id={idmngmnt}")
	
    return render(request,"nexgendoctorprescription.html")
@login_required
def newview_previous_prescriptions(request):
    if request.method == 'GET':
        mrno = request.GET.get('mrNumber')  # Fetch the MR number from the GET request
        
        try:
            # Fetch distinct prescription details for the given MR number
            previous_prescriptions = (nexdoctorprescription.objects
                                      .filter(MR_Number_id=mrno)
                                      .values('Current_Date', 'medicinename__itemnm', 'dosage', 'note','direction')
                                      .distinct())
            
            # Prepare the response data
            if previous_prescriptions:
                # Convert the queryset to a list of dictionaries
                prescriptions_list = list(previous_prescriptions)
                return JsonResponse({'previous_prescriptions': prescriptions_list})
            else:
                return JsonResponse({'error': 'No prescriptions found for this MR Number.'}, status=404)
        
        except nexdoctorprescription.DoesNotExist:
            return JsonResponse({'error': 'No prescriptions found for this MR Number.'}, status=404)
        
        except Exception as e:
            return JsonResponse({'error': f'An error occurred: {str(e)}'}, status=400)

    return JsonResponse({'error': 'Invalid request method.'}, status=405)
