def viewcasehstrymedreport(request, mrno):
    try:
        # Fetch distinct prescription dates for the given MR number
        previous_prescriptions = (casemedicalreport.objects
                                  .filter(mrno_id=mrno)
                                  .values_list('Current_Date', flat=True)
                                  .distinct())
        
        # If no prescriptions found, return an appropriate JSON response
        if not previous_prescriptions:
            return JsonResponse({'error': 'No prescriptions found for this MR Number.'}, status=404)
        
        # Return JSON response with the prescription dates
        return JsonResponse({'previous_prescriptions': list(previous_prescriptions)})
    
    except nexdoctorprescription.DoesNotExist:
        return JsonResponse({'error': 'No prescriptions found for this MR Number.'}, status=404)
    
    except Exception as e:
        return JsonResponse({'error': f'An error occurred: {str(e)}'}, status=400)
   
def medicalreport_details(request, mrno, date):
    prescriptions = casemedicalreport.objects.filter(mrno=mrno, Current_Date=date)  # Use created_at if that's your field name

    # Fetch files associated with the medical reports
    medical_files = MedicalReportFile.objects.filter(report__mrno=mrno, report__Current_Date=date)
    idmngmnt = request.session.get('savecshsrtobjmngid')
    context = {
        'prescriptions': prescriptions,  # Pass the queryset to the template
        'mrno': mrno,
        'date': date,
        'medical_files': medical_files,
        'idmngmnt':idmngmnt
    }
     
    return render(request, 'nexamedreport.html', context)
