def save_treatment_details(request):
    if request.method == 'POST' and 'save_btn' in request.POST:
        idmngmnt = request.session.get('trmntmgmntobjobjid')
        mr_number_id = request.POST.get('mr_number')  # The ID of the patient
        room_no = request.POST.get('room_no')  # Room number
        record_count = int(request.POST.get('record_count', 0))  # Get record count for the loop

        # Log extracted details for debugging
        logger.debug(f"MR Number ID: {mr_number_id}")
        logger.debug(f"Room Number: {room_no}")
        logger.debug(f"Record Count: {record_count}")
        
        stff = request.session.get('staffid')
        brid = request.session.get('branchid')

        # Start a database transaction
        try:
            with transaction.atomic():
                # Create master record
                treatment_master = nextreatmentdetailsmaster.objects.create(
                    MR_Number_id=mr_number_id,
                    room_no=room_no,
                    branchstff_id=brid,
                    prepairedstaff_id=stff
                )
                idtr = treatment_master.id

                # List to hold treatment details
                treatment_details = []

                # Iterate through the treatments data based on record count
                for i in range(record_count):
                    tratmntid_value = request.POST.get(f'treatments[{i}][tratmntid]')  # Fetch treatment ID
                    if not tratmntid_value:
                        continue  # Skip if no treatment ID is provided

                    # Fetch handled by staff IDs as a comma-separated string
                    handled_by = request.POST.getlist(f'treatments[{i}][handledby]')  # Fetch as list
                    handled_by_ids = ','.join(handled_by)  # Convert to comma-separated string

                    # Fetch given by staff IDs as a comma-separated string
                    given_by = request.POST.getlist(f'treatments[{i}][givenby]')  # Fetch as list
                    given_by_ids = ','.join(given_by)  # Convert to comma-separated string
                    
                    # Fetch the treatment date for this specific treatment
                    treatment_date = request.POST.get(f'treatments[{i}][trtdate]')
                    if not treatment_date:  # If no treatment date provided, set to today's date
                        treatment_date = date.today()

                    # Log treatment detail for debugging
                    logger.debug(f"Treatment {i + 1}:")
                    logger.debug(f"  Treatment ID: {tratmntid_value}")
                    logger.debug(f"  Handled By: {handled_by_ids}")
                    logger.debug(f"  Given By: {given_by_ids}")
                    logger.debug(f"  Treatment Date: {treatment_date}")

                    # Save treatment details in child records
                    treatment_child = nextreatmentdetailschild.objects.create(
                        MR_Number_id=mr_number_id,
                        nexmaster_id=idtr,
                        tratmntid_id=tratmntid_value,
                        handled_by=handled_by_ids,
                        given_by=given_by_ids,
                        treatment_date=treatment_date,  # Save the treatment date
                    )
                    treatment_details.append({
                        'treatment_id': tratmntid_value,
                        'handled_by': handled_by_ids,
                        'given_by': given_by_ids,
                        'treatment_date': treatment_date,
                    })

                # Log the successfully created treatment details
                logger.debug(f"Successfully saved treatment details: {treatment_details}")

            # Redirect to treatment view with success message
            return redirect(f"{reverse('nextreatment')}?menumanagement_id={idmngmnt}")
        
        except Exception as e:
            logger.error(f"Error occurred while saving treatment details: {e}")
            # Redirect with an error message or handle appropriately
            return redirect(f"{reverse('nextreatment')}?menumanagement_id={idmngmnt}&error=save_failed")

    # If method is not POST or save_btn not in request, return to the treatment page
    return redirect(f"{reverse('nextreatment')}?menumanagement_id={idmngmnt}")
        # Return a success response with details
        # return JsonResponse({'success': True, 'message': 'Treatment details saved successfully!', 'treatment_details': treatment_details})
    # If the method is not POST or save_btn not in request, return an error response
    # return JsonResponse({'success': False, 'message': 'Invalid request method.'})
    idmngmnt = request.session.get('trmntmgmntobjobjid')
    return redirect(f"{reverse('nextreatment')}?menumanagement_id={idmngmnt}")
