def get_staff_by_branch(request):
    branch_id = request.GET.get('branch')
    if branch_id:
        staff_allocations = Staffallocation.objects.filter(
            Branch_Name_id=branch_id,
            Status='active'
        ).select_related('Staff', 'Department_Name')

        staff_data = [
            {
                'id': staff_allocation.Staff.id,  # use "id" for consistency with JS
                'Staff_firstname': staff_allocation.Staff.Staff_firstname,
                'Staff_lastname': staff_allocation.Staff.Staff_lastname,
                'deprt': staff_allocation.Department_Name.Department_Name
            }
            for staff_allocation in staff_allocations
        ]
        return JsonResponse({'staff': staff_data})  # wrap in dict
    return JsonResponse({'staff': []})
