import re
@login_required
def savetax(request):
    if request.method == 'POST':
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant you the necessary menu permissions.")
            return redirect('error_page')

        staff_design = request.session.get('loginstaffdesign')
        if not staff_design:
            return redirect('staff_login')

        addtax = request.POST.get('tax')
        if not addtax:
            messages.error(request, "Tax Rate cannot be empty.")
            return redirect(f"{reverse('savetax')}?menumanagement_id={idmngmnt}")

        # Sanitize the tax rate input to remove any non-numeric characters except decimal points
        sanitized_tax = re.sub(r'[^\d.]', '', addtax)

        # Validate if sanitized_tax is a valid float
        try:
            tax_rate = float(sanitized_tax)
        except ValueError:
            messages.error(request, "Invalid Tax Rate. Please enter a valid numeric value.")
            return redirect(f"{reverse('savetax')}?menumanagement_id={idmngmnt}")

        try:
            # Save tax rate in the database
            obj_tax = Taxmaster(taxrate=tax_rate)
            obj_tax.save()
            messages.success(request, 'Tax Rate added successfully.')
            return redirect(f"{reverse('savetax')}?menumanagement_id={idmngmnt}")
        except Exception as e:
            messages.error(request, f"An error occurred while saving Tax details: {str(e)}. Please contact the admin.")
            return redirect('error_page')

    else:
        try:
            stdesign = request.session.get('loginstaffdesign')
            staff_design = request.session.get('loginstaffdesign')
            if not staff_design:
                return redirect('staff_login')

            menu_management_id = request.GET.get('menumanagement_id')
            if not menu_management_id:
                messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to allow the menu permission to you.")
                return redirect('error_page')

            taxmgmntobj = get_object_or_404(menumanagement, id=menu_management_id)
            request.session['taxmgmntobjid'] = menu_management_id
            request.session['taxmgmntobjadd'] = taxmgmntobj.add
            request.session['taxmgmntobjview'] = taxmgmntobj.view
            request.session['taxmgmntobjedit'] = taxmgmntobj.edit
            request.session['taxmgmntobjdelete'] = taxmgmntobj.delete
            context = {
                'stdesign': stdesign,
                'idmngmnt': menu_management_id,
                'staff_design': staff_design,
                'taxmgmntadd': request.session.get('taxmgmntobjadd'),
                'taxmgmntview': request.session.get('taxmgmntobjview'),
                'taxmgmntedit': request.session.get('taxmgmntobjedit'),
                'taxmgmntdelete': request.session.get('taxmgmntobjdelete'),
            }
            return render(request, "tax.html", context)
        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')
        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin for assistance.")
            return redirect('error_page')
  
