def treatmentlistrecord(request):
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    st_id = request.session.get('loginstaff')
    if not st_id:
        return redirect('staff_login')
    
    branch_id = request.session.get('branchid')  # Staff's branch ID from session

    # Check if a date is posted, else use the current date
    if request.method == 'POST':
        selected_date_str = request.POST.get('sdate', '')
        if selected_date_str:
            try:
                selected_date = datetime.strptime(selected_date_str, '%Y-%m-%d')
                selected_date_str = selected_date.strftime('%Y-%m-%d')  # Ensure consistent format
            except ValueError:
                print(f"Invalid date format: {selected_date_str}")
                selected_date_str = datetime.now().strftime('%Y-%m-%d')
        else:
            selected_date_str = datetime.now().strftime('%Y-%m-%d')
    else:
        selected_date_str = datetime.now().strftime('%Y-%m-%d')
    
    # Convert the selected_date_str back to a date object for filtering
    selected_date = datetime.strptime(selected_date_str, '%Y-%m-%d').date()

    # Filter treatments by the selected date and branch
    treatments = nextreatmentdetailschild.objects.filter(
        treatment_date=selected_date,
        nexmaster__branchstff_id=branch_id
    ).select_related('MR_Number', 'tratmntid')
    
    treatment_count = treatments.count()
    
    # Prepare treatment data for the template
    treatment_data = []
    for treatment in treatments:
        treatment_data.append({
            'treatment_name': treatment.tratmntid.Treatment_name if treatment.tratmntid else 'N/A',
            'patient_name': treatment.MR_Number.Patient_Name if treatment.MR_Number else 'N/A',
            'handled_by': treatment.get_handled_by_names() if hasattr(treatment, 'get_handled_by_names') else 'N/A',
            'given_by': treatment.get_given_by_names() if hasattr(treatment, 'get_given_by_names') else 'N/A',
            'treatment_date': treatment.treatment_date.strftime('%Y-%m-%d') if treatment.treatment_date else 'N/A',
        })

    # Render the template with the context
    context = {
        'sdate': selected_date_str,  # Always in YYYY-MM-DD format
        'stdesign': stdesign,
        'st_id': st_id,
        'selected_date': selected_date_str,  # Consistent format for display and input
        'treatment_data': treatment_data,
        'treatment_count': treatment_count
    }

    return render(request, 'listtreatment.html', context)

def searchpharmacymedicine(request):
    search_term = request.GET.get('term', '').strip()

    if not search_term:
        return JsonResponse({'error': 'Invalid search term'}, status=400)

    staff_id = request.session.get('loginstaff')
    if not staff_id:
        return JsonResponse({'error': 'User not authenticated'}, status=403)

    try:
        # Get the branch of the logged-in staff
        staff_allocation = Staffallocation.objects.get(id=staff_id)
        staff_branch_id = staff_allocation.Branch_Name_id

        current_date = timezone.now().date()

        available_medicines = Physicalstockdetails.objects.filter(
            itemnm__itemnm__icontains=search_term,
            qty__gt=0,
            deleted=False,
            stockbranch=staff_branch_id
        ).select_related('itemnm', 'unt', 'Comapany_name', 'itemnm__taxpercentage', 'unt__bsuntid')

        data = []
        for medicine in available_medicines:
            try:
                # Check if unit name contains STRP or STRIP
                is_strip = False
                base_rate = None
                tablets_per_strip = 1
                
                if medicine.unt and medicine.unt.unitname:
                    unit_name_upper = medicine.unt.unitname.upper()
                    is_strip = 'STRP' in unit_name_upper or 'STRIP' in unit_name_upper
                    
                    # Get tablets per strip from basequantity
                    if medicine.unt.basequantity:
                        try:
                            tablets_per_strip = int(medicine.unt.basequantity)
                        except (ValueError, TypeError):
                            tablets_per_strip = 1
                
                # Calculate base_rate if it's a strip item
                rate_value = float(medicine.Rate) if medicine.Rate else 0
                if is_strip and tablets_per_strip > 0 and rate_value > 0:
                    base_rate = rate_value / tablets_per_strip
                    # Round to 2 decimal places
                    base_rate = round(base_rate, 2)
                
                data.append({
                    'stockbranch': medicine.stockbranch_id,
                    'item_id': medicine.itemnm.id if medicine.itemnm else None,
                    'unit': medicine.unt.unitname if medicine.unt else None,
                    'bsunit': medicine.unt.bsuntid.unit if medicine.unt and medicine.unt.bsuntid else None,
                    'item_name': medicine.itemnm.itemnm if medicine.itemnm else None,
                    'batchno': medicine.Batch_no,
                    'hsncode': medicine.itemnm.hsncode if medicine.itemnm else None,
                    'manufacturer_date': medicine.Manufacturer_date,
                    'expdate': medicine.Expiry_date,
                    'rate': medicine.Rate,
                    'base_rate': base_rate,  
                    'is_strip': is_strip,    
                    'tablets_per_strip': tablets_per_strip,  
                    'unt': medicine.unt.unitname if medicine.unt else None,
                    'compid': medicine.Comapany_name_id,
                    'compname': medicine.Comapany_name.Comapany_name if medicine.Comapany_name else None,
                    'med_id': medicine.itemnm_id,
                    'currentstock': medicine.qty,
                    'supplier_name': medicine.suppliernm_id if medicine.suppliernm_id else None,
                    'tax': float(medicine.itemnm.taxpercentage.taxrate) if medicine.itemnm and medicine.itemnm.taxpercentage else None,
                })
            except AttributeError as e:
                logger.error(f"Data Processing Error: {e}")

        return JsonResponse(data, safe=False)

    except Staffallocation.DoesNotExist:
        return JsonResponse({'error': 'Staff allocation not found'}, status=404)

    except Exception as e:
        logger.error(f"Server Error: {e}")
        return JsonResponse({'error': 'Server error occurred', 'details': str(e)}, status=500)
