def safe_float(val, default=0.0):
    try:
        return float(val)
    except (TypeError, ValueError):
        return default
import math   
def create_invoice(request):
    if request.method == "POST":
        today = date.today()
        todateinv = now().strftime("%Y%m%d")
        errors = []

        try:
            with transaction.atomic():
                hospital_id = request.POST.get('hosptname')
                branch_id = request.POST.get('branchname')
                mrno_id = request.POST.get('mrnum')
                current_date = now().strftime("%Y-%m-%d")
                last_entry = invoicemaster.objects.filter(currentdate=today).order_by('-id').first()
                refnid = (int(last_entry.Invoicenumber[13:]) + 1) if last_entry else 1
                invoicen = f"INVNO{todateinv}{refnid}"
                if not all([hospital_id, branch_id, mrno_id]):
                    return JsonResponse({"success": False, "error": "Missing required master fields."}, status=400)
                subtotal = safe_float(request.POST.get('subtotal'))
                tax = safe_float(request.POST.get('tax'))
                shipping = safe_float(request.POST.get('shipping'))
                discount = safe_float(request.POST.get('totalDiscountInput'))
                total = safe_float(request.POST.get('totalAmount'))
                invoice = invoicemaster.objects.create(
                    hospitalname_id=hospital_id,
                    branch_id=branch_id,
                    Mrno_id=mrno_id,
                    Invoicenumber=invoicen,
                    currentdate=current_date,
                    subtotal=subtotal,
                    tax=tax,
                    shipping=shipping,
                    total=total,
                    patientname=request.POST.get('ptname', ''),
                    patientphno=request.POST.get('contact', ''),
                    discount=discount,
                    preparedby_id=request.session.get('loginstaff'),
                    consultationfee=request.POST.get('consultationfee', 0),
                    consultationfeecumregfee=request.POST.get('registrationfee', 0),
                    restockstatus=True
                )
                invid = invoice.id

                item_count = int(request.POST.get('items_count', 0))

                for i in range(1, item_count + 1):
                    particulars = request.POST.get(f'items[{i}][particulars]', '').strip()
                    batchno = request.POST.get(f'items[{i}][batchno]', '').strip()
                    mfg = request.POST.get(f'items[{i}][compnm]', '').strip()
                    expirydate = request.POST.get(f'items[{i}][expirydate]', '').strip()

                    # Handle expiry date safely
                    expiry_date = None
                    item_label = f"Item {i} ('{particulars}', Batch '{batchno}')"
                    if expirydate and expirydate.lower() not in ["null", "none", "undefined", ""]:
                        try:
                            expiry_date = datetime.strptime(expirydate, '%Y-%m-%d').date()
                        except ValueError:
                            errors.append(f"{item_label}: Invalid expiry date '{expirydate}'. Expected format YYYY-MM-DD.")
                            continue

                    hsncode = request.POST.get(f'items[{i}][hsncode]', '').strip()
                    raw_suppid = request.POST.get(f'items[{i}][suppid]', '').strip()
                    quantity = int(request.POST.get(f'items[{i}][quantity]', 1))
                    bsunit = request.POST.get(f'items[{i}][bsunit]', 0)
                    amount = safe_float(request.POST.get(f'items[{i}][amount]'))
                    tax = safe_float(request.POST.get(f'items[{i}][tax]'))
                    taxamount = safe_float(request.POST.get(f'items[{i}][taxamount]'))
                    cgst = request.POST.get(f'items[{i}][cgst]')
                    sgst = request.POST.get(f'items[{i}][sgst]')
                   
                    if not particulars:
                        errors.append(f"{item_label}: Missing 'particulars' (medicine name).")
                        continue
                    if not raw_suppid or not raw_suppid.isdigit():
                        errors.append(f"{item_label}: Missing or invalid 'suppid'.")
                        continue
                    suppid = int(raw_suppid)
                    subtotal_item = float(f"{math.ceil(quantity * amount):.1f}")
                    try:
                        itemaster_obj = Physicalstockdetails.objects.filter(
                            itemnm__itemnm=particulars,
                            Batch_no=batchno,
                            suppliernm_id=suppid
                        ).first()

                        if not itemaster_obj:
                            raise Physicalstockdetails.DoesNotExist

                        invoicechild.objects.create(
                            quantity=quantity,
                            particulars=particulars,
                            amount=amount,
                            sutotal=subtotal_item,
                            Mrno_id=mrno_id,
                            currentdate=current_date,
                            invoiceno=invoicen,
                            description=request.POST.get(f'items[{i}][description]', ''),
                            patientname=request.POST.get('ptname', ''),
                            patientphno=request.POST.get('contact', ''),
                            invmasterid_id=invid,
                            batchno=batchno,
                            expirydate=expiry_date,
                            mfg=mfg,
                            unt=request.POST.get(f'items[{i}][unt]', 'N/A'),
                            hsncode=hsncode,
                            suppid_id=suppid,
                            tax=tax,
                            taxamount=taxamount,
                            baseqty=bsunit,
                            sgst=sgst,
                            cgst=cgst

                        )
                        itemaster_obj.qty = F('qty') - quantity
                        itemaster_obj.save()
                    except Physicalstockdetails.DoesNotExist:
                        errors.append(f"{item_label}: Stock not found for supplier ID {suppid}.")
                        continue

                if errors:
                    return JsonResponse({
                        "success": False,
                        "invoice": invoicen,
                        "errors": errors
                    }, status=400)

                return redirect('printoption')

        except Exception as e:
            InvoiceErrorLog.objects.create(
                error_message=str(e),
                related_invoice=invoicen,
                staff_id=request.session.get('loginstaff')
            )
            return JsonResponse({"success": False, "error": str(e)}, status=400)

    # GET request
    medname = medicinemaster.objects.all()
    objhospt = Hospitaldetails.objects.all()
    todate = now().strftime("%Y/%m/%d")
    mrnoobj = Patient_details.objects.all()
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    st_id = request.session.get('loginstaff')
    if not st_id:
        return redirect('staff_login')

    staff_branch = Staffallocation.objects.get(id=st_id)
    stbtachid = staff_branch.Branch_Name_id
    brname = Branch.objects.filter(id=stbtachid)
    last_entry = invoicemaster.objects.filter(currentdate=today).order_by('-id').first()
    refnid = (int(last_entry.Invoicenumber[13:]) + 1) if last_entry else 1
    inv = f"INVNO{todateinv}{refnid}"
    context = {
        'medname': medname,
        'st_id': st_id,
        'objhospt': objhospt,
        'today': today,
        'todate': todate,
        'mrnoobj': mrnoobj,
        'stdesign': stdesign,
        'brname': brname,
        'inv_id': inv
    }
    return render(request, "invoicenew.html", context)
logger = logging.getLogger(__name__)
def nexcasehistory(request):
    if request.method == "POST":
        today = date.today()
        mrno = request.POST.get('mrnum')
        
        if not mrno:
            return JsonResponse({"success": False, "error": "MR number is required."}, status=400)
        
        try:
            with transaction.atomic():
                chief_complaint = request.POST.get('chief_complaint')
                
                followupdateinconsultation = request.POST.get('followupdateinconsultation')
                if not chief_complaint:
                    return JsonResponse({"success": False, "error": "Chief complaint is required."}, status=400)
                medicalfollowup.objects.create(Mrno_id=mrno, currentsymptioms=chief_complaint,
                nextfollowupdate=followupdateinconsultation if followupdateinconsultation else today,currentdate=today)
                dietdt = request.POST.get('dietnm') 
                note = request.POST.get('note', '')
                prescription = NexDoctorPrescription.objects.create(
                    patient_id=mrno,
                    dietid_id=dietdt if dietdt else 1,
                    note=note
                )
                medication_names = request.POST.getlist("med_name[]")
                ex_stock_names = request.POST.getlist("ex_stock_med_name[]")
                counts = request.POST.getlist("med_count[]")
                dosages = request.POST.getlist("dosage[]")
                directions = request.POST.getlist("med_notes[]") 
                # Filter out rows where all values are empty
                valid_entries = []
                for i in range(len(medication_names)):
                    medicinename_id = medication_names[i].strip() if medication_names[i] else None
                    ex_stock_name = ex_stock_names[i].strip() if ex_stock_names[i] else None
                    count = counts[i].strip() if counts[i] else None
                    dosage = dosages[i].strip() if dosages[i] else None
                    direction = directions[i].strip() if directions[i] else None

                    # Skip the entry if Medication Name, Count, and Dosage are all empty
                    if not medicinename_id and not count and not dosage:
                        continue

                    # Add valid rows for further processing
                    valid_entries.append((medicinename_id, ex_stock_name, count, dosage, direction))

                # Check if the resulting entries are consistent
                if not all(len(entry) == 5 for entry in valid_entries):
                    return JsonResponse({"success": False, "error": "Invalid medication entry data."}, status=400)

                # Process valid entries
                for medicinename_id, ex_stock_name, count, dosage, direction in valid_entries:
                    if not count or not dosage:
                        return JsonResponse({"success": False, "error": "Count and dosage are required for all medication entries."}, status=400)

                    try:
                        count = int(count)  # Ensure count is a valid integer
                    except ValueError:
                        return JsonResponse({"success": False, "error": "Invalid count value."}, status=400)

                    # Fetch medicine instance if provided
                    medicinename_instance = None
                    if medicinename_id:
                        try:
                            medicinename_instance = medicinemaster.objects.get(id=medicinename_id)
                        except medicinemaster.DoesNotExist:
                            return JsonResponse({"success": False, "error": f"Medicine ID {medicinename_id} does not exist."}, status=400)

                    # Create medication entry
                    MedicationEntry.objects.create(
                        prescription=prescription,
                        medicinename=medicinename_instance,
                        ex_stock_medicinename=ex_stock_name,
                        count=count,
                        dosage=dosage,
                        direction=direction
                    )

                # Step 4: Save or Update Case History Personal Info
                age = request.POST.get('age', '0')
                weight = request.POST.get('weight', '0')
                height = request.POST.get('height', '0')
                try:
                    age = int(age) if age else 0
                    weight = float(weight) if weight else 0.0
                    height = float(height) if height else 0.0
                except ValueError:
                    return JsonResponse({"success": False, "error": "Invalid age, weight, or height."}, status=400)

                # Update or create case history personal info based on MR number
                casehistrypersonalinfo.objects.update_or_create(
                    mrno=mrno,
                    defaults={
                        'age': age,
                        'weight': weight,
                        'height': height
                    }
                )

                # Step 5: Create and Save Medical Report
                drugHistory = request.POST.get('drugHistory', '')
                historyofpresentcomplaint = request.POST.get('historyofpresentcomplaint', '')
                finaldiagnosis = request.POST.get('finaldiagnosis', '')
                testneeded = request.POST.get('testneeded', '')
                ptdt = get_object_or_404(Patient_details, id=mrno)
                report = casemedicalreport.objects.create(
                    mrno=ptdt, 
                    drugHistory=drugHistory,
                    historyofpresentcomplaint=historyofpresentcomplaint,
                    finaldiagnosis=finaldiagnosis,
                    testneeded=testneeded
                )

                
                # Return success with a possible redirect URL
                idmngmnt = request.session.get('savecshsrtobjmngid')
                # return JsonResponse({
                #     'success': True,
                    # 'redirect_url': f"{
                # reverse('nexcasehistory')}?menumanagement_id={idmngmnt}
                return redirect(f"{reverse('nexcasehistory')}?menumanagement_id={idmngmnt}")
                #          "
                # })
                
        except Exception as e:
            # Log and handle errors
            casehistoryErrorLog.objects.create(
                error_message=str(e),
                related_mrno=mrno,
                staff_id=request.session.get('loginstaff')
            )
            logger.error(f"Error processing request for MRNO {mrno}: {str(e)}")
            return JsonResponse({"success": False, "error": "An error occurred while saving data."}, status=400)

    # Handle GET request, render form
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
            messages.error(request, "Menumanagement ID not provided.")
            return redirect('error_page')
        
    try:
            # Fetch menu management details
            savecasehstobj = get_object_or_404(menumanagement, id=idmngmnt)
            # Store menu management permissions in session
            request.session['savecshsrtobjmngid'] = idmngmnt
            request.session['savecshsrtobjmngadd'] = savecasehstobj.add
            request.session['savecshsrtobjmngview'] = savecasehstobj.view
            request.session['savecshsrtobjmngedit'] = savecasehstobj.edit
            request.session['savecshsrtobjmngdelete'] = savecasehstobj.delete
            # Check if user is logged in
            stdesign = request.session.get('loginstaffdesign')
            if not stdesign:
                return redirect('staff_login')
            dt=Diet.objects.all()
            context = {
                 'dt':dt,
                'idmngmnt': idmngmnt,
                'stdesign': stdesign,
                'savecshstradd': request.session.get('savecshsrtobjmngadd'),
                'savecshstrview': request.session.get('savecshsrtobjmngview'),
                'savecshstredit': request.session.get('savecshsrtobjmngedit'),
                'savecshstrdelete': request.session.get('savecshsrtobjmngdelete'),
            }
            return render(request, "nexcasehistory.html", context)
    except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')
    except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin for assistance.")
            return redirect('error_page')
    

