def get_casepatient_history(request):
    # Get MR Number from the query parameters
    mrno = request.GET.get('mrnoid')
    if not mrno:
        return JsonResponse({"success": False, "error": "MR Number is required."}, status=400)
    # Fetch patient details
    patient = get_object_or_404(Patient_details, id=mrno)
    # Fetch case history (prescriptions and reports)
    prescriptions = NexDoctorPrescription.objects.filter(patient_id=mrno)
    medical_reports = casemedicalreport.objects.filter(mrno_id=mrno)
    # Prepare the data to send back to the frontend
    patient_data = {
        'patient_name': patient.Patient_Name,
        'age': patient.Age,  # Assuming age is part of the patient model
        'contactno': patient.contactno,
        'prescriptions': [],
        'medical_reports':[]
    }
    # Add prescription details
    for prescription in prescriptions:
        patient_data['prescriptions'].append({
            'current_date': prescription.current_date,
            'diet': prescription.dietid.name,
            'note': prescription.note,
            'medications': [
                {
                   'medicine_name': medication.medicinename.itemnm if medication.medicinename else medication.ex_stock_medicinename,
              		 'count': medication.count,
                    'dosage': medication.dosage,
                    'direction': medication.direction
                }for medication in prescription.medications.all()
            ]
        })
    # Add medical report details
    for report in medical_reports:
        patient_data['medical_reports'].append({
            'current_date': report.Current_Date,
            'drug_history': report.drugHistory,
            'history_of_present_complaint': report.historyofpresentcomplaint,
            'final_diagnosis': report.finaldiagnosis,
            'tests_needed': report.testneeded,
            'files': [
                {
                    'file_name': file.file.name,
                    'file_url': file.file.url
                } for file in report.files.all()
            ]
        })
#
    # Return data as JSON
    return JsonResponse(patient_data)
@require_GET
def search_medications(request):
    query = request.GET.get('q', '').strip()  # Get the query from the AJAX request
    if query:
        # Filter medications based on the query and qty > 0 (in-stock)
        results = Physicalstockdetails.objects.filter(itemnm__itemnm__icontains=query, qty__gt=0).select_related('itemnm')[:10]
        medications = [{'id': med.itemnm.id, 'name': med.itemnm.itemnm} for med in results]
    else:
        medications = []
    return JsonResponse({'medications': medications})

