@login_required
def todaymedicalfollowup(request):
    today = date.today()
    
    # Get the logged-in staff ID
   
    staff_id = request.session.get('staffid')
    
    # Get the branch of the logged-in staff
    try:
        staff_allocation = Staffallocation.objects.get(Staff_id=staff_id)
        staff_branch = staff_allocation.Branch_Name
    except Staffallocation.DoesNotExist:
        staff_branch = None
        
    # Filter case histories for today and for doctors in the same branch
    if staff_branch:
        mddt = clairvedaCaseHistory.objects.filter(
            follow_up_date=today,
            prepairedby_id__staffallocation__Branch_Name=staff_branch
        ).distinct()
    else:
        mddt = clairvedaCaseHistory.objects.none()

    context = {
        'mddt': mddt,
        'stdesign': request.session.get('loginstaffdesign')
    }
    return render(request, "todaymedicalfollowup.html", context)
