def check_patient_status(request):
    mr_number = request.GET.get('mr_number')
    if not mr_number:
        return JsonResponse({'status': ''})  # No status if no MR number is provided
    
    # Check if the patient has records in Complaints or NexDoctorPrescription
    has_followup = Complaints.objects.filter(MR_Number__id=mr_number).exists() or \
                   NexDoctorPrescription.objects.filter(patient__id=mr_number).exists()

    # Return 'Followup' if records exist; otherwise, return 'Consultation'
    status = "Followup" if has_followup else "Consultation"
    return JsonResponse({'status': status})
