def edit_dietplan(request):  
    if request.method == 'POST':
        try:
            dietplan_id = request.POST.get('dietplan_id')
            diet_id = request.POST.get('diet')
            noofdays = request.POST.get('noofdays')
            foodavoided = request.POST.get('foodavoided')
            
            if not dietplan_id:
                return JsonResponse({"success": False, "error": "Diet plan ID is required."}, status=400)
            
            dietplan = get_object_or_404(casehistorydietplan, id=dietplan_id)
            
            # Update fields
            if diet_id:
                dietplan.diet_id = diet_id
            if noofdays:
                dietplan.noofdays = noofdays
            if foodavoided:
                dietplan.foodtobeavoided = foodavoided
            
            dietplan.save()
            
            return JsonResponse({
                "success": True,
                "message": "Diet plan updated successfully!",
                "dietplan": {
                    "id": dietplan.id,
                    "diet_id": dietplan.diet.id if dietplan.diet else None,
                    "diet_name": dietplan.diet.name if dietplan.diet else "",
                    "noofdays": dietplan.noofdays,
                    "foodtobeavoided": dietplan.foodtobeavoided,
                    "created_at": dietplan.created_at.strftime("%d-%m-%Y")
                }
            })
            
        except Exception as e:
            logger.error(f"Error editing diet plan: {str(e)}")
            return JsonResponse({"success": False, "error": str(e)}, status=400)
    
    return JsonResponse({"success": False, "error": "Invalid request method"}, status=405)


