            dietplan_id = request.POST.get('dietplan_id')
            
            if not dietplan_id:
                return JsonResponse({"success": False, "error": "Diet plan ID is required."}, status=400)
            
            dietplan = get_object_or_404(casehistorydietplan, id=dietplan_id)
            
            # Get patient ID for response if needed
