def todayremaindertable(request):
    if request.method == 'POST':
        enqdate = request.POST.get('sdate')
        try:
            stdesign = request.session['loginstaffdesign']
            branch_id = request.session['branchid']
        except KeyError:
            # Handle missing session data gracefully
            return render(request, "error.html", {"error": "Session data missing."})

        followups = followup.objects.filter(
            remainderdate=enqdate,
            enqid__status__in=["Pending", "Re-contact", "Recontact2","Priority"],
            enqid__branch_id=branch_id
        )
        context = {
        'stdesign': stdesign,
        'followups': followups,
        'current_date': enqdate,
        }
        return render(request, "todayremainder.html", context)

    current_date = date.today()
    try:
        stdesign = request.session['loginstaffdesign']
        branch_id = request.session['branchid']
    except KeyError:
        # Handle missing session data gracefully
        return render(request, "error.html", {"error": "Session data missing."})

    followups = followup.objects.filter(
        remainderdate=current_date,
        enqid__status__in=["Pending", "Re-contact", "Recontact2","Priority"],
        enqid__branch_id=branch_id
    )
    followup_count = followups.count() 

    context = {
        'stdesign': stdesign,
        'followups': followups,
        'current_date': current_date,
    }
    return render(request, "todayremainder.html", context)

def get_patientfollowup_history(request, mrno_id):
    followups = medicalfollowup.objects.filter(Mrno_id=mrno_id).values(
        'currentdate', 'progressnote', 'currentsymptioms'
    ).order_by('-currentdate')
    return JsonResponse({'followups': list(followups)})
    
    

def newcasehistory(request):
    case_histories = clairvedaCaseHistory.objects.all()

    # Lists to store case histories with and without follow-up prescriptions
    case_histories_no_followup = []
    

    for case_history in case_histories:
        # Filter prescriptions with no follow-up ID (case history prescriptions)
        no_followup_prescriptions = case_history.prescriptions.filter(followup__isnull=True)
        case_histories_no_followup.append({
            'case_history': case_history,
            'prescriptions': no_followup_prescriptions
        })
        
        # Filter prescriptions with follow-up ID (follow-up prescriptions)
    
    # Lists to store case history information and follow-up details
    case_histories_with_followup = []

    for case_history in case_histories:
        # Filter prescriptions with follow-up ID (follow-up prescriptions)
        followup_prescriptions = clairvedaPrescription.objects.filter(case_history=case_history, followup__isnull=False)
        
        # Group prescriptions by their follow-up
        followup_by_date = {}
        for prescription in followup_prescriptions:
            followup = prescription.followup
            followup_date = followup.created_at
            if followup_date not in followup_by_date:
                followup_by_date[followup_date] = {
                    'complaint': case_history.chief_complaint,
                    'test_needed': case_history.test_needed,
                    'prescriptions': [],
                    'followup': followup
                }
            followup_by_date[followup_date]['prescriptions'].append(prescription)

        # Store the grouped follow-up data for the case history
        for followup_date, data in followup_by_date.items():
            case_histories_with_followup.append({
                'follow_up_date': followup_date,
                'complaint': data['complaint'],
                'test_needed': data['test_needed'],
                'prescriptions': data['prescriptions'],
                'followup': data['followup'],
                'notes': data['followup'].notes,  # Adding notes
                'handledbystaff': data['followup'].handledbystaff,  # Adding handled by staff (doctor)
            })
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
            return redirect('staff_login')
    context = {
         'stdesign':stdesign,
        'case_histories_with_followup': case_histories_with_followup,
        'case_histories_no_followup': case_histories_no_followup,
      
    }
    

    return render(request,"newcasehistory.html",context)
    # case_histories = clairvedaCaseHistory.prescriptions.filter(followup__isnull=True)
    # # .all()
    # context={
    #      'case_histories': case_histories
    # }
    # return render(request,"newcasehistory.html",context)


logger = logging.getLogger(__name__)
def addcasehistory(request):
    if request.method == 'POST':
        try:
            # Extract form data
            patient_id = request.POST.get('mrnum')
            doctor_id = request.POST.get('doctor')
            status = request.POST.get('status')
            chief_complaint = request.POST.get('chief_complaint')
            drug_history = request.POST.get('drug_history')
            present_complaint = request.POST.get('present_complaint')
            final_diagnosis = request.POST.get('final_diagnosis')
            test_needed = request.POST.get('testneeded')
            diet_id = request.POST.get('diet')
            additional_notes = request.POST.get('notes')
            follow_up_date = request.POST.get('follow_up_date', str(date.today()))
            prepared_by = request.session.get('staffid')
            brchid=request.session.get('branchid')
            # Ensure patient_id is provided
            if not patient_id:
                return JsonResponse({"success": False, "error": "Patient ID is required."}, status=400)
            # Fetch related objects
            patient = get_object_or_404(Patient_details, id=patient_id)
            doctor = get_object_or_404(Staffdetails, id=doctor_id) if doctor_id else None
            diet = Diet.objects.filter(id=diet_id).first() if diet_id else None  # Use filter().first() to avoid exceptions
            # Create case history record
            case_history = clairvedaCaseHistory.objects.create(
                patient=patient,
                assigned_doctor=doctor,
                status=status,
                chief_complaint=chief_complaint,
                drug_history=drug_history,
                present_complaint=present_complaint,
                final_diagnosis=final_diagnosis,
                test_needed=test_needed,
                diet=diet,
                additional_notes=additional_notes,
                follow_up_date=follow_up_date,
                created_at=date.today(),
                prepairedby_id=prepared_by
            )
            # Handle file uploads
            for file in request.FILES.getlist('files[]', []):
                casehistoryresultReport.objects.create(casehistory=case_history, file=file)
            # Parse personal info fields
            try:
                age = int(request.POST.get('age', "").strip()) if request.POST.get('age') else None
                height = float(request.POST.get('height', "").strip()) if request.POST.get('height') else None
                weight = float(request.POST.get('weight', "").strip()) if request.POST.get('weight') else None
            except ValueError:
                return JsonResponse({"success": False, "error": "Invalid age, height, or weight format."}, status=400)

            # Create personal info entry if any field is provided
            if any([age, height, weight]):
                clairvedcasehistrypersonalinfo.objects.create(
                    age=age,
                    weight=weight,
                    height=height,
                    clrcasehistory_id=case_history.id,
                    mrno_id=patient_id
                )

            selected_medicines_json = request.POST.get("selectedMedicinesInput")
            selected_medicines = json.loads(selected_medicines_json) if selected_medicines_json else []
            prescriptions = []
            for medicine in selected_medicines:
                try:
                    prescriptions.append(
                        clairvedaPrescription(
                            case_history=case_history,
                            medicine_name=medicine.get("name", ""),
                            count=int(medicine.get("count", 1)),
                            dosage=medicine.get("dosage", ""),
                            prescribeddoctor_id=prepared_by,  # or doctor_id if doctor prescribes
                            physicalstock_id=medicine.get("physicalstockid")
                        )
                    )
                except Exception as med_err:
                    logger.warning(f"Skipping invalid medicine: {medicine} due to {str(med_err)}")

            if prescriptions:
                clairvedaPrescription.objects.bulk_create(prescriptions)
            
            # Insert into nextreatmentdetailsmaster
            master_entry = nextreatmentdetailsmaster.objects.create(
                MR_Number_id=patient_id,
                prepairedstaff_id=request.session.get('staffid'),
                branchstff_id=brchid,
                casehistoryid_id=case_history.id
            )
            # Insert multiple treatment details
            treatments_json = request.POST.get("selected_treatments")
            treatments = json.loads(treatments_json) if treatments_json else []
            for treatment in treatments:
                treatment_date_str = treatment.get("treatment_date", "").strip()
                treatment_time = treatment.get("treatment_time", "").strip()
                try:
                    treatment_date = datetime.strptime(treatment_date_str, "%Y-%m-%d").date() if treatment_date_str else date.today()
                except ValueError:
                    return JsonResponse({"success": False,"error": f"Invalid date format for treatment: {treatment_date_str}"}, status=400)
                handled_by_list = treatment.get("handled_by",[])
                given_by_list = treatment.get("given_by",[])
                handled_by_str = ",".join(map(str, handled_by_list)) if isinstance(handled_by_list, list) else ""
                given_by_str = ",".join(map(str, given_by_list)) if isinstance(given_by_list, list) else ""
                nextreatmentdetailschild.objects.create(
                    nexmaster=master_entry,
                    MR_Number_id=patient_id,
                    tratmntid_id=treatment["id"],
                    treatment_date=treatment_date,
                    handled_by=handled_by_str,
                    given_by=given_by_str,
                    treatmenttime=treatment_time
                )
            return JsonResponse({"success": True, "message": "Case history added successfully."}, status=200)
            # return JsonResponse({"success": True, "message": "Case history added successfully."}, status=200)
        except Exception as e:
            logger.error(f"Error processing request for MRNO {patient_id}: {str(e)}")
            casehistoryErrorLog.objects.create(
                error_message=str(e),
                related_mrno=patient_id,
                staff_id=request.session.get('staffid')
            )
            return JsonResponse({"success": False, "error": "An error occurred while saving data."}, status=400)

    try:
        # Validate session
        staff_designation = request.session.get('loginstaffdesign')
        if not staff_designation:
            return redirect('staff_login')
        # Fetch required data
        diets = Diet.objects.all()
        staff_id = request.session.get('staffid')
        allocated_staff = Staffallocation.objects.filter(Designation_Name__in=["2", "3", "5", "6","9","14"])
        # select_related('Staff')
        context = {
            'stdesign': staff_designation,
            'stffdt': allocated_staff,
            'st': staff_id,
            'diets': diets,
        }
        return render(request,"casehistoryinsert.html", context)
    except ObjectDoesNotExist:
        messages.error(request, "Menu Management details not found. Please contact the admin.")
        return redirect('error_page')

    except Exception as e:
        messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin for assistance.")
        return redirect('error_page')

def search_treatmentcasehistory(request):
    query = request.GET.get('query', '')

    if query:
        treatments = Treatment_master.objects.filter(Treatment_name__icontains=query).values('id', 'Treatment_name', 'Rate', 'Description')
        return JsonResponse(list(treatments), safe=False)

    return JsonResponse([], safe=False)

from datetime import date

def case_history_list(request):
    logged_in_staff = request.session.get('staffid')
    logstaffbrid = request.session.get('branchid')
    stdesign_id = request.session.get('loginstaffdesign')

    if not stdesign_id:
        return redirect('staff_login')

    # 🔹 Check designation
    try:
        designation = Designation.objects.get(id=stdesign_id)
        is_superadmin = designation.Designation_Name.lower() == 'superadmin'
    except Designation.DoesNotExist:
        is_superadmin = False

    case_histories = []
    follow_up_data = {}

    # 🔹 Capture date range
    start_date = None
    end_date = None

    if request.method == 'POST':
        query = request.POST.get('query', '').strip()
        start_date = request.POST.get('start_date')
        end_date = request.POST.get('end_date')

        if query:
            patients = Patient_details.objects.filter(
                Q(Patient_Name__icontains=query) |
                Q(contactno__icontains=query) |
                Q(Medical_Record_Number__icontains=query),
                deleted=False
            )
            if is_superadmin:
                case_histories = clairvedaCaseHistory.objects.filter(patient__in=patients)
            else:
                case_histories = clairvedaCaseHistory.objects.filter(
                    patient__in=patients,
                    patient__Branch_Name=logstaffbrid
                )
        else:
            filters = {
                "patient__deleted": False,
                "deletestatus": False,
            }
            if not is_superadmin:
                filters["patient__Branch_Name"] = logstaffbrid

            # 🔹 Date filtering (works for both DateField & DateTimeField)
            if start_date and end_date:
                filters["created_at__range"] = (start_date, end_date)
            elif start_date:
                filters["created_at__gte"] = start_date
            elif end_date:
                filters["created_at__lte"] = end_date

            case_histories = clairvedaCaseHistory.objects.filter(**filters).prefetch_related(
                'prescriptions', 'follow_ups'
            )
    else:
        filters = {
            "patient__deleted": False,
            "deletestatus": False,
        }
        if  is_superadmin:
            filters["created_at"] = date.today()
              # ✅ works for DateField
        else:
            filters["patient__Branch_Name"] = logstaffbrid
            filters["created_at"] = date.today()
            

        case_histories = clairvedaCaseHistory.objects.filter(**filters).prefetch_related(
            'prescriptions', 'follow_ups'
        )

    # 🔹 Process follow-ups
    for case_history in case_histories:
        follow_ups = case_history.follow_ups.all()
        prescriptions = case_history.prescriptions.all()

        follow_up_entries = []
        for follow_up in follow_ups:
            followup_prescriptions = follow_up.prescriptions.all() if hasattr(follow_up, 'prescriptions') else []
            followup_reports = clairvedaFollowUpReport.objects.filter(follow_up=follow_up)

            follow_up_entries.append({
                'follow_up_date': follow_up.created_at,
                'notes': follow_up.notes,
                'prescriptions': followup_prescriptions,
                'handledbystaff': follow_up.handledbystaff.all() if hasattr(follow_up.handledbystaff, 'all') else [],
                'reports': followup_reports,
            })

        follow_up_data[case_history.id] = follow_up_entries

    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')

    context = {
        'case_histories': case_histories,
        'follow_up_data': follow_up_data,
        'logged_in_staff': logged_in_staff,
        'logstaffbrid': logstaffbrid,
        'stdesign': stdesign,
        'start_date': start_date,
        'end_date': end_date,
    }
    return render(request, 'case_history_list.html', context)
