def save_followup(request):
    if request.method != "POST":
        return JsonResponse({"success": False, "error": "Invalid request method."}, status=405)

    try:
        case_history_id = request.POST.get("case_history_id")
        patient_id = request.POST.get("ptid")
        notes = request.POST.get("progress_note", "").strip()

        case_history = clairvedaCaseHistory.objects.get(pk=case_history_id)
        patient = Patient_details.objects.get(pk=patient_id)

        # 🔹 Create follow-up
        followup = clairvedaFollowUp.objects.create(
            case_history=case_history,
            notes=notes,
            handledbystaff_id=request.session.get("staffid")
        )

        # 🔹 Treatments
        treatments = request.POST.getlist("treatment_id[]")
        counts = request.POST.getlist("count[]")
        dates = request.POST.getlist("date[]")

        has_date_field = "date" in [f.name for f in casehistorytreatmentplan._meta.fields]

        for tr_id, cnt, dt in zip(treatments, counts, dates):
            if tr_id:
                casehistorytreatmentplan.objects.create(
                    patient_id=patient_id,
                    case_history=case_history,
                    followup=followup,
                    treatment_id=tr_id,
                    count=cnt or None,
                    date=dt or None if has_date_field else None,
                    prepairedby=getattr(request.user, "staffdetails", None)
                )

        # 🔹 Prescriptions
        medicine_ids = request.POST.getlist("medicine_id[]")
        medicines = request.POST.getlist("medicine[]")
        days = request.POST.getlist("days[]")
        mornings = request.POST.getlist("morning[]")
        noons = request.POST.getlist("noon[]")
        nights = request.POST.getlist("night[]")
        diet_timings = request.POST.getlist("diet_timing[]")
        guidelines = request.POST.getlist("guidelines[]")
        stockids = request.POST.getlist("stock_id[]")
        qtys = request.POST.getlist("qty[]")

        for med_id, name, day, morn, noon, night, diet, guide, stock, qty in zip(
            medicine_ids, medicines, days, mornings, noons, nights, diet_timings, guidelines, stockids, qtys
        ):
            if not med_id and not name.strip():
                continue

            try:
                qtyprescriped = int(qty)
            except (TypeError, ValueError):
                qtyprescriped = 1

            Prescriptionnew.objects.create(
    case_history=case_history,
    followup=followup,
    medicine_name=name.strip(),   # ✅ correct field
    noofdays=day or None,
    moringtime=morn or "",
    noontime=noon or "",
    nighttime=night or "",
    beforeorafterdiet=diet or "",
    medicineguideline=guide or "",
    physicalstock_id=stock or None,   # ✅ correct FK
    prescribeddoctor_id=request.session.get("staffid"),  # ✅ correct FK
    patient_id=patient_id,  # ✅ correct FK
    qtyprescriped=int(qty) if qty and qty.isdigit() else 1
)

        return redirect("case_history_list")  # ✅ safer for forms

    except clairvedaCaseHistory.DoesNotExist:
        return JsonResponse({"success": False, "error": "Case history not found."}, status=404)
    except Patient_details.DoesNotExist:
        return JsonResponse({"success": False, "error": "Patient not found."}, status=404)
    except Exception as e:
        return JsonResponse({"success": False, "error": str(e)}, status=500)
