@login_required
def edit_case_history(request):
    if request.method == 'POST':
        try:
            case_history_id = request.POST.get('ids')
            print(f"Editing case history ID: {case_history_id}")
            case_history = get_object_or_404(clairvedaCaseHistory, id=case_history_id)
            
            # Update case history fields - IMPORTANT: Use present_complaint as chief_complaint
            present_complaint = request.POST.get('present_complaint')
            
            case_history.chief_complaint = present_complaint
            # case_history.present_complaint = present_complaint
            case_history.final_diagnosis = request.POST.get('final_diagnosis')
            case_history.status = request.POST.get('status')
            
            follow_up_date = request.POST.get('follow_up_date')
            if follow_up_date:
                try:
                    from datetime import datetime
                    case_history.follow_up_date = datetime.strptime(follow_up_date, '%Y-%m-%d').date()
                except ValueError:
                    try:
                        case_history.follow_up_date = datetime.strptime(follow_up_date, '%d-%m-%Y').date()
                    except ValueError:
                        case_history.follow_up_date = date.today()
            
            case_history.save()
            print("Case history saved successfully")
            
            # Return the updated complaint data for frontend dynamic update
            return JsonResponse({
                'success': True,
                'message': 'Complaint updated successfully',
                'updated_complaint': {
                    'id': case_history.id,
                    'chief_complaint': case_history.chief_complaint,
                    'present_complaint': case_history.present_complaint,
                    'final_diagnosis': case_history.final_diagnosis,
                    'status': case_history.status,
                    'created_at': case_history.created_at.isoformat() if case_history.created_at else None,
                    'follow_up_date': case_history.follow_up_date.isoformat() if case_history.follow_up_date else None,
                }
            })
            
        except Exception as e:
            logger.error(f"Error updating case history {case_history_id}: {str(e)}")
            print(f"Error: {str(e)}")
            return JsonResponse({
                'success': False,
                'error': str(e)
            })
    
    return JsonResponse({'success': False, 'error': 'Invalid request method'})



