def get_assigned_doctor(request):
    mrno = request.GET.get('mrno')
    if not mrno:
        return JsonResponse({'success': False, 'error': 'MR Number is required'}, status=400)
    
    try:
        # Fetch the latest appointment with doctor details for the given MR Number
        appointment = Appointments.objects.select_related('Doctor_Name').filter(MR_Number_id=mrno).latest('Appointment_date')
        assigned_doctor = appointment.Doctor_Name  # The currently assigned doctor
        
        # Fetch all doctors with specific designations (4, 5, 6)
        doctor_allocations = Staffallocation.objects.filter(
             Designation_Name__id__in=["2", "3", "5", "6","9","14"],  # Filter based on designation IDs
            Staff__deleted=False  # Ensure the staff member is not deleted
        ).select_related('Staff')
        
        # Create a list of doctor data from the filtered allocations
        doctor_list = [
            {
                'id': allocation.Staff.id,
                'full_name': f"{allocation.Staff.Staff_firstname} {allocation.Staff.Staff_lastname}"
            }
            for allocation in doctor_allocations
        ]
        
        return JsonResponse({
            'success': True,
            'assigned_doctor': {
                'id': assigned_doctor.id,
                'full_name': f"{assigned_doctor.Staff_firstname} {assigned_doctor.Staff_lastname}"
            },
            'doctors': doctor_list  # List of all filtered doctors
        })
    except Appointments.DoesNotExist:
        # If no doctor is assigned, still return all filtered doctors
        doctor_allocations = Staffallocation.objects.filter(
            Designation_Name__id__in=["2", "3", "5", "6","9","14"],
            Staff__deleted=False
        ).select_related('Staff')
        
        doctor_list = [
            {
                'id': allocation.Staff.id,
                'full_name': f"{allocation.Staff.Staff_firstname} {allocation.Staff.Staff_lastname}"
            }
            for allocation in doctor_allocations
        ]
        
        return JsonResponse({'success': True, 'assigned_doctor': None, 'doctors': doctor_list})
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)
def calculate_daily_data(selected_date):
    """Helper function to calculate daily report data."""
    walkins_count = Appointments.objects.filter(Appointment_date=selected_date).count()
    new_patient_count = Patient_details.objects.filter(Date=selected_date).count()
    # clairvedaCaseHistory.objects.filter(status='Consultation', created_at=selected_date).count()
    follow_up_count = Appointments.objects.filter(status="Followup").count()
    # clairvedaFollowUp.objects.filter(nextfollowupdate=selected_date).count()
    treatment_income_data = treatmentinvoicemaster.objects.filter(currentdate=selected_date)
    consultation_income_data = invoicemaster.objects.filter(currentdate=selected_date)
    med_income_data = invoicechild.objects.filter(currentdate=selected_date)
    treatment_income_total = treatment_income_data.aggregate(total_income=Sum('total'))['total_income'] or 0
    consultation_income_total = consultation_income_data.aggregate(total_income=Sum('total'))['total_income'] or 0
    med_income_total = med_income_data.aggregate(total_income=Sum('sutotal'))['total_income'] or 0
    total_tax_collected = med_income_data.aggregate(totaltax_income=Sum('taxamount'))['totaltax_income'] or 0
    # (treatment_income_data.aggregate(total=Sum('tax'))['total'] or 0) + \
    #                   (consultation_income_data.aggregate(total=Sum('tax'))['total'] or 0)
    daily_closing_total = treatment_income_total  + med_income_total + total_tax_collected
  
    return {
      
        'walkins_count': walkins_count,
        'new_patient_count': new_patient_count,
        'follow_up_count': follow_up_count,
        'treatment_income_total': treatment_income_total,
        'consultation_income_total': consultation_income_total,
        'med_income_total': med_income_total,
        'total_tax_collected': total_tax_collected,
        'daily_closing_total': daily_closing_total,
    }

def dailyinc(request):
    selected_date = request.GET.get('report_date', str(date.today()))
    try:
        selected_date = date.fromisoformat(selected_date)  # Ensure valid date object
    except ValueError:
        selected_date = date.today()
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
                return redirect('staff_login')
    data = calculate_daily_data(selected_date)
    context = {**data, 'selected_date': selected_date.isoformat(),'stdesign':stdesign}  # Pass date as string for the URL
    return render(request, 'dailyincome.html', context)


def generate_income_graph(request, selected_date):
    try:
        selected_date = date.fromisoformat(selected_date)
    except ValueError:
        selected_date = date.today()
    data = calculate_daily_data(selected_date)
    total_income = data['treatment_income_total'] + data['total_tax_collected'] + data['med_income_total']
    
    graph_data = {
        'Total Income': round(total_income, 2),  # Round to 2 decimal places
        'Med Income': data['med_income_total'],
        'Tax Income': data['total_tax_collected'],
        'Treatment Income': data['treatment_income_total'],  # Fixed key formatting
    }
    return JsonResponse(data=graph_data)
