def fetch_reports(request):
    month = request.POST.get('month', datetime.now().strftime('%Y-%m'))
    year, month = map(int, month.split('-'))  # Convert year and month to integers
    # Get the number of days in the specified month
    _, num_days_in_month = calendar.monthrange(year, month)
    case_histories = Appointments.objects.filter(
       Appointment_date__year=year,
    Appointment_date__month=month,
    )
    # Follow-ups statistics
    follow_ups = Appointments.objects.filter(status="Followup",
         Appointment_date__year=year,
            Appointment_date__month=month,
    )
    # Invoice statistics
    invoices = invoicechild.objects.filter(
        currentdate__year=year,
        currentdate__month=month
    )
    treatment_income_data=treatmentinvoicemaster.objects.filter(
        currentdate__year=year,
        currentdate__month=month
    )
    # Aggregate data for the month
    total_walk_ins = case_histories.count()
    total_new_consulted = case_histories.filter(status="Consultation").count()
    total_follow_up = follow_ups.count()
    total_meds_income = invoices.aggregate(Sum('sutotal'))['sutotal__sum'] or 0
    total_tax_collected = invoices.aggregate(Sum('taxamount'))['taxamount__sum'] or 0
    treatment_income = treatment_income_data.aggregate(total_income=Sum('total'))['total_income'] or 0
    total_income = total_meds_income + total_tax_collected + treatment_income
    daily_reports = []
    for day in range(1, num_days_in_month + 1):  # Loop through valid days of the month
        daily_case_histories = case_histories.filter(
            Appointment_date__year=year,
            Appointment_date__month=month,
            Appointment_date__day=day
        )
        daily_invoices = invoices.filter(
            currentdate__year=year,
            currentdate__month=month,
            currentdate__day=day
        )
        daily_treatment = treatment_income_data.filter(
            currentdate__year=year,
            currentdate__month=month,
            currentdate__day=day
        )
        daily_walk_ins = daily_case_histories.count()
        daily_meds_income = daily_invoices.aggregate(Sum('sutotal'))['sutotal__sum'] or 0
        daily_tax_collected = daily_invoices.aggregate(Sum('taxamount'))['taxamount__sum'] or 0
        daily_treatment_income =  daily_treatment.aggregate(total_income=Sum('total'))['total_income'] or 0
        daily_incometot = daily_meds_income + daily_tax_collected + daily_treatment_income
        daily_income=round(daily_incometot, 2)
        daily_reports.append({
            'date': f"{year}-{str(month).zfill(2)}-{str(day).zfill(2)}",
            'daily_walk_ins': daily_walk_ins,
            'daily_meds_income': daily_meds_income,
            'daily_tax_collected': daily_tax_collected,
            'daily_treatment_income': daily_treatment_income,
            'daily_income': daily_income
        })
    # Context for the template 
    readable_month = datetime(year, month, 1).strftime('%B %Y')
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
                return redirect('staff_login')
    context = {
        'stdesign':stdesign,
        'readable_month': readable_month, 
        'month': f"{year}-{str(month).zfill(2)}",
        'daily_reports': daily_reports,
        'total_walk_ins': total_walk_ins,
        'total_new_consulted': total_new_consulted,
        'total_follow_up': total_follow_up,
        'total_meds_income': total_meds_income,
        'total_tax_collected': total_tax_collected,
        'treatment_income': treatment_income,
        'total_income': total_income,
    }
    return render(request, 'monthreport.html', context)
    

