def get_staff_by_branch_and_designation(request):
    """
    Get staff members filtered by branch, department, and designation
    """
    branch_id = request.GET.get('branch')
    department_id = request.GET.get('department')
    designation_id = request.GET.get('designation')
    
    try:
        staff_allocations = Staffallocation.objects.select_related(
            'Staff', 'Department_Name', 'Designation_Name'
        ).filter(
            Status='Active'
        )
        
        if branch_id:
            staff_allocations = staff_allocations.filter(Branch_Name_id=branch_id)
        
        if department_id:
            staff_allocations = staff_allocations.filter(Department_Name_id=department_id)
        
        if designation_id:
            staff_allocations = staff_allocations.filter(Designation_Name_id=designation_id)
        
        staff_data = []
        seen_staff_ids = set()
        
        for allocation in staff_allocations:
            staff = allocation.Staff
            if staff and staff.id not in seen_staff_ids and not staff.deleted:
                seen_staff_ids.add(staff.id)
                staff_data.append({
                    'Staff_id': staff.id,
                    'Staff_firstname': staff.Staff_firstname,
                    'Staff_lastname': staff.Staff_lastname or '',
                    'deprt': allocation.Department_Name.Department_Name if allocation.Department_Name else ''
                })
        
        return JsonResponse(staff_data, safe=False)
        
    except Exception as e:
        return JsonResponse([], safe=False)



@login_required
def smilee_kannur_appointment(request):
    idmngmnt = request.GET.get('menumanagement_id')
    request.session['onlineappmngid'] = idmngmnt

    if not idmngmnt:
        messages.error(request, "Unable to retrieve Menu Management details.")
        return redirect('error_page')

    mangmntobj = get_object_or_404(menumanagement, id=idmngmnt)

    # ==========================================================
    # POST : SAVE SMILEE KANNUR APPOINTMENT
    # ==========================================================
    if request.method == 'POST':
        try:
            addmrnumber = request.POST.get('mrnum')
            addbranch = request.POST.get('branch')
            adddocname = request.POST.get('docname')
            addappoinmentdate = request.POST.get('apntdate')
            addremarks = request.POST.get('remarks')
            addcontactnumber = request.POST.get('contactnum')
            add_visit_type = request.POST.get('visit_type', 'Consultation')
            payment_status = request.POST.get('pstatus')  # NEW: Get payment status from form
            
            # ==========================================================
            # FEE LOGIC - FETCH FROM AppointmentFee TABLE ONLY
            # ==========================================================
            fee = 0
            fee_found = False
            
            try:
                # Get fee from AppointmentFee table
                fee_obj = AppointmentFee.objects.filter(
                    branch_id=addbranch,
                    doctor_id=adddocname,
                    visit_type=add_visit_type,
                    is_active=True
                ).first()
                
                if fee_obj:
                    fee = float(fee_obj.fee_amount)
                    fee_found = True
                else:
                    messages.error(
                        request, 
                        f"Fee not configured for this doctor and visit type. Please contact admin."
                    )
                    return redirect(f"{reverse('smilee_kannur_appointment')}?menumanagement_id={idmngmnt}")
                    
            except Exception as e:
                messages.error(request, f"Error fetching fee: {str(e)}")
                return redirect(f"{reverse('smilee_kannur_appointment')}?menumanagement_id={idmngmnt}")

            if not addmrnumber or not addbranch or not adddocname:
                messages.error(request, "Patient, Branch and Doctor are required.")
                return redirect(f"{reverse('smilee_kannur_appointment')}?menumanagement_id={idmngmnt}")

            if not payment_status:  # NEW: Validate payment status
                messages.error(request, "Payment status is required.")
                return redirect(f"{reverse('smilee_kannur_appointment')}?menumanagement_id={idmngmnt}")

            branch_id = int(addbranch)
            doctor_id = int(adddocname)
            today = date.today()
            todate = today.strftime("%Y%m%d")

            patient_obj = Patient_details.objects.filter(id=addmrnumber).first()
            if not patient_obj:
                messages.error(request, "Patient details not found.")
                return redirect(f"{reverse('smilee_kannur_appointment')}?menumanagement_id={idmngmnt}")

            # ==========================================================
            # TOKEN GENERATION (SK Prefix)
            # ==========================================================
            with transaction.atomic():
                last_entry = Appointments.objects.select_for_update().filter(
                    Current_Date=today,
                    Branch_id=branch_id
                ).order_by('-id').first()

                if last_entry and last_entry.Tokenno:
                    try:
                        # Extract the sequence number from the token
                        # Token format: SKYYYYMMDDXXX
                        last_seq = int(last_entry.Tokenno[-3:])
                        refnid = last_seq + 1
                    except (ValueError, IndexError):
                        refnid = 1
                else:
                    refnid = 1

                token_prefix = "SK"  # Smilee Kannur
                token_no = f"{token_prefix}{todate}{refnid}"

                appointment_data = {
                    'Tokenno': token_no,
                    'MR_Number_id': addmrnumber,
                    'Branch_id': branch_id,
                    'Doctor_Name_id': doctor_id,
                    'Appointment_date': datetime.strptime(addappoinmentdate, "%Y-%m-%d").date(),
                    'contactno': addcontactnumber,
                    'status': add_visit_type,
                    'Fee': str(fee),
                    'Remark': addremarks,
                    'Current_Date': today,
                }

                appointment = Appointments.objects.create(**appointment_data)

                # ==========================================================
                # CREATE INVOICE ONLY FOR NON-REVISIT APPOINTMENTS
                # ==========================================================
                if add_visit_type != 'Revisit':
                    hospital_obj = Hospitaldetails.objects.first()
                    if not hospital_obj:
                        messages.error(request, "Hospital details not found.")
                        return redirect('error_page')

                    staff_id = request.session.get("staff_id")
                    patient_name = patient_obj.Patient_Name
                    patient_phone = patient_obj.contactno or addcontactnumber

                    invoice = appointmentinvoicemaster.objects.create(
                        hospitalname=hospital_obj,
                        branch_id=branch_id,
                        Mrno_id=addmrnumber,
                        treatmentInvoicenumber=token_no,
                        currentdate=datetime.strptime(addappoinmentdate, "%Y-%m-%d").date(),
                        subtotal=float(fee),
                        tax=0,
                        shipping=0,
                        total=float(fee),
                        patientname=patient_name,
                        patientphno=patient_phone,
                        discount="0",
                        preparedby_id=staff_id,
                        consultationfee=str(fee),
                        consultationfeecumregfee=str(fee),
                        cancelstatus=False,
                        payementmode=payment_status,  # UPDATED: Use the selected payment status
                    )
                    
                    messages.success(request, f"Appointment booked successfully! Token: {token_no} | Fee: ₹{fee}")
                    return redirect(f"{reverse('appointmentinvoice')}?invoice_id={invoice.id}")
                else:
                    # For Revisit appointments - no invoice created
                    messages.success(request, f"Revisit appointment booked successfully! Token: {token_no}")
                    return redirect(f"{reverse('smilee_kannur_appointment')}?menumanagement_id={idmngmnt}")

        except Exception as e:
            messages.error(request, f"Error booking appointment: {str(e)}")
            return redirect('error_page')

    # ==========================================================
    # GET : LOAD FORM
    # ==========================================================
    try:
        today = date.today()
        todate = today.strftime("%Y%m%d")
        staff_alloc_id = request.session.get('loginstaff')
        
        # You can adjust this filter based on your actual branch names/IDs
        branchobj = Branch.objects.filter(
            Q(Branch_Name__icontains="Smilee") | Q(id=29),
            inactive=False
        )
        
        if not branchobj.exists():
            # Fallback to all branches if no Smilee branch found
            branchobj = Branch.objects.filter(inactive=False)
            print("No Smilee branch found, using all branches")  # For debugging

        # Token Preview - Use the first Smilee branch or first available branch
        staff_branch_id = branchobj.first().id if branchobj.exists() else None
        
        # Get last token for token preview
        last_entry = None
        if staff_branch_id:
            last_entry = Appointments.objects.filter(
                Current_Date=today, 
                Branch_id=staff_branch_id
            ).order_by('-id').first()
        
        if last_entry and last_entry.Tokenno and last_entry.Tokenno.startswith('SK'):
            try:
                refnid = int(last_entry.Tokenno[-3:]) + 1
            except (ValueError, IndexError):
                refnid = 1
        else:
            refnid = 1
            
        tk_id = f"SK{todate}{refnid:03d}"

        appointment_fees = []
        fees = AppointmentFee.objects.filter(
            is_active=True
        ).select_related('doctor', 'branch')
        
        print(f"Found {fees.count()} active fees")  
        
        for fee in fees:
            appointment_fees.append({
                'branch_id': fee.branch.id if fee.branch else None,
                'doctor_id': fee.doctor.id if fee.doctor else None,
                'visit_type': fee.visit_type,
                'fee_amount': float(fee.fee_amount)
            })

        # Debug print
        print(f"Appointment fees JSON: {appointment_fees}")

        context = {
            'idmngmnt': idmngmnt,
            'tk_id': tk_id,
            'branchobj': branchobj,
            'onlmngview': mangmntobj.view,
            'onlmngadd': mangmntobj.add,
            'onlmngedit': mangmntobj.edit,
            'onlmngdelete': mangmntobj.delete,
            'is_smilee_page': True,
            'appointment_fees_json': json.dumps(appointment_fees),
        }
        return render(request, "smilee_kannur_appointment.html", context)

    except Exception as e:
        messages.error(request, f"Error loading page: {str(e)}")
        print(f"Error in smilee_kannur_appointment GET: {str(e)}")  # For debugging
        return redirect('error_page')

  


@login_required  
def room(request):
    idmngmnt = request.GET.get('menumanagement_id')

    # Validate Menu Management ID
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided. Please contact the admin.")
        return redirect('error_page')

    # Check if user is logged in
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')

    if request.method == 'POST':
        # Retrieve form data
        addbranchname = request.POST.get('branchname')
        addfloornum = request.POST.get('floornumber')
        addblocknum = request.POST.get('blocknumber')
        addroomnum = request.POST.get('roomnumber', None)  # Only for Room
        addroomtype = request.POST.get('roomtype', None)  # Only for Room
        addbedtype = request.POST.get('bedtype')
        addrate = request.POST.get('rate')
        accommodation_type = request.POST.get('accommodation')  # Ward or Room
        wardbedno = request.POST.get('bednumber', None)  # Only for Ward
        addnursingcharge = request.POST.get('nursingcharge', None)
        addwaterelectricitycharge = request.POST.get('waterelectricitycharge', None)

        try:
            branch_id = int(addbranchname)

            # Create room object
            objroom = Room_details(
                branchidrm_id=branch_id,
                Floorno=addfloornum,
                Blockno=addblocknum,
                Roomno=addroomnum if accommodation_type == "Room" else None,
                Room_type=addroomtype if accommodation_type == "Room" else None,
                wardorroom=accommodation_type,
                bed_type=addbedtype,
                rate=addrate,
                wardbedno=wardbedno if accommodation_type == "Ward" else None,
                nursing_charge=addnursingcharge if accommodation_type == "Room" and addnursingcharge else None,
                water_electricity_charge=addwaterelectricitycharge if accommodation_type == "Room" and addwaterelectricitycharge else None
            )
            objroom.save()
            messages.success(request, "Room details saved successfully.")
            return redirect(f"{reverse('room')}?menumanagement_id={idmngmnt}")

        except ValueError:
            messages.error(request, "Invalid branch selection.")
        except Exception as e:
            messages.error(request, f"Error saving room details: {str(e)}. Please contact the admin.")

        return redirect('error_page')

    else:
        try:
            # Fetch menu management object
            roomobj = get_object_or_404(menumanagement, id=idmngmnt)

            # Store menu permissions in session
            request.session['roomobjmngid'] = idmngmnt
            request.session['roomobjmngadd'] = roomobj.add
            request.session['roomobjmngview'] = roomobj.view
            request.session['roomobjmngedit'] = roomobj.edit
            request.session['roomobjmngdelete'] = roomobj.delete

            # Fetch branches for dropdown
            branchobj = Branch.objects.all()

            context = {
                'branchobj': branchobj,
                'idmngmnt': idmngmnt,
                'stdesign': stdesign,
                'roomadd': request.session.get('roomobjmngadd'),
                'roomview': request.session.get('roomobjmngview'),
            }
            return render(request, "room.html", context)

        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin.")

        return redirect('error_page')
   
