@login_required
def editroom(request):
    if request.method == 'POST':
        idrm = request.POST.get('roomid')
        if not idrm:
            messages.error(request, "Room ID is missing.")
            return redirect('error_page')

        idmngmnt = request.session.get('roomobjmngid')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided. Please contact the admin to grant necessary permissions.")
            return redirect('error_page')

        try:
            objroom = Room_details.objects.get(id=idrm)

            # Fetch form values safely
            addbranchname = request.POST.get('branchname')
            addfloornum = request.POST.get('floornumber')
            addblocknum = request.POST.get('blocknumber')
            accommodation_type = request.POST.get('accommodation')  # Ward or Room
            addbedtype = request.POST.get('bedtype')
            addrate = request.POST.get('rate')
            addavailability = request.POST.get('is_available') == '1'  # Convert string to boolean
            branch1 = int(addbranchname)
            addnursingcharge = request.POST.get('nursingcharge', None)
            addwaterelectricitycharge = request.POST.get('waterelectricitycharge', None)
            
            # Update common fields
            objroom.branchidrm_id = branch1
            objroom.Floorno = addfloornum
            objroom.Blockno = addblocknum
            objroom.bed_type = addbedtype
            objroom.rate = addrate
            objroom.is_available = addavailability
            objroom.wardorroom = accommodation_type
           
            if accommodation_type == "Room":
                objroom.Roomno = (request.POST.get('roomnumber') or "").strip()
                objroom.Room_type = (request.POST.get('roomtype') or "").strip()
                objroom.wardbedno = None  # Clear ward-related data if switching to Room
                objroom.nursing_charge = addnursingcharge if addnursingcharge else None
                objroom.water_electricity_charge = addwaterelectricitycharge if addwaterelectricitycharge else None
            else:  # If it's a Ward
                objroom.Roomno = None
                objroom.Room_type = None
                objroom.wardbedno = (request.POST.get('wardbedno') or "").strip()
                objroom.nursing_charge = None
                objroom.water_electricity_charge = None

            objroom.save()
            messages.success(request, "Room/Ward edited successfully!")
            return redirect(f"{reverse('room')}?menumanagement_id={idmngmnt}")

        except ObjectDoesNotExist:
            messages.error(request, "Room/Ward not found.")
        except ValueError:
            messages.error(request, "Invalid input provided.")
        except Exception as e:
            messages.error(request, f"An error occurred: {str(e)}")
        return redirect(f"{reverse('room')}?menumanagement_id={idmngmnt}")
    else:
        idmngmnt = request.session.get('roomobjmngid')
        if not idmngmnt:
            messages.error(request, "Menu Management ID not provided. Please contact the admin.")
            return redirect('error_page')
        idenq = request.GET.get('ids')
        if not idenq:
            messages.error(request, "Room ID is missing.")
            return redirect('error_page')
        try:
            objedroom = Room_details.objects.get(id=idenq)
        except ObjectDoesNotExist:
            messages.error(request, "Room/Ward not found.")
            return redirect(f"{reverse('room')}?menumanagement_id={idmngmnt}")
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
            return redirect('staff_login')
        branchobj = Branch.objects.all()
        context = {
            'idmngmnt': idmngmnt,
            'objedroom': objedroom,
            'stdesign': stdesign,
            'branchobj': branchobj,
            'roomview': request.session.get('roomobjmngview'),
            'roomedit': request.session.get('roomobjmngedit'),
        }
        return render(request,"roomedit.html", context)
        
        
