def ip_patient_view(request):
    admission_id = request.GET.get('admission_id')
    idmngmnt = request.GET.get('menumanagement_id')
    if not admission_id:
        messages.error(request, "No admission ID provided.")
        return redirect('iptable')
    try:
        admission = ippatientadmission.objects.get(id=admission_id)
    except ippatientadmission.DoesNotExist:
        messages.error(request, "IP admission not found.")
        return redirect('iptable')
    patient = admission.MR_Number
    room_booking = ippatientroombooking.objects.filter(
        ipno=admission, bookingcancel=False
    ).order_by('-Admission_Date').first()
    treatment_qs = iptreatmentdetails.objects.filter(
        ipno=admission, deletedstatus=False
    ).select_related('tratmntid').order_by('treatment_date')
    treatments = [{
        'id': t.id,
        'tratmntid': t.tratmntid,
        'treatment_date': t.treatment_date,
        'treatmenttime': t.treatmenttime or '',
        'treatmentcount': t.treatmentcount,
    } for t in treatment_qs]

    medicine_qs = ipdailymedicine.objects.filter(
        ipno=admission
    ).select_related('medicinename').order_by('Current_Date')
    medicines = [{
        'id': m.id,
        'medicinename': m.medicinename,
        'Current_Date': m.Current_Date,
        'dosage': m.dosage or '',
        'count': m.count or '',
        'morning': '',
        'noon': '',
        'night': '',
        'medicinegiventime': m.medicinegiventime or '',
    } for m in medicine_qs]
    context = {
        'admission': admission,
        'patient': patient,
        'room_booking': room_booking,
        'treatments': treatments,
        'medicines': medicines,
        'idmngmnt': idmngmnt,
    }
    return render(request, 'ip_patient_view.html', context)

import logging
import traceback


logger = logging.getLogger(__name__)


def update_ip_treatment(request):
    try:
        data = json.loads(request.body.decode('utf-8'))
        treatment_id = data.get('id')
        from datetime import datetime
        treatment_date_str = data.get('treatment_date')
        treatment_count = data.get('treatment_count')

        try:
            treatment = iptreatmentdetails.objects.get(id=treatment_id, deletedstatus=False)
            if treatment_date_str:
                treatment.treatment_date = datetime.strptime(treatment_date_str, '%Y-%m-%d').date()
            if treatment_count is not None:
                treatment.treatmentcount = treatment_count
            treatment.save()
            return JsonResponse({"success": True, "message": "Treatment updated successfully."})
        except iptreatmentdetails.DoesNotExist:
            pass

        try:
            treatment = casehistorytreatmentplan.objects.get(id=treatment_id, deletedstatus=False)
            if treatment_date_str:
                treatment.date = datetime.strptime(treatment_date_str, '%Y-%m-%d').date()
            if treatment_count is not None:
                treatment.count = treatment_count
            treatment.save()
            return JsonResponse({"success": True, "message": "Treatment updated successfully."})
        except casehistorytreatmentplan.DoesNotExist:
            return JsonResponse({"success": False, "error": "Treatment record not found."})
    except json.JSONDecodeError:
        return JsonResponse({"success": False, "error": "Invalid JSON format."})
    except Exception as e:
        return JsonResponse({"success": False, "error": str(e)})


def update_ip_medicine(request):
    try:
        data = json.loads(request.body.decode('utf-8'))
        medicine_id = data.get('id')
        from datetime import datetime
        medicine_date_str = data.get('prescription_date')
        medicine_dosage = data.get('dosage')
        medicine_count = data.get('count')
        morning = data.get('morning')
        noon = data.get('noon')
        night = data.get('night')

        try:
            medicine = ipdailymedicine.objects.get(id=medicine_id)
            if medicine_date_str:
                medicine.Current_Date = datetime.strptime(medicine_date_str, '%Y-%m-%d').date()
            if medicine_dosage is not None:
                medicine.dosage = medicine_dosage
            if medicine_count is not None:
                medicine.count = medicine_count
            if morning is not None or noon is not None or night is not None:
                medicine.medicinegiventime = 'Morning: {} / Noon: {} / Night: {}'.format(
                    morning or '', noon or '', night or ''
                )
            medicine.save()
            return JsonResponse({"success": True, "message": "Medicine updated successfully."})
        except ipdailymedicine.DoesNotExist:
            pass

        try:
            medicine = Prescriptionnew.objects.get(id=medicine_id, deletedstatus=False)
            if medicine_date_str:
                medicine.prescriptiondate = datetime.strptime(medicine_date_str, '%Y-%m-%d').date()
            if medicine_dosage is not None:
                medicine.beforeorafterdiet = medicine_dosage
            if medicine_count is not None:
                medicine.qtyprescriped = medicine_count
            if morning is not None:
                medicine.moringtime = morning
            if noon is not None:
                medicine.noontime = noon
            if night is not None:
                medicine.nighttime = night
            medicine.save()
            return JsonResponse({"success": True, "message": "Medicine updated successfully."})
        except Prescriptionnew.DoesNotExist:
            return JsonResponse({"success": False, "error": "Medicine record not found."})
    except json.JSONDecodeError:
        return JsonResponse({"success": False, "error": "Invalid JSON format."})
    except Exception as e:
        return JsonResponse({"success": False, "error": str(e)})

        
def ippatient(request):
    staff_id = request.session.get('loginstaff')
    if not  staff_id:
        return redirect('staff_login')
    idmngmnt = request.session.get('ipmngid')
    is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest'
    if request.method == 'POST':
        mr_number_id = request.POST.get('ptid')
        bloodgroup = request.POST.get('bloodgroup') or 'Unknown'
        age = request.POST.get('age') or '0'
        contactnumber = request.POST.get('contactnumber') or 'N/A'
        diagns = request.POST.get('diagnosis') or 'Not specified'
        address = request.POST.get('address') or 'Not provided'
        gender = request.POST.get('gender') or 'Not disclosed'
        department_id = request.POST.get('department')
        doctor_id = request.POST.get('admitted_doctor')
        
        # Get staff branch
        try:
            staff_branch = Staffallocation.objects.get(id=staff_id)
            branch_id = staff_branch.Branch_Name_id
        except Staffallocation.DoesNotExist:
            messages.error(request, "Staff allocation not found.")
            return redirect('staff_login')
       

        if mr_number_id:
            mr_number_instance = get_object_or_404(Patient_details, id=mr_number_id)
            # Check for existing admission
            existing_admission = ippatientadmission.objects.filter(
                MR_Number_id=mr_number_instance.id,
                Admittedstatus=True
            ).first()
            if existing_admission:
                admission_date = existing_admission.Current_Date.strftime('%d-%m-%Y')
                if is_ajax:
                    return JsonResponse({'success': False, 'error': f"This patient was already admitted on {admission_date}."})
                messages.error(request, f"This patient was already admitted on {admission_date}.")
                return redirect(f"{reverse('ippatient')}?menumanagement_id={idmngmnt}")
            # Save admission
            today = date.today()
            today_str = today.strftime("%Y%m%d")
        
            # Get the last IP bill for today to generate sequential number
            last_bill = ippatientadmission.objects.filter(
                ipnumber__startswith=f"IPNo{today_str}"
            ).order_by('-ipnumber').first()
        
            if last_bill and last_bill.ipnumber:
                try:
                    # Extract the last 3 digits from the invoice number
                    last_number = int(last_bill.ipnumber[-3:])
                    new_number = last_number + 1
                except (ValueError, IndexError):
                    new_number = 1
            else:
                new_number = 1
        
            ip_invoice_number = f"IPNo{today_str}{new_number:03d}"
        
            # Debug: Print values to check
            print(f"Generated IP Number: {ip_invoice_number}")
            try:
                with transaction.atomic():
                    admission = ippatientadmission.objects.create(
                        MR_Number=mr_number_instance,
                        bloodgroup=bloodgroup,
                        age=age,
                        address=address,
                        contactnumber=contactnumber,
                        reasonforadmission=diagns,
                        Current_Date=date.today(),
                        Admittedstatus=True,
                        admittedbranch_id = branch_id,
                        ipnumber=ip_invoice_number,
                        department_id=department_id if department_id else None,  # Add department
                        admitted_doctor_id=doctor_id if doctor_id else None,
                        patient_name=request.POST.get('patient_name', ''),
                    gender=request.POST.get('gender', ''),
                    marital_status=request.POST.get('marital_status', ''),
                    nationality=request.POST.get('nationality', ''),
                    consultant_incharge=request.POST.get('consultant_incharge', ''),
                    
                    admission_category=request.POST.get('admission_category', ''),
                    booking_start_date=request.POST.get('booking_start_date') or None,
                    estimated_stay_days=request.POST.get('estimated_stay_days') or None,
                   
                    procedures_planned=request.POST.get('procedures_planned', ''),
                    surgical_procedure_date=request.POST.get('surgical_procedure_date') or None,
                    referral_source=request.POST.get('referral_source', ''),
  admission_datetime=datetime.now(),
                    )
                    _save_ip_patient_room_booking(admission, request, branch_id, contactnumber)
            except ValueError as exc:
                if is_ajax:
                    return JsonResponse({'success': False, 'error': str(exc)})
                messages.error(request, str(exc))
                return redirect(f"{reverse('ippatient')}?menumanagement_id={idmngmnt}")
            

            if is_ajax:
                return JsonResponse({'success': True, 'redirect': reverse('ippatient') + f'?menumanagement_id={idmngmnt}'})
            messages.success(request, 'Patient admission recorded successfully!')

            return redirect(f"{reverse('ippatient')}?menumanagement_id={idmngmnt}")


    # GET request
    try:
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided.")
            return redirect('error_page')
        ipobj = get_object_or_404(menumanagement, id=idmngmnt)
        request.session.update({
            'ipmngid': idmngmnt,
            'ipobjmngadd': ipobj.add,
            'ipobjmngview': ipobj.view,
            'ipobjmngedit': ipobj.edit,
            'ipobjmngdelete': ipobj.delete,
        })
        if not request.session.get('loginstaffdesign'):
            return redirect('staff_login')
        loggedbranchid = request.session.get('branchid')
        if not loggedbranchid:
                return redirect('staff_login')
        pktdt=packagemaster.objects.filter(branchdt=loggedbranchid,deleted="False")
        stdesign = request.session.get('loginstaffdesign')
        if not stdesign:
                return redirect('staff_login')
        # Get departments excluding the specified IDs (12,13,14,11,10,9,6,8,3)
        excluded_departments = [12, 13, 14, 11, 10, 9, 6, 8, 3,21]
        departments = Department.objects.exclude(id__in=excluded_departments)
        context={
        'stdesign':stdesign,
        'pktdt':pktdt,
            'branchobj': Branch.objects.all(),
            'unique_room_types': Room_details.objects.filter(Room_type__isnull=False).values_list('Room_type', flat=True).distinct(),
            'idmngmnt': idmngmnt,
            'stdesign': request.session['loginstaffdesign'],
            'ipadd': ipobj.add,
            'ipview': ipobj.view,

            'departments': departments,  
        }
        return render(request, "ippatient.html", context)

    except ObjectDoesNotExist:
        messages.error(request, "Menu Management details not found.")
        return redirect('error_page')
    except Exception as e:
        logger.error(f"Error in ippatient view: {e}\n{traceback.format_exc()}")
        messages.error(request, f"Unable to load details. Contact admin.")
        return redirect('error_page')

def view_occupied_rooms(request):
    staff_id = request.session.get('loginstaff')
    if not staff_id:
        return redirect('staff_login')

    try:
        staff_branch = Staffallocation.objects.get(id=staff_id)
        branch_id = staff_branch.Branch_Name_id
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff allocation not found.")
        return redirect('staff_login')

    staff_design_id = request.session.get('loginstaffdesign')
    try:
        designation = Designation.objects.get(id=staff_design_id)
        designation_name = designation.Designation_Name.lower()
    except Designation.DoesNotExist:
        designation_name = ''

    bookings = ippatientroombooking.objects.filter(
        bookingcancel=False,
        ipno__Admittedstatus=True
    ).select_related('ipno', 'MR_Number', 'room_number', 'bed_number', 'roomdt')

    if designation_name != 'superadmin':
        bookings = bookings.filter(branchdt=branch_id)

    occupied_rooms = []
    for b in bookings:
        patient_name = b.MR_Number.Patient_Name if b.MR_Number else 'N/A'
        patient_mrno = b.MR_Number.Medical_Record_Number if b.MR_Number else 'N/A'
        patient_phone = b.MR_Number.contactno if b.MR_Number else 'N/A'

        if b.accommodation_type and b.accommodation_type.lower() == 'ward':
            room_ref = b.bed_number or b.roomdt
            ward_name = room_ref.Blockno if room_ref else 'N/A'
            ward_number = room_ref.wardbedno if room_ref else 'N/A'
            room_name = f"Ward Bed {ward_number}"
        else:
            room_ref = b.room_number or b.roomdt
            ward_name = 'N/A'
            ward_number = 'N/A'
            room_name = f"{room_ref.Roomno} ({room_ref.Room_type})" if room_ref and room_ref.Roomno else 'N/A'

        occupied_rooms.append({
            'ward_name': ward_name,
            'ward_number': ward_number,
            'room_name': room_name,
            'patient_name': patient_name,
            'patient_mrno': patient_mrno,
            'patient_phone': patient_phone,
            'accommodation_type': b.accommodation_type or 'N/A',
            'booking_id': b.id,
            'ipno_id': b.ipno_id,
        })

    context = {
        'occupied_rooms': occupied_rooms,
    }
    return render(request, 'view_occupied_rooms.html', context)


@login_required
def get_treatment_details(request):
    booking_id = request.GET.get('booking_id')
    ipno_id = request.GET.get('ipno_id')

    patient_info = {
        'patient_name': 'N/A',
        'ward_name': 'N/A',
        'ward_number': 'N/A',
        'room_name': 'N/A',
        'accommodation_type': 'N/A',
    }

    # Fetch real patient info if booking exists
    if booking_id:
        try:
            booking = ippatientroombooking.objects.select_related(
                'ipno', 'MR_Number', 'room_number', 'bed_number', 'roomdt'
            ).get(id=booking_id)

            patient_name = booking.MR_Number.Patient_Name if booking.MR_Number else 'N/A'
            accommodation_type = booking.accommodation_type or 'N/A'

            if accommodation_type.lower() == 'ward':
                room_ref = booking.bed_number or booking.roomdt
                ward_name = room_ref.Blockno if room_ref else 'N/A'
                ward_number = room_ref.wardbedno if room_ref else 'N/A'
                room_name = f"Ward Bed {ward_number}"
            else:
                room_ref = booking.room_number or booking.roomdt
                ward_name = 'N/A'
                ward_number = 'N/A'
                room_name = f"{room_ref.Roomno} ({room_ref.Room_type})" if room_ref and room_ref.Roomno else 'N/A'

            patient_info = {
                'patient_name': patient_name,
                'ward_name': ward_name,
                'ward_number': ward_number,
                'room_name': room_name,
                'accommodation_type': accommodation_type,
            }
        except ippatientroombooking.DoesNotExist:
            pass

    # Set session for existing prescription/treatment save views
    patient_id = None
    if booking_id:
        try:
            booking_for_session = ippatientroombooking.objects.select_related('MR_Number').get(id=booking_id)
            if booking_for_session.MR_Number:
                patient_id = booking_for_session.MR_Number.id
                request.session['tabcasehstptid'] = patient_id
        except ippatientroombooking.DoesNotExist:
            pass

    # Store admission ID in session for save endpoints
    if ipno_id:
        request.session['tab_ipno_id'] = ipno_id

    # Fetch current admission object
    current_admission = None
    if ipno_id:
        try:
            current_admission = ippatientadmission.objects.get(id=ipno_id)
        except ippatientadmission.DoesNotExist:
            pass

    # Fetch prescriptions from ipdailymedicine (filtered by current admission)
    prescriptions = []
    if current_admission:
        med_qs = Prescriptionnew.objects.filter(
            patient_id=current_admission.MR_Number_id
        ).order_by('-id')
        for m in med_qs:
            prescriptions.append({
                'id': m.id,
                'medicine_name': m.medicine_name if m.medicine_name else '',
                'noofdays': m.noofdays,
                'moringtime': m.moringtime,
                'noontime': m.noontime or '',
                'nighttime': m.nighttime or  '',
                'beforeorafterdiet': m.beforeorafterdiet or '',
                'medicineguideline': '',
                'qtyprescriped': m.qtyprescriped or 1,
                'stock_id': m.physicalstock_id or None,
            })

    # Fetch treatments from iptreatmentdetails (filtered by current admission)
    treatments = []
    if current_admission:
        treat_qs = iptreatmentdetails.objects.filter(
            ipno=current_admission, deletedstatus=False
        ).select_related('tratmntid').order_by('-id')
        for t in treat_qs:
            treatments.append({
                'id': t.id,
                'treatment_name': t.tratmntid.Treatment_name if t.tratmntid else '',
                'treatment_id': t.tratmntid_id or None,
                'count': t.treatmentcount or '',
                'date': t.treatment_date.strftime('%Y-%m-%d') if t.treatment_date else '',
            })

    response_data = {
        'patient_info': patient_info,
        'prescriptions': prescriptions,
        'treatments': treatments,
    }

    return JsonResponse(response_data)

def _save_ip_patient_room_booking(admission, request, branch_id, emergency_contact, start_date=None, end_date=None):
    accommodation_type, selected_room, selected_bed, floor_number, room_type = _get_ip_patient_accommodation_selection(request)
    selected_accommodation = selected_room if selected_room else selected_bed

    dates_explicitly_provided = start_date is not None or end_date is not None
    if not dates_explicitly_provided:
        start_date_str = request.POST.get("booking_start_date")
        end_date_str = request.POST.get("booking_end_date")
        if start_date_str and end_date_str:
            start_date = datetime.strptime(start_date_str, '%Y-%m-%d').date()
            end_date = datetime.strptime(end_date_str, '%Y-%m-%d').date()
            dates_explicitly_provided = True

    if not start_date:
        start_date = admission.Current_Date or date.today()
    if not end_date:
        end_date = admission.Current_Date or date.today()

    if start_date > end_date:
        raise ValueError("Start Date should not be after End Date.")

    booking = ippatientroombooking.objects.filter(ipno=admission).order_by("-id").first()

    # Room/Ward availability overlap check
    if dates_explicitly_provided and selected_accommodation:
        overlap_filter = Q(
            roomdt_id=selected_accommodation.id,
            bookingcancel=False,
            ipno__Admittedstatus=True,
            Admission_Date__lte=end_date,
            admissionenddate__gte=start_date,
        )
        if booking:
            overlap_filter &= ~Q(id=booking.id)

        if ippatientroombooking.objects.filter(overlap_filter).exists():
            raise ValueError(
                "The selected Room/Ward is already booked for the selected date range. "
                "Please choose different dates or another Room/Ward."
            )

    if booking:
        if booking.room_number and booking.room_number_id != (selected_room.id if selected_room else None):
            booking.room_number.is_available = True
            booking.room_number.save()
        if booking.bed_number and booking.bed_number_id != (selected_bed.id if selected_bed else None):
            booking.bed_number.is_available = True
            booking.bed_number.save()
    else:
        booking = ippatientroombooking(
            ipno=admission,
            MR_Number=admission.MR_Number,
            admissiontime=timezone.now().time(),
        )

    booking.Admission_Date = start_date
    booking.admissionenddate = end_date
    booking.emergencycontact = emergency_contact or admission.contactnumber or "N/A"
    booking.branchdt_id = branch_id
    booking.accommodation_type = accommodation_type
    booking.roomdt = selected_accommodation
    booking.room_number = selected_room
    booking.bed_number = selected_bed
    booking.floor_number = floor_number
    booking.room_type = room_type if selected_room else None
    booking.save()

    if selected_accommodation:
        selected_accommodation.is_available = False
        selected_accommodation.save()
@login_required
def _get_ip_patient_accommodation_selection(request):
    accommodation_type = request.POST.get("accommodation")
    room_id = request.POST.get("roommnumber")
    bed_id = request.POST.get("wardbedno")
    room_floor = request.POST.get("roomfloor")
    ward_floor = request.POST.get("wardfloor")
    floor_number = room_floor if accommodation_type == "Room" else ward_floor
    room_type = request.POST.get("roomtype")

    if not accommodation_type:
        raise ValueError("Please select an accommodation type.")

    selected_room, selected_bed = None, None
    if accommodation_type == "Room":
        if not room_id:
            raise ValueError("Please select a room.")
        selected_room = Room_details.objects.filter(id=room_id).first()
        if not selected_room:
            raise ValueError("Selected room is not available.")
    elif accommodation_type == "Ward":
        if not bed_id:
            raise ValueError("Please select a bed.")
        selected_bed = Room_details.objects.filter(id=bed_id).first()
        if not selected_bed:
            raise ValueError("Selected bed is not available.")
    else:
        raise ValueError("Invalid accommodation type.")

    return accommodation_type, selected_room, selected_bed, floor_number, room_type        
@login_required
def advance_payment_bill(request):
    admission_id=request.GET.get('admission_id')
    admission = get_object_or_404(ippatientadmission, id=admission_id)
    patient = admission.MR_Number  # Assuming the relation with Patient_details
    # Package details if a package is selected
    package = admission.package if admission.need_package else None
    # Bystander rate if applicable
    bystander_rate = admission.bystander_rate if admission.need_bystander else None
    # Retrieve the hospital information
    objhospt = Hospitaldetails.objects.all()  # Assuming you have a model for hospital details
    advance = admission.advance_amount or Decimal(0)
    discount = admission.discount or Decimal(0)
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
                return redirect('staff_login')
    if admission.need_bystander and admission.bystander_rate:
        discounted_bystander = admission.bystander_rate 
        now_paid_amount = advance + max(discounted_bystander, Decimal(0))
    else:
        now_paid_amount = advance # Ensure it doesn't go negative
    # Pass relevant data to the template
    context = {
    'stdesign':stdesign,
        'admission': admission,
        'patient': patient,
        'package': package,
        'bystander_rate': bystander_rate,
        'advance_amount': admission.advance_amount,
        'admission_date': admission.Current_Date,
        'objhospt': objhospt,  # Pass the hospital details
        'now_paid_amount':now_paid_amount
    }
    return render(request, 'advance_payment_bill.html', context)
@login_required
def admission(request):
    if request.method == "POST":
        try:
            # Collect POST data
            admission_date = request.POST.get("admdate")
            admission_time = request.POST.get("admtime")
            emergency_contact = request.POST.get("emgcont")
            admitted_department = request.POST.get("admdpt")
            admitted_doctor = request.POST.get("admdoc")
            mr_number = request.POST.get("patientid")
            branch = request.POST.get("branch")
            accommodation_type = request.POST.get("accommodation")
            room_id = request.POST.get("roommnumber")
            bed_id = request.POST.get("wardbedno")
            floor_number = request.POST.get("roomfloor")
            room_type = request.POST.get("roomtype")
            enddate = request.POST.get("enddate")
            # Get latest admission record
            # admission_record = ippatientadmission.objects.filter(MR_Number_id=mr_number).latest('Current_Date')
            ipnumber =request.POST.get("patientipid") 
            # admission_record.id if admission_record else None
            if not accommodation_type:
                messages.error(request, "Please select an accommodation type.")
                return redirect(f"{reverse('admission')}")
            selected_room, selected_bed = None, None
            if accommodation_type == "Room":
                if not room_id:
                    messages.error(request, "Please select a room.")
                    return redirect(f"{reverse('admission')}")
                selected_room = Room_details.objects.filter(id=room_id).first()
                # if not selected_room:
                #     messages.error(request, "Selected room is not available.")
                #     return redirect(f"{reverse('admission')}")

            elif accommodation_type == "Ward":
                if not bed_id:
                    messages.error(request, "Please select a bed.")
                    return redirect(f"{reverse('admission')}")
                selected_bed = Room_details.objects.filter(id=bed_id).first()
                # if not selected_bed:
                #     messages.error(request, "Selected bed is not available.")
                #     return redirect(f"{reverse('admission')}")

            # Check if already booked
            if ippatientroombooking.objects.filter(
                MR_Number_id=mr_number, roomdt__is_available=False
            ).exists():
                messages.error(request, "Patient is already admitted to another room/bed.")
                return redirect(f"{reverse('admission')}")
            if selected_room:
                overlapping_bookings = ippatientroombooking.objects.filter(
                    roomdt_id=selected_room.id,
                    Admission_Date__lte=enddate,
                    admissionenddate__gte=admission_date,
                )
                if overlapping_bookings.exists():
                    messages.error(request, "This room is already booked for the selected dates.")
                    return redirect(f"{reverse('admission')}")

            # Same for bed (ward)
            if selected_bed:
                overlapping_bookings = ippatientroombooking.objects.filter(
                    roomdt_id=selected_bed.id,
                    Admission_Date__lte=enddate,
                    admissionenddate__gte=admission_date,
                )
                if overlapping_bookings.exists():
                    messages.error(request, "This bed is already booked for the selected dates.")
                    return redirect(f"{reverse('admission')}")
            # Save room booking
            with transaction.atomic():
                ippatientroombooking.objects.create(
                    ipno_id=ipnumber,
                    Admission_Date=admission_date,
                    admissiontime=admission_time,
                    emergencycontact=emergency_contact,
                    admitteddepartmnt_id=admitted_department,
                    admitteddoctor_id=admitted_doctor,
                    MR_Number_id=mr_number,
                    branchdt_id=branch,
                    accommodation_type=accommodation_type,
                    roomdt_id = selected_room.id if selected_room else selected_bed.id if selected_bed else None,
                    room_number_id=selected_room.id if selected_room else None,
                    bed_number=selected_bed,
                    floor_number=floor_number,
                    room_type=room_type if selected_room else None,
                    admissionenddate=enddate
                )

                # Set availability
                if selected_room:
                    selected_room.is_available = False
                    selected_room.save()
                if selected_bed:
                    selected_bed.is_available = False
                    selected_bed.save()

            messages.success(request, f"{accommodation_type} booked successfully!")
            return redirect(f"{reverse('admission')}")

        except Exception as e:
            logger.error(f"Admission error: {e}\n{traceback.format_exc()}")
            messages.error(request, "An unexpected error occurred. Please try again.")
            return redirect(f"{reverse('admission')}")

    context = {
       
        'brch': Branch.objects.values('id', 'Branch_Name'),
     'unique_room_types': Room_details.objects \
    .filter(Room_type__isnull=False) \
    .values_list('Room_type', flat=True) \
    .distinct(),

        # , flat=True
        'rm': Room_details.objects.all(),
        # filter(is_available=True).values('id', 'Roomno'),
        'ward_beds': Room_details.objects.filter(Room_type="Ward").values('id', 'Roomno'),
        #
        'dpt': Department.objects.values('id', 'Department_Name'),
        'stffallc': Staffallocation.objects.select_related('Staff').values(
            'id', 'Staff__Staff_firstname', 'Staff__Staff_lastname'),
    }

    return render(request, "admission.html", context)


@login_required
def get_patient_admission_dates(request):
    """Fetch admission dates from ippatientadmission for a patient"""
    try:
        patient_id = request.GET.get('patient_id')
        if not patient_id:
            return JsonResponse({'error': 'Patient ID required'}, status=400)
        
        # Get the latest admission record for this patient
        latest_admission = ippatientadmission.objects.filter(
            MR_Number_id=patient_id
        ).order_by('-Current_Date').first()
        
        if latest_admission:
            dates_data = {
                'has_dates': True,
                'admission_date': latest_admission.start_date.strftime('%Y-%m-%d') if latest_admission.start_date and latest_admission.package_id else None,
                'end_date': latest_admission.end_date.strftime('%Y-%m-%d') if latest_admission.end_date and latest_admission.package_id else None,
            }
        else:
            dates_data = {
                'has_dates': False,
                'message': 'No admission record found'
            }
        
        return JsonResponse(dates_data)
        
    except Exception as e:
        logger.error(f"Error fetching admission dates: {e}")
        return JsonResponse({'error': str(e)}, status=500)

def search_ipptmrno(request):
    query = request.GET.get('query', '').strip()
    if not query:
        return JsonResponse([], safe=False)

    staff_id = request.session.get('loginstaff')
    staff_design_id = request.session.get('loginstaffdesign')

    if not staff_id or not staff_design_id:
        return JsonResponse({'error': 'Not authenticated'}, status=403)

    try:
        designation = Designation.objects.get(id=staff_design_id)
    except Designation.DoesNotExist:
        return JsonResponse({'error': 'Designation not found'}, status=403)

    is_superadmin = designation.Designation_Name.strip().lower() == 'superadmin'

    filters = Q(Medical_Record_Number__icontains=query) | \
              Q(contactno__icontains=query) | \
              Q(Patient_Name__icontains=query)

    if not is_superadmin:
        try:
            staff_branch = Staffallocation.objects.get(id=staff_id).Branch_Name_id
        except Staffallocation.DoesNotExist:
            return JsonResponse({'error': 'Staff branch not found'}, status=403)
        filters &= Q(Branch_Name_id=staff_branch) & Q(deleted=False)

    matching_mrnos = Patient_details.objects.filter(filters).values(
        'id', 'Medical_Record_Number', 'Patient_Name', 'contactno', 'Age', 'Gender','address'
    )[:10]

    return JsonResponse(list(matching_mrnos), safe=False)
