def delete_other_service(request):
    if request.method == 'POST':
        service_id = request.POST.get('service_id')
        bill_id = request.POST.get('bill_id')
        if not service_id or not bill_id:
            return JsonResponse({"success": False, "error": "Missing parameters."})
        try:
            service = ipexpandedbillotherexpensesdetail.objects.get(id=service_id, ipbilldt_id=bill_id)
            service.deletedstatus = True
            service.save(update_fields=["deletedstatus"])
            return JsonResponse({"success": True, "message": "Service deleted successfully."})
        except ipexpandedbillotherexpensesdetail.DoesNotExist:
            return JsonResponse({"success": False, "error": "Service not found."})
    return JsonResponse({"success": False, "error": "Invalid request method."})
def fetch_medicines(request):
    query = request.GET.get("query", "").strip()

    # Fetch medicines, filtering by search query if provided
    medicines = Physicalstockdetails.objects.select_related('itemnm')
    
    if query:
        medicines = medicines.filter(
            Q(itemnm__itemnm__icontains=query) |  # Search by medicine name
            Q(itemnm__Generic_name__icontains=query) |  # Search by generic name
            Q(Batch_no__icontains=query)  # Search by batch number
        )

    medicine_list = []
    for medicine in medicines:
      
        medicine_list.append({
            "id": medicine.itemnm_id,
            "itemname": medicine.itemnm.itemnm,
            "generic_name": medicine.itemnm.Generic_name,
            "batch_no": medicine.Batch_no,
            "expiry_date": medicine.Expiry_date.strftime("%Y-%m-%d") if medicine.Expiry_date else None,
            "rate": medicine.Rate,
            "qty": medicine.qty,
            "physicalstockid":medicine.id,
          
        })

    return JsonResponse(medicine_list, safe=False)

def get_available_accommodations(request):
    """
    Fetches available floor numbers, room numbers, and bed numbers based on the selected accommodation type.
    """
    accommodation_type = request.GET.get('accommodation_type')
    room_type = request.GET.get('room_type', None)
    if accommodation_type == "Room":
        rooms = Room_details.objects.filter(wardorroom="Room", Room_type=room_type).values("id", "Roomno", "Floorno")
        # , is_available=True
        return JsonResponse({"rooms": list(rooms)})
    elif accommodation_type == "Ward":
        beds = Room_details.objects.filter(wardorroom="Ward").values("id", "wardbedno", "Floorno")
        # , is_available=True
        return JsonResponse({"beds": list(beds)})
    return JsonResponse({"error": "Invalid selection"}, status=400)

