from django.views.decorators.csrf import csrf_exempt
from django.http import JsonResponse
import json
def save_treatment_and_medicine(request):
    if request.method == 'POST':
        try:
            data = json.loads(request.body.decode('utf-8'))  # Parse JSON data
            
            pt_id = data.get('pt_id')
            ipno_id = data.get('ipno')

            # Debugging: Check received data
            print("Received pt_id:", pt_id)
            print("Received ipno_id:", ipno_id)

            if not pt_id or not ipno_id:
                return JsonResponse({"success": False, "error": "Missing patient or admission ID."})

            # Check if Patient and Admission exist
            try:
                patient = Patient_details.objects.get(id=pt_id)
            except Patient_details.DoesNotExist:
                return JsonResponse({"success": False, "error": "Invalid patient ID."})

            try:
                ip_admission = ippatientadmission.objects.get(id=ipno_id)
            except ippatientadmission.DoesNotExist:
                return JsonResponse({"success": False, "error": "Invalid admission ID."})

            # Process Treatments
            selected_treatments = data.get("selected_treatments", [])
            for treatment in selected_treatments:
                iptreatmentdetails.objects.create(
                    treatmenttime=treatment.get("treatment_time"),
                    treatment_date=treatment.get("treatment_date"),
                    treatmentcount=treatment.get("treatment_count"),
                    MR_Number=patient,
                    ipno=ip_admission,
                    tratmntid_id=treatment.get("id"),  # Ensure this ID exists in Treatment_master
                    handled_by=",".join(map(str, treatment.get("handled_by", []))),
                    given_by=",".join(map(str, treatment.get("given_by", []))),
                )

            # Process Medicines
            selected_medicines = data.get("selected_medicines", [])
            for medicine in selected_medicines:
                ipdailymedicine.objects.create(
                    MR_Number=patient,
                    ipno=ip_admission,
                    medicinegiventime=medicine.get("medicine_time"),
                    count=medicine.get("count"),
                    dosage=medicine.get("dosage"),
                    medicinename_id=medicine.get("medid"),
                    physicalstock_id=medicine.get("physicalstid"),
                )

            return JsonResponse({"success": True, "message": "Data saved successfully."})

        except json.JSONDecodeError:
            return JsonResponse({"success": False, "error": "Invalid JSON format."})
        except Exception as e:
            return JsonResponse({"success": False, "error": str(e)})

    return JsonResponse({"success": False, "error": "Invalid request method."})

def ip_full_details(request):
    patient_id = request.GET.get('ids')
    patient = get_object_or_404(Patient_details, id=patient_id)
    
    # Fetch patient admission details
    admission = ippatientadmission.objects.filter(MR_Number=patient).last()
    
    # Fetch daily treatment and medicine records
    treatment_records = iptreatmentdetails.objects.filter(MR_Number=patient,ipno=admission).order_by('treatment_date')
    medicine_records = ipdailymedicine.objects.filter(MR_Number=patient,ipno=admission).order_by('Current_Date')
    
    
    # Combine data based on date
    daily_records = {}
    for treatment in treatment_records:
        date = treatment.treatment_date
        if date not in daily_records:
            daily_records[date] = {'medicine': [], 'treatment': []}

        # Convert `treatmenttime` safely
        treatment_time = treatment.treatmenttime.strip() if treatment.treatmenttime else "N/A"


        # Retrieve staff names
        handled_by_staff = treatment.get_handled_by_staffnames()
        given_by_staff = treatment.get_given_by_staffnames()

        daily_records[date]['treatment'].append({
            "name": treatment.tratmntid.Treatment_name if treatment.tratmntid else "Treatment details not available",
            "time": treatment_time,
            "handled_by": handled_by_staff if handled_by_staff else "N/A",
            "given_by": given_by_staff if given_by_staff else "N/A"
        })
    for medicine in medicine_records:
        date = medicine.Current_Date
        if date not in daily_records:
            daily_records[date] = {'medicine': [], 'treatment': []}
        daily_records[date]['medicine'].append(f"{medicine.medicinename.itemnm} - {medicine.count} ({medicine.dosage})")
    context = {
        'patient': patient,
        'admission': admission,
        'daily_records': daily_records,
    }
    return render(request, 'ipdaillyview.html', context)

def ipdttable(request):
    st = request.session.get('loginstaff')
    if not st:
        messages.error(request, "You are not logged in.")
        return redirect('staff_login')
    # Get the menu management ID
   
    # Check if the staff design session exists
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    #Retrieve the staff branch
    try:
        staff_branch = Staffallocation.objects.get(id=st)
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff allocation details not found.")
        return redirect('staff_login')
    # Get the branch ID and filter patient details based on it
    staffbranchid = staff_branch.Branch_Name_id
    try:
        designation_obj = Designation.objects.get(id=stdesign)
        designation_name = designation_obj.Designation_Name.lower()
    except Designation.DoesNotExist:
        designation_name = '' 
    
    from_date = request.GET.get('from_date')
    to_date = request.GET.get('to_date')
    if designation_name == "superadmin":
        patients = ippatientadmission.objects.all()
    else:
        patients = ippatientadmission.objects.filter(admittedbranch=staffbranchid)

    if from_date and to_date:
        try:
            from datetime import datetime
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            patients = patients.filter(Current_Date__range=[from_date_obj, to_date_obj])
        except ValueError:
            pass  # Invalid date format, ignore filter
    elif from_date:
        # Only from date provided
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            patients = patients.filter(Current_Date__gte=from_date_obj)
        except ValueError:
            pass
    elif to_date:
        # Only to date provided
        try:
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            patients = patients.filter(Current_Date__lte=to_date_obj)
        except ValueError:
            pass

    context={
         "patients":patients,
         "from_date": from_date,  
        "to_date": to_date,
    }
    return render(request,"ipdetailtable.html",context)

