def changeroom(request):
    room_bookings = ippatientroombooking.objects.filter(ipno__Admittedstatus=True)
    unique_room_types = Room_details.objects.filter(wardorroom="room").values_list('Room_type', flat=True).distinct()
    available_wards = Room_details.objects.filter(wardorroom="ward", is_available=True)

    if request.method == "POST":
        ipno_id = request.POST.get('ipno')
        accommodation = request.POST.get('accommodation')
        remarks = request.POST.get('remarks', '')

        booking = get_object_or_404(ippatientroombooking, ipno_id=ipno_id)
        patient_admission = booking.ipno

        # Old room/ward
        from_room_or_ward = booking.room_number or booking.bed_number

        # Duration and billing
        admission_date = booking.Admission_Date or timezone.now().date()
        stay_days = (timezone.now().date() - admission_date).days or 1
        rate = float(from_room_or_ward.rate) if from_room_or_ward and from_room_or_ward.rate else 0
        total_rent = rate * stay_days

        # Release old room/bed
        if from_room_or_ward:
            from_room_or_ward.is_available = True
            from_room_or_ward.save()

        # Set new room/bed
        if accommodation == "Room":
            room_id = request.POST.get('roommnumber')
            room = get_object_or_404(Room_details, id=room_id)
            room.is_available = False
            room.save()

            booking.room_number = room
            booking.bed_number = None
            booking.accommodation_type = "Room"
            booking.room_type = room.Room_type
            booking.floor_number = room.Floorno

            to_room_or_ward = room

        elif accommodation == "Ward":
            bed_id = request.POST.get('wardbedno')
            bed = get_object_or_404(Room_details, id=bed_id)
            bed.is_available = False
            bed.save()

            booking.bed_number = bed
            booking.room_number = None
            booking.accommodation_type = "Ward"
            booking.room_type = None
            booking.floor_number = bed.Floorno

            to_room_or_ward = bed

        booking.save()

        # Log the change
        RoomChangeLog.objects.create(
            ipno=booking.ipno,
            from_room_or_ward=from_room_or_ward,
            to_room_or_ward=to_room_or_ward,
            change_date=timezone.now().date(),
            change_time=timezone.now().time(),
            no_of_days_stayed=stay_days,
            rate_per_day=rate,
            total_rent=total_rent,
            changed_by=request.user.staffallocation if hasattr(request.user, 'staffallocation') else None,
            remarks=remarks
        )

        messages.success(request, "Accommodation changed successfully.")
        return redirect('changeroom')

    return render(request, 'chnageroom.html', {
        'room_bookings': room_bookings,
        'unique_room_types': unique_room_types,
        'available_wards': available_wards,
       
         "ipdt":ippatientadmission.objects.filter(Admittedstatus=True)
    })
