import traceback
import logging
logger = logging.getLogger(__name__)
from django.utils.dateparse import parse_date
from decimal import Decimal, InvalidOperation

def safe_decimal(value, default=Decimal('0.00')):
    try:
        return Decimal(value)
    except (ValueError, TypeError, InvalidOperation):
        return default

def edit_ippatient(request):
    try:
        if request.method == 'POST':
            admid = request.POST.get('admssid')
            if not admid:
                messages.error(request, "Admission ID is missing.")
                return redirect('error_page')
            admission = get_object_or_404(ippatientadmission, id=admid)

            # Basic info
            admission.bloodgroup = request.POST.get('bloodgroup', '').strip()
            admission.contactnumber = request.POST.get('contactnumber', 'N/A').strip()
            admission.reasonforadmission = request.POST.get('reasonforadmission', '').strip()
            admission.address = request.POST.get('address', '').strip()
            try:
                admission.age = int(request.POST.get('age', 0))
            except (ValueError, TypeError):
                admission.age = 0
            admission.save()
            messages.success(request, "Patient admission details updated successfully.")
            idmngmnt = request.session.get('ipmngid')
            return redirect(f"{reverse('iptable')}?menumanagement_id={idmngmnt}")
        # Handle GET
        admission_id = request.GET.get('ids')
        admission = get_object_or_404(ippatientadmission, id=admission_id)
        idmngmnt = request.session.get('ipmngid')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided.")
            return redirect('error_page')
        packages = packagemaster.objects.filter(deleted=False)
        context = {
            'ipmngid': idmngmnt,
            'ipobjmngadd': request.session.get('ipobjmngadd'),
            'ipobjmngview': request.session.get('ipobjmngview'),
            'ipobjmngedit': request.session.get('ipobjmngedit'),
            'ipobjmngdelete': request.session.get('ipobjmngdelete'),
            'admission': admission,
            'pktdt': packages,
        }
        return render(request,"edit_ippatient.html", context)
    except Exception as e:
        logger.error(f"Error editing patient admission: {e}\n{traceback.format_exc()}")
        messages.error(request, "Failed to load or update patient details.")
        return redirect('error_page')
        
