def get_assigned_dashboards(request):
    """Fetches assigned dashboards dynamically via AJAX."""
    role_id = request.GET.get("role_id")
    assigned_dashboard_ids = []

    if role_id:
        assigned_dashboard_ids = list(dashboardallocation.objects.filter(roleid=role_id).values_list("dashboardid_id", flat=True))

    return JsonResponse({"assigned_dashboards": assigned_dashboard_ids})

def assign_dashboard_to_role(request):
    """Handles the form submission and assigns dashboards to the selected role."""
    if request.method == "POST":
        role_id = request.POST.get("rolename")
        selected_dashboards = request.POST.getlist("head[]")
        order = request.POST.get("order").split(",")

        dashboardallocation.objects.filter(roleid=role_id).delete()  # Remove old allocations

        for index, dashboard_id in enumerate(order):
            if dashboard_id in selected_dashboards:
                dashboardallocation.objects.create(
                    roleid_id=role_id,
                    dashboardid_id=dashboard_id,
                    ordering=index + 1,  # Save order
                    status="Assigned"
                )
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    return render(request, "dashboardallocation.html", {"roles": Role.objects.all(), "dashboardesign_headings": dashboardesign.objects.all(),'stdesign':stdesign})




