def treatmentroom(request):
    idmngmnt = request.GET.get('menumanagement_id')
    # Validate Menu Management ID
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided. Please contact the admin.")
        return redirect('error_page')
    # Check if user is logged in
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    if request.method == 'POST':
        # Retrieve form data
        addfloornum = request.POST.get('floornumber') 
        addroomnum = request.POST.get('roomnumber', None)  # Only for Room
        try:
            branch_id = request.session.get('branchid')
            room_exists = TreatmentRoom_details.objects.filter(
                    Floorno=addfloornum,
                    Roomno=addroomnum
            ).exists()
            if room_exists:
                    messages.warning(request, "This room is already registered.")
                    return redirect(f"{reverse('treatmentroom')}?menumanagement_id={idmngmnt}")
            roomtr= TreatmentRoom_details.objects.create(
                    Floorno=addfloornum,
                    Roomno=addroomnum
            )
            roomtr.save()
            messages.success(request, "Treatment Room details saved successfully.")
            return redirect(f"{reverse('treatmentroom')}?menumanagement_id={idmngmnt}")
        except ValueError:
            messages.error(request, "Invalid branch selection.")
        except Exception as e:
            messages.error(request, f"Error saving Treatment room details: {str(e)}. Please contact the admin.")
        return redirect('error_page')
    else:
        try:
            # Fetch menu management object
            treatmntroomobj = get_object_or_404(menumanagement, id=idmngmnt)
            # Store menu permissions in session
            request.session['trmntroomobjmngid'] = idmngmnt
            request.session['trmntroomobjmngadd'] = treatmntroomobj.add
            request.session['trmntroomobjmngview'] = treatmntroomobj.view
            request.session['trmntroomobjmngedit'] = treatmntroomobj.edit
            request.session['trmntroomobjmngdelete'] = treatmntroomobj.delete
            # Fetch branches for dropdown
            branchobj = Branch.objects.all()
            context = {
                'branchobj': branchobj,
                'idmngmnt': idmngmnt,
                'stdesign': stdesign,
                'trmntroomadd': request.session.get('trmntroomobjmngadd'),
                'trmntroomview': request.session.get('trmntroomobjmngview'),
            }
            return render(request, "treatmentroom.html", context)
        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
        except Exception as e:
            messages.error(request, f"Unable to retrieve Menu Management details: {str(e)}. Please contact the admin.")
            return redirect('error_page')
    

