from datetime import datetime, time

def treatment_room_booking(request):
    menu_mgmt_id = request.GET.get('menumanagement_id')  # ✅ Needed for redirects
    if request.method == 'POST':
        try:
            patient_id = request.POST.get('mrnum') or request.POST.get('patientid')
            room_id = request.POST.get('treatmntroom')
            booking_date = request.POST.get('bookingdate')
            end_date = request.POST.get('bookingenddate')
            start_time = request.POST.get('bookingstarttime', '')
            end_time = request.POST.get('bookingendtime', '')
            branch_id = request.session.get('branchid')
            staff_id = request.session.get('staffid')
            handling_staff_id = request.POST.get('handlingatsff')

            try:
                start = datetime.strptime(start_time, "%H:%M").time()
                end = datetime.strptime(end_time, "%H:%M").time()
                start_date_obj = datetime.strptime(booking_date, "%Y-%m-%d").date()
                end_date_obj = datetime.strptime(end_date, "%Y-%m-%d").date() if end_date else start_date_obj
            except ValueError:
                messages.error(request, "Invalid date or time format.")
                return redirect(f"{reverse('treatment_room_booking')}?menumanagement_id={menu_mgmt_id}")

            if start >= end:
                messages.error(request, "End time must be after start time.")
                return redirect(f"{reverse('treatment_room_booking')}?menumanagement_id={menu_mgmt_id}")

            if end_date_obj < start_date_obj:
                messages.error(request, "End date cannot be before start date.")
                return redirect(f"{reverse('treatment_room_booking')}?menumanagement_id={menu_mgmt_id}")

            # ✅ Overlap check across the date range
            date_cursor = start_date_obj
            while date_cursor <= end_date_obj:
                overlapping = oppatienttreamentroombooking.objects.filter(
                    treatmntroom_id=room_id,
                    bookingdate=date_cursor,
                    bookingstatus=True,
                    bookingstarttime__lt=end,
                    bookingendtime__gt=start
                )
                if overlapping.exists():
                    messages.error(request, f"The room is already booked on {date_cursor} during this time.")
                    return redirect(f"{reverse('treatment_room_booking')}?menumanagement_id={menu_mgmt_id}")
                date_cursor += timedelta(days=1)

            # ✅ Create bookings
            date_cursor = start_date_obj
            while date_cursor <= end_date_obj:
                oppatienttreamentroombooking.objects.create(
                    patientid_id=patient_id,
                    bookingdate=date_cursor,
                    bookingstarttime=start,
                    bookingendtime=end,
                    treatmntroom_id=room_id,
                    branchdt_id=branch_id,
                    preparedby_id=staff_id,
                    bookingstatus=True,
                    handledystaff_id=handling_staff_id,
                    bookingenddate=end_date_obj
                )
                date_cursor += timedelta(days=1)

            messages.success(request, "Booking successful.")
            return redirect(f"{reverse('treatment_room_booking')}?menumanagement_id={menu_mgmt_id}")

        except Exception as e:
            messages.error(request, f"Unexpected error occurred: {e}")
            return redirect(f"{reverse('treatment_room_booking')}?menumanagement_id={menu_mgmt_id}")
    else:
        try:
            # Check staff login
            staff_designation = request.session.get('loginstaffdesign')
            if not staff_designation:
                return redirect('staff_login')
            menu_obj = get_object_or_404(menumanagement, id=menu_mgmt_id)
            # Store permissions in session
            request.session['trmntroombknobjmngid'] = menu_mgmt_id
            request.session['trmntroombknobjmngadd'] = menu_obj.add
            request.session['trmntroombknobjmngview'] = menu_obj.view
            request.session['trmntroombknobjmngedit'] = menu_obj.edit
            request.session['trmntroombknobjmngdelete'] = menu_obj.delete
            rooms = TreatmentRoom_details.objects.all()
            doctor_staff = Staffallocation.objects.filter(Designation_Name__in=["2", "3", "5", "6"])
            context = {
                'rooms': rooms,
                'doctor_staff': doctor_staff,
                'idmngmnt': menu_mgmt_id,
                'stdesign': staff_designation,
                'trmntroombkadd': request.session['trmntroombknobjmngadd'],
                'trmntroombkview': request.session['trmntroombknobjmngview'],
            }
            return render(request, 'treatment_room_booking.html', context)
        except ObjectDoesNotExist:
            messages.error(request, "Menu Management details not found. Please contact the admin.")
            return redirect('error_page')
        except Exception as e:
            messages.error(request, f"Unable to load booking page: {e}")
            return redirect('error_page')
    # GET: load context

@login_required
def treatment_booking_list(request):
    bookings = []
    if request.method == 'POST':
        sdate = request.POST.get('sdate')
        edate = request.POST.get('edate')
        if sdate and edate:
            try:
                sdate_obj = datetime.strptime(sdate, "%Y-%m-%d").date()
                edate_obj = datetime.strptime(edate, "%Y-%m-%d").date()
                bookings = oppatienttreamentroombooking.objects.filter(
                    bookingdate__range=[sdate_obj,edate_obj],
                    bookingstatus=True
                ).select_related('patientid', 'treatmntroom', 'preparedby')
            except Exception as e:
                messages.error(request, f"Error fetching bookings: {e}")
    else:
        bookings = oppatienttreamentroombooking.objects.filter(
                    bookingstatus=True
                ).select_related('patientid', 'treatmntroom', 'preparedby').order_by('-bookingdate')
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
            return redirect('staff_login')
    today = date.today().isoformat()
    context = {
        'inv': bookings,
        'stdesign':stdesign,
        'today': today,
    }
    return render(request, 'treatmentbookinglist.html', context)

@login_required
def get_bookings_json(request):
    bookings = oppatienttreamentroombooking.objects.filter(bookingstatus=True)
    events = {}
    for booking in bookings:
        date_str = booking.bookingdate.strftime('%Y-%m-%d')
        if date_str not in events:
            events[date_str] = []
        events[date_str].append({
            "id": booking.id,
            "title": booking.patientid.Patient_Name,
            "start":booking.bookingstarttime,
            "end": booking.bookingendtime,
            "room": f"Floor {booking.treatmntroom.Floorno}, Room {booking.treatmntroom.Roomno}",
         "staff": (
        f"{booking.handledystaff.Staff.Staff_firstname} {booking.handledystaff.Staff.Staff_lastname}"
        if booking.handledystaff and booking.handledystaff.Staff else ""
    ),
        })
    response = []
    for date, bookings in events.items():
        response.append({
            "title": f"{len(bookings)} Booked",
            "start": date,
            "allDay": True,
            "extendedProps": {
                "bookings": bookings
            }
        })
    return JsonResponse(response, safe=False)

