from calendar import monthrange
@login_required
def timeshechudler_list(request):
    today = date.today()
    month_start = today.replace(day=1)
    next_month = (month_start.replace(day=28) + timedelta(days=4)).replace(day=1)
    month_end = next_month - timedelta(days=1)
    bookings = oppatienttreamentroombooking.objects.filter(
        bookingstatus=True,
        bookingdate__range=(month_start, month_end)
    ).select_related('patientid')
    # Unique time slots
    time_slots = sorted(set((b.bookingstarttime, b.bookingendtime) for b in bookings))
    # All dates in current month
    num_days = (month_end - month_start).days + 1
    all_dates = [month_start + timedelta(days=i) for i in range(num_days)]
    # Build direct-access dictionary (no filter needed)
    booking_map = {}
    for b in bookings:
        key = (b.bookingstarttime, b.bookingendtime, b.bookingdate)
        booking_map[key] = b.patientid.Patient_Name
    context = {
        'all_dates': all_dates,
        'time_slots': time_slots,
        'booking_map': booking_map,
    }
    return render(request, 'timeshechudler_list.html', context)

