@login_required
def oppatientdetails(request):
    idmngmnt = request.session.get('opmngid')
    if request.method == 'POST':
        mr_number_id = request.POST.get('ptid')
        bloodgroup = request.POST.get('bloodgroup') or 'Unknown'
        age = request.POST.get('age') or '0'
        contactnumber = request.POST.get('contactnumber') or 'N/A'
        diagns = request.POST.get('diagnosis') or 'Not specified'
        address = request.POST.get('address') or 'Not provided'
        gender = request.POST.get('gender') or 'Not disclosed'
        need_package = request.POST.get('need_package') or 'no'
        package_id = request.POST.get('pckid') or None
        need_bystander = request.POST.get('need_bystander') or 'no'
        bystander_rate = request.POST.get('bystanderTotal') or '0'
        advance_amount = request.POST.get('advance_amount') or '0'
        discount = request.POST.get('discount') or '0'
        paying_amount = request.POST.get('paying_amount') or '0'
        selectedrangeTotal= request.POST.get('selectedDateTotal') or '0'
        selectedrangeselectedDateDue= request.POST.get('selectedDateDue') or '0'
        fdate=request.POST.get('from_date')
        todate=request.POST.get('to_date')

        try:
            payementstart_date = datetime.strptime(fdate, "%Y-%m-%d").date() if fdate else None
        except (ValueError, TypeError):
            payementstart_date = timezone.now().date()
        try:
            paymentenddate = datetime.strptime(todate,"%Y-%m-%d").date()  if todate else None
        except (ValueError, TypeError):
            paymentenddate = timezone.now().date()

        if mr_number_id:
            mr_number_instance = get_object_or_404(Patient_details, id=mr_number_id)
            # Check for existing admission
            existing_admission = oppatientadmission.objects.filter(
                MR_Number_id=mr_number_instance.id,
                Admittedstatus=True
            ).first()
            if existing_admission:
                admission_date = existing_admission.Current_Date.strftime('%d-%m-%Y')
                messages.error(request, f"This patient was already admitted on {admission_date}.")
                return redirect(f"{reverse('oppatientdetails')}?menumanagement_id={idmngmnt}")
            # Save admission
            admission = oppatientadmission.objects.create(
                MR_Number=mr_number_instance,
                bloodgroup=bloodgroup,
                age=age,
                address=address,
                contactnumber=contactnumber,
                reasonforadmission=diagns,
                Current_Date=date.today(),
                Admittedstatus=True
            )
            # If package is selected, create related data (you can adapt this logic)
            if need_package == 'yes' and package_id:
                admission.package_id = package_id
                admission.need_package=True
                admission.need_bystander = need_bystander == 'yes'
                admission.bystander_rate = bystander_rate
                admission.advance_amount = advance_amount
                admission.due_amount = selectedrangeselectedDateDue
                admission.total_package_rate =  paying_amount
                admission.totalpaidamount=advance_amount
                admission.payingamount=paying_amount
                admission.amountpaidwithoutbystander=advance_amount
                admission.discount=discount
                admission.start_date=payementstart_date 
                admission.end_date =paymentenddate 
                admission.advancedue=selectedrangeselectedDateDue
                admission.originalpcktotaalamountpaid=advance_amount
                admission.totalpackageamountwithoutdiscount=selectedrangeTotal
                admission.save()
            # Create initial payment record if advance is paid
            if need_package == 'yes' and advance_amount and float(advance_amount) > 0:
                OPPackagePayment.objects.create(
                    admission=admission,
                    mr_number=mr_number_instance,
                    package_id=admission.package,
                    amount_paid=advance_amount,
                    total_amount=selectedrangeTotal or 0,
                    due_amount=selectedrangeselectedDateDue,
                    start_date=payementstart_date ,
                    end_date=paymentenddate,
                    bystander_payment = bystander_rate
                )

            messages.success(request, 'Patient admission recorded successfully!')

            # Redirect to advance payment bill if package and advance amount are provided
            if need_package == 'yes' and advance_amount and float(advance_amount) > 0:
                return redirect(f"{reverse('opadvance_payment_bill')}?admission_id={admission.id}")

            return redirect(f"{reverse('oppatientdetails')}?menumanagement_id={idmngmnt}")


    # GET request
    try:
        idmngmnt = request.GET.get('menumanagement_id')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided.")
            return redirect('error_page')
        opobj = get_object_or_404(menumanagement, id=idmngmnt)
        request.session.update({
            'opmngid': idmngmnt,
            'opobjmngadd': opobj.add,
            'opobjmngview': opobj.view,
            'opobjmngedit': opobj.edit,
            'opobjmngdelete': opobj.delete,
        })
        if not request.session.get('loginstaffdesign'):
            return redirect('staff_login')
        loggedbranchid = request.session.get('branchid')
        if not loggedbranchid:
                return redirect('staff_login')
        pktdt=packagemaster.objects.filter(branchdt=loggedbranchid,deleted="False")
        context={
        'pktdt':pktdt,
            'branchobj': Branch.objects.all(),
            'idmngmnt': idmngmnt,
            'stdesign': request.session['loginstaffdesign'],
            'opadd': opobj.add,
            'opview': opobj.view,
        }
        return render(request, "oppatient.html", context)
    except ObjectDoesNotExist:
        messages.error(request, "Menu Management details not found.")
        return redirect('error_page')
    except Exception as e:
        logger.error(f"Error in ippatient view: {e}\n{traceback.format_exc()}")
        messages.error(request, f"Unable to load details. Contact admin.")
        return redirect('error_page')
    

@login_required
def opadvance_payment_bill(request):
    admission_id=request.GET.get('admission_id')
    admission = get_object_or_404(oppatientadmission, id=admission_id)
    patient = admission.MR_Number  # Assuming the relation with Patient_details
    # Package details if a package is selected
    package = admission.package if admission.need_package else None
    # Bystander rate if applicable
    bystander_rate = admission.bystander_rate if admission.need_bystander else None
    # Retrieve the hospital information
    objhospt = Hospitaldetails.objects.all()  # Assuming you have a model for hospital details
    advance = admission.advance_amount or Decimal(0)
    discount = admission.discount or Decimal(0)
    if admission.need_bystander and admission.bystander_rate:
        discounted_bystander = admission.bystander_rate 
        now_paid_amount = advance + max(discounted_bystander, Decimal(0))
    else:
        now_paid_amount = advance # Ensure it doesn't go negative
    # Pass relevant data to the template
    context = {
        'admission': admission,
        'patient': patient,
        'package': package,
        'bystander_rate': bystander_rate,
        'advance_amount': admission.advance_amount,
        'admission_date': admission.Current_Date,
        'objhospt': objhospt,  # Pass the hospital details
        'now_paid_amount':now_paid_amount
    }
    return render(request, 'opadvanvance_payment_bill.html', context)
     
