def edit_oppatient(request):
    try:
        if request.method == 'POST':
            admid = request.POST.get('admssid')
            if not admid:
                messages.error(request, "Admission ID is missing.")
                return redirect('error_page')
            admission = get_object_or_404(oppatientadmission, id=admid)
            admission.bloodgroup = request.POST.get('bloodgroup', '').strip()
            admission.contactnumber = request.POST.get('contactnumber', 'N/A').strip()
            admission.reasonforadmission = request.POST.get('reasonforadmission', '').strip()
            admission.address = request.POST.get('address','').strip()
            try:
                admission.age = int(request.POST.get('age', 0))
            except (ValueError, TypeError):
                admission.age = 0
            # Boolean flags
            need_package = request.POST.get('need_package') == 'yes'
            need_bystander = request.POST.get('need_bystander') == 'yes'
            fdate=request.POST.get('start_date')
            todate=request.POST.get('end_date')
            try:
                admission.start_date = datetime.strptime(fdate, "%Y-%m-%d").date() if fdate else None
            except (ValueError, TypeError):
               admission.start_date = timezone.now().date()
            try:
                admission.end_date = datetime.strptime(todate,"%Y-%m-%d").date()  if todate else None
            except (ValueError, TypeError):
                admission.end_date= timezone.now().date()
            if need_package:
                pkg_id = request.POST.get('package')
                if pkg_id:
                    package = get_object_or_404(packagemaster, id=pkg_id)
                    admission.package = package
                    rate = safe_decimal(package.rate)
                    if admission.start_date and admission.end_date:
                        duration = (admission.end_date - admission.start_date).days + 1
                        admission.total_package_rate = rate * duration
                    else:
                        admission.total_package_rate = rate
                    # Financial fields
                    admission.advance_amount = safe_decimal(request.POST.get('advance_amount'))
                    admission.bystander_rate = safe_decimal(request.POST.get('bystander_rate'))
                    admission.discount = safe_decimal(request.POST.get('discount'))
                    admission.totalpaidamount = admission.advance_amount + (admission.bystander_rate if need_bystander else Decimal('0.00'))
                    admission.due_amount = safe_decimal(request.POST.get('selectedDateDue'))
                    admission.originalpcktotaalamountpaid = safe_decimal(request.POST.get('total_package_rate'))
                    admission.totalpackageamountwithoutdiscount = safe_decimal(request.POST.get('total_package_rate'))
                    admission.amountpaidwithoutbystander = safe_decimal(request.POST.get('amountpaidwithoutbystander'))
                    admission.advancedue = safe_decimal(request.POST.get('selectedDateDue'))
                    admission.payingamount = safe_decimal(request.POST.get('paying_amount'))
                    # Handle possible multiple payment records
                    payments = OPPackagePayment.objects.filter(admission=admission, mr_number=admission.MR_Number)
                    if payments.exists():
                        payment_record = payments.first()  # Pick the first one if multiple exist
                    else:
                        payment_record = OPPackagePayment(
                            admission=admission,
                            mr_number=admission.MR_Number
                        )
                    # Update payment details
                    payment_record.package_id = admission.package
                    payment_record.amount_paid = admission.advance_amount
                    payment_record.total_amount = admission.totalpackageamountwithoutdiscount
                    payment_record.due_amount = admission.advancedue
                    payment_record.start_date = admission.start_date
                    payment_record.end_date = admission.end_date
                    payment_record.bystander_payment = admission.bystander_rate
                    payment_record.save()
                else:
                    messages.error(request, "Package selection is required when 'need package' is yes.")
                    return redirect('error_page')
            else:
                # Reset all package-related fields
                admission.package = None
                admission.total_package_rate = Decimal('0.00')
                admission.bystander_rate = Decimal('0.00')
                admission.advance_amount = Decimal('0.00')
                admission.discount = Decimal('0.00')
                admission.totalpaidamount = Decimal('0.00')
                admission.due_amount = Decimal('0.00')
                admission.originalpcktotaalamountpaid = Decimal('0.00')
                admission.totalpackageamountwithoutdiscount = Decimal('0.00')
                admission.amountpaidwithoutbystander = Decimal('0.00')
                admission.advancedue = Decimal('0.00')
                admission.payingamount = Decimal('0.00')
            admission.save()
            messages.success(request, "Patient admission details updated successfully.")
            idmngmnt = request.session.get('opmngid')
            return redirect(f"{reverse('optable')}?menumanagement_id={idmngmnt}")
        # Handle GET
        admission_id = request.GET.get('ids')
        admission = get_object_or_404(oppatientadmission, id=admission_id)
        idmngmnt = request.session.get('opmngid')
        if not idmngmnt:
            messages.error(request, "Invalid Menu Management ID provided.")
            return redirect('error_page')
        packages = packagemaster.objects.filter(deleted=False)
        context = {
            'opmngid': idmngmnt,
            'opobjmngadd': request.session.get('opobjmngadd'),
            'opobjmngview': request.session.get('opobjmngview'),
            'opobjmngedit': request.session.get('opobjmngedit'),
            'opobjmngdelete': request.session.get('opobjmngdelete'),
            'admission': admission,
            'pktdt': packages,
            'idmngmnt':idmngmnt,
        }
        return render(request,"oppatientedit.html", context)
    except Exception as e:
        logger.error(f"Error editing patient admission: {e}\n{traceback.format_exc()}")
        messages.error(request, "Failed to load or update patient details.")
        return redirect('error_page')


@login_required
def opduepayemnt(request):
    if request.method == 'POST':
        try:
            pt_id = request.POST.get('pt_id')
            ipno = request.POST.get('ipno')
            amount_paying = Decimal(request.POST.get('amount_paying') or 0)
            bystander_days = int(request.POST.get('bystander_days') or 0)
            bystander_rate = Decimal(request.POST.get('bystander_total') or 0)
            admission = get_object_or_404(oppatientadmission, id=ipno)
            bystander_total = bystander_days * bystander_rate
            total_paid_now = amount_paying + bystander_total
            remaining_payment = amount_paying
            # Initialize date range for the payment period
            payment_start_date = None
            payment_end_date = None
            # 1. Apply to original package due (advancedue)
            if admission.advancedue > 0:
                if remaining_payment >= admission.advancedue:
                    remaining_payment -= admission.advancedue
                    paid_to_original = admission.advancedue
                    admission.advancedue = Decimal(0)
                else:
                    admission.advancedue -= remaining_payment
                    paid_to_original = remaining_payment
                    remaining_payment = Decimal(0)
                admission.originalpcktotaalamountpaid = (admission.originalpcktotaalamountpaid or 0) + paid_to_original
                if paid_to_original > 0:
                    payment_start_date = admission.start_date
                    payment_end_date = admission.end_date  
            # Ensure this field exists and is correct
            # 3. Recalculate total due_amount (advancedue + extensions)
            total_remaining_due = admission.advancedue
            admission.due_amount = total_remaining_due
            # 4. Update admission payment info
            admission.amountpaidwithoutbystander = (admission.amountpaidwithoutbystander or 0) + amount_paying
            admission.totalpaidamount = (admission.totalpaidamount or 0) + total_paid_now
            admission.bystander_rate = (admission.bystander_rate or 0) + bystander_rate
            admission.save()
            # 5. Record the payment with date range
            OPPackagePayment.objects.create(
                admission=admission,
                discount=Decimal(0.00),
                amount_paid=amount_paying,
                total_amount=admission.total_package_rate or Decimal(0.00),
                due_amount=admission.due_amount,
                bystander_payment=bystander_total,
                mr_number=admission.MR_Number,
                package_id=admission.package,
                start_date=payment_start_date,
                end_date=payment_end_date
            )
            messages.success(request, "Package payment recorded successfully.")
            return redirect(f"{reverse('opdueprint')}?admission_id={admission.id}")
        except Exception as e:
            messages.error(request, f"Error occurred: {e}")
            return redirect('opduepayemnt')
    return render(request, "opduepayment.html")

