def opsearch_patinetwithpackage(request):
    query = request.GET.get('query', '').strip()
    if not query:
        return JsonResponse([], safe=False)
    # Find admitted patients with a package and matching query
    admissions = oppatientadmission.objects.filter(
        Q(MR_Number__Patient_Name__icontains=query) |
        Q(MR_Number__contactno__icontains=query) |
        Q(MR_Number__Medical_Record_Number__icontains=query),
        Admittedstatus=True,
        package__isnull=False,
        due_amount__gt=0      
    )
    results = []
    for adm in admissions:
        patient = adm.MR_Number
        pkg = adm.package
        # Original package duration
        original_start = adm.start_date
        original_end = adm.end_date
        # Collect all extended dates from IPPackageextend
        # extended_entries = IPPackageextend.objects.filter(admission=adm)
        # extended_dates = []
        # for ext in extended_entries:
        #     if ext.start_date and ext.end_date:
        #         current = ext.start_date
        #         while current <= ext.end_date:
        #             extended_dates.append(current.strftime('%Y-%m-%d'))
        #             current += timedelta(days=1)
        results.append({
            'Medical_Record_Number': patient.Medical_Record_Number,
            'Patient_Name': patient.Patient_Name,
            'contactno': adm.contactnumber,
            'Admission_Date': adm.Current_Date.strftime('%Y-%m-%d') if adm.Current_Date else '',
            'patientid': patient.id,
            'age': adm.age,
            'diagnosis': adm.reasonforadmission,
            'ip_id': adm.id,
            'total_package_amount': str(adm.total_package_rate or 0),
            'amount_paid': str(adm.totalpaidamount or 0),
            'due_amount': str(adm.due_amount or 0),
            'package': pkg.packagename if pkg else '',
            'perdaypckrate': str(pkg.rate if pkg else 0),
            'pckid': pkg.id if pkg else '',
            'original_start': original_start.strftime('%Y-%m-%d') if original_start else '',
            'original_end': original_end.strftime('%Y-%m-%d') if original_end else '',
        })
    return JsonResponse(results, safe=False)
from django.db.models import Sum, Value as V, FloatField
from django.db.models.functions import Coalesce, Cast

def revenue_dashboard(request):
    # Step 1: Get selected date or default to today
    selected_date_str = request.GET.get('date')
    if selected_date_str:
        try:
            selected_date = datetime.strptime(selected_date_str, '%Y-%m-%d').date()
        except ValueError:
            selected_date = now().date()
    else:
        selected_date = now().date()

    treatment_data = (
        treatmentinvoicemaster.objects
        .filter(currentdate=selected_date, cancelstatus=False)
        .values('branch__Branch_Name')
        .annotate(
            total_revenue=Coalesce(Sum('total'), V(0.0)),
            tax=Coalesce(Sum('tax'), V(0.0)),
            shipping=Coalesce(Sum('shipping'), V(0.0)),
        )
        .order_by('branch__Branch_Name')
    )

    consultation_data = (
        treatmentinvoicemaster.objects
        .filter(currentdate=selected_date, cancelstatus=False)
        .values('branch__Branch_Name')
        .annotate(
            consultation_fee=Coalesce(Sum(Cast('consultationfee', FloatField())), V(0.0)),
            registration_fee=Coalesce(Sum(Cast('consultationfeecumregfee', FloatField())), V(0.0)),
        )
        .annotate(
            total=Coalesce(
                Sum(Cast('consultationfee', FloatField())) +
                Sum(Cast('consultationfeecumregfee', FloatField())),
                V(0.0)
            )
        )
        .order_by('branch__Branch_Name')
    )

    pharmacy_data = (
        invoicemaster.objects
        .filter(currentdate=selected_date)
        .values('branch__Branch_Name')
        .annotate(
            total_sales=Coalesce(Sum('total'), V(0.0)),
            tax=Coalesce(Sum('tax'), V(0.0)),
            shipping=Coalesce(Sum('shipping'), V(0.0)),
        )
        .order_by('branch__Branch_Name')
    )

    # Summary totals for dashboard cards
    treatment_total = treatmentinvoicemaster.objects.filter(currentdate=selected_date, cancelstatus=False).aggregate(
        total=Coalesce(Sum('total'), V(0.0))
    )['total']

    pharmacy_total = invoicemaster.objects.filter(currentdate=selected_date).aggregate(
        total=Coalesce(Sum('total'), V(0.0))
    )['total']

    consultation_total = treatmentinvoicemaster.objects.filter(currentdate=selected_date, cancelstatus=False).aggregate(
        total=Coalesce(
            Sum(Cast('consultationfee', FloatField())) +
            Sum(Cast('consultationfeecumregfee', FloatField())),
            V(0.0)
        )
    )['total']

    context = {
        'selected_date': selected_date,
        'treatment_data': treatment_data,
        'consultation_data': consultation_data,
        'pharmacy_data': pharmacy_data,
        'treatment_total': treatment_total,
        'pharmacy_total': pharmacy_total,
        'consultation_total': consultation_total,
    }

    return render(request, 'revenuedash.html', context)
    

