logger = logging.getLogger(__name__)

def create_casehistory(request):
    if request.method == 'POST':
        try:
            # Debug: Log all POST data
            logger.info(f"create_casehistory POST data: {dict(request.POST)}")
            
            # Extract form data - REMOVE chief_complaint extraction
            patient_id = request.POST.get('ptid')
            doctor_id = request.POST.get('doctor')
            status = request.POST.get('status')
            present_complaint = request.POST.get('present_complaint')  # This is from Quill editor
            final_diagnosis = request.POST.get('final_diagnosis')
            follow_up_date = request.POST.get('follow_up_date')
            prepared_by = request.session.get('staffid')
            branch_id = request.session.get('branchid')

            logger.info(f"Extracted: patient_id={patient_id}, doctor_id={doctor_id}, status={status}")
            logger.info(f"present_complaint exists: {bool(present_complaint)}")
            logger.info(f"final_diagnosis: {final_diagnosis}")
            logger.info(f"follow_up_date: {follow_up_date}")

            # Validate required fields
            if not patient_id:
                return JsonResponse({
                    "success": False, 
                    "error": "Patient ID is required."
                }, status=400)
            
            # Validate present complaint (from Quill editor)
            if not present_complaint or present_complaint.strip() == '':
                return JsonResponse({
                    "success": False, 
                    "error": "Present Complaint is required. Please enter complaint details."
                }, status=400)
            
            # Check if it's just empty HTML
            clean_present = re.sub('<[^<]+?>', '', present_complaint).strip()
            if not clean_present:
                return JsonResponse({
                    "success": False, 
                    "error": "Present Complaint is required. Please enter complaint details."
                }, status=400)
            
            if not final_diagnosis or final_diagnosis.strip() == '':
                return JsonResponse({
                    "success": False, 
                    "error": "Final Diagnosis is required."
                }, status=400)
            
            if not status:
                return JsonResponse({
                    "success": False, 
                    "error": "Status is required."
                }, status=400)

            # Fetch related objects
            patient = get_object_or_404(Patient_details, id=patient_id)
            
            # Handle optional doctor field
            doctor = None
            if doctor_id and doctor_id.strip():
                try:
                    doctor = get_object_or_404(Staffdetails, id=doctor_id)
                except Exception as e:
                    logger.warning(f"Doctor with ID {doctor_id} not found: {str(e)}")

            # Parse follow-up date or use today
            parsed_follow_up_date = None
            if follow_up_date and follow_up_date.strip():
                try:
                    # Try different date formats
                    from datetime import datetime
                    try:
                        parsed_follow_up_date = datetime.strptime(follow_up_date, '%Y-%m-%d').date()
                    except ValueError:
                        try:
                            parsed_follow_up_date = datetime.strptime(follow_up_date, '%d-%m-%Y').date()
                        except ValueError:
                            parsed_follow_up_date = date.today()
                except Exception as e:
                    logger.warning(f"Could not parse follow_up_date '{follow_up_date}': {str(e)}")
                    parsed_follow_up_date = date.today()
            else:
                parsed_follow_up_date = date.today()

            # 🔴 REMOVED: Chief complaint extraction logic
            
            logger.info(f"Creating case history without chief_complaint extraction")

            # Create case history record - ONLY save present_complaint
            case_history = clairvedaCaseHistory.objects.create(
                patient=patient,
                assigned_doctor=doctor,
                status=status,
                # Only save present_complaint (from Quill editor)
                # present_complaint=present_complaint,
                # Keep chief_complaint empty or use present_complaint if required by model
                chief_complaint=present_complaint,  # OR use "" if you want it empty
                final_diagnosis=final_diagnosis,
                follow_up_date=parsed_follow_up_date,
                created_at=date.today(),
                prepairedby_id=prepared_by
            )
            
            request.session['cashstidtab'] = case_history.id

            logger.info(f"Case history created successfully with ID: {case_history.id}")

            return JsonResponse({
                "success": True,
                "message": "Complaint saved successfully!",
                "complaint": {
                    "id": case_history.id,
                    "present_complaint": case_history.present_complaint,
                    "chief_complaint": case_history.chief_complaint,  # Will be same as present_complaint
                    "final_diagnosis": case_history.final_diagnosis,
                    "status": case_history.status,
                    "created_at": case_history.created_at.isoformat() if hasattr(case_history.created_at, 'isoformat') else date.today().isoformat()
                }
            }, status=200)

        except Exception as e:
            logger.error(f"Error creating case history: {str(e)}", exc_info=True)
            try:
                casehistoryErrorLog.objects.create(
                    error_message=str(e),
                    related_mrno=patient_id if 'patient_id' in locals() else 'unknown',
                    staff_id=request.session.get('staffid')
                )
            except Exception as log_error:
                logger.error(f"Failed to create error log: {str(log_error)}")
            return JsonResponse({
                "success": False, 
                "error": f"An error occurred while saving data: {str(e)}"
            }, status=400)

    # GET request section - REMAINS SAME
    try:
        # Validate session
        staff_designation = request.session.get('loginstaffdesign')
        if not staff_designation:
            return redirect('staff_login')

        # Fetch required data
        diets = Diet.objects.all()
        foods = Food.objects.all().order_by('name')
        staff_id = request.session.get('staffid')
        allocated_staff = Staffallocation.objects.filter(Designation_Name__in=["2", "3", "5", "6", "9", "14"])
        groups = labtestmaster.objects.filter(status=True).prefetch_related('labtestchild_set')

        # Get patient ID from session or GET param
        patient_id_from_get = request.GET.get('ids')
        if patient_id_from_get:
            request.session['tabcasehstptid'] = patient_id_from_get
        
        tbptid = request.session.get('tabcasehstptid')

        if not tbptid:
            context = {
                'stdesign': staff_designation,
                'stffdt': allocated_staff,
                'st': staff_id,
                'diets': diets,
                'groups': groups,
                'foods': foods,
                'tbptid': None,
                'patient_prescriptions': [],
                'latescomp': [],
                'lab_results': [], 
                'lab_test': [],
                'treatments': [],
                'history': [],
                'patient_vitals': [],
                'doctors_notes': [],
                'diet_plans': [],
            }
            return render(request, "tabcasehistory.html", context)

        # Fetch prescriptions for this patient
        patient_prescriptions = Prescriptionnew.objects.filter(patient_id=tbptid).order_by('-prescriptiondate')
        
        # Fetch case history (complaints) for this patient
        # Display existing chief_complaint from database
        latescomp = clairvedaCaseHistory.objects.filter(patient_id=tbptid).order_by('-created_at')

        # Fetch patient details
        try:
            patient = Patient_details.objects.get(id=tbptid)
        except Patient_details.DoesNotExist:
            patient = None

        # ===== Fetch previous lab results =====
        lab_results = casehistorylabresult.objects.filter(patient_id=tbptid).order_by('-labtestdate')

        # ===== Fetch previous lab tests =====
        lab_test = casehistorylabtestrequisition.objects.filter(patient_id=tbptid).order_by('-created_at')

        # ===== Fetch treatments =====
        treatments = casehistorytreatmentplan.objects.filter(patient_id=tbptid,deletedstatus=False).order_by('-date')

        history = casehistorymedicalandsurgicalhistory.objects.filter(patient_id=tbptid).order_by('-created_at')
        patient_vitals = casehistryvitals.objects.filter(mrno_id=tbptid).order_by('-created_at')
        doctors_notes = casehistorydoctorsnote.objects.filter(patient_id=tbptid).order_by('-created_at')
        diet_plans = casehistorydietplan.objects.filter(patient_id=tbptid).order_by('-created_at')

        context = {
            'stdesign': staff_designation,
            'stffdt': allocated_staff,
            'st': staff_id,
            'diets': diets,
            'groups': groups,
            'foods': foods,
            'tbptid': tbptid,
            'patient': patient,
            'patient_prescriptions': patient_prescriptions,
            'latescomp': latescomp,  # This will display existing chief_complaint
            'lab_results': lab_results, 
            'lab_test': lab_test,
            'treatments': treatments,
            'history': history,
            'patient_vitals': patient_vitals,
            'doctors_notes': doctors_notes,
            'diet_plans': diet_plans,
        }

        return render(request, "tabcasehistory.html", context)

    except ObjectDoesNotExist as e:
        logger.error(f"Object not found in create_casehistory: {str(e)}")
        messages.error(request, "Menu Management details not found. Please contact the admin.")
        return redirect('error_page')
    except Exception as e:
        logger.error(f"Error in create_casehistory GET: {str(e)}", exc_info=True)
        messages.error(request, f"Unable to retrieve data: {str(e)}. Please contact admin.")
        return redirect('error_page')



