def update_medical_history(request):
    if request.method == 'POST':
        try:
            history_id = request.POST.get('history_id')
            medical_history = request.POST.get('medhist')
            prepared_by = request.session.get('staffid')

            if not history_id:
                return JsonResponse({"success": False, "error": "History ID is required."}, status=400)

            history = get_object_or_404(casehistorymedicalandsurgicalhistory, id=history_id)
            history.medicalhistory = medical_history
            history.handledbystaff_id = prepared_by
            history.save()

            return JsonResponse({
                "success": True,
                "message": "Medical history updated successfully.",
                "history": {
                    "id": history.id,
                    "medicalhistory": history.medicalhistory,
                    "surgicalhist": history.surgicalhist,
                    "created_at": history.created_at.strftime("%Y-%m-%d") if history.created_at else "",
                }
            }, status=200)

        except Exception as e:
            logger.error(f"Error updating medical history for ID {request.POST.get('history_id')}: {str(e)}")
            return JsonResponse({"success": False, "error": str(e)}, status=400)

    return JsonResponse({"success": False, "error": "Invalid request method"}, status=405)

