def get_casehistory(request):
    patient_id = request.GET.get("patient_id")
    histories = (
        clairvedaCaseHistory.objects
        .filter(patient_id=patient_id, deletestatus=False)
        .order_by("-created_at")
        .values("chief_complaint", "present_complaint", "created_at")
    )
    # format date for frontend
    results = [
        {
            "created_at": h["created_at"].strftime("%d-%m-%Y"),
            "chief_complaint": h["chief_complaint"],
            "present_complaint": h["present_complaint"],
        }
        for h in histories
    ]
    return JsonResponse(results, safe=False)

def treatment_search(request):
    query = request.GET.get("q", "").strip()
    if query:
        treatments = (
            Treatment_master.objects
            .filter(Treatment_name__icontains=query, Status="Active")  # only active treatments
            .values("id", "Treatment_name", "Rate", "Description")[:10]
        )
    else:
        treatments = Treatment_master.objects.filter(Status="Active").values("id", "Treatment_name", "Rate", "Description")[:10]

    return JsonResponse(list(treatments), safe=False)


