def testmasteredit(request):
    if request.method == "POST":
        testid = request.POST.get("testid")
        groupname = request.POST.get("groupname")
        rate = request.POST.get("rate")
        status = request.POST.get("status")  # Active / Inactive
        idmngmnt = request.session.get('testmstmngid')

        if not (testid and idmngmnt):
            messages.error(request, "Invalid request. Please contact the admin.")
            return redirect('error_page')

        try:
            obj = labtestmaster.objects.get(id=testid)

            # Validate group name unique
            if labtestmaster.objects.filter(groupname__iexact=groupname).exclude(id=testid).exists():
                messages.warning(request, "This Test Group already exists.")
                return redirect(f"{reverse('testmasteredit')}?ids={testid}&menumanagement_id={idmngmnt}")

            obj.groupname = groupname.strip()
            obj.rate = rate
            obj.status = True if status == "Active" else False
            obj.save()

            messages.success(request, "Test Master updated successfully.")
            return redirect(f"{reverse('testmaster')}?menumanagement_id={idmngmnt}")

        except labtestmaster.DoesNotExist:
            messages.error(request, "Test not found.")
            return redirect('error_page')

    else:
        idmngmnt = request.session.get('testmstmngid')
        testid = request.GET.get("ids")
       
        if not (idmngmnt and testid):
            messages.error(request, "Invalid test ID or menu ID.")
            return redirect('error_page')

        try:
            objtest = labtestmaster.objects.get(id=testid)
        except:
            messages.error(request, "Test not found.")
            return redirect('error_page')

        stdesign = request.session.get("loginstaffdesign")
        if not stdesign:
            return redirect('staff_login')

        context = {
            "objtest": objtest,
            "idmngmnt": idmngmnt,
            "stdesign": stdesign,
            "testmstrview": request.session.get("testmstmngview"),
            "testmstredit": request.session.get("testmstmngedit"),
        }

        return render(request, "testmasteredit.html", context)
