def testchild_edit(request):
    """
    Single function to handle edit test child - both display and update
    """
    # Check if user is logged in
    id=request.GET.get('ids')
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    # Get menu management ID from GET or POST or session
    idmngmnt = request.GET.get('menumanagement_id') or request.POST.get('menumanagement_id') or request.session.get('testchildmngid')
    
    if not idmngmnt:
        messages.error(request, "Menu Management ID not provided.")
        return redirect('error_page')
    
    try:
        # Get the test child record to edit
        test_child = get_object_or_404(labtestchild, id=id,status=True)
        
        # Check edit permission
        if not request.session.get('testchildedit', False):
            messages.error(request, "You don't have permission to edit test records.")
            return redirect(f"{reverse('testchild')}?menumanagement_id={idmngmnt}")
        
        # Fetch menu management details
        testchildmng = get_object_or_404(menumanagement, id=idmngmnt)
        
        # Store menu management permissions in session
        request.session['testchildmngid'] = idmngmnt
        request.session['testchildadd'] = testchildmng.add
        request.session['testchildview'] = testchildmng.view
        request.session['testchildedit'] = testchildmng.edit
        request.session['testchilddelete'] = testchildmng.delete
        
        # Handle POST request (Update)
        if request.method == 'POST':
            # Get form data
            group_id = request.POST.get('group')
            testname = request.POST.get('testname')
            status = request.POST.get('status')
            symbol = request.POST.get('symbol')
            rate = request.POST.get('rate')
            
            # Validation
            if not group_id:
                messages.error(request, "Group must be selected.")
                return redirect(f"{reverse('testchild_edit')}?ids={id}&menumanagement_id={idmngmnt}")
            
            if not testname:
                messages.error(request, "Test name cannot be empty.")
                return redirect(f"{reverse('testchild_edit')}??ids={id}&menumanagement_id={idmngmnt}")
            
            if not rate:
                messages.error(request, "Rate is required.")
                return redirect(f"{reverse('testchild_edit')}??ids={id}&menumanagement_id={idmngmnt}")
            
            try:
                # Get the group object
                group_obj = get_object_or_404(labtestmaster, id=group_id)
                
                # Convert radio value to Boolean
                status_bool = True if status == "Active" else False
                
                # Update the record
                test_child.group = group_obj
                test_child.testname = testname
                test_child.status = status_bool
                test_child.symbol = symbol
                test_child.rate = rate
                test_child.save()
                
                messages.success(request, f"Test '{testname}' updated successfully!")
                return redirect(f"{reverse('testchild')}?menumanagement_id={idmngmnt}")
                
            except Exception as e:
                messages.error(request, f"Error updating test record: {str(e)}")
                return redirect(f"{reverse('testchild_edit')}?ids={id}&menumanagement_id={idmngmnt}")
        
        # Handle GET request (Display form)
        else:
            # Fetch available groups for dropdown
            groups = labtestmaster.objects.all()
            
            context = {
                'idmngmnt': idmngmnt,
                'stdesign': stdesign,
                'testchildadd': request.session.get('testchildadd'),
                'testchildview': request.session.get('testchildview'),
                'testchildedit': request.session.get('testchildedit'),
                'testchilddelete': request.session.get('testchilddelete'),
                'groups': groups,
                'test_child': test_child,
                'edit_mode': True,
            }
            return render(request, "testchild_edit.html", context)
        
    except Exception as e:
        messages.error(request, f"Error loading test record: {str(e)}")
        return redirect(f"{reverse('testchild')}?menumanagement_id={idmngmnt}")
