def generate_requisition_number():
    """Generate unique requisition number in views.py"""
    from datetime import datetime
    prefix = "LABREQ"
    date_str = datetime.now().strftime("%Y%m%d")
    base_pattern = f"{prefix}{date_str}"
    
    last_requisition = LabRequisitionMaster.objects.filter(
        requisition_number__startswith=base_pattern
    ).order_by('-id').first()
    
    if last_requisition and last_requisition.requisition_number:
        try:
            last_num = int(last_requisition.requisition_number[-4:])
            new_num = last_num + 1
        except (ValueError, IndexError):
            new_num = 1
    else:
        new_num = 1
    
    return f"{base_pattern}{str(new_num).zfill(4)}"
@transaction.atomic
def create_casehistorylabtestrequisition(request):
    if request.method == "POST":
        try:
            # ✅ GET BOTH test_ids AND group_ids from request
            raw_tests = request.POST.get("labtests")  # Keep for backward compatibility
            raw_test_ids = request.POST.get("test_ids")  # Individual test IDs
            raw_group_ids = request.POST.get("group_ids")  # Group IDs (Select All)
            patientid = request.POST.get("selectedPatientId") or request.session.get('tabcasehstptid')
            
            if not patientid:
                return JsonResponse({"success": False, "error": "Patient ID is required"})

            # Get patient instance
            patient_instance = Patient_details.objects.filter(id=patientid).first()
            if not patient_instance:
                return JsonResponse({"success": False, "error": f"Patient with ID {patientid} not found"})

            # ✅ Parse test IDs (individual tests)
            test_ids = []
            if raw_test_ids:
                try:
                    test_ids = json.loads(raw_test_ids)
                except json.JSONDecodeError as e:
                    return JsonResponse({"success": False, "error": f"Invalid JSON for test_ids: {str(e)}"})

            # ✅ Parse group IDs (Select All groups)
            group_ids = []
            if raw_group_ids:
                try:
                    group_ids = json.loads(raw_group_ids)
                except json.JSONDecodeError as e:
                    return JsonResponse({"success": False, "error": f"Invalid JSON for group_ids: {str(e)}"})

            # ✅ Fallback: If test_ids and group_ids are empty, try using raw_tests (for backward compatibility)
            if not test_ids and not group_ids and raw_tests:
                try:
                    tests = json.loads(raw_tests)
                    test_ids = tests  # Treat all as individual tests
                except json.JSONDecodeError as e:
                    return JsonResponse({"success": False, "error": f"Invalid JSON for labtests: {str(e)}"})

            staff_id = request.session.get("staffid")
            staff_instance = Staffdetails.objects.filter(id=staff_id).first() if staff_id else None

            # Get active case history for this patient
            active_case_history = clairvedaCaseHistory.objects.filter(
                patient=patient_instance,
                deletestatus=False
            ).order_by('-created_at').first()

            saved = []
            prefix = "LABREQ"
            date_str = datetime.now().strftime("%Y%m%d")
            base_pattern = f"{prefix}{date_str}"
            
            last_requisition = LabRequisitionMaster.objects.filter(
                requisition_number__startswith=base_pattern
            ).order_by('-id').first()
            
            if last_requisition and last_requisition.requisition_number:
                try:
                    last_num = int(last_requisition.requisition_number[-4:])
                    new_num = last_num + 1
                except (ValueError, IndexError):
                    new_num = 1
            else:
                new_num = 1
            
            requisition_number = f"{base_pattern}{str(new_num).zfill(4)}"
            
            # ✅ Collect all tests to save
            all_tests_to_save = []

            # ✅ Process individual test IDs
            for test_id in test_ids:
                try:
                    labtest = labtestchild.objects.filter(id=test_id, status=True).first()
                    if labtest:
                        all_tests_to_save.append({
                            'labtest': labtest,
                            'source': 'individual',
                            'test_id': test_id,
                            'group_id': None  # ✅ Explicitly set to None for individual tests
                        })
                except (ValueError, TypeError):
                    # If not an integer, try by symbol or name
                    labtest = labtestchild.objects.filter(symbol=test_id, status=True).first()
                    if not labtest:
                        labtest = labtestchild.objects.filter(testname=test_id, status=True).first()
                    if labtest:
                        all_tests_to_save.append({
                            'labtest': labtest,
                            'source': 'individual',
                            'test_id': test_id,
                            'group_id': None  # ✅ Explicitly set to None for individual tests
                        })

            # ✅ Process group IDs (Select All) - ONLY if group_ids is not empty
            if group_ids:
                # ✅ Process each group ID
                for group_id in group_ids:
                    try:
                        # Get the group (labtestmaster)
                        labtest_group = labtestmaster.objects.filter(id=group_id, status=True).first()
                        
                        if labtest_group:
                            # Get all tests in this group
                            tests_in_group = labtestchild.objects.filter(
                                group_id=group_id, 
                                status=True
                            )
                            for labtest in tests_in_group:
                                # ✅ Check if this test is already in the list (avoid duplicates)
                                already_added = any(
                                    item['labtest'].id == labtest.id 
                                    for item in all_tests_to_save
                                )
                                if not already_added:
                                    all_tests_to_save.append({
                                        'labtest': labtest,
                                        'source': 'group',
                                        'group_id': group_id,  # ✅ Store the group ID
                                        'labtest_group': labtest_group  # ✅ Store the group object
                                    })
                    except Exception as e:
                        print(f"Error processing group {group_id}: {str(e)}")

            with transaction.atomic():
                # ✅ Create Master Requisition
                requisition_master = LabRequisitionMaster.objects.create(
                    requisition_number=requisition_number,
                    patient=patient_instance,
                    created_by=staff_instance,
                    notes=f"Requisition created with {len(all_tests_to_save)} tests ({len(test_ids)} individual, {len(group_ids)} groups)"
                )
                
                # ✅ Create Child Items with group reference
                for item in all_tests_to_save:
                    labtest = item['labtest']
                    group_id = item.get('group_id')  # ✅ Get group ID if from group
                    
                    # ✅ IMPORTANT: Only save group_id if it's from a group (Select All)
                    # For individual tests, group_id should be None
                    if item['source'] == 'individual':
                        group_id_to_save = None
                    else:
                        group_id_to_save = group_id
                    
                    obj = casehistorylabtestrequisition.objects.create(
                        patient=patient_instance,
                        case_history=active_case_history,
                        labtestchild=labtest,
                        handledbystaff=staff_instance,
                        requisition_master=requisition_master,
                        labtestgroup_id=group_id_to_save,  # ✅ Save the group ID only for group tests
                        created_at=timezone.now()
                    )
                    
                    saved.append({
                        "id": obj.id,
                        "created_at": obj.created_at.strftime("%Y-%m-%d") if obj.created_at else "",
                        "testname": labtest.testname,
                        "symbol": labtest.symbol or labtest.testname,
                        "requisition_number": requisition_number,
                        "source": item['source'],
                        "group_id": group_id_to_save,  # ✅ Include group_id in response
                        "group_name": item.get('labtest_group').groupname if item.get('labtest_group') else None
                    })

            return JsonResponse({
                "success": True, 
                "labtests": saved,
                "requisition_id": requisition_master.id,
                "requisition_number": requisition_number,
                "tests_saved": len(test_ids),
                "groups_saved": len(group_ids),
                "total_saved": len(saved),
                "message": f"Saved {len(saved)} tests successfully"
            })
            
        except Exception as e:
            print(f"Error: {str(e)}")
            import traceback
            traceback.print_exc()
            return JsonResponse({"success": False, "error": str(e)})
    
    return JsonResponse({"success": False, "error": "Invalid request method"})




def medicine_search(request):
    query = request.GET.get("q", "").strip()

    # Get branch id from session
    stbranchid = request.session.get("branchid")
    if not stbranchid:
        return JsonResponse({"error": "No branch in session."}, status=401)

    # Search stock for this branch only
    stock_qs = Physicalstockdetails.objects.select_related(
        "itemnm", "Comapany_name"
    ).filter(
        deleted=False,
        stockbranch_id=stbranchid
    )

    if query:
        stock_qs = stock_qs.filter(itemnm__itemnm__icontains=query)

    stock_qs = stock_qs[:10]

    results = [
        {
            "id": stock.itemnm.id,                               # medicine id
            "name": stock.itemnm.itemnm,                         # medicine name
            "brand": stock.Comapany_name.Comapany_name if stock.Comapany_name else "",
            "stockid": stock.id,
            "qty": stock.qty,
            
        }
        for stock in stock_qs
    ]

    return JsonResponse(results, safe=False)

