# Patient history for tabs
def patient_history(request):
    mrno = request.GET.get('mrno')
    patient = get_object_or_404(Patient_details, id=mrno)

    # Get all case histories
    case_histories = clairvedaCaseHistory.objects.filter(patient=patient, deletestatus=False).order_by('-created_at')

    diagnosis_data = []
    notes_data = []
    diet_data = []
    labtests_data = []
    prescriptions_data = []

    for case in case_histories:
        # Diagnosis info
        diagnosis_data.append({
            'date': case.created_at,
            'chief_complaint': case.chief_complaint,
            'present_complaint': case.present_complaint,
            'final_diagnosis': case.final_diagnosis,
            'status': case.status,
            'follow_up_date': case.follow_up_date
        })

        # Doctor notes
        for note in case.casehistorydoctorsnote.all():
            notes_data.append({
                'date': note.created_at,
                'notes': note.notes
            })

        # Diet plans
        for diet in case.casehistorydietplan.all():
            diet_data.append({
                'date': diet.created_at,
                'diet': diet.diet.diet_name if diet.diet else '',
                'notes': diet.notes,
                'noofdays': diet.noofdays,
                'foodtobeavoided': diet.foodtobeavoided
            })

        # Lab tests
        for lab in case.casehistorylabtestrequisition.all():
            labtests_data.append({
                'date': lab.created_at,
                'testname': lab.labtestchild.testname if lab.labtestchild else ''
            })

        # Prescriptions
        for pres in case.Prescriptionnew.all():
            prescriptions_data.append({
                'date': pres.prescriptiondate,
                'medicine_name': pres.medicine_name,
                'moringtime': pres.moringtime,
                'noontime': pres.noontime,
                'nighttime': pres.nighttime,
                'beforeorafterdiet': pres.beforeorafterdiet,
                'guideline': pres.medicineguideline,
                'noofdays': pres.noofdays
            })
    vitals_qs = casehistryvitals.objects.filter(mrno_id=mrno).order_by("-created_at")
    vitals_data = [
        {
            'date': v.created_at.strftime("%Y-%m-%d %H:%M"),
            'bp': v.bp,
            'weight': v.weight,
            'height': v.height,
            'bmi': v.bmi,
            'fbs': v.fbs,
            'ppbs': v.ppbs,
            'hba1c': v.hba1c,
            'tchol': v.tchol,
            'hdl': v.hdl,
            'tg': v.tg,
            'ldl': v.ldl,
            's_creatinine': v.s_creatinine,
            'uric_acid': v.uric_acid,
            'sgpt': v.sgpt,
            'sgot': v.sgot,
            'alcohol': v.alcohol,
            'smoking': v.smoking
        }
        for v in vitals_qs
    ]
    treatments_data = []
    for case in case_histories:
        for trmnt in case.casetreatmntplan.all():
            treatments_data.append({
                'date': trmnt.date,
                'treatment': trmnt.treatment.treatment_name if trmnt.treatment else '',
                'count': trmnt.count,
                'preparedby': trmnt.prepairedby.full_name if trmnt.prepairedby else ''
            })
    labresults_data = []
    for case in case_histories:
        for labres in case.caselabresults.all():
            labresults_data.append({
                'date': labres.created_at,
                'test': labres.labtest.testname if labres.labtest else '',
                'result_value': labres.result_value,
                'normal_value': labres.normal_value,
                'report_file': labres.report_file.url if labres.report_file else ''
            })

    return JsonResponse({
        'diagnosis': diagnosis_data,
        'notes': notes_data,
        'diets': diet_data,
        'labtests': labtests_data,
        'prescriptions': prescriptions_data,
       'vitals': vitals_data,
        'treatments': treatments_data,
           'labresults': labresults_data
    })

def get_patient_full_history(request):
    mrno = request.GET.get("mrno")
    patient = get_object_or_404(Patient_details, id=mrno)
    histories = patient.case_histories.filter(deletestatus=False).order_by('-created_at')
    vitals = casehistryvitals.objects.filter(mrno=patient).order_by('-created_at')
    labresults = casehistorylabresult.objects.filter(patient=patient).order_by('-created_at')

    data = {
        "case_history": [],
        "doctors_notes": [],
        "diet_plans": [],
        "lab_tests": [],
        "med_surg_history": [],
        "prescriptions": [],
         "vitals": [],
         "labresults": []
    }
    for h in histories:
        data["case_history"].append({
            "id": h.id,  # Add this line to include the ID
            "date": h.created_at.strftime("%Y-%m-%d"),
            "status": h.status,
            "chief": h.chief_complaint,
            "present": h.present_complaint,
            "diagnosis": h.final_diagnosis,
            "follow_up": h.follow_up_date.strftime("%Y-%m-%d") if h.follow_up_date else ""
        })
        data["doctors_notes"] += list(h.doctorsnote.values("notes", "created_at"))
        data["diet_plans"] += list(h.casehistdietplan.values( "diet__name", "noofdays", "foodtobeavoided", "created_at"))
        data["lab_tests"] += list(h.casehistlabtest.values("labtestchild__testname", "created_at"))
        data["med_surg_history"] += list(h.casehistory.values("id","medicalhistory", "surgicalhist", "created_at"))
        data["prescriptions"] += list(h.prescriptionnew.values("id",
            "medicine_name", "moringtime", "noontime", "nighttime",
            "beforeorafterdiet", "medicineguideline", "noofdays", "prescriptiondate"
        ))
    for v in vitals:
        data["vitals"].append({
            "id": v.id, 
            "date": v.created_at.strftime("%Y-%m-%d %H:%M"),
            "age": v.age,
            "weight": v.weight,
            "height": v.height,
            "bmi": v.bmi,
            "pr":v.pr,
            "spo2":v.spo2,
            "temperature":v.temperature,
            "bp": v.bp,
            "fbs": v.fbs,
            "ppbs": v.ppbs,
            "hba1c": v.hba1c,
            "tchol": v.tchol,
            "hdl": v.hdl,
            "tg": v.tg,
            "ldl": v.ldl,
            "s_creatinine": v.s_creatinine,
            "uric_acid": v.uric_acid,
            "sgpt": v.sgpt,
            "sgot": v.sgot,
            "alcohol": v.alcohol,
            "smoking": v.smoking,
          
        })
    for lr in labresults:
        data["labresults"].append({
            "date": lr.labtestdate,
            "test": lr.labtest.testname if lr.labtest else None,
            "result_value": lr.result_value,
            "normal_value": lr.normal_value,
            "report_file": lr.report_file.url if lr.report_file else None,
            "preparedby": lr.preparedby.Staff_firstname if lr.preparedby else None,
        })
    return JsonResponse({
    "patient": {
        "id": patient.id,
        "Patient_Name": patient.Patient_Name,
        "Medical_Record_Number": patient.Medical_Record_Number,
        "contactno": patient.contactno,
        "Gender": patient.Gender,
        "address": patient.address
    },
    "history": data
})

