    prescriptions = (
        Prescriptionnew.objects
        .select_related('physicalstock')  # adjust to match your field name
        .filter(patient_id=case_id)
    )

    data = []
    for p in prescriptions:
        stock = p.physicalstock  # adjust to correct field name
