def save_unregistered_patient_from_get(request):
    """
    Save a new unregistered patient from GET request (modal submission)
    """
    try:
        # Get data from GET parameters
        patient_name = request.GET.get('patient_name', '').strip()
        patient_age = request.GET.get('patient_age', '').strip()
        patient_gender = request.GET.get('patient_gender', '').strip()
        patient_phone = request.GET.get('patient_phone', '').strip()
        patient_email = request.GET.get('patient_email', '').strip()
        patient_address = request.GET.get('patient_address', '').strip()
        
        # Validate required fields
        if not patient_name:
            return JsonResponse({'success': False, 'error': 'Patient name is required'})
        
        if not patient_age:
            return JsonResponse({'success': False, 'error': 'Patient age is required'})
        
        if not patient_gender:
            return JsonResponse({'success': False, 'error': 'Patient gender is required'})
        
        if not patient_phone:
            return JsonResponse({'success': False, 'error': 'Contact number is required'})
        
        # Validate age is numeric
        try:
            age_float = float(patient_age)
            if age_float < 0 or age_float > 150:
                return JsonResponse({'success': False, 'error': 'Invalid age. Age must be between 0 and 150'})
        except ValueError:
            return JsonResponse({'success': False, 'error': 'Age must be a valid number'})
        
        # Get branch from session
        branch_id = request.session.get('branch_id')
        if not branch_id:
            from .models import Branch
            first_branch = Branch.objects.filter(inactive=False).first()
            if first_branch:
                branch_id = first_branch.id
            else:
                return JsonResponse({'success': False, 'error': 'No branch found'})
        
        with transaction.atomic():
            # Generate MR Number
            todate = datetime.now().strftime("%Y%m%d")
            
            # Get last entry for today
            last_entry = Patient_details.objects.filter(
                Entry_Date=todate
            ).select_for_update().order_by('-id').first()
            
            refnid = 1
            if last_entry and last_entry.Medical_Record_Number:
                try:
                    refnid = int(last_entry.Medical_Record_Number[12:]) + 1
                except (ValueError, IndexError):
                    refnid = 1
            
            mrn_id = f"MRNO{todate}{refnid}"
            
            # Create new patient
            patient = Patient_details.objects.create(
                Patient_Name=patient_name,
                contactno=patient_phone,
                address=patient_address if patient_address else '',
                Age=str(age_float),
                Gender=patient_gender,
                Email=patient_email if patient_email else '',
                Medical_Record_Number=mrn_id,
                Entry_Date=todate,
                Date=datetime.now().date(),
                Branch_Name_id=branch_id,
                consultation_type='offline',
                deleted=False
            )
        
        # Return success response
        return JsonResponse({
            'success': True,
            'patient_id': patient.id,
            'patient_name': patient.Patient_Name,
            'mr_number': patient.Medical_Record_Number,
            'patient_phone': patient.contactno,
            'patient_age': patient.Age,
            'patient_gender': patient.Gender,
            'message': f'Patient {patient_name} registered successfully'
        })
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return JsonResponse({'success': False, 'error': str(e)})

@transaction.atomic 
def save_lab_invoice(request):
    staff_id = request.session.get('staffid')
    if not staff_id:
        return redirect('staff_login')

    if request.method == 'GET':
        patient_name = request.GET.get('patient_name')
        if patient_name:
            return save_unregistered_patient_from_get(request)
        return JsonResponse({'success': False, 'error': 'Invalid GET request'})
    
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request'})

    try:
        data = request.POST

        # Generate Invoice Number
        invoiceno = data.get('invno')
        if not invoiceno:
            today = date.today()
            last_invoice = LabInvoiceMaster.objects.filter(
                invoiceno__startswith=f"LAB-{today.year}-{today.month:02d}-"
            ).order_by('-invoiceno').first()
            
            if last_invoice:
                try:
                    last_num = int(last_invoice.invoiceno.split('-')[-1])
                    new_num = last_num + 1
                except:
                    new_num = 1
            else:
                new_num = 1
            invoiceno = f"LAB-{today.year}-{today.month:02d}-{new_num:04d}"

        # Patient Info
        patient_id = data.get('mrnum')
        patient = None
        
        if patient_id:
            try:
                patient = Patient_details.objects.get(id=patient_id)
            except Patient_details.DoesNotExist:
                return JsonResponse({'success': False, 'error': 'Patient not found'})
        
        if not patient:
            return JsonResponse({'success': False, 'error': 'Patient ID required'})

        # NEW: Get IP Credit checkbox value
        ip_credit = data.get('ip_credit', 'false') == 'true'

        today_date = date.today()
        
        # Get pending requisition
        pending_requisitions = LabRequisitionMaster.objects.filter(
            patient=patient,
            created_at__date=today_date,
            invoice__isnull=True,
            is_cancelled=False
        )
        
        if not pending_requisitions.exists():
            messages.warning(request, 'No pending lab requisitions found. Tests will be saved as extra items.')
            pending_requisition = None
        else:
            pending_requisition = pending_requisitions.first()

        # Financials
        subtotal = float(data.get('totsubtoal') or 0)
        tax_percentage = float(data.get('taxperc') or 0)
        discount = float(data.get('discount') or 0)
        cfee = float(data.get('cfee') or 0)
        # Registration fee is always 0 (hidden)
        rgfee = 0.00
        total = float(data.get('totalIncludingTax') or 0)

        tax_amount = (subtotal * tax_percentage) / 100

        # Payment Details - If IP Credit is checked, reset all payments
        if ip_credit:
            cash_amount = 0
            gpay_amount = 0
            card_amount = 0
            credit_amount = 0
            is_credit = False
            payment_status = "IP Credit"
        else:
            cash_amount = float(data.get('cash_amount') or 0)
            gpay_amount = float(data.get('gpay_amount') or 0)
            card_amount = float(data.get('card_amount') or 0)
            credit_amount = float(data.get('credit_amount') or 0)
            is_credit = credit_amount > 0
            payment_status = "Credit" if is_credit else "Paid"
        
        # Create Invoice
        invoice = LabInvoiceMaster.objects.create(
            invoiceno=invoiceno,
            patient=patient,
            subtotal=subtotal,
            tax_percentage=tax_percentage,
            tax_amount=tax_amount,
            discount=discount,
            consultation_fee=cfee,
            registration_fee=rgfee,  # Always 0
            total=total,
            cash_amount=cash_amount,
            gpay_amount=gpay_amount,
            card_amount=card_amount,
            credit_amount=credit_amount,
            is_credit=is_credit,
            payment_status=payment_status,
            created_by_id=staff_id,
            ip_credit=ip_credit  # NEW: Save IP Credit flag
        )
        
        # ✅ Save Test Items
        i = 1
        requisition_items_linked = 0
        extra_items_added = 0
        group_items_processed = 0
        
        while True:
            test_id = data.get(f'testid{i}')
            if not test_id:
                break
                
            test_name = data.get(f'testname{i}')
            qty = float(data.get(f'qty{i}') or 0)
            rate = float(data.get(f'rate{i}') or 0)
            amount = float(data.get(f'amount{i}') or 0)
            
            # ✅ Check if this is a group (starts with "group_" in test_id)
            is_group = str(test_id).startswith('group_')
            
            if is_group:
                # ✅ Extract group ID from test_id (format: group_123)
                group_id = test_id.replace('group_', '')
                
                # ✅ Get the group object
                from .models import labtestmaster
                group_obj = labtestmaster.objects.filter(id=group_id).first()
                
                if group_obj:
                    # ✅ SAVE AS GROUP - Single entry with group reference
                    LabInvoiceChild.objects.create(
                        invoice=invoice,
                        sl_no=i,
                        testname=test_name,
                        qty=qty,
                        rate=rate,
                        amount=amount,
                        test=None,           # ✅ No individual test
                        group=group_obj,     # ✅ Store group reference
                    )
                    
                    # ✅ Link all requisition items in this group
                    if pending_requisition:
                        from .models import casehistorylabtestrequisition
                        # Get all requisition items belonging to this group
                        group_requisition_items = casehistorylabtestrequisition.objects.filter(
                            requisition_master=pending_requisition,
                            labtestgroup_id=group_id
                        )
                        
                        if group_requisition_items.exists():
                            # Link all items in this group to the invoice
                            for req_item in group_requisition_items:
                                req_item.invoice = invoice
                                req_item.save()
                                requisition_items_linked += 1
                        else:
                            extra_items_added += 1
                    else:
                        extra_items_added += 1
                    
                    group_items_processed += 1
                    
            else:
                # ✅ INDIVIDUAL TEST
                # Get the test object
                from .models import labtestchild
                test_obj = labtestchild.objects.filter(id=test_id).first()
                
                LabInvoiceChild.objects.create(
                    invoice=invoice,
                    sl_no=i,
                    testname=test_name,
                    qty=qty,
                    rate=rate,
                    amount=amount,
                    test=test_obj,       # ✅ Individual test reference
                    group=None,          # ✅ No group
                )
                
                # Link to requisition if exists
                if pending_requisition:
                    from .models import casehistorylabtestrequisition
                    requisition_item = casehistorylabtestrequisition.objects.filter(
                        requisition_master=pending_requisition,
                        labtestchild_id=test_id
                    ).first()
                    if requisition_item:
                        requisition_item.invoice = invoice
                        requisition_item.save()
                        requisition_items_linked += 1
                    else:
                        extra_items_added += 1
                else:
                    extra_items_added += 1
            
            i += 1
        
        # Update requisition master if it exists
        if pending_requisition:
            pending_requisition.invoice = invoice
            pending_requisition.save()
        
        message_parts = []
        if requisition_items_linked > 0:
            message_parts.append(f"{requisition_items_linked} requisition test(s) linked")
        if extra_items_added > 0:
            message_parts.append(f"{extra_items_added} extra test(s) added")
        if group_items_processed > 0:
            message_parts.append(f"{group_items_processed} group(s) processed")
        
        if message_parts:
            messages.success(request, f"Invoice {invoice.invoiceno} created successfully!")
        
        # Redirect based on IP Credit or payment type
        if ip_credit:
            # For IP Credit, show print option directly
            return redirect(reverse('lab_invoice_print_option') + f"?invid={invoice.id}")
        elif is_credit:
            return redirect('lab_invoice_list')
        else:
            return redirect(reverse('lab_invoice_print_option') + f"?invid={invoice.id}")
       
    except Exception as e:
        import traceback
        traceback.print_exc()
        return JsonResponse({'success': False, 'error': str(e)})

def lab_invoice_cancel(request):
    invoice_id = request.GET.get('invoice_id')
    staff_id=request.session.get('staffid')
    if not invoice_id:
        messages.error(request, "Invoice ID is required.")
        return redirect('lab_invoice_list')

    invoice = get_object_or_404(LabInvoiceMaster, id=invoice_id)

    if invoice.is_cancelled:
        messages.warning(request, "This invoice is already cancelled.")
    else:
        invoice.is_cancelled = True
        invoice.cancelled_by_id = staff_id
        invoice.cancelled_at = timezone.now()
        invoice.save()
        messages.success(request, f"Lab Invoice {invoice.invoiceno} has been cancelled successfully.")

    return redirect('lab_invoice_list')


