def get_test_normal_values(request):
    test_id = request.GET.get('test_id')
    gender = request.GET.get('gender', '')
    age = request.GET.get('age', None)
    
    if not test_id:
        return JsonResponse({'error': 'Test ID required'}, status=400)
    
    try:
        test = labtestchild.objects.get(id=test_id)
    except labtestchild.DoesNotExist:
        return JsonResponse({'error': 'Test not found'}, status=404)
    
    # Get normal values for this test
    normal_values = NormalValueMaster.objects.filter(testchild_id=test_id, status=True)
    
    # Apply gender filter if provided
    if gender:
        normal_values = normal_values.filter(
            Q(gender=gender) | Q(gender='Both') | Q(gender='') | Q(gender__isnull=True)
        )
    
    # Apply age filter if provided
    if age:
        try:
            age_float = float(age)
            # Create a list of matching values
            matching_values = []
            for nv in normal_values:
                if (nv.age_from is None and nv.age_to is None):
                    matching_values.append(nv)
                elif (nv.age_from is not None and nv.age_to is not None and 
                      nv.age_from <= age_float <= nv.age_to):
                    matching_values.append(nv)
            normal_values = matching_values
        except ValueError:
            pass
    
    data = []
    for nv in normal_values:
        age_range = "Any"
        if nv.age_from is not None or nv.age_to is not None:
            age_range = f"{nv.age_from or 'Any'} - {nv.age_to or 'Any'}"
        
        data.append({
            'id': nv.id,
            'gender': nv.gender or 'Any',
            'age_range': age_range,
            'unit': nv.unit.unit if nv.unit else '',
            'min_value': str(nv.min_value),
            'max_value': str(nv.max_value),
        })
    
    return JsonResponse({
        'test_name': test.testname,
        'test_symbol': test.symbol or '',
        'normal_values': data
    })

