def lab_invoice_list(request):
    """View to display list of lab invoices with filter by date range"""
    
    # Get date range from request
    sdate = request.GET.get('sdate')
    edate = request.GET.get('edate')
    payment_status = request.GET.get('payment_status')

    # Base queryset
    invoices = LabInvoiceMaster.objects.all().order_by('-id')
    
    # Apply date filter if provided
    if sdate and edate:
        try:
            start_date = datetime.strptime(sdate, '%Y-%m-%d').date()
            end_date = datetime.strptime(edate, '%Y-%m-%d').date()
            invoices = invoices.filter(date__range=[start_date, end_date])
        except ValueError:
            messages.error(request, "Invalid date format")
    
    if payment_status and payment_status != '':
        invoices = invoices.filter(payment_status=payment_status)
    
    invoices = invoices.annotate(
        has_results=Exists(
            LabResultMaster.objects.filter(
                invoice=OuterRef('id'),
                is_completed=True
            )
        )
    )
    # Calculate total amount for filtered invoices
    total_amount = invoices.exclude(is_cancelled=True).aggregate(Sum('total'))['total__sum'] or 0
    
    context = {
        'invoices': invoices,
        'total_amount': total_amount,
        'sdate': sdate if sdate else '',
        'edate': edate if edate else '',
        'payment_status':payment_status
    }
    
    return render(request, 'lab_invoice_list.html', context)


