def normal_value_edit(request):
    """Single function to handle edit - GET to display, POST to update"""
    
    # Handle POST request (Update)
    if request.method == "POST":
        normal_id = request.POST.get('id')
        
        if not normal_id:
            messages.error(request, "Normal Value ID not provided")
            return redirect('normal_value_list')
        
        try:
            normal_value = get_object_or_404(NormalValueMaster, id=normal_id)
            
            # Get form data
            test_id = request.POST.get("group")
            gender = request.POST.get("gender")
            age_from = request.POST.get("age_from")
            age_to = request.POST.get("age_to")
            unit_id = request.POST.get("unit")
            min_value = request.POST.get("min_value")
            max_value = request.POST.get("max_value")
            
            # Validate min and max
            if float(min_value) >= float(max_value):
                messages.error(request, "Min value must be less than Max value")
                return redirect(f"{reverse('normal_value_edit')}?id={normal_id}")
            
            # Convert empty age values to None
            age_from = age_from if age_from != "" else None
            age_to = age_to if age_to != "" else None
            
            # Update the record
            normal_value.testchild_id = test_id
            normal_value.gender = gender
            normal_value.age_from = age_from
            normal_value.age_to = age_to
            normal_value.unit_id = unit_id if unit_id else None
            normal_value.min_value = min_value
            normal_value.max_value = max_value
            normal_value.save()
            
            messages.success(request, "Normal Value Updated Successfully!")
            return redirect('normal_value_list')
            
        except Exception as e:
            messages.error(request, f"Error updating normal value: {str(e)}")
            return redirect(f"{reverse('normal_value_edit')}?id={normal_id}")
    
    # Handle GET request (Display form)
    else:
        normal_id = request.GET.get('id')
        
        if not normal_id:
            messages.error(request, "Normal Value ID not provided")
            return redirect('normal_value_list')
        
        try:
            normal_value = get_object_or_404(NormalValueMaster, id=normal_id)
            lbchild = labtestchild.objects.all()
            unt = labunitmaster.objects.filter(status=True)
            
            context = {
                'normal_value': normal_value,
                'lbchild': lbchild,
                'unt': unt,
            }
            return render(request, 'normal_value_edit.html', context)
        except Exception as e:
            messages.error(request, f"Error loading normal value: {str(e)}")
            return redirect('normal_value_list')
        
def search_lab_group(request):
    """Search lab test groups (labtestmaster)"""
    term = request.GET.get('term', '')
    if term:
        groups = labtestmaster.objects.filter(
            Q(groupname__icontains=term) & Q(status=True)
        ).order_by('groupname')[:10]
        
        results = []
        for group in groups:
            results.append({
                'id': group.id,
                'label': f"{group.groupname}",  # Required for autocomplete
                'value': group.groupname,       # Also needed
                'groupname': group.groupname
            })
        return JsonResponse(results, safe=False)
    return JsonResponse([], safe=False)

def search_lab_child(request):
    """Search individual lab tests (labtestchild)"""
    term = request.GET.get('term', '')
    if term:
        children = labtestchild.objects.filter(
            Q(testname__icontains=term) & Q(status=True)
        ).select_related('group').order_by('testname')[:10]
        
        results = []
        for child in children:
            results.append({
                'id': child.id,
                'label': f"{child.testname} - ₹{child.rate if child.rate else '0'}",  # Display with rate
                'value': child.testname,       # Also needed
                'testname': child.testname,
                'rate': child.rate if child.rate else "0"
            })
        return JsonResponse(results, safe=False)
    return JsonResponse([], safe=False)

