def get_lab_results(request):
    if request.method == "GET":
        patient_id = request.GET.get("patient_id")
        if not patient_id:
            return JsonResponse({"success": False, "error": "Patient ID required"})

        try:
            results = (
                casehistorylabresult.objects
                .filter(patient_id=patient_id)
                .select_related("labtest")
                .order_by("-created_at")
            )

            results_data = []
            for result in results:
                # Use labtestdate if available, otherwise use created_at date
                if result.labtestdate:
                    date_display = result.labtestdate.strftime("%Y-%m-%d")
                elif result.created_at:
                    date_display = result.created_at.strftime("%Y-%m-%d")
                else:
                    date_display = ""
                
                results_data.append({
                    "id": result.id,
                    "test": result.labtest.testname if result.labtest else "Unknown Test",
                    "result_value": result.result_value or "",
                    "normal_value": result.normal_value or "",
                    "date": result.created_at.strftime("%Y-%m-%d %H:%M") if result.created_at else "",
                    "labtestdate": result.labtestdate.strftime("%Y-%m-%d") if result.labtestdate else "",
                    "report_file": result.report_file.url if result.report_file else None,
                    "created_at": result.created_at.strftime("%Y-%m-%d %H:%M") if result.created_at else "",
                })

            return JsonResponse({"success": True, "results": results_data})

        except Exception as e:
            return JsonResponse({"success": False, "error": str(e)})

    return JsonResponse({"success": False, "error": "Invalid request method"})

