def update_lab_result(request):
    if request.method == "POST":
        try:
            result_id = request.POST.get("result_id")
            if not result_id:
                return JsonResponse({"success": False, "error": "No result ID provided."})

            result = casehistorylabresult.objects.get(id=result_id)
            
            # Update fields
            result.result_value = request.POST.get("result_value")
            result.normal_value = request.POST.get("normal_value")
            
            # Update test date if provided
            test_date_str = request.POST.get("test_date")
            if test_date_str:
                try:
                    test_date = datetime.strptime(test_date_str, "%Y-%m-%d").date()
                    result.labtestdate = test_date
                except (ValueError, TypeError):
                    pass
            
            # Update report file if provided
            report_file = request.FILES.get("report_file")
            if report_file:
                result.report_file = report_file
            
            result.save()
            
            return JsonResponse({"success": True})
        except casehistorylabresult.DoesNotExist:
            return JsonResponse({"success": False, "error": "Lab result not found."})
        except Exception as e:
            return JsonResponse({"success": False, "error": str(e)})
    
    return JsonResponse({"success": False, "error": "Invalid request method"})

def delete_lab_result(request):
    if request.method == "POST":
        try:
            result_id = request.POST.get("result_id")
            if not result_id:
                return JsonResponse({"success": False, "error": "No result ID provided."})

            result = casehistorylabresult.objects.get(id=result_id)
            result.delete()
            
            return JsonResponse({"success": True})
        except casehistorylabresult.DoesNotExist:
            return JsonResponse({"success": False, "error": "Lab result not found."})
        except Exception as e:
            return JsonResponse({"success": False, "error": str(e)})
    
    return JsonResponse({"success": False, "error": "Invalid request method"})


def update_group_lab_results(request):
    if request.method == "POST":
        try:
            patient_id = request.POST.get("patient_id")
            group_date = request.POST.get("group_date")
            group_time = request.POST.get("group_time", "00:00")
            
            if not patient_id or not group_date:
                return JsonResponse({"success": False, "error": "Missing required data"})
            
            # Create full datetime string
            full_datetime = f"{group_date} {group_time}"
            
            # Get arrays of data
            result_ids = request.POST.getlist("result_ids[]")
            result_values = request.POST.getlist("result_values[]")
            normal_values = request.POST.getlist("normal_values[]")
            test_dates = request.POST.getlist("test_dates[]")
            
            # Update report file if provided
            report_file = request.FILES.get("report_file")
            
            updated_count = 0
            
            # Update each result
            for i, result_id in enumerate(result_ids):
                try:
                    result = casehistorylabresult.objects.get(id=result_id, patient_id=patient_id)
                    
                    # Update values if provided
                    if i < len(result_values):
                        result.result_value = result_values[i]
                    if i < len(normal_values):
                        result.normal_value = normal_values[i]
                    if i < len(test_dates) and test_dates[i]:
                        try:
                            test_date = datetime.strptime(test_dates[i], "%Y-%m-%d").date()
                            result.labtestdate = test_date
                        except (ValueError, TypeError):
                            pass
                    
                    # Update report file if provided (same file for all in group)
                    if report_file:
                        result.report_file = report_file
                    
                    # Update the created_at field to maintain grouping
                    try:
                        new_datetime = datetime.strptime(full_datetime, "%Y-%m-%d %H:%M")
                        result.created_at = new_datetime
                    except (ValueError, TypeError):
                        pass
                    
                    result.save()
                    updated_count += 1
                    
                except casehistorylabresult.DoesNotExist:
                    continue
                except Exception as e:
                    print(f"Error updating result {result_id}: {str(e)}")
                    continue
            
            return JsonResponse({
                "success": True,
                "message": f"Successfully updated {updated_count} lab results",
                "updated_count": updated_count
            })
            
        except Exception as e:
            return JsonResponse({"success": False, "error": str(e)})
    
    return JsonResponse({"success": False, "error": "Invalid request method"})    


def food_list(request):
    foods = Food.objects.all().order_by('name')
    context = {
        'foods': foods,
        'stdesign': request.session.get('loginstaffdesign')
    }
    return render(request, 'food_list.html', context)

def food_create(request):
    if request.method == 'POST':
        name = request.POST.get('name')
        
        if not name:
            messages.error(request, "Food name is required.")
            return redirect('food_list')
        
        if Food.objects.filter(name__iexact=name).exists():
            messages.warning(request, "This food already exists.")
            return redirect('food_list')
        
        try:
            Food.objects.create(name=name)
            messages.success(request, "Food item created successfully!")
            return redirect('food_list')
        except Exception as e:
            messages.error(request, f"Error creating food item: {str(e)}")
            return redirect('food_list')
    
    foods = Food.objects.all().order_by('name')
    context = {
        'foods': foods,
        'stdesign': request.session.get('loginstaffdesign')
    }
    return render(request, 'food_list.html', context)
    
