from django.utils.timezone import now
from django.db.models import Max
def pharmacyqueue(request):
    st = request.session['loginstaff']
    staff_branch = Staffallocation.objects.get(id=st)
    staffbranchid = staff_branch.Branch_Name_id  # ✅ branch ID of staff

    today = now().date()

    # ✅ Get patients only from this staff's branch
    patient = Patient_details.objects.filter(Branch_Name_id=staffbranchid)

    # ✅ Get the latest prescription for each patient today
    pharmacy_queue = Prescriptionnew.objects.filter(
        prescriptiondate=today,
        patient_id__in=patient.values_list("id", flat=True)
    ).values('patient').annotate(
        latest_prescription=Max('id')
    )

    # ✅ Get the full prescription objects for the latest ones
    latest_prescriptions = Prescriptionnew.objects.filter(
        id__in=[item['latest_prescription'] for item in pharmacy_queue]
    )

    staff = Staffdetails.objects.all()

    context = {
        "pharmacy_queue": latest_prescriptions,
        "patient": patient,
        "staff": staff,
    }
    return render(request, "pharmacy_queue_list.html", context)
def get_financial_year():
    """Return current financial year in display format (YY/YY)"""
    today = date.today()
    year = today.year
    next_year = year + 1
    
    # Financial year starts from April 1
    if today.month >= 4:
        return f"{str(year)[-2:]}/{str(next_year)[-2:]}"  # 26/27
    else:
        return f"{str(year-1)[-2:]}/{str(year)[-2:]}"    # 25/26


def get_financial_year_compact():
    """Return compact financial year (YYYY)"""
    today = date.today()
    year = today.year
    next_year = year + 1
    
    if today.month >= 4:
        return f"{str(year)[-2:]}{str(next_year)[-2:]}"  # 2627
    else:
        return f"{str(year-1)[-2:]}{str(year)[-2:]}"    # 2526


# ------------------ SAFE FLOAT ------------------
def safe_float(value):
    try:
        return float(value) if value else 0.0
    except (TypeError, ValueError):
        return 0.0


