# ------------------ OWN BRANCH INVOICE GENERATOR ------------------
@transaction.atomic
def generate_own_invoice(branch_code, digits=5):
    """
    Generate invoice number for own branches
    Format: HOC/00001/2627
    """
    fy_compact = get_financial_year_compact()
    pattern = f"{branch_code}/"
    
    # Get existing invoices for this branch
    invoices = (
        newInvoiceMaster.objects.select_for_update()
        .filter(Invoicenumber__startswith=pattern)
        .values_list("Invoicenumber", flat=True)
    )
    
    last_num = 0
    
    for inv in invoices:
        try:
            # Parse format: HOC/00001/2627
            parts = inv.split('/')
            if len(parts) >= 2:
                num_part = parts[1]
                if num_part.isdigit():
                    last_num = max(last_num, int(num_part))
        except (ValueError, IndexError):
            continue
    
    # Start from 1 or continue from last number
    next_num = last_num + 1
    
    # Ensure uniqueness
    while True:
        invoice_no = f"{branch_code}/{next_num:0{digits}d}/{fy_compact}"
        if not newInvoiceMaster.objects.filter(Invoicenumber=invoice_no).exists():
            break
        next_num += 1
    
    logger.info(f"Generated own invoice: {invoice_no}")
    return invoice_no


# ------------------ FRANCHISE BRANCH INVOICE GENERATOR ------------------
@transaction.atomic
def generate_franchise_invoice(branch_code, digits):
    """
    Generate invoice number for franchise branches
    Format: JM26/27-AYG00001
    """
    fy_display = get_financial_year()
    
    # The full pattern to search for (without the number)
    pattern = f"JM{fy_display}-{branch_code}"
    
    # Get existing invoices for this branch
    invoices = (
        newInvoiceMaster.objects.select_for_update()
        .filter(Invoicenumber__startswith=pattern)
        .values_list("Invoicenumber", flat=True)
    )
    
    last_num = 0
    
    for inv in invoices:
        try:
            # Remove the pattern to get the number part
            # Example: "JM26/27-AYG00001" -> "00001"
            number_str = inv.replace(pattern, "")
            if number_str and number_str.isdigit():
                last_num = max(last_num, int(number_str))
        except (ValueError, IndexError):
            continue
    
    # Start from 1 or continue from last number
    next_num = last_num + 1
    
    # Generate the invoice number
    invoice_no = f"{pattern}{next_num:0{digits}d}"
    
    # Ensure uniqueness
    while newInvoiceMaster.objects.filter(Invoicenumber=invoice_no).exists():
        next_num += 1
        invoice_no = f"{pattern}{next_num:0{digits}d}"
    
    logger.info(f"Generated franchise invoice: {invoice_no}")
    return invoice_no


