def get_invoice_number(branch_name=None):
    """
    Generate unified invoice number in format: INV{current_year}/{next_year}{sequential_number}
    Example: INV26/270001 (for financial year 2026-27)
    
    Args:
        branch_name: Optional parameter kept for compatibility but not used
    """
    today = date.today()
    current_year = today.year % 100  # Get last 2 digits (26 for 2026)
    next_year = (today.year + 1) % 100  # Get last 2 digits of next year (27 for 2026)
    
    # Financial year calculation (April-March)
    if today.month >= 4:
        # April to December: use current_year/next_year
        financial_year_prefix = f"INV{current_year:02d}/{next_year:02d}"
    else:
        # January to March: use previous_year/current_year
        previous_year = (today.year - 1) % 100
        financial_year_prefix = f"INV{previous_year:02d}/{current_year:02d}"
    
    # Get the last invoice number for this financial year pattern
    last_invoice = newInvoiceMaster.objects.filter(
        Invoicenumber__startswith=financial_year_prefix
    ).order_by('-id').first()
    
    if last_invoice and last_invoice.Invoicenumber:
        try:
            # Extract the 4-digit sequential number from the end
            last_number = int(last_invoice.Invoicenumber[-4:])
            new_number = last_number + 1
        except (ValueError, IndexError):
            logger.error(f"Failed to parse invoice number: {last_invoice.Invoicenumber}")
            new_number = 1
    else:
        new_number = 1
    
    # Format with 4 digits (0001, 0002, ..., 9999)
    return f"{financial_year_prefix}{new_number:04d}"

from django.db.models import Q
@transaction.atomic
def pharmacy_invoice(request):
    today = date.today()
    todateinv = timezone.now().strftime("%Y%m%d")
    if request.method == "POST":
        errors = []
        invoicen = None
        try:
            with transaction.atomic():
                hospital_id = request.POST.get('hosptname')
                branch_id = request.POST.get('branchname')
                customer_type = request.POST.get('customerType', 'registered')
                
                # ----------------- CUSTOMER HANDLING -----------------
                if customer_type == 'registered':
                    mrno_id = request.POST.get('mrnum')
                    billdate = request.POST.get('billdate')
                    patient_name = request.POST.get('ptname', '')
                    patient_contact = request.POST.get('contact', '')
                    if not mrno_id:
                        return JsonResponse({"success": False, "error": "Please select a registered patient."}, status=400)
                else:
                    # Unregistered
                    mrno_id = None
                    billdate = request.POST.get('unreg_date')
                    patient_name = request.POST.get('unreg_name', '').strip()
                    patient_contact = request.POST.get('unreg_contact', '').strip()
                    if not patient_name:
                        return JsonResponse({"success": False, "error": "Customer name is required for unregistered customers."}, status=400)
                
                if not all([hospital_id, branch_id]):
                    return JsonResponse({"success": False, "error": "Missing required master fields."}, status=400)
                
                # ----------------- BRANCH & INVOICE -----------------
                branch_obj = Branch.objects.get(id=branch_id)
                branch_name = branch_obj.Branch_Name.upper().strip()
                
                # Generate invoice number
                invoicen = get_invoice_number(branch_name)
                        
                # ----------------- AMOUNTS -----------------
                # Discount handling - support both percentage and fixed amount
                discount_type = request.POST.get('discountType', 'percentage')
                discount_percent = safe_float(request.POST.get('totalDiscountInput', 0))
                discount_amount = safe_float(request.POST.get('discountAmount', 0))
                
                # For percentage discount, discount_amount will be calculated in the loop
                # For fixed amount, discount_percent will be 0
                totsgst = safe_float(request.POST.get('totsgst', 0))
                totcgst = safe_float(request.POST.get('totcgst', 0))
                tottaxamount = safe_float(request.POST.get('tottaxamount', 0))
                cash_amount = safe_float(request.POST.get('cash_amount', 0))
                gpay_amount = safe_float(request.POST.get('gpay_amount', 0))
                card_amount = safe_float(request.POST.get('card_amount', 0))
                stff_id = request.session.get('branchid')
                
                # Rounding flag from checkbox
                use_rounding = request.POST.get('use_rounding', 'false') == 'true'
                
                # NEW: Get IP Credit checkbox value
                ip_credit = request.POST.get('ip_credit', 'false') == 'true'
                
                # ----------------- ITEMS & BACKEND TOTAL CALC -----------------
                item_count = int(request.POST.get('items_count', 0))
                calculated_subtotal = 0
                calculated_tax = 0
                calculated_taxable_amount = 0 
                
                # Store created invoice items for later linking
                created_invoice_items = []
                
                for i in range(1, item_count + 1):
                    particulars = request.POST.get(f'items[{i}][particulars]', '').strip()
                    batchno = request.POST.get(f'items[{i}][batchno]', '')
                    raw_suppid = request.POST.get(f'items[{i}][suppid]', '').strip()
                    
                    # Skip completely empty rows
                    if not any([particulars, batchno, raw_suppid]):
                        continue
                    
                    item_label = f"Item {i} ('{particulars}', Batch '{batchno}')"
                    
                    if not particulars:
                        errors.append(f"{item_label}: Missing 'particulars' (medicine name).")
                        continue
                    if not raw_suppid or not raw_suppid.isdigit():
                        errors.append(f"{item_label}: Missing or invalid 'suppid'.")
                        continue
                    
                    suppid = int(raw_suppid)
                    quantity = safe_float(request.POST.get(f'items[{i}][quantity]', 1))
                    amount = safe_float(request.POST.get(f'items[{i}][amount]', 0))
                    tax = safe_float(request.POST.get(f'items[{i}][tax]', 0))
                    compid = int(request.POST.get(f'items[{i}][compid]', 0))

                    taxamount = safe_float(request.POST.get(f'items[{i}][taxamount]', 0))
                    taxable_amount = safe_float(request.POST.get(f'items[{i}][taxable]', 0))
                    
                    # Update totals
                    calculated_subtotal += (quantity * amount)
                    calculated_tax += taxamount
                    calculated_taxable_amount += taxable_amount
                    
                    # expiry date
                    expirydate = request.POST.get(f'items[{i}][expirydate]', '').strip()
                    expiry_date = None
                    if expirydate and expirydate.lower() not in ["null", "none", "undefined", ""]:
                        try:
                            expiry_date = datetime.strptime(expirydate, '%Y-%m-%d').date()
                        except ValueError:
                            errors.append(f"{item_label}: Invalid expiry date '{expirydate}'. Expected format YYYY-MM-DD.")
                            continue

                    manufacturedate_raw = request.POST.get(f'items[{i}][manufacturedate]', '').strip()
                    manufacture_date = None
                    if manufacturedate_raw and manufacturedate_raw.lower() not in ["null", "none", "undefined", ""]:
                        try:
                            manufacture_date = datetime.strptime(manufacturedate_raw, '%Y-%m-%d').date()
                        except ValueError:
                            errors.append(f"{item_label}: Invalid manufacture date '{manufacturedate_raw}'. Expected format YYYY-MM-DD.")
                            continue
                    
                    try:
                        # More flexible stock search
                        # First try: exact match with batch and supplier
                        qs = Physicalstockdetails.objects.filter(
                            itemnm__itemnm=particulars,
                            Batch_no=batchno,
                            suppliernm_id=suppid,
                            stockbranch=stff_id,
                            deleted=False
                        )
                        
                        if compid:
                            qs = qs.filter(Comapany_name_id=compid)
                        
                        itemaster_obj = qs.first()
                        
                        # Second try: without batch number
                        if not itemaster_obj:
                            print(f"⚠️ Stock not found with batch {batchno}, trying without batch")
                            qs = Physicalstockdetails.objects.filter(
                                itemnm__itemnm=particulars,
                                suppliernm_id=suppid,
                                stockbranch=stff_id,
                                deleted=False
                            )
                            if compid:
                                qs = qs.filter(Comapany_name_id=compid)
                            itemaster_obj = qs.first()
                            
                            if itemaster_obj:
                                batchno = itemaster_obj.Batch_no
                                print(f"✅ Found stock with batch: {batchno}")
                        
                        # Third try: without supplier
                        if not itemaster_obj:
                            print(f"⚠️ Stock not found with supplier {suppid}, trying without supplier")
                            qs = Physicalstockdetails.objects.filter(
                                itemnm__itemnm=particulars,
                                stockbranch=stff_id,
                                deleted=False
                            )
                            if compid:
                                qs = qs.filter(Comapany_name_id=compid)
                            itemaster_obj = qs.first()
                            if itemaster_obj:
                                batchno = itemaster_obj.Batch_no
                                suppid = itemaster_obj.suppliernm_id if itemaster_obj.suppliernm_id else suppid
                                print(f"✅ Found stock with batch: {batchno}, supplier: {suppid}")
                        
                        if not itemaster_obj:
                            errors.append(f"{item_label}: Stock not found")
                            continue

                        # Check if sufficient stock is available
                        current_qty = int(itemaster_obj.qty or 0)
                        if current_qty < quantity:
                            errors.append(f"{item_label}: Insufficient stock. Available: {current_qty}, Requested: {quantity}")
                            continue

                        # Deduct stock
                        itemaster_obj.qty = F('qty') - quantity
                        itemaster_obj.save()
                        
                        # Create invoice child
                        invoice_child = newInvoiceChild(
                            quantity=quantity,
                            particulars=particulars,
                            amount=amount,
                            sutotal=(quantity * amount),
                            Mrno_id=mrno_id,
                            currentdate=billdate,
                            invoiceno=invoicen,
                            description=request.POST.get(f'items[{i}][description]', ''),
                            patientname=patient_name,
                            patientphno=patient_contact,
                            invmasterid_id=None,
                            batchno=batchno,
                            expirydate=expiry_date,
                            mfg=request.POST.get(f'items[{i}][compnm]', '').strip(),
                            unt=request.POST.get(f'items[{i}][unt]', 'N/A'),
                            hsncode=request.POST.get(f'items[{i}][hsncode]', '').strip(),
                            suppid_id=suppid,
                            tax=tax,
                            taxamount=taxamount,
                            baseqty=request.POST.get(f'items[{i}][bsunit]', 0),
                            sgst=request.POST.get(f'items[{i}][sgst]'),
                            cgst=request.POST.get(f'items[{i}][cgst]'),
                            sgstamount=request.POST.get(f'items[{i}][sgstamt]'),
                            cgstamount=request.POST.get(f'items[{i}][cgstamt]'),
                            taxableamount=request.POST.get(f'items[{i}][taxable]'),
                            manufacturedate=manufacture_date
                        )
                        invoice_child.save()
                        created_invoice_items.append(invoice_child)
                        
                    except Exception as e:
                        errors.append(f"{item_label}: Error - {str(e)}")
                        continue
                
                # ----------------- DISCOUNT HANDLING -----------------
                # Calculate discount based on type
                final_discount_amount = 0
                final_discount_percent = 0
                
                if discount_type == 'percentage':
                    final_discount_percent = min(discount_percent, 100)
                    final_discount_amount = calculated_subtotal * (final_discount_percent / 100)
                else:  # amount
                    final_discount_amount = min(discount_amount, calculated_subtotal)
                    final_discount_percent = (final_discount_amount / calculated_subtotal * 100) if calculated_subtotal > 0 else 0
                
                # ----------------- FINAL TOTAL -----------------
                calculated_total = calculated_subtotal - final_discount_amount
                
                # Check if rounding is enabled
                if use_rounding:
                    # Apply rounding (0.5 and above rounds up)
                    final_total = int(round(calculated_total))
                else:
                    # Use exact amount
                    final_total = calculated_total
                
                # ----------------- PAYMENTS AUTO-ADJUST -----------------
                payment_modes = request.POST.getlist('payment_modes')
                payment_mode_str = ','.join(payment_modes) if payment_modes else 'Cash'
                payment_total = cash_amount + gpay_amount + card_amount
                
                # If IP Credit is checked, set payment mode to "IP Credit"
                if ip_credit:
                    payment_mode_str = "IP Credit"
                    # Reset payment amounts for IP Credit
                    cash_amount = 0
                    gpay_amount = 0
                    card_amount = 0
                    payment_total = 0
                
                # Round values for database storage
                rounded_subtotal = int(round(calculated_subtotal))
                rounded_total = int(round(final_total))
                rounded_tax = int(round(calculated_tax))
                rounded_taxable_amount = int(round(calculated_taxable_amount))
                rounded_totsgst = int(round(totsgst))
                rounded_totcgst = int(round(totcgst))
                rounded_tottaxamount = int(round(tottaxamount))
                rounded_cash_amount = int(round(cash_amount))
                rounded_gpay_amount = int(round(gpay_amount))
                rounded_card_amount = int(round(card_amount))
                
                # Only adjust payment if not IP Credit
                if not ip_credit and abs(payment_total - final_total) > 0.01:
                    difference = final_total - payment_total
                    cash_amount += difference
                    payment_total = cash_amount + gpay_amount + card_amount
                    rounded_cash_amount = int(round(cash_amount))
                
                # ----------------- CREATE INVOICE MASTER -----------------
                invoice = newInvoiceMaster.objects.create(
                    hospitalname_id=hospital_id,
                    branch_id=branch_id,
                    Mrno_id=mrno_id,
                    Invoicenumber=invoicen,
                    currentdate=billdate,
                    subtotal=rounded_subtotal,
                    tax=calculated_tax,
                    total=rounded_total,
                    discount=str(round(final_discount_amount, 2)),
                    discount_percent=Decimal(str(round(final_discount_percent, 2))),
                    patientname=patient_name,
                    patientphno=patient_contact,
                    preparedby_id=request.session.get('loginstaff'),
                    restockstatus=True,
                    totalsgstamount=str(totsgst),
                    totalcgstamount=str(totcgst),
                    totaltaxableamount=str(rounded_taxable_amount),
                    cash_amount=str(rounded_cash_amount),
                    gpay_amount=str(rounded_gpay_amount),
                    card_amount=str(rounded_card_amount),
                    payementmode=payment_mode_str,
                    ip_credit=ip_credit  # NEW: Save IP Credit flag
                )
                
                # Update children with master id
                for child in created_invoice_items:
                    child.invmasterid_id = invoice.id
                    child.save()

                if errors:
                    return JsonResponse({"success": False, "invoice": invoicen, "errors": errors}, status=400)
                    
                return redirect('newtaxprintoption')
                
        except Exception as e:
            InvoiceErrorLog.objects.create(
                error_message=str(e),
                related_invoice=invoicen,
                staff_id=request.session.get('loginstaff')
            )
            return JsonResponse({"success": False, "error": str(e)}, status=400)
    
    # ----------------- GET REQUEST -----------------
    medname = medicinemaster.objects.all()
    objhospt = Hospitaldetails.objects.first()
    todate = timezone.now().strftime("%Y/%m/%d")
    mrnoobj = Patient_details.objects.all()

    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')

    st_id = request.session.get('loginstaff')
    if not st_id:
        return redirect('staff_login')
    
    staff_branch = Staffallocation.objects.get(id=st_id)
    stbtachid = staff_branch.Branch_Name_id
    brname = Branch.objects.filter(id=stbtachid)
    branch_obj = Branch.objects.get(id=staff_branch.Branch_Name_id)
    branch_name = branch_obj.Branch_Name.upper().strip()
    
    # Generate invoice number for preview
    inv = get_invoice_number(branch_name)
    
    context = {
        'medname': medname,
        'st_id': st_id,
        'objhospt': objhospt,
        'today': today,
        'todate': todate,
        'mrnoobj': mrnoobj,
        'stdesign': stdesign,
        'brname': brname,
        'inv_id': inv
    }
    return render(request, "pharmacyinvoice.html", context)




def new_pharmacy_invoice(request):
    today = date.today()
    todateinv = timezone.now().strftime("%Y%m%d")
    if request.method == "POST":
        errors = []
        invoicen = None
        try:
            with transaction.atomic():
                hospital_id = request.POST.get('hosptname')
                branch_id = request.POST.get('branchname')
                customer_type = request.POST.get('customerType', 'registered')
                # --- Customer handling ---
                if customer_type == 'registered':
                    mrno_id = request.POST.get('mrnum')
                    billdate = request.POST.get('billdate')
                    patient_name = request.POST.get('ptname', '')
                    patient_contact = request.POST.get('contact', '')
                    if not mrno_id:
                        return JsonResponse({"success": False, "error": "Please select a registered patient."}, status=400)
                else:
                    mrno_id = None
                    billdate = request.POST.get('unreg_date')
                    patient_name = request.POST.get('unreg_name', '').strip()
                    patient_contact = request.POST.get('unreg_contact', '').strip()

                    if not patient_name:
                        return JsonResponse({"success": False, "error": "Customer name is required for unregistered customers."}, status=400)

                if not all([hospital_id, branch_id]):
                    return JsonResponse({"success": False, "error": "Missing required master fields."}, status=400)

                # --- Branch-specific invoice number (NEW prefix) ---
                branch_obj = Branch.objects.get(id=branch_id)
                branch_name = branch_obj.Branch_Name.upper()
                branch_info = BRANCH_CODES.get(branch_name, {"code": "GEN", "digits": 6})
                # Add "NEW" prefix for new system invoices
                invoicen = generate_invoice_number(branch_info['code'], branch_info['digits'])
                # --- Totals & payments ---
                subtotal = safe_float(request.POST.get('subtotal', 0))
                tax = safe_float(request.POST.get('tax', 0))
                shipping = safe_float(request.POST.get('shipping', 0))
                discount = safe_float(request.POST.get('totalDiscountInput', 0))
                total = safe_float(request.POST.get('totalAmount', 0))
                totsgst = safe_float(request.POST.get('totsgst', 0))
                totcgst = safe_float(request.POST.get('totcgst', 0))
                tottaxamount = safe_float(request.POST.get('tottaxamount', 0))
                cash_amount = safe_float(request.POST.get('cash_amount', 0))
                gpay_amount = safe_float(request.POST.get('gpay_amount', 0))
                card_amount = safe_float(request.POST.get('card_amount', 0))

                stff_id = request.session.get('branchid')

                payment_modes = request.POST.getlist('payment_modes')
                payment_mode_str = ','.join(payment_modes) if payment_modes else 'Cash'
                payment_total = cash_amount + gpay_amount + card_amount
                if abs(payment_total - total) > 0.01:
                    return JsonResponse({
                        "success": False,
                        "error": f"Payment amounts ({payment_total}) do not match invoice total ({total})"
                    }, status=400)

                # --- Create NEW Invoice Master ---
                invoice = invoicemaster.objects.create(
                    hospitalname_id=hospital_id,
                    branch_id=branch_id,
                    Mrno_id=mrno_id,
                    Invoicenumber=invoicen,
                    currentdate=billdate,
                    subtotal=subtotal,
                    tax=tax,
                    shipping=shipping,
                    total=total,
                    patientname=patient_name,
                    patientphno=patient_contact,
                    discount=str(discount),
                    preparedby_id=request.session.get('loginstaff'),
                    consultationfee=request.POST.get('consultationfee', '0'),
                    consultationfeecumregfee=request.POST.get('registrationfee', '0'),
                    restockstatus=True,
                    totalsgstamount=str(totsgst),
                    totalcgstamount=str(totcgst),
                    totaltaxableamount=str(tottaxamount),
                    cash_amount=str(cash_amount),
                    gpay_amount=str(gpay_amount),
                    card_amount=str(card_amount),
                    payementmode=payment_mode_str
                )
                invid = invoice.id

                # --- Process Items ---
                item_count = int(request.POST.get('items_count', 0))
                for i in range(1, item_count + 1):
                    particulars = request.POST.get(f'items[{i}][particulars]', '').strip()
                    batchno = request.POST.get(f'items[{i}][batchno]', '').strip()
                    mfg = request.POST.get(f'items[{i}][compnm]', '').strip()
                    expirydate = request.POST.get(f'items[{i}][expirydate]', '').strip()

                    expiry_date = None
                    item_label = f"Item {i} ('{particulars}', Batch '{batchno}')"
                    if expirydate and expirydate.lower() not in ["null", "none", "undefined", "", "n/a", "na"]:
                        try:
                            expiry_date = datetime.strptime(expirydate, '%Y-%m-%d').date()
                        except ValueError:
                            errors.append(f"{item_label}: Invalid expiry date '{expirydate}'. Expected format YYYY-MM-DD.")
                            continue

                    hsncode = request.POST.get(f'items[{i}][hsncode]', '').strip()
                    raw_suppid = request.POST.get(f'items[{i}][suppid]', '').strip()
                    suppid = int(raw_suppid) if raw_suppid.isdigit() else None

                    quantity = int(request.POST.get(f'items[{i}][quantity]', 1))
                    bsunit = request.POST.get(f'items[{i}][bsunit]', 0)
                    amount = safe_float(request.POST.get(f'items[{i}][amount]'))
                    tax = safe_float(request.POST.get(f'items[{i}][tax]'))
                    taxamount = safe_float(request.POST.get(f'items[{i}][taxamount]'))
                    cgst = request.POST.get(f'items[{i}][cgst]')
                    sgst = request.POST.get(f'items[{i}][sgst]')
                    sgstamt = request.POST.get(f'items[{i}][sgstamt]')
                    cgstamt = request.POST.get(f'items[{i}][cgstamt]')
                    taxable = request.POST.get(f'items[{i}][taxable]')
                    subtotal_item = float(f"{math.ceil(quantity * amount):.1f}")

                    if not particulars:
                        errors.append(f"{item_label}: Missing 'particulars' (medicine name).")
                        continue

                    try:
                        # Ensure medicine exists in NEW master
                        medicine_obj = medicinemaster_new.objects.filter(itemnm=particulars).first()
                        if not medicine_obj:
                            raise medicinemaster_new.DoesNotExist

                        # Stock lookup (using new medicine master)
                        stock_filter = {
                            "itemnm__itemnm": particulars,
                            "Batch_no": batchno,
                            "stockbranch": stff_id
                        }
                        if suppid:
                            stock_filter["suppliernm_id"] = suppid

                        itemaster_obj = Physicalstockdetails.objects.filter(**stock_filter).first()
                        if not itemaster_obj:
                            raise Physicalstockdetails.DoesNotExist

                        # Create NEW invoice child
                        invoicechild.objects.create(
                            quantity=quantity,
                            particulars=particulars,
                            amount=amount,
                            sutotal=subtotal_item,
                            Mrno_id=mrno_id,
                            currentdate=billdate,
                            invoiceno=invoicen,
                            description=request.POST.get(f'items[{i}][description]', ''),
                            patientname=patient_name,
                            patientphno=patient_contact,
                            invmasterid_id=invid,
                            batchno=batchno,
                            expirydate=expiry_date,
                            mfg=mfg,
                            unt=request.POST.get(f'items[{i}][unt]', 'N/A'),
                            hsncode=hsncode,
                            suppid_id=suppid if suppid else None,
                            tax=tax,
                            taxamount=taxamount,
                            baseqty=bsunit,
                            sgst=sgst,
                            cgst=cgst,
                            sgstamount=sgstamt,
                            cgstamount=cgstamt,
                            taxableamount=taxable
                        )

                        # Update stock
                        itemaster_obj.qty = F('qty') - quantity
                        itemaster_obj.save()

                    except (medicinemaster_new.DoesNotExist, Physicalstockdetails.DoesNotExist):
                        errors.append(f"{item_label}: Medicine or stock not found.")
                        continue

                if errors:
                    return JsonResponse({
                        "success": False,
                        "invoice": invoicen,
                        "errors": errors
                    }, status=400)

                return redirect('printoption')

        except Exception as e:
            InvoiceErrorLog.objects.create(
                error_message=str(e),
                related_invoice=invoicen,
                staff_id=request.session.get('loginstaff')
            )
            return JsonResponse({"success": False, "error": str(e)}, status=400)

    # --- GET request ---
    medname = medicinemaster_new.objects.all()
    objhospt = Hospitaldetails.objects.all()
    todate = timezone.now().strftime("%Y/%m/%d")
    mrnoobj = Patient_details.objects.all()

    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')

    st_id = request.session.get('loginstaff')
    if not st_id:
        return redirect('staff_login')

    staff_branch = Staffallocation.objects.get(id=st_id)
    stbtachid = staff_branch.Branch_Name_id
    brname = Branch.objects.filter(id=stbtachid)
    branch_obj = Branch.objects.get(id=stbtachid)
    branch_name = branch_obj.Branch_Name.upper()
    branch_info = BRANCH_CODES.get(branch_name, {"code": "GEN", "digits": 6})
    # Add "NEW" prefix for new system
    inv = f"NEW-{generate_invoice_number(branch_info['code'], branch_info['digits'])}"

    context = {
        'medname': medname,
        'st_id': st_id,
        'objhospt': objhospt,
        'today': today,
        'todate': todate,
        'mrnoobj': mrnoobj,
        'stdesign': stdesign,
        'brname': brname,
        'inv_id': inv
    }
    return render(request, "newpharmacyinvoice.html", context)
    
def search_new_medicine(request):
    term = request.GET.get('term', '').strip()
    branch_id = request.session.get('branchid')

    if not term or not branch_id:
        return JsonResponse([], safe=False)

    medicines = medicinemaster_new.objects.filter(itemnm__icontains=term)[:10]
    results = []

    for medicine in medicines:
        stock_data = Physicalstockdetails.objects.filter(
            itemnm_id=medicine.id,
            stockbranch=branch_id,
            qty__gt=0
        )

        if not stock_data.exists():
            continue

        batch_list = []

        for stock in stock_data:
            # ✅ Fetch all rates for this medicine in this branch
            med_rates = medicinemasterrate.objects.filter(
                itemid_id=medicine.id,
                branchid=branch_id
            )

            rates = [
                {"rate_id": r.id, "mrp": float(r.mrp)}
                for r in med_rates
            ]

            batch_list.append({
                "id": medicine.id,
                "stock_id": stock.id,
                "Batch_no": stock.Batch_no,
                "Expiry_date": stock.Expiry_date.strftime("%Y-%m-%d") if stock.Expiry_date else "N/A",
                "Manufacturer_date": stock.Manufacturer_date.strftime("%Y-%m-%d") if stock.Manufacturer_date else "N/A",
                "qty": stock.qty,
                "compid": stock.Comapany_name.id if stock.Comapany_name else None,
                "compname": stock.Comapany_name.Comapany_name if stock.Comapany_name else "N/A",
                "suppid": stock.suppliernm.id if stock.suppliernm else None,
                "supplier_name": stock.suppliernm.shopname if stock.suppliernm else "N/A",
                "stockbranch": stock.stockbranch_id,
                "rates": rates,  # ✅ all rates for this medicine/batch
                "taxpercentage": medicine.taxpercentage.taxrate if medicine.taxpercentage else 0,
            })

        results.append({
            "id": medicine.id,
            "medid": medicine.id,
            "itemnm": medicine.itemnm,
            "itemcode": medicine.itemcode,
            "Generic_name": medicine.Generic_name,
            "hsncode": medicine.hsncode,
            "bsuntid": {
                "id": medicine.bsuntid.id if medicine.bsuntid else None,
                "unit": medicine.bsuntid.unit if medicine.bsuntid else "N/A",
            },
            "taxpercentage": medicine.taxpercentage.taxrate if medicine.taxpercentage else "0",
             "batches": batch_list,
            'Batch_no': stock.Batch_no,

        })

    return JsonResponse(results, safe=False)

# -----------------------------
# Search Available Stock (with all rates per medicine)
# -----------------------------
def search_available_stock(request):
    medicine_name = request.GET.get('medicine_name', '')
    branch_id = request.session.get('branchid')

    if medicine_name and branch_id:
        stock_items = Physicalstockdetails.objects.filter(
            itemnm_id=medicine_name,
            stockbranch=branch_id,
            qty__gt=0
        )[:5]

        results = []
        for stock in stock_items:
            # Fetch all rates for this medicine in this branch
            med_rates = medicinemasterrate.objects.filter(
                itemid_id=stock.itemnm_id,
                branchid=branch_id
            ).values('id', 'mrp')

            stock_data = {
                'id': stock.id,
                'Batch_no': stock.Batch_no,
                'Expiry_date': stock.Expiry_date.strftime('%Y-%m-%d') if stock.Expiry_date else 'N/A',
                'qty': stock.qty,
                'stockbranch': stock.stockbranch_id,
  'itemid': stock.itemnm.id if stock.itemnm else None,  # Medicine Master ID

                # ✅ Direct IDs for easier use in invoice form
                'compid': stock.Comapany_name.id if stock.Comapany_name else None,
                'suppid': stock.suppliernm.id if stock.suppliernm else None,

                # ✅ Names for display
                'company_name': stock.Comapany_name.Comapany_name if stock.Comapany_name else 'N/A',
                'supplier_name': stock.suppliernm.shopname if stock.suppliernm else 'N/A',

                # Item details
                'item_details': {
                    'item_id': stock.itemnm.id if stock.itemnm else None,
                    'item_name': stock.itemnm.itemnm if stock.itemnm else 'N/A',
                    'generic_name': stock.itemnm.Generic_name if stock.itemnm else 'N/A',
                    'hsn_code': stock.itemnm.hsncode if stock.itemnm else 'N/A',
                } if stock.itemnm else {},

                # Unit details
                'unit_details': {
                    'unit_id': stock.unt.id if stock.unt else None,
                    'unit_name': stock.unt.unitname if stock.unt else 'N/A',
                } if stock.unt else {},

                # Extra fields
                'mfg_date': stock.Manufacturer_date.strftime('%Y-%m-%d') if stock.Manufacturer_date else 'N/A',
                
                # ✅ Return all MRPs instead of just one
                'rates': [
                    {'rate_id': r['id'], 'mrp': float(r['mrp']) if r['mrp'] else 0.0}
                    for r in med_rates
                ]
            }

            results.append(stock_data)

        return JsonResponse(results, safe=False)

    return JsonResponse([], safe=False)


