def a5print(request):
    # Last invoice and child items
    stbtachid = request.session.get('branchid')
    lsinvoice = newInvoiceMaster.objects.filter(branch=stbtachid).last()
    chinvoice = newInvoiceChild.objects.filter(invmasterid=lsinvoice.id)
    # Chunking for printing
    chunk_size = 10
    chinvoice_list = list(chinvoice)
    chinvoice_chunks = []
    for i in range(0, len(chinvoice_list), chunk_size):
        chunk_items = chinvoice_list[i:i+chunk_size]
        chunk_subtotal = sum(item.sutotal for item in chunk_items)
        chinvoice_chunks.append((chunk_items, chunk_subtotal))
    # Staff and branch info
    st_id = request.session['loginstaff']
    staff_branch = Staffallocation.objects.get(id=st_id)
    staffn = staff_branch
    medname = Itemaster.objects.all()
    objhospt = Hospitaldetails.objects.first()
    today = date.today()
    todateinv = timezone.now().strftime("%Y%m%d")
    todate = timezone.now().strftime("%Y/%m/%d")
    mrnoobj = Patient_details.objects.all()
    stdesign = request.session['loginstaffdesign']
    # Branch info - single object
    stbtachid = request.session.get('branchid')
    br = Branch.objects.filter(id=stbtachid).first()
    # GST & Composition flags
    branch_has_gst = bool(br and br.gstno and br.gstno.lower() != 'none')
    branch_is_composition = bool(br and br.compositiontax)

    # Generate invoice number with new pattern INV26/270001
    current_year = today.year % 100  # Get last 2 digits (26 for 2026)
    next_year = (today.year + 1) % 100  # Get last 2 digits of next year (27 for 2026)
    
    # Get the last invoice for the current financial year pattern
    financial_year_prefix = f"INV{current_year:02d}/{next_year:02d}"
    
    last_entry = newInvoiceMaster.objects.filter(
        currentdate__year=today.year,
        Invoicenumber__startswith=financial_year_prefix
    ).order_by('-id').first()
    
    if last_entry and last_entry.Invoicenumber:
        # Extract the numeric part after the prefix
        try:
            last_number = int(last_entry.Invoicenumber.split('/')[-1])
            refnid = last_number + 1
        except (ValueError, IndexError):
            refnid = 1
    else:
        refnid = 1
    
    # Format with 4 digits (0001, 0002, etc.)
    inv_id = f"{financial_year_prefix}{refnid:04d}"

    # Amount in words
    bill = newInvoiceMaster.objects.filter(currentdate=today).order_by('-id').first()
    amount_in_words = ""
    if bill and bill.total is not None:
    # Indian numbering system (Lakhs, Crores)
        amount_in_words = num2words(bill.total, lang='en_IN').title()
        amount_in_words = f"Rupees {amount_in_words} Only"
    request.session['invoice_print_accessed'] = True
    mninvadd = request.session.get('invmnobjadd')
    mninvview = request.session.get('invmnobjview')
    context = {
        'amount_in_words': amount_in_words,
        'mninvadd': mninvadd,
        'mninvview': mninvview,
        'chinvoice_chunks': chinvoice_chunks,
        'staffn': staffn,
        'chinvoice': chinvoice,
        'lsinvoice': lsinvoice,
        'medname': medname,
        'st_id': st_id,
        'objhospt': objhospt,
        'today': today,
        'todate': todate,
        'mrnoobj': mrnoobj,
        'stdesign': stdesign,
        'br': br,
        'inv_id': inv_id,
        'branch_has_gst': branch_has_gst,
        'branch_is_composition': branch_is_composition,
    }
    return render(request, "newtaxprinta5.html", context)
