        chinvoice_chunks = []
        for i in range(num_chunks):
            start_index = i * chunk_size
            end_index = min((i + 1) * chunk_size, len(chinvoice_list))
            chunk_items = chinvoice_list[start_index:end_index]
            chunk_subtotal = sum(item.sutotal for item in chunk_items)
            chinvoice_chunks.append((chunk_items, chunk_subtotal))
        stff=request.session['loginstaff']
        staffn=Staffallocation.objects.get(id=stff)
