def get_diagnosis_details(request):
    """Get diagnosis details for editing"""
    if request.method == 'GET':
        diagnosis_id = request.GET.get('diagnosis_id')
        
        # Validate diagnosis_id
        if not diagnosis_id or diagnosis_id == 'undefined':
            return JsonResponse({'success': False, 'error': 'Diagnosis ID is required'})
        
        try:
            # Convert to integer
            diagnosis_id = int(diagnosis_id)
            diagnosis = clairvedaCaseHistory.objects.get(id=diagnosis_id)
            data = {
                'success': True,
                'diagnosis': {
                    'id': diagnosis.id,
                    'status': diagnosis.status,
                    'follow_up_date': diagnosis.follow_up_date.strftime('%Y-%m-%d') if diagnosis.follow_up_date else '',
                    'chief_complaint': diagnosis.chief_complaint,
                    'present_complaint': diagnosis.present_complaint,
                    'final_diagnosis': diagnosis.final_diagnosis,
                }
            }
            return JsonResponse(data)
        except (clairvedaCaseHistory.DoesNotExist, ValueError):
            return JsonResponse({'success': False, 'error': 'Diagnosis not found'})
    return JsonResponse({'success': False, 'error': 'Invalid request method'})


def update_diagnosis(request):
    """Update diagnosis details"""
    if request.method == 'POST':
        try:
            diagnosis_id = request.POST.get('diagnosis_id')
            
            # Validate diagnosis_id
            if not diagnosis_id:
                return JsonResponse({'success': False, 'error': 'Diagnosis ID is required'})
            
            diagnosis = clairvedaCaseHistory.objects.get(id=diagnosis_id)
            
            # Update fields
            diagnosis.status = request.POST.get('status')
            diagnosis.chief_complaint = request.POST.get('chief_complaint')
            diagnosis.present_complaint = request.POST.get('present_complaint')
            diagnosis.final_diagnosis = request.POST.get('final_diagnosis')
            
            follow_up_date = request.POST.get('follow_up_date')
            if follow_up_date:
                diagnosis.follow_up_date = follow_up_date
            else:
                diagnosis.follow_up_date = None
                
            diagnosis.save()
            
            return JsonResponse({'success': True, 'message': 'Diagnosis updated successfully'})
        except clairvedaCaseHistory.DoesNotExist:
            return JsonResponse({'success': False, 'error': 'Diagnosis not found'})
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
    return JsonResponse({'success': False, 'error': 'Invalid request method'})
    
    
def transactiondash(request):
    today = date.today()
    from_date = request.GET.get("from_date")
    to_date = request.GET.get("to_date")
    payment_mode = request.GET.get("payment_mode", "All")
    branch = request.GET.get("branch", "All")

    # 🟢 Get login staff info
    st = str(request.session.get("loginstaff"))
    designation_name = request.session.get("loginstaffdesignname")

    # 🟢 Handle branch access
    if st == "6":  # Superadmin
        branches = Branch.objects.all()
    else:
        staff_branch = Staffallocation.objects.get(id=st)
        staffbranchid = staff_branch.Branch_Name_id
        branches = Branch.objects.filter(id=staffbranchid)
        branch = str(staffbranchid)

    # 🟢 Initialize querysets with restockstatus=True for pharmacy invoices and cancelstatus=False for appointments
    pharmacy_invoices = newInvoiceMaster.objects.filter(restockstatus=True)
    treatment_invoices = treatmentinvoicemaster.objects.all()
    appointments = appointmentinvoicemaster.objects.filter(cancelstatus=False)

    # 🟢 Apply branch filter
    if st == "6":  # Superadmin can see all branches
        if branch != "All":
            pharmacy_invoices = pharmacy_invoices.filter(branch_id=branch, restockstatus=True)
            treatment_invoices = treatment_invoices.filter(branch_id=branch)
            appointments = appointments.filter(branch_id=branch, cancelstatus=False)
    else:
        pharmacy_invoices = pharmacy_invoices.filter(branch_id=staffbranchid, restockstatus=True)
        treatment_invoices = treatment_invoices.filter(branch_id=staffbranchid)
        appointments = appointments.filter(branch_id=staffbranchid, cancelstatus=False)

    # 🟢 Date filter (defaults to today)
    if not from_date and not to_date:
        from_date = to_date = today.strftime("%Y-%m-%d")
        pharmacy_invoices = pharmacy_invoices.filter(currentdate=today)
        treatment_invoices = treatment_invoices.filter(currentdate=today)
        appointments = appointments.filter(currentdate=today, cancelstatus=False)
    else:
        if from_date and to_date:
            pharmacy_invoices = pharmacy_invoices.filter(currentdate__range=[from_date, to_date])
            treatment_invoices = treatment_invoices.filter(currentdate__range=[from_date, to_date])
            appointments = appointments.filter(currentdate__range=[from_date, to_date], cancelstatus=False)

    # 🟢 Payment mode filter - ENHANCED FOR COMBINED PAYMENTS
    if payment_mode != "All":
        if payment_mode == "Cash":
            # For Cash filter: show invoices where payementmode contains "Cash" OR "Cash,Gpay" AND cash_amount > 0
            pharmacy_invoices = pharmacy_invoices.filter(
                (models.Q(payementmode__icontains="Cash") | models.Q(payementmode__icontains="Cash,Gpay")) & 
                models.Q(cash_amount__gt=0)
            )
            treatment_invoices = treatment_invoices.filter(
                (models.Q(paymentmode__icontains="Cash") | models.Q(paymentmode__icontains="Cash,Gpay")) & 
                models.Q(total__gt=0)
            )
            appointments = appointments.filter(
                (models.Q(payementmode__icontains="Cash") | models.Q(payementmode__icontains="Cash,Gpay")) & 
                models.Q(total__gt=0),
                cancelstatus=False
            )
        elif payment_mode == "Gpay":
            # For Gpay filter: show invoices where payementmode contains "Gpay" OR "Cash,Gpay" AND gpay_amount > 0
            pharmacy_invoices = pharmacy_invoices.filter(
                (models.Q(payementmode__icontains="Gpay") | models.Q(payementmode__icontains="Cash,Gpay")) & 
                models.Q(gpay_amount__gt=0)
            )
            treatment_invoices = treatment_invoices.filter(
                (models.Q(paymentmode__icontains="Gpay") | models.Q(paymentmode__icontains="Cash,Gpay")) & 
                models.Q(total__gt=0)
            )
            appointments = appointments.filter(
                (models.Q(payementmode__icontains="Gpay") | models.Q(payementmode__icontains="Cash,Gpay")) & 
                models.Q(total__gt=0),
                cancelstatus=False
            )
        elif payment_mode == "Card":
            # For Card filter: show invoices where payementmode contains "Card" AND card_amount > 0
            pharmacy_invoices = pharmacy_invoices.filter(
                models.Q(payementmode__icontains="Card") & 
                models.Q(card_amount__gt=0)
            )
            treatment_invoices = treatment_invoices.filter(
                models.Q(paymentmode__icontains="Card") & 
                models.Q(total__gt=0)
            )
            appointments = appointments.filter(
                models.Q(payementmode__icontains="Card") & 
                models.Q(total__gt=0),
                cancelstatus=False
            )
        else:
            # For exact matches (backward compatibility)
            pharmacy_invoices = pharmacy_invoices.filter(
                payementmode__iexact=payment_mode
            ).exclude(total=0)
            treatment_invoices = treatment_invoices.filter(
                paymentmode__iexact=payment_mode
            ).exclude(total=0)
            appointments = appointments.filter(
                payementmode__iexact=payment_mode,
                cancelstatus=False
            ).exclude(total=0)

    # 🟢 Calculate totals based on payment mode - ENHANCED
    if payment_mode == "All":
        # Total for all payment modes
        pharmacy_total = pharmacy_invoices.aggregate(total=Sum("total"))["total"] or 0
        treatment_total = treatment_invoices.aggregate(total=Sum("total"))["total"] or 0
        appointment_total = appointments.aggregate(total=Sum("total"))["total"] or 0
        
        # Set individual payment mode totals to None since we're showing combined total
        pharmacy_cash_total = pharmacy_card_total = pharmacy_gpay_total = None
        treatment_cash_total = treatment_card_total = treatment_gpay_total = None
        appointment_cash_total = appointment_card_total = appointment_gpay_total = None
        
    elif payment_mode == "Cash":
        # Calculate totals for Cash payments
        pharmacy_cash_total = pharmacy_invoices.aggregate(
            total=Sum("cash_amount")
        )["total"] or 0
        treatment_cash_total = treatment_invoices.aggregate(total=Sum("total"))["total"] or 0
        appointment_cash_total = appointments.aggregate(total=Sum("total"))["total"] or 0
        
        pharmacy_total = pharmacy_cash_total
        treatment_total = treatment_cash_total
        appointment_total = appointment_cash_total
        
        pharmacy_card_total = pharmacy_gpay_total = None
        treatment_card_total = treatment_gpay_total = None
        appointment_card_total = appointment_gpay_total = None
        
    elif payment_mode == "Gpay":
        # Calculate totals for Gpay payments
        pharmacy_gpay_total = pharmacy_invoices.aggregate(
            total=Sum("gpay_amount")
        )["total"] or 0
        treatment_gpay_total = treatment_invoices.aggregate(total=Sum("total"))["total"] or 0
        appointment_gpay_total = appointments.aggregate(total=Sum("total"))["total"] or 0
        
        pharmacy_total = pharmacy_gpay_total
        treatment_total = treatment_gpay_total
        appointment_total = appointment_gpay_total
        
        pharmacy_cash_total = pharmacy_card_total = None
        treatment_cash_total = treatment_card_total = None
        appointment_cash_total = appointment_card_total = None
        
    elif payment_mode == "Card":
        # Calculate totals for Card payments
        pharmacy_card_total = pharmacy_invoices.aggregate(
            total=Sum("card_amount")
        )["total"] or 0
        treatment_card_total = treatment_invoices.aggregate(total=Sum("total"))["total"] or 0
        appointment_card_total = appointments.aggregate(total=Sum("total"))["total"] or 0
        
        pharmacy_total = pharmacy_card_total
        treatment_total = treatment_card_total
        appointment_total = appointment_card_total
        
        pharmacy_cash_total = pharmacy_gpay_total = None
        treatment_cash_total = treatment_gpay_total = None
        appointment_cash_total = appointment_gpay_total = None
        
    else:
        # For other payment modes
        pharmacy_total = pharmacy_invoices.aggregate(total=Sum("total"))["total"] or 0
        treatment_total = treatment_invoices.aggregate(total=Sum("total"))["total"] or 0
        appointment_total = appointments.aggregate(total=Sum("total"))["total"] or 0
        
        pharmacy_cash_total = pharmacy_card_total = pharmacy_gpay_total = None
        treatment_cash_total = treatment_card_total = treatment_gpay_total = None
        appointment_cash_total = appointment_card_total = appointment_gpay_total = None

    # 🟢 Enhanced pharmacy data with payment breakdown for display
    enhanced_pharmacy_invoices = []
    for inv in pharmacy_invoices:
        # Determine display total based on payment mode
        if payment_mode == "Cash":
            display_total = inv.cash_amount
        elif payment_mode == "Gpay":
            display_total = inv.gpay_amount
        elif payment_mode == "Card":
            display_total = inv.card_amount
        else:
            display_total = inv.total
            
        enhanced_pharmacy_invoices.append({
            'invoice': inv,
            'display_total': display_total
        })

    # 🟢 Enhanced treatment data with payment breakdown for display
    enhanced_treatment_invoices = []
    for inv in treatment_invoices:
        enhanced_treatment_invoices.append({
            'invoice': inv,
            'display_total': inv.total
        })

    # 🟢 Enhanced appointment data with payment breakdown
    appointment_data = []
    for ap in appointments.select_related("Mrno", "branch"):
        appointment_data.append({
            "InvoiceNo": ap.treatmentInvoicenumber,
            "Patient": ap.Mrno.Patient_Name if ap.Mrno else "",
            "Branch": ap.branch.Branch_Name if ap.branch else "",
            "Fee": ap.total,
            "Date": ap.currentdate,
            "PaymentMode": ap.payementmode or "N/A",
        })

    context = {
        "from_date": from_date,
        "to_date": to_date,
        "payment_mode": payment_mode,
        "branch": branch,
        "branches": branches,
        "pharmacy_invoices": pharmacy_invoices,
        "enhanced_pharmacy_invoices": enhanced_pharmacy_invoices,
        "treatment_invoices": treatment_invoices,
        "enhanced_treatment_invoices": enhanced_treatment_invoices,
        "appointments": appointment_data,
        "pharmacy_total": pharmacy_total,
        "treatment_total": treatment_total,
        "appointment_total": appointment_total,
        "pharmacy_cash_total": pharmacy_cash_total,
        "pharmacy_card_total": pharmacy_card_total,
        "pharmacy_gpay_total": pharmacy_gpay_total,
        "treatment_cash_total": treatment_cash_total,
        "treatment_card_total": treatment_card_total,
        "treatment_gpay_total": treatment_gpay_total,
        "appointment_cash_total": appointment_cash_total,
        "appointment_card_total": appointment_card_total,
        "appointment_gpay_total": appointment_gpay_total,
        "designation_name": designation_name,
        "st": st,
    }

    return render(request, "transactiondash.html", context)
    

from django.db.models import Sum, Count, Q
from django.shortcuts import render, redirect
from django.utils import timezone
from datetime import date

def appointment_invlist(request):
    staff_id = request.session.get("loginstaff")
    staff_design_id = request.session.get("loginstaffdesign")
    if not staff_id or not staff_design_id:
        return redirect("staff_login")

    # Get Staff Details
    try:
        staff = Staffallocation.objects.select_related(
            'Branch_Name', 'Staff', 'Designation_Name'
        ).get(id=staff_id)
    except Staffallocation.DoesNotExist:
        return redirect("staff_login")

    staff_branch_id = staff.Branch_Name_id

    # Designation Check
    designation = Designation.objects.filter(id=staff_design_id).first()
    is_superadmin = designation and designation.Designation_Name.strip().lower() == "superadmin"

    objhospt = Hospitaldetails.objects.first()
    today = timezone.now().date()

    # Date Filter
    if request.method == "POST":
        sdate_str = request.POST.get("start_date")
        edate_str = request.POST.get("end_date")
        if sdate_str and edate_str:
            sdate = date.fromisoformat(sdate_str)
            edate = date.fromisoformat(edate_str)
        else:
            sdate = edate = today
    else:
        sdate = edate = today

    # Branch Filter
    if not is_superadmin and staff_branch_id:
        base_invoice_filter = Q(currentdate__range=[sdate, edate], branch_id=staff_branch_id)
        base_appointment_filter = Q(Appointment_date__range=[sdate, edate], Branch_id=staff_branch_id)
    else:
        base_invoice_filter = Q(currentdate__range=[sdate, edate])
        base_appointment_filter = Q(Appointment_date__range=[sdate, edate])

    # =========================
    # FETCH ALL INVOICES (including cancelled for status mapping)
    # =========================
    all_invoices = (
        appointmentinvoicemaster.objects
        .filter(base_invoice_filter)
        .select_related("branch", "Mrno")
        .order_by("-currentdate")
    )

    # =========================
    # FETCH APPOINTMENTS FOR STATUS MAPPING
    # =========================
    appointments = (
        Appointments.objects
        .filter(base_appointment_filter)
        .select_related('MR_Number', 'Branch', 'Doctor_Name')
    )

    # Create mapping for easier lookup: patient_id + token_no -> appointment
    appointment_dict = {}
    for app in appointments:
        key = (app.MR_Number_id, app.Tokenno)
        appointment_dict[key] = app

    # =========================
    # PROCESS INVOICES WITH STATUS (EXACT SAME LOGIC AS daily_transaction_report)
    # =========================
    appointment_fees_by_status = {
        "consultation": 0.0,
        "followup": 0.0,
        "revisit": 0.0,
        "whatsapp": 0.0,
        "camp": 0.0,
        "treatment": 0.0,
        "zoho online consultation": 0.0,
        "zoho online revisit": 0.0,
        "whatsapp revisit": 0.0,
        "online": 0.0,  # legacy
        "": 0.0
    }

    appointment_counts_by_status = {
        "consultation": 0,
        "followup": 0,
        "revisit": 0,
        "whatsapp": 0,
        "camp": 0,
        "treatment": 0,
        "zoho online consultation": 0,
        "zoho online revisit": 0,
        "whatsapp revisit": 0,
        "online": 0,  # legacy
        "": 0
    }

    invoice_list = []
    active_invoices = []
    cancelled_invoices = []

    for inv in all_invoices:
        # Try to find matching appointment
        appointment = None
        status = ""

        if inv.Mrno_id and inv.treatmentInvoicenumber:
            key = (inv.Mrno_id, inv.treatmentInvoicenumber)
            appointment = appointment_dict.get(key)

        if appointment:
            status = (appointment.status or "").strip().lower()
        else:
            # If no appointment found, check if MR number matches any appointment on the same date
            matching_app = appointments.filter(
                MR_Number_id=inv.Mrno_id,
                Appointment_date=inv.currentdate
            ).first()
            if matching_app:
                status = (matching_app.status or "").strip().lower()

        # Add status to invoice object for display
        inv.appointment_status = status.capitalize() if status else "N/A"

        # Calculate fee
        fee = float(inv.total or 0)

        # Update fees and counts by status (for ACTIVE invoices only - same as daily report)
        if not inv.cancelstatus:
            if status in appointment_fees_by_status:
                appointment_fees_by_status[status] += fee
                appointment_counts_by_status[status] += 1
            else:
                appointment_fees_by_status[""] += fee
                appointment_counts_by_status[""] += 1
            active_invoices.append(inv)
        else:
            cancelled_invoices.append(inv)

        invoice_list.append(inv)

    # Calculate totals for active invoices only
    total_visits = sum(appointment_counts_by_status.values())
    total_amount = sum(appointment_fees_by_status.values())

    # Calculate cancelled totals
    cancelled_count = len(cancelled_invoices)
    cancelled_total = sum(float(inv.total or 0) for inv in cancelled_invoices)

    # =========================
    # PAYMENT MODE TOTALS (EXACT SAME AS daily_transaction_report)
    # =========================
    appointment_totals = {
        "cash": 0.0,
        "gpay": 0.0,
        "card": 0.0,
        "total": total_amount
    }

    # For payment mode, only consider active invoices (same as daily report)
    for inv in active_invoices:
        mode = (inv.payementmode or "").lower()
        fee = float(inv.total or 0)
        if "cash" in mode:
            appointment_totals["cash"] += fee
        elif "gpay" in mode or "google" in mode or "upi" in mode:
            appointment_totals["gpay"] += fee
        elif "card" in mode:
            appointment_totals["card"] += fee

    # =========================
    # BRANCHWISE SUMMARY
    # =========================
    branchwise_summary = []
    if is_superadmin:
        # Only active invoices for branch summary
        branchwise_summary = (
            appointmentinvoicemaster.objects
            .filter(base_invoice_filter, cancelstatus=False)
            .values("branch__Branch_Name")
            .annotate(
                branch_total=Sum("total"),
                branch_visits=Count("id"),
            )
            .order_by("branch__Branch_Name")
        )

    # =========================
    # CONTEXT - EXACTLY MATCHING daily_transaction_report structure
    # =========================
    context = {
        "objhospt": objhospt,
        "stdesign": designation.Designation_Name.strip().lower() if designation else "",
        "inv": invoice_list,  # All invoices (for table display)
        "sdate": sdate,
        "edate": edate,
        "is_superadmin": is_superadmin,
        "staff_design_id": staff_design_id,

        # Visit counts (matching daily_transaction_report exactly)
        "total_visits": total_visits,
        "consultation_count": appointment_counts_by_status["consultation"],
        "followup_count": appointment_counts_by_status["followup"],
        "revisit_count": appointment_counts_by_status["revisit"],
        "whatsapp_count": appointment_counts_by_status["whatsapp"],
        "whatsapp_revisit_count": appointment_counts_by_status["whatsapp revisit"],
        "zoho_online_consultation_count": appointment_counts_by_status["zoho online consultation"],
        "zoho_online_revisit_count": appointment_counts_by_status["zoho online revisit"],
        "camp_count": appointment_counts_by_status["camp"],
        "treatment_count": appointment_counts_by_status["treatment"],
        "online_count": appointment_counts_by_status["online"],
        "other_count": appointment_counts_by_status[""],

        # Visit fees (matching daily_transaction_report exactly)
        "consultation_fee": appointment_fees_by_status["consultation"],
        "followup_fee": appointment_fees_by_status["followup"],
        "revisit_fee": appointment_fees_by_status["revisit"],
        "whatsapp_fee": appointment_fees_by_status["whatsapp"],
        "whatsapp_revisit_fee": appointment_fees_by_status["whatsapp revisit"],
        "zoho_online_consultation_fee": appointment_fees_by_status["zoho online consultation"],
        "zoho_online_revisit_fee": appointment_fees_by_status["zoho online revisit"],
        "camp_fee": appointment_fees_by_status["camp"],
        "treatment_fee": appointment_fees_by_status["treatment"],
        "other_fee": appointment_fees_by_status[""],

        # Payment totals (matching daily_transaction_report)
        "cash_total": appointment_totals["cash"],
        "gpay_total": appointment_totals["gpay"],
        "card_total": appointment_totals["card"],
        "appointment_total": appointment_totals["total"],

        # Cancelled info
        "cancelled_count": cancelled_count,
        "cancelled_total": cancelled_total,

        # Branch summary
        "branchwise_summary": branchwise_summary,
    }

    return render(request, "appointmentinvoicelist.html", context)



def cancel_appointment_invoice(request):
    
    invoice_id = request.GET.get("ids")
    # Get staff & designation info from session
    staff_id = request.session.get("loginstaff")
    staff_design_id = request.session.get("loginstaffdesign")

    if not staff_id or not staff_design_id:
        messages.error(request, "You must be logged in to cancel invoices.")
        return redirect("staff_login")

    # ✅ Get staff info
    try:
        staff = Staffallocation.objects.select_related("Branch_Name").get(id=staff_id)
        branch_id = staff.Branch_Name_id
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff not found.")
        return redirect("staff_login")

    # ✅ Get designation name
    try:
        designation = Designation.objects.get(id=staff_design_id)
        designation_name = designation.Designation_Name.strip().lower()
    except Designation.DoesNotExist:
        designation_name = ""

    # ✅ Get invoice
    invoice = get_object_or_404(appointmentinvoicemaster, id=invoice_id)

    # ✅ Check permissions
    if designation_name != "superadmin" and invoice.branch_id != branch_id:
        messages.error(request, "You are not allowed to cancel invoices from another branch.")
        return redirect("appointment_invlist")

    if invoice.cancelstatus:
        messages.warning(request, f"Invoice {invoice.treatmentInvoicenumber} is already cancelled.")
    else:
        invoice.cancelstatus = True
        invoice.save()
        messages.success(request, f"Invoice {invoice.treatmentInvoicenumber} cancelled successfully.")

    return redirect("appointment_invlist")

def appointment_invview(request):
    invoice_id = request.GET.get('ids')
    lsinvoice = get_object_or_404(appointmentinvoicemaster, id=invoice_id)
    objhospt = Hospitaldetails.objects.first()

    # ✅ Fetch appointment related to this invoice (using MR and Token number)
    appointment = Appointments.objects.filter(
        MR_Number_id=lsinvoice.Mrno_id,
        Tokenno=lsinvoice.treatmentInvoicenumber
    ).select_related("Doctor_Name").first()

    doctor_name = appointment.Doctor_Name.Staff_firstname if appointment else ""

    # Convert total to words
    from num2words import num2words
    amount_in_words = num2words(lsinvoice.total, to="cardinal", lang="en").title() + " Only"
    st_id= request.session['loginstaff'] 
    staff_branch=Staffallocation.objects.get(id=st_id)
    stbtachid=staff_branch.Branch_Name_id
    brname = Branch.objects.filter(id=stbtachid)
    context = {
    'brname':brname,
        'lsinvoice': lsinvoice,
        'objhospt': objhospt,
        'doctor_name': doctor_name,   # ✅ add doctor name
        'appointment': appointment,   # optional if you need appointment date
        'amount_in_words': amount_in_words,
    }
    return render(request, "appointmentinvoice.html", context)




