def update_vitals(request):
    if request.method == 'POST':
        try:
            vitals_id = request.POST.get('vitals_id')
            vitals = get_object_or_404(casehistryvitals, id=vitals_id)
            
            # Helper function to handle empty values
            def get_float_value(value):
                if value is None or value == '':
                    return None
                try:
                    return float(value)
                except ValueError:
                    return None
            
            # Update fields with proper handling of empty values
            vitals.age = int(request.POST.get('age')) if request.POST.get('age') else None
            vitals.height = get_float_value(request.POST.get('height'))
            vitals.weight = get_float_value(request.POST.get('weight'))
            vitals.bmi = get_float_value(request.POST.get('bmi'))
            vitals.bp = request.POST.get('bp')
            vitals.pr= request.POST.get("pr")
            vitals.spo2=request.POST.get("spo2")
            vitals.temperature=request.POST.get("temperature")
            vitals.fbs = get_float_value(request.POST.get('fbs'))
            vitals.ppbs = get_float_value(request.POST.get('ppbs'))
            vitals.hba1c = get_float_value(request.POST.get('hba1c'))
            vitals.tchol = get_float_value(request.POST.get('tchol'))
            vitals.hdl = get_float_value(request.POST.get('hdl'))
            vitals.tg = get_float_value(request.POST.get('tg'))
            vitals.ldl = get_float_value(request.POST.get('ldl'))
            vitals.s_creatinine = get_float_value(request.POST.get('s_creatinine'))
            vitals.uric_acid = get_float_value(request.POST.get('uric_acid'))
            vitals.sgpt = get_float_value(request.POST.get('sgpt'))
            vitals.sgot = get_float_value(request.POST.get('sgot'))
            vitals.alcohol = request.POST.get('alcohol') == 'yes'
            vitals.smoking = request.POST.get('smoking') == 'yes'
            
            vitals.save()
            
            return JsonResponse({'success': True, 'message': 'Vitals updated successfully'})
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
    
    return JsonResponse({'success': False, 'error': 'Invalid request method'})


