def update_history(request):
    if request.method == 'POST':
        try:
            history_id = request.POST.get('history_id')
            history = get_object_or_404(casehistorymedicalandsurgicalhistory, id=history_id)
            
            # Update fields
            history.medicalhistory = request.POST.get('medhist', '')
            history.surgicalhist = request.POST.get('surgicalhist', '')
            
            history.save()
            
            return JsonResponse({'success': True, 'message': 'Medical/Surgical history updated successfully'})
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
    
    return JsonResponse({'success': False, 'error': 'Invalid request method'})   

from django.db.models import Exists, OuterRef
from django.utils import timezone

    
def get_pending_labtests(request):
    mrno = request.GET.get("mrno")
    if not mrno:
        return JsonResponse([], safe=False)
    
    try:
        from datetime import date
        today_date = date.today()
        
        # ✅ Get pending requisitions for this patient (not cancelled and not invoiced yet)
        pending_requisitions = LabRequisitionMaster.objects.filter(
            patient_id=mrno,
            is_cancelled=False,
            invoice__isnull=True,
            created_at__date=today_date,
        ).prefetch_related('requisition_items__labtestchild', 'requisition_items__labtestgroup')
        
        data = []
        group_tests = {}  # To track tests by group
        
        for req in pending_requisitions:
            for item in req.requisition_items.all():
                labtest = item.labtestchild
                if labtest:
                    # ✅ Check if this test has a group
                    group_id = item.labtestgroup_id
                    group_name = item.labtestgroup.groupname if item.labtestgroup else None
                    
                    # ✅ Determine rate based on group or individual test
                    if group_id and group_name:
                        # ✅ If group exists, get rate from labtestmaster (group)
                        group_rate = item.labtestgroup.rate if item.labtestgroup and item.labtestgroup.rate else "0"
                        rate = float(group_rate) if group_rate else 0
                    else:
                        # ✅ If no group, use individual test rate
                        rate = float(labtest.rate) if labtest.rate else 0
                    
                    data.append({
                        "id": labtest.id,
                        "testname": labtest.testname,
                        "rate": rate,  # Rate from group or individual
                        "normal_value": getattr(labtest, "normal_value", ""),
                        "created_at": req.created_at.strftime("%Y-%m-%d") if req.created_at else "",
                        "requisition_id": req.id,
                        "requisition_number": req.requisition_number,
                        "item_id": item.id,
                        # ✅ Added group information
                        "group_id": group_id,
                        "group_name": group_name,
                        "is_from_group": group_id is not None,
                        "source_rate": "group" if group_id else "individual"
                    })
        
        return JsonResponse(data, safe=False)
        
    except Exception as e:
        print(f"Error in get_pending_labtests: {str(e)}")
        return JsonResponse({"error": str(e)}, status=500)


def pharmacyinvoicereport(request):
    total_amount = None  
    sdate = None  
    edate = None  

    logstaffbrid = request.session.get('branchid')
    stdesign_id = request.session.get('loginstaffdesign')

    if not stdesign_id:
        return redirect('staff_login')

    # check if superadmin
    try:
        designation = Designation.objects.get(id=stdesign_id)
        is_superadmin = designation.Designation_Name.lower() == 'superadmin'
    except Designation.DoesNotExist:
        is_superadmin = False

    if request.method == 'POST':
        sdate = request.POST.get('sdate')
        edate = request.POST.get('edate')

        filters = {"restockstatus": True}
        if not is_superadmin:  # ✅ staff only sees their branch
            filters["branch_id"] = logstaffbrid  

        if sdate and edate:
            filters["currentdate__range"] = [sdate, edate]

        inv = invoicemaster.objects.filter(**filters).order_by('-currentdate')
        total_amount = inv.aggregate(total_amount=Sum('total'))['total_amount']

        context = {
            'sdate': sdate,
            'edate': edate,
            'inv': inv,
            'stdesign': stdesign_id,
            'total_amount': total_amount
        }
        return render(request, "pharmacyinvoicereport.html", context)

    # For GET requests
    objhospt = Hospitaldetails.objects.all()

    filters = {}
    if not is_superadmin:  # ✅ staff restricted by branch
        filters["branch_id"] = logstaffbrid  

    inv = invoicemaster.objects.filter(**filters).order_by('-currentdate')

    if not sdate and not edate:  
        invst = invoicemaster.objects.filter(restockstatus=True, **filters)
        total_amount = invst.aggregate(total_amount=Sum('total'))['total_amount']

    context = {
        'objhospt': objhospt,
        'stdesign': stdesign_id,
        'inv': inv,
        'total_amount': total_amount, 
    }
    return render(request, "pharmacyinvoicereport.html", context)
    


