@require_GET
def check_patient_appointment(request):
    patient_id = request.GET.get("patient_id")
    if not patient_id:
        return JsonResponse({"has_appointment": False})

    try:
        # FIRST CHECK FOR ASSIGNED APPOINTMENTS (higher priority)
        assigned_appointment = AssignedAppointments.objects.filter(
            patient_id=patient_id,
            is_used=False
        ).order_by('-appointment_date').first()
        
        if assigned_appointment:
            # This is an ASSIGNED appointment
            return JsonResponse({
                "has_appointment": True,
                "appointment_id": assigned_appointment.id,
                "appointment_type": "assigned",  # CRITICAL: Mark as 'assigned'
                "doctor_name": f"{assigned_appointment.doctor.Staff_firstname} {assigned_appointment.doctor.Staff_lastname}",
                "doctor_id": assigned_appointment.doctor.id,  # Include doctor ID
                "appointment_date": assigned_appointment.appointment_date.strftime("%Y-%m-%d"),
                "schedule_date": assigned_appointment.schedule_date.strftime("%Y-%m-%d") if assigned_appointment.schedule_date else assigned_appointment.appointment_date.strftime("%Y-%m-%d"),
                "status": "Assigned for Prescription",
                "is_linked": bool(assigned_appointment.appointment),
                "tokenno": assigned_appointment.appointment.Tokenno if assigned_appointment.appointment else None
            })
        
        # If no assigned appointment, check regular appointments
        regular_appointment = Appointments.objects.filter(
            MR_Number_id=patient_id
        ).order_by('-Appointment_date').first()
        
        if regular_appointment:
            # This is a REGULAR appointment
            return JsonResponse({
                "has_appointment": True,
                "appointment_id": regular_appointment.id,
                "appointment_type": "regular",  # CRITICAL: Mark as 'regular'
                "doctor_name": f"{regular_appointment.Doctor_Name.Staff_firstname} {regular_appointment.Doctor_Name.Staff_lastname}",
                "doctor_id": regular_appointment.Doctor_Name.id,
                "appointment_date": regular_appointment.Appointment_date.strftime("%Y-%m-%d"),
                "schedule_date": regular_appointment.Appointment_date.strftime("%Y-%m-%d"),
                "status": regular_appointment.status,
                "tokenno": regular_appointment.Tokenno
            })
        
        return JsonResponse({"has_appointment": False})
        
    except Exception as e:
        print(f"Error checking appointment: {e}")
        return JsonResponse({"has_appointment": False, "error": str(e)})

from django.utils import timezone

@csrf_exempt
def create_appointment_for_prescription(request):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request method'})
    
    # Check if user is superadmin
    staff_design_id = request.session.get('loginstaffdesign')
    try:
        designation = Designation.objects.get(id=staff_design_id)
        is_superadmin = (designation.Designation_Name.lower() == "superadmin" or staff_design_id == 9)
        if not is_superadmin:
            return JsonResponse({'success': False, 'error': 'Only superadmin can assign appointments'})
    except Designation.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Invalid user designation'})
    
    # Get form data
    patient_id = request.POST.get('patient_id')
    doctor_id = request.POST.get('doctor_id')
    branch_id = request.POST.get('branch_id')
    appointment_date = request.POST.get('appointment_date')
    appnid = request.POST.get('appnid')  # This is the appointment_id from Appointments table
    schedule_date = request.POST.get('schedule_date')
    remarks = request.POST.get('remarks', '')
    
    # Validate required fields
    if not all([patient_id, doctor_id, branch_id, appointment_date]):
        return JsonResponse({'success': False, 'error': 'All required fields must be filled'})
    
    try:
        # Parse dates
        appointment_date_obj = parse_date(appointment_date)
        if not appointment_date_obj:
            return JsonResponse({'success': False, 'error': 'Invalid appointment date format'})
        
        schedule_date_obj = None
        if schedule_date and schedule_date.strip():
            schedule_date_obj = parse_date(schedule_date)
        else:
            # If schedule date is not provided, use appointment date
            schedule_date_obj = appointment_date_obj
        
        # Get objects
        patient = get_object_or_404(Patient_details, id=patient_id)
        doctor = get_object_or_404(Staffdetails, id=doctor_id)
        branch = get_object_or_404(Branch, id=branch_id)
        
        # Get current staff (assigned_by)
        staff_id = request.session.get('staffid')
        assigned_by = get_object_or_404(Staffdetails, id=staff_id)
        
        # ✅ CRITICAL: Check if appointment already exists in Appointments table
        existing_appointment = Appointments.objects.filter(
            MR_Number=patient,
            Doctor_Name=doctor,
            Appointment_date=appointment_date_obj,
            Branch=branch
        ).first()
        
        # ✅ CRITICAL: Check for duplicate assigned appointment
        # Check if an AssignedAppointment already exists with the same appointment_id and schedule_date
        if appnid and appnid.strip():  # If appnid is provided
            try:
                # Convert appnid to integer
                appnid_int = int(appnid)
                
                # Check if there's already an AssignedAppointment with this appointment_id and schedule_date
                duplicate_assigned = AssignedAppointments.objects.filter(
                    appointment_id=appnid_int,
                    schedule_date=schedule_date_obj,
                    is_used=False  # Only check for unused appointments
                ).first()
                
                if duplicate_assigned:
                    # Get appointment details for warning message
                    appointment_details = Appointments.objects.filter(id=appnid_int).first()
                    appointment_date_str = appointment_details.Appointment_date.strftime('%d-%m-%Y') if appointment_details else 'Unknown'
                    
                    return JsonResponse({
                        'success': False,
                        'error': f'This appointment (ID: {appnid}) for date {appointment_date_str} is already assigned with schedule date {schedule_date_obj.strftime("%d-%m-%Y")}. Please choose a different schedule date.',
                        'is_duplicate': True,
                        'duplicate_details': {
                            'appointment_id': appnid,
                            'schedule_date': schedule_date_obj.strftime('%Y-%m-%d'),
                            'assigned_doctor': f"{duplicate_assigned.doctor.Staff_firstname} {duplicate_assigned.doctor.Staff_lastname}",
                            'assigned_branch': duplicate_assigned.branch.Branch_Name
                        }
                    })
            except ValueError:
                # appnid is not a valid integer, continue without duplicate check
                pass
        
        # ✅ Create new assigned appointment in AssignedAppointments table
        assigned_appointment = AssignedAppointments.objects.create(
            appointment=existing_appointment,  # Link to existing appointment if found
            patient=patient,
            doctor=doctor,
            branch=branch,
            appointment_date=appointment_date_obj,
            schedule_date=schedule_date_obj,  # This is the CRITICAL date for prescription
            remarks=remarks,
            assigned_by=assigned_by,
            appointment_id=appnid  # Store the appointment ID
        )
        
        # Format dates for response
        formatted_schedule_date = schedule_date_obj.strftime('%Y-%m-%d')
        formatted_appointment_date = appointment_date_obj.strftime('%Y-%m-%d')
        
        # ✅ PRESERVE THE TOKENNO FROM EXISTING APPOINTMENT IF IT EXISTS
        tokenno = existing_appointment.Tokenno if existing_appointment else None
        
        # Return success with appointment details
        return JsonResponse({
            'success': True,
            'message': 'Appointment assigned successfully',
            'appointment': {
                'id': assigned_appointment.id,  # AssignedAppointments ID
                'appointment_id': existing_appointment.id if existing_appointment else None,
                'doctor_name': f"{doctor.Staff_firstname} {doctor.Staff_lastname}",
                'doctor_id': doctor_id,
                'branch_id': branch_id,
                'appointment_date': formatted_appointment_date,
                'schedule_date': formatted_schedule_date,  # This is what prescription button should check
                'patient_id': patient_id,
                'patient_name': patient.Patient_Name,
                'is_linked': bool(existing_appointment),
                'tokenno': tokenno  
            }
        })
    except Exception as e:
        print(f"Error creating assigned appointment: {e}")
        return JsonResponse({'success': False, 'error': str(e)})

