def newtaxinvedit(request):
    invoice_id = request.GET.get("ids")
    invoice = get_object_or_404(newInvoiceMaster, id=invoice_id)

    if not invoice.restockstatus:
        messages.error(request, "Cancelled invoice cannot be edited.")
        return redirect("newtaxinvlist")

    if request.method == "POST":
        # --- Read payment inputs ---
        cash = request.POST.get("cash_amount", "0").strip()
        gpay = request.POST.get("gpay_amount", "0").strip()
        card = request.POST.get("card_amount", "0").strip()
        
        # Convert to float safely
        try:
            cash_val = float(cash) if cash else 0.0
            gpay_val = float(gpay) if gpay else 0.0
            card_val = float(card) if card else 0.0
        except ValueError:
            messages.error(request, "Invalid amount entered.")
            return redirect(request.path + f"?ids={invoice_id}")

        # --- Calculate total from entered amounts ---
        total_entered = cash_val + gpay_val + card_val
        
        # Check if total matches invoice total (allow small rounding differences)
        if abs(total_entered - float(invoice.total)) > 0.01:
            messages.error(
                request,
                f"Sum of payment amounts (₹{total_entered:.2f}) must equal invoice total (₹{invoice.total:.2f})."
            )
            return redirect(request.path + f"?ids={invoice_id}")

        # --- Store previous values for logging ---
        previous_values = {
            'payment_mode': invoice.payementmode,
            'cash_amount': invoice.cash_amount,
            'gpay_amount': invoice.gpay_amount,
            'card_amount': invoice.card_amount,
            'total': invoice.total
        }

        # --- Update payment amounts ---
        invoice.cash_amount = cash_val
        invoice.gpay_amount = gpay_val
        invoice.card_amount = card_val

        # --- Determine payment mode as comma-separated string ---
        payment_modes = []
        if cash_val > 0:
            payment_modes.append("Cash")
        if gpay_val > 0:
            payment_modes.append("GPay")
        if card_val > 0:
            payment_modes.append("Card")
        
        if len(payment_modes) == 0:
            invoice.payementmode = "Cash"  # Default if all zeros
        else:
            # Join with comma and space for multiple modes
            invoice.payementmode = ", ".join(payment_modes)

        invoice.save()
        
        # --- Create Payment Update Log ---
        try:
            # Get current staff from session
            staff_id = request.session.get('loginstaff')
            if staff_id:
                staff_allocation = Staffallocation.objects.get(id=staff_id)
                
                # Get user info
                ip_address = request.META.get('REMOTE_ADDR', '')
                user_agent = request.META.get('HTTP_USER_AGENT', '')[:500]  # Limit length
                
                # Create log entry
                PaymentUpdateLognew.objects.create(
                    invoice=invoice,
                    previous_payment_mode=previous_values['payment_mode'],
                    updated_payment_mode=invoice.payementmode,
                    previous_cash_amount=previous_values['cash_amount'],
                    previous_gpay_amount=previous_values['gpay_amount'],
                    previous_card_amount=previous_values['card_amount'],
                    updated_cash_amount=invoice.cash_amount,
                    updated_gpay_amount=invoice.gpay_amount,
                    updated_card_amount=invoice.card_amount,
                    previous_total=float(previous_values['total']),
                    updated_total=float(invoice.total),
                    updated_by=staff_allocation,
                    ip_address=ip_address,
                    user_agent=user_agent,
                    remarks=f"Payment updated via edit form. Invoice total: ₹{invoice.total}"
                )
                
                # Also log to console for debugging
                print(f"Payment update logged: Invoice {invoice.Invoicenumber} updated by {staff_allocation.Staff.Staff_firstname}")
                
        except Exception as e:
            # Log error but don't stop the process
            print(f"Error creating payment update log: {str(e)}")
            # Optionally, you can log this to a separate error log
        
        messages.success(request, "Payment details updated successfully.")
        return redirect("newtaxinvlist")

    # GET request - show edit form
    # Get payment update history for this invoice
    payment_logs = PaymentUpdateLognew.objects.filter(invoice=invoice).order_by('-updated_date')[:10]
    
    return render(request, "newtaxinvedit.html", {
        "invoice": invoice,
        "payment_logs": payment_logs
    })
    


