def restock_itemsfromnewtax(request, invoice_id):
    invoice = get_object_or_404(newInvoiceMaster, id=invoice_id)

    branch_id = invoice.branch_id

    if not invoice.restockstatus:
        messages.warning(request, "Invoice already restocked.")
        return redirect('newtaxinvlist')

    if request.method == 'POST':

        invoice_items = invoice.newinvoicechild_set.all()

        try:
            with transaction.atomic():

                for item in invoice_items:

                    expiry_date = None
                    if item.expirydate:
                        try:
                            expiry_date = datetime.strptime(item.expirydate, "%Y-%m-%d").date()
                        except:
                            expiry_date = None

                    stock_item = Physicalstockdetails.objects.get(
                        itemnm__itemnm__iexact=item.particulars,
                        Batch_no=item.batchno,
                        suppliernm_id=item.suppid_id,
                        Expiry_date=expiry_date,
                        Comapany_name__Comapany_name=item.mfg,
                        deleted=False,
                        stockbranch_id=branch_id
                    )

                    print("Restocking:", stock_item)

                    stock_item.qty += item.quantity
                    stock_item.save()

                # If all restock successful
                invoice.restockstatus = False
                invoice.save()

                messages.success(
                    request,
                    f"Invoice {invoice.Invoicenumber} restocked successfully."
                )

        except Physicalstockdetails.DoesNotExist:

            # If ANY item fails → rollback happens automatically
            messages.error(
                request,
                "Restock failed. Some items were not found in stock. No changes were made."
            )

        return redirect('newtaxinvlist')

    messages.error(request, "Invalid request method.")
    return redirect('newtaxinvlist')

from django.template.loader import render_to_string



def newtaxinvview(request):
    lsinvoice = newInvoiceMaster.objects.get(id=request.GET.get('ids'))
    chinvoice = newInvoiceChild.objects.filter(invmasterid=lsinvoice.id)
    # Chunk items for printing
    chunk_size = 10
    chinvoice_list = list(chinvoice)
    chinvoice_chunks = []
    for i in range(0, len(chinvoice_list), chunk_size):
        chunk_items = chinvoice_list[i:i+chunk_size]
        chunk_subtotal = sum(item.sutotal for item in chunk_items)
        chinvoice_chunks.append((chunk_items, chunk_subtotal))

    # Staff info
    st_id = request.session['loginstaff']
    staff_branch = Staffallocation.objects.get(id=st_id)

    # Hospital & branch info
    br = lsinvoice.branch
    objhospt = Hospitaldetails.objects.all()

    # ✅ GST flags with condition
    branch_has_gst = False
    branch_is_composition = False

    if br:
        cutoff_date = datetime.strptime("18-02-2026", "%d-%m-%Y").date()

        # Hide GST only for branch id 5 before 17-02-2026
        if not (br.id in [5, 25] and lsinvoice.currentdate < cutoff_date):
            branch_has_gst = bool(br.gstno and br.gstno.lower() != 'none')
            branch_is_composition = bool(br.compositiontax)

    # Amount in words
    amount_in_words = ""
    if lsinvoice.total:
        amount_in_words = num2words(lsinvoice.total, lang='en_IN').title()
        amount_in_words = f"Rupees {amount_in_words} Only"

    context = {
        'lsinvoice': lsinvoice,
        'chinvoice_chunks': chinvoice_chunks,
        'staffn': staff_branch,
        'objhospt': objhospt,
        'br': br,
        'branch_has_gst': branch_has_gst,
        'branch_is_composition': branch_is_composition,
        'amount_in_words': amount_in_words,
    }

    return render(request, "newtaxinvview.html", context)

