def restock_itemsfrompharmacy(request, invoice_id):
    # Ensure invoice exists
    invoice = get_object_or_404(invoicemaster, id=invoice_id)
    branch_id = request.session.get('branchid')

    if request.method == 'POST':
        invoice_items = invoice.invoicechild_set.all()
        for item in invoice_items:
            try:
                # Find corresponding physical stock item
                stock_item = Physicalstockdetails.objects.get(
                    itemnm__itemnm=item.particulars,
                    Batch_no=item.batchno,
                    suppliernm=item.suppid_id,
                    Expiry_date=item.expirydate,
                    Comapany_name__Comapany_name=item.mfg,
                    deleted=False,
                    stockbranch=invoice.branch_id
                )
                # Add the invoice quantity back to stock
                stock_item.qty = int(stock_item.qty) + int(item.quantity)
                stock_item.save()
            except Physicalstockdetails.DoesNotExist:
                # Optional: log missing stock
                print(f"Stock not found for {item.particulars}")

        invoice.restockstatus = False
        invoice.save()
        messages.success(request, f"Invoice {invoice.Invoicenumber} restocked successfully.")
        return redirect('pharmacyinvoicereport')

    messages.error(request, "Invalid request method.")
    return redirect('pharmacyinvoicereport')
    

def add_medicinerate(request):
    """
    View to add a new medicine rate for a specific branch.
    """
    # Fetch all medicines and branches for dropdowns
    medicines = medicinemaster_new.objects.all().order_by('itemnm')
    branches = Branch.objects.all().order_by('Branch_Name')

    if request.method == 'POST':
        itemid = request.POST.get('itemid')
        branchid = request.POST.get('branchid')
        mrp = request.POST.get('mrp')

        # Basic validation
        if not itemid or not branchid or not mrp:
            messages.error(request, "All fields are required.")
            return redirect('add_medicinerate')

        # Validate MRP number
        try:
            float(mrp)
        except ValueError:
            messages.error(request, "MRP must be a valid number.")
            return redirect('add_medicinerate')

        # Check if medicine rate already exists for this branch
        existing_rate = medicinemasterrate.objects.filter(
            itemid_id=itemid,
            branchid_id=branchid,
            mrp=float(mrp)

        ).first()

        if existing_rate:
            messages.warning(request, "This medicine rate already exists for the selected branch.")
            return redirect('add_medicinerate')
        # Save new record
        medicinemasterrate.objects.create(
            itemid_id=itemid,
            branchid_id=branchid,
            mrp=mrp
        )
        messages.success(request, "Medicine rate added successfully!")
        return redirect('add_medicinerate')
    context = {
        'medicines': medicines,
        'branches': branches,
    }
    return render(request, 'medicinerate.html', context)
    
    
