from django.db.models import Max

def get_financial_year():
    """Return current financial year in display format (YY/YY)"""
    today = date.today()
    year = today.year
    next_year = year + 1
    
    # Financial year starts from April 1
    if today.month >= 4:
        return f"{str(year)[-2:]}/{str(next_year)[-2:]}"  # 26/27
    else:
        return f"{str(year-1)[-2:]}/{str(year)[-2:]}"    # 25/26


def get_financial_year_compact():
    """Return compact financial year (YYYY)"""
    today = date.today()
    year = today.year
    next_year = year + 1
    
    if today.month >= 4:
        return f"{str(year)[-2:]}{str(next_year)[-2:]}"  # 2627
    else:
        return f"{str(year-1)[-2:]}{str(year)[-2:]}"    # 2526


# ------------------ SAFE FLOAT ------------------
def safe_float(value):
    try:
        return float(value) if value else 0.0
    except (TypeError, ValueError):
        return 0.0


