def branch_list(request):
    today = date.today()
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')

    if start_date and end_date:
        sdate = date.fromisoformat(start_date)
        edate = date.fromisoformat(end_date)
    else:
        sdate = edate = today

    branch_data = []
    active_branches = Branch.objects.filter(inactive=False)

    for branch in active_branches:
        # ---------- Visits ----------
        total_visit = Appointments.objects.filter(
            Branch=branch,
            Appointment_date__range=[sdate, edate]
        ).count()

        # ---------- Appointments ----------
        appointment_qs = appointmentinvoicemaster.objects.filter(
            branch=branch,
            currentdate__range=[sdate, edate],
            cancelstatus=False
        )

        ap_cash_total = appointment_qs.filter(payementmode__iexact='Cash').aggregate(total=Sum('total'))['total'] or 0
        ap_gpay_total = appointment_qs.filter(payementmode__iexact='GPay').aggregate(total=Sum('total'))['total'] or 0
        ap_card_total = appointment_qs.filter(payementmode__iexact='Card').aggregate(total=Sum('total'))['total'] or 0
        appointment_total = ap_cash_total + ap_gpay_total + ap_card_total

        total_appointment_invoice_count = appointment_qs.count()
        cancelled_appointment_invoice_count = appointmentinvoicemaster.objects.filter(
            branch=branch,
            currentdate__range=[sdate, edate],
            cancelstatus=True
        ).count()
        active_appointment_invoice_count = total_appointment_invoice_count - cancelled_appointment_invoice_count

        # ---------- Pharmacy ----------
        pharmacy_qs = newInvoiceMaster.objects.filter(
            branch=branch,
            currentdate__range=[sdate, edate],
            restockstatus=True
        )

        ph_cash_total = pharmacy_qs.aggregate(
            total=Sum(Coalesce(Cast('cash_amount', FloatField()), 0.0))
        )['total'] or 0
        ph_gpay_total = pharmacy_qs.aggregate(
            total=Sum(Coalesce(Cast('gpay_amount', FloatField()), 0.0))
        )['total'] or 0
        ph_card_total = pharmacy_qs.aggregate(
            total=Sum(Coalesce(Cast('card_amount', FloatField()), 0.0))
        )['total'] or 0

        pharmacy_total = ph_cash_total + ph_gpay_total + ph_card_total

        total_pharmacy_invoice_count = newInvoiceMaster.objects.filter(
            branch=branch,
            currentdate__range=[sdate, edate]
        ).count()
        active_pharmacy_invoice_count = pharmacy_qs.count()
        cancelled_pharmacy_invoice_count = total_pharmacy_invoice_count - active_pharmacy_invoice_count

       
        # ---------- Grand total ----------
        total_collection = appointment_total + pharmacy_total 

        branch_data.append({
            'branch': branch,
            'total_visit': total_visit,
            'cash_total': ap_cash_total,
            'gpay_total': ap_gpay_total,
            'card_total': ap_card_total,
            'appointment_total': appointment_total,
            'total_appointment_invoice_count': total_appointment_invoice_count,
            'active_appointment_invoice_count': active_appointment_invoice_count,
            'cancelled_appointment_invoice_count': cancelled_appointment_invoice_count,
            'ph_cash_total': ph_cash_total,
            'ph_gpay_total': ph_gpay_total,
            'ph_card_total': ph_card_total,
            'pharmacy_total': pharmacy_total,
            'total_pharmacy_invoice_count': total_pharmacy_invoice_count,
            'active_pharmacy_invoice_count': active_pharmacy_invoice_count,
            'cancelled_pharmacy_invoice_count': cancelled_pharmacy_invoice_count,
           
            'total_collection': total_collection,
        })

    context = {
        'branch_data': branch_data,
        'start_date': sdate,
        'end_date': edate,
    }

    return render(request, 'branch_list.html', context)
    
    
def get_latest_vitals(request):
    mrno_id = request.GET.get('mrno')
    if not mrno_id:
        return JsonResponse({'success': False, 'error': 'No MR number provided'})
    try:
        latest_vitals = (
            casehistryvitals.objects.filter(mrno_id=mrno_id)
            .order_by('-id')
            .first()
        )
        if latest_vitals:
            return JsonResponse({
                'success': True,
                'age': latest_vitals.age or '',
                'height': latest_vitals.height or '',
            })
        else:
            return JsonResponse({'success': True, 'age': '', 'height': ''})
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)})
        
        
        
def inventory_invlist(request):
    total_amount = None
    sdate = None
    edate = None

