            patient_id = request.POST.get('ptid')
            doctor_id = request.POST.get('doctor')
            status = request.POST.get('status')
            chief_complaint = request.POST.get('chief_complaint')
            present_complaint = request.POST.get('present_complaint')
            final_diagnosis = request.POST.get('final_diagnosis')
            additional_notes = request.POST.get('notes')
            follow_up_date = request.POST.get('follow_up_date', str(date.today()))
            prepared_by = request.session.get('staffid')
            brchid = request.session.get('branchid')

            # Ensure patient_id is provided
            if not patient_id:
                return JsonResponse({"success": False, "error": "Patient ID is required."}, status=400)

