def creditnote_list(request):
    staff_design_id = request.session.get('loginstaffdesign')
    staff_id = request.session.get('loginstaff')

    # Session validation
    if not staff_design_id or not staff_id:
        return redirect('staff_login')

    # Get staff info
    try:
        staff_branch = Staffallocation.objects.select_related('Branch_Name').get(id=staff_id)
        branch_id = staff_branch.Branch_Name_id
    except Staffallocation.DoesNotExist:
        messages.error(request, "Staff allocation not found.")
        return redirect('staff_login')

    # Get designation
    try:
        designation = Designation.objects.get(id=staff_design_id)
        designation_name = designation.Designation_Name.strip().lower()
    except Designation.DoesNotExist:
        designation_name = ""

    # Base Query
    if designation_name == "superadmin":
        credit_notes = CreditNoteMaster.objects.all().select_related(
            "branch", "hospitalname", "created_by", "invoicemaster"
        )
        branches = Branch.objects.all().order_by("Branch_Name")
    else:
        credit_notes = CreditNoteMaster.objects.filter(branch_id=branch_id).select_related(
            "branch", "hospitalname", "created_by", "invoicemaster"
        )
        branches = Branch.objects.filter(id=branch_id)

    # Handle POST filters
    if request.method == "POST":
        branch_filter = request.POST.get("branch")
        creditnote_number = request.POST.get("creditnote_number")
        invoice_number = request.POST.get("invoice_number")
        patientname = request.POST.get("patientname")
        patientphno = request.POST.get("patientphno")
        from_date = request.POST.get("from_date")
        to_date = request.POST.get("to_date")
        min_total = request.POST.get("min_total")
        max_total = request.POST.get("max_total")

        # Apply filters
        if branch_filter and branch_filter != "All Branches":
            credit_notes = credit_notes.filter(branch_id=branch_filter)
        if creditnote_number:
            credit_notes = credit_notes.filter(creditnote_number__icontains=creditnote_number)
       
        if patientname:
            credit_notes = credit_notes.filter(patientname__icontains=patientname)
        if patientphno:
            credit_notes = credit_notes.filter(patientphno__icontains=patientphno)
        if from_date:
            credit_notes = credit_notes.filter(creditnote_date__gte=from_date)
        if to_date:
            credit_notes = credit_notes.filter(creditnote_date__lte=to_date)
        if min_total:
            credit_notes = credit_notes.filter(total__gte=min_total)
        if max_total:
            credit_notes = credit_notes.filter(total__lte=max_total)
    # Sort newest first
    credit_notes = credit_notes.order_by("-creditnote_date", "-id")
    context = {
        "creditnotes": credit_notes,
        "branches": branches,
        "designation_name": designation_name,
        "staff_branch": staff_branch,
        "idmngmnt": request.POST.get("menumanagement_id", ""),
    }
    return render(request,"creditnote_list.html", context)

