# === CREATE CREDIT NOTE Number ===

from django.utils.timezone import now


def get_financial_year():
    """
    Get financial year in format '25/26' based on April–March cycle
    """
    current_date = now().date()
    current_year = current_date.year
    
    if current_date.month >= 4:
        fy_start = current_year
        fy_end = current_year + 1
    else:
        fy_start = current_year - 1
        fy_end = current_year
        
    return f"{fy_start % 100}/{fy_end % 100}"


def generate_custom_creditnote_number():
    from datetime import datetime
    today = datetime.today()
    
    # Financial year calculation (India)
    if today.month >= 4:
        start_year = today.year % 100
        end_year = (today.year + 1) % 100
    else:
        start_year = (today.year - 1) % 100
        end_year = today.year % 100

    # Keep slash format
    fy_prefix = f"{start_year:02d}/{end_year:02d}"   # 26/27

    last_cn = CreditNoteMaster.objects.filter(
        creditnote_number__startswith=f"CN{fy_prefix}"
    ).order_by('-id').first()

    if last_cn and last_cn.creditnote_number:
        last_number = last_cn.creditnote_number
        

        temp = last_number[2:]
        
        if '/' in temp:
            parts = temp.split('/')
            if len(parts) >= 2:
                seq_str = parts[1]
                if len(seq_str) >= 4:
                    sequence = int(seq_str[-4:])
                else:
                    sequence = int(seq_str) if seq_str else 0
                new_seq = sequence + 1
            else:
                new_seq = 1
        else:
            new_seq = 1
    else:
        new_seq = 1
    
    result = f"CN{fy_prefix}{new_seq:04d}"
    return result

@transaction.atomic
def create_creditnote(request):
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Menumanagement ID not provided.")
        return redirect('error_page')

    staff_id = request.session.get('staffid')
    branch_id = request.session.get('branchid')
    stffallid = request.session.get('loginstaff')

    if not staff_id or not branch_id or not stffallid:
        messages.error(request, "Session expired or staff/branch missing.")
        return redirect('staff_login')

    try:
        staff_branch = Staffallocation.objects.get(id=stffallid)
        branch = Branch.objects.get(id=staff_branch.Branch_Name_id)
    except (Staffallocation.DoesNotExist, Branch.DoesNotExist):
        messages.error(request, "Staff branch information not found.")
        return redirect('staff_login')

    invoice_id = request.GET.get("invoice_id") or request.POST.get("invoice_id")
    if not invoice_id:
        return render(request, "create_creditnote.html", {"idmngmnt": idmngmnt})

    invoice = get_object_or_404(newInvoiceMaster, id=invoice_id)
    items = [i for i in newInvoiceChild.objects.filter(invmasterid=invoice) if i.remaining_qty > 0]

    if request.method == "POST":
        reason = request.POST.get("reason", "").strip() or "Return of items"
        subtotal = float(request.POST.get("subtotal", 0) or 0)
        tax = float(request.POST.get("tax", 0) or 0)
        total = float(request.POST.get("total", 0) or 0)
        staff = Staffdetails.objects.filter(id=staff_id).first()

        creditnote_number = generate_custom_creditnote_number()

        creditnote = CreditNoteMaster.objects.create(
            hospitalname=invoice.hospitalname,
            branch=branch,
            invoicemaster=invoice,
            creditnote_number=creditnote_number,
            reason=reason,
            subtotal=subtotal,
            tax=tax,
            total=total,
            patientname=invoice.patientname,
            patientphno=invoice.patientphno,
            created_by_id=stffallid,
            creditnote_date=now().date(),
        )

        total_credit_amount = 0
        created_items = 0

        with transaction.atomic():
            for item in items:
                return_qty = int(request.POST.get(f"qty_{item.id}", "0") or 0)
                if return_qty <= 0:
                    continue
                if return_qty > item.remaining_qty:
                    messages.error(request, f"Cannot return more than {item.remaining_qty} for {item.particulars}.")
                    transaction.set_rollback(True)
                    return redirect(f"{reverse('create_creditnote')}?invoice_id={invoice.id}&menumanagement_id={idmngmnt}")

                line_total = round(return_qty * (item.amount or 0), 2)
                line_tax = float(item.tax or 0)
                item_reason = request.POST.get(f"reason_{item.id}", "").strip() or f"Return from Invoice {invoice.Invoicenumber}"

                CreditNoteChild.objects.create(
                    creditnote_master=creditnote,
                    invoice_child=item,
                    particulars=item.particulars,
                    quantity=return_qty,
                    amount=item.amount,
                    tax=line_tax,
                    total=line_total,
                    remarks=item_reason,
                    restocked=True,
                )

                # Update returned quantity
                item.returned_qty = F("returned_qty") + return_qty
                item.save(update_fields=["returned_qty"])
                total_credit_amount += line_total
                created_items += 1

                # === 🧾 Physical Stock Update ===
                try:
                    # Get medicinemaster instance
                    medicine_instance = medicinemaster.objects.filter(itemnm=item.particulars).first()
                    if not medicine_instance:
                        messages.error(request, f"Medicine {item.particulars} not found in master list.")
                        transaction.set_rollback(True)
                        return redirect(f"{reverse('create_creditnote')}?invoice_id={invoice.id}&menumanagement_id={idmngmnt}")
                    unit_instance = unitdt.objects.filter(unitname=item.unt).first()
                    if not unit_instance:
                        raise Exception(f"Unit {item.unt} not found in unit master.")
                    supplier_instance = None
                    if item.suppid_id:
                        supplier_instance = supplier.objects.filter(id=item.suppid_id).first()

                    company_instance = None

                    if item.mfg:
                        company_instance = Comapany.objects.filter(
                            Comapany_name__iexact=item.mfg.strip()
                        ).first()

                    mfg_date = item.manufacturedate
                    exp_date = item.expirydate

                    if isinstance(mfg_date, str):
                        mfg_date = datetime.strptime(mfg_date, "%Y-%m-%d").date()

                    if isinstance(exp_date, str):
                        exp_date = datetime.strptime(exp_date, "%Y-%m-%d").date()
                                        # Looser filter first
                    stock_qs = Physicalstockdetails.objects.filter(
                        itemnm=medicine_instance,
                        Batch_no=item.batchno,
                        stockbranch=branch.id,
                        deleted=False,
                    )

                    # Refine filter in Python
                    stock_rec = None
                    for s in stock_qs:
                        supplier_match = (s.suppliernm.id if s.suppliernm else None) == (item.suppid_id or None)
                        company_match = (s.Comapany_name.Comapany_name if s.Comapany_name else None) == (item.mfg or None)
                        unit_match = (s.unt.unitname if s.unt else None) == (item.unt or None)
                        if supplier_match and company_match and unit_match:
                            stock_rec = s
                            break

                    if stock_rec:
                        # Update existing stock
                        stock_rec.qty = F('qty') + return_qty
                        stock_rec.lastupdatedate = now().date()
                        stock_rec.save(update_fields=['qty', 'lastupdatedate'])
                    else:
                        # Create new stock record
                        Physicalstockdetails.objects.create(
                            storenm=storedetails.objects.first(),
                            itemnm=medicine_instance,
                            unt=unit_instance,  # ✅ FIXED HERE
                            suppliernm=supplier_instance,
                            Comapany_name=company_instance,

                            Manufacturer_date=mfg_date,
Expiry_date=exp_date,

                            Batch_no=item.batchno,
                            Rate=item.amount,
                            qty=return_qty,
                            insertedstaffid=staff,
                            stockbranch=branch,
                        )

                except Exception as e:
                    transaction.set_rollback(True)
                    messages.error(request, f"Error updating stock for {item.particulars}: {e}")
                    return redirect(f"{reverse('create_creditnote')}?invoice_id={invoice.id}&menumanagement_id={idmngmnt}")

            if created_items == 0:
                creditnote.delete()
                messages.warning(request, "No items selected for credit note.")
                return redirect(f"{reverse('create_creditnote')}?invoice_id={invoice.id}&menumanagement_id={idmngmnt}")

            # Update totals if not set
            if total == 0:
                creditnote.subtotal = total_credit_amount
                creditnote.total = total_credit_amount
                creditnote.save()

        messages.success(request, f"✅ Credit Note {creditnote.creditnote_number} created successfully. Stock updated.")
        return redirect(f"{reverse('creditnote_detail')}?creditnote_id={creditnote.id}")

    context = {"invoice": invoice, "items": items, "idmngmnt": idmngmnt}
    return render(request, "create_creditnote.html", context)

