def get_inventoryreorder_level(request):
    med_id = request.GET.get('med_id')
    quantity = int(request.GET.get('quantity', 0))
    batchId = request.GET.get('batchId')
    compid = request.GET.get('compid')
    stockbranch = request.GET.get('stockbranch')
    selectedsupid = request.GET.get('selectedsupid')
    # 🧩 Get total stock for matching entries
    qs = Inventorystockdetails.objects.filter(
        itemnm_id=med_id,
        Batch_no=batchId,
        Comapany_name_id=compid,
        suppliernm_id=selectedsupid,
        stockbranch_id=stockbranch
    )
    total_qty = qs.aggregate(total=Sum('qty'))['total'] or 0
    if total_qty == 0:
        return JsonResponse({'stock_status': 'Out Of Stock', 'available_stock': 0})
    # 🧩 Ge reorder level (default 10)
    reorder_detail = invreorderdetails.objects.filter(
        itemname_id=med_id,
        companyid_id=compid
    ).first()
    reorder_level = int(reorder_detail.qty) if reorder_detail else 10
    available_stock = total_qty - quantity
    if available_stock < 0:
        status = 'Stock depleted'
    elif available_stock < reorder_level:
        status = 'Stock below reorder level'
    else:
        status = 'Stock available'

    return JsonResponse({'stock_status': status, 'available_stock': total_qty})
    
    
    

from django.db.models import Sum
