from django.shortcuts import render, redirect
from django.contrib import messages
from django.db.models import Sum, FloatField
from django.db.models.functions import Coalesce
from django.utils import timezone

def inventory_sales_report(request):
    sdate = None
    edate = None

    logstaffbrid = request.session.get('branchid')
    stdesign_id = request.session.get('loginstaffdesign')

    # ---------- SESSION CHECK ----------
    if not stdesign_id:
        messages.error(request, "Session expired. Please log in again.")
        return redirect('staff_login')

    # ---------- SUPERADMIN CHECK ----------
    try:
        designation = Designation.objects.get(id=stdesign_id)
        is_superadmin = designation.Designation_Name.lower() == 'superadmin'
    except Designation.DoesNotExist:
        is_superadmin = False

    # ---------- BASE FILTER ----------
    filters = {}
    if not is_superadmin:
        filters['branch_id'] = logstaffbrid

    # ---------- DATE FILTER ----------
    if request.method == 'POST':
        sdate = request.POST.get('sdate')
        edate = request.POST.get('edate')

        if sdate and edate:
            filters['currentdate__range'] = [sdate, edate]
    else:
        filters['currentdate'] = timezone.now().date()

    # ---------- INVENTORY INVOICES ----------
    inv = inventoryInvoiceMaster.objects.filter(**filters).order_by('-currentdate')

    # ---------- TOTALS ----------
    active_total_amount = inventoryInvoiceMaster.objects.filter(
        restockstatus=True,
        **filters
    ).aggregate(
        total=Coalesce(Sum('total'), 0.0, output_field=FloatField())
    )['total']

    inactive_total_amount = inventoryInvoiceMaster.objects.filter(
        restockstatus=False,
        **filters
    ).aggregate(
        total=Coalesce(Sum('total'), 0.0, output_field=FloatField())
    )['total']

    # ---------- COUNTS ----------
    total_invoice_count = inv.count()
    active_invoice_count = inv.filter(restockstatus=True).count()
    inactive_invoice_count = inv.filter(restockstatus=False).count()

    context = {
        'sdate': sdate,
        'edate': edate,
        'inv': inv,

        # totals
        'active_total_amount': active_total_amount,
        'inactive_total_amount': inactive_total_amount,

        # counts
        'total_invoice_count': total_invoice_count,
        'active_invoice_count': active_invoice_count,
        'inactive_invoice_count': inactive_invoice_count,
    }

    return render(request, "inventory_sales_report.html", context)





def doctor_visit_report(request):
    # ---------- SESSION ----------
    staff_design_id = request.session.get('loginstaffdesign')
    staff_id = request.session.get('loginstaff')

    if not staff_design_id or not staff_id:
        return redirect('staff_login')

    try:
        staff = Staffallocation.objects.select_related(
            'Branch_Name', 'Staff'
        ).get(id=staff_id)
    except Staffallocation.DoesNotExist:
        return redirect('staff_login')

    staff_branch_id = staff.Branch_Name_id
    staff_details_id = staff.Staff_id

    designation = Designation.objects.filter(id=staff_design_id).first()
    is_superadmin = designation and designation.Designation_Name.lower() == "superadmin"
    is_doctor = designation and designation.Designation_Name.lower() in [
        "cmo", "chief medical officer", "Associate Doctors","Associate Doctors"
    ]

    # ---------- DATE RANGE ----------
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')

    if start_date and end_date:
        start_date = date.fromisoformat(start_date)
        end_date = date.fromisoformat(end_date)
    else:
        # Default to today's date for both start and end
        start_date = end_date = date.today()

    # ---------- FILTERS ----------
    selected_branch_id = request.GET.get('branch')
    selected_doctor_id = request.GET.get('doctor')

    # ---------- DOCTOR SELECTION ----------
    if is_superadmin and selected_doctor_id and selected_doctor_id.isdigit():
        doctor_id = int(selected_doctor_id)
    elif is_doctor and not selected_doctor_id:
        # For doctors, default to their own ID
        doctor_id = staff.Staff.id
    else:
        # For superadmin with no doctor selected, set doctor_id to None (all doctors)
        doctor_id = None

    # ---------- BRANCH FILTER ----------
    if is_superadmin and selected_branch_id and selected_branch_id.isdigit():
        branch_filter = Q(branch_id=int(selected_branch_id))
        appointment_branch_filter = Q(Branch_id=int(selected_branch_id))
    elif not is_superadmin:
        branch_filter = Q(branch_id=staff_branch_id)
        appointment_branch_filter = Q(Branch_id=staff_branch_id)
    else:
        # Superadmin with no branch selected - no branch filter
        branch_filter = Q()
        appointment_branch_filter = Q()

    # ---------- DOCTOR DETAILS ----------
    if doctor_id:
        try:
            selected_doctor = Staffdetails.objects.get(id=doctor_id)
            doctor_name = f"{selected_doctor.Staff_firstname} {selected_doctor.Staff_lastname}"
        except Staffdetails.DoesNotExist:
            doctor_name = "Unknown Doctor"
    else:
        doctor_name = "All Doctors"

    # =====================================================
    # 1️⃣ APPOINTMENTS (SOURCE OF TRUTH)
    # =====================================================
    # Base appointments queryset
    appointments_qs = Appointments.objects.filter(
        Appointment_date__range=(start_date, end_date)
    ).filter(appointment_branch_filter)
    
    # Apply doctor filter only if a specific doctor is selected
    if doctor_id:
        appointments_qs = appointments_qs.filter(Doctor_Name_id=doctor_id)
    
    appointments = appointments_qs

    # Initialize status counts - SEPARATE new statuses from old "Online" status
    appointment_counts_by_status = {
        # Existing statuses
        "consultation": 0,
        "followup": 0,
        "revisit": 0,
        "camp": 0,
        "treatment": 0,
        "online": 0,  # This is for OLD "Online" status (not the new ones)
        
        # New online statuses (separate from "online")
        "zoho online consultation": 0,
        "zoho online revisit": 0,
        "whatsapp": 0,
        "whatsapp revisit": 0,
        
        # NEW: Treatment Revisit status
        "treatment revisit": 0,
        
        # Other/blank
        "": 0  
    }

    for appt in appointments:
        status = (appt.status or "").strip().lower()
        
        # Check for exact matches first
        if status in appointment_counts_by_status:
            appointment_counts_by_status[status] += 1
        else:
            # Handle new status patterns (case-insensitive)
            if 'zoho' in status and 'consultation' in status:
                appointment_counts_by_status["zoho online consultation"] += 1
            elif 'zoho' in status and 'revisit' in status:
                appointment_counts_by_status["zoho online revisit"] += 1
            elif 'whatsapp' in status and 'revisit' in status:
                appointment_counts_by_status["whatsapp revisit"] += 1
            elif 'whatsapp' in status:
                appointment_counts_by_status["whatsapp"] += 1
            elif 'treatment' in status and 'revisit' in status:
                appointment_counts_by_status["treatment revisit"] += 1  # NEW: Treatment Revisit
            elif status == 'online':
                # This is for OLD "Online" status (exact match)
                appointment_counts_by_status["online"] += 1
            else:
                appointment_counts_by_status[""] += 1

    # =====================================================
    # 2️⃣ FEES FROM INVOICES
    # =====================================================
    appointment_fees_by_status = {
        key: 0.0 for key in appointment_counts_by_status.keys()
    }

    appointment_invoices = []

    # Base invoices queryset
    invoices_qs = appointmentinvoicemaster.objects.filter(
        currentdate__range=(start_date, end_date),
        cancelstatus=False
    ).filter(branch_filter).select_related('Mrno', 'branch')
    
    # For superadmin with no doctor selected, we need to filter invoices
    # by matching appointments for the selected criteria
    if is_superadmin and not doctor_id:
        # Filter invoices that have matching appointments
        invoices_qs = invoices_qs.filter(
            Mrno_id__in=appointments.values_list('MR_Number_id', flat=True),
            currentdate__in=appointments.values_list('Appointment_date', flat=True)
        )
    elif doctor_id:
        # Filter invoices by doctor through appointments
        invoices_qs = invoices_qs.filter(
            Mrno_id__in=appointments.values_list('MR_Number_id', flat=True),
            currentdate__in=appointments.values_list('Appointment_date', flat=True)
        )
    
    invoices = invoices_qs

    for invoice in invoices:
        # Try to find matching appointment
        appt_filter = Q(
            MR_Number_id=invoice.Mrno_id,
            Appointment_date=invoice.currentdate
        )
        
        # If a specific doctor is selected, add that filter
        if doctor_id:
            appt_filter &= Q(Doctor_Name_id=doctor_id)
        
        appt = appointments.filter(appt_filter).first()

        if not appt:
            continue

        status = (appt.status or "").strip().lower()
        fee = float(invoice.total or 0)
        
        # Normalize status for counting (same logic as above)
        normalized_status = status
        if 'zoho' in status and 'consultation' in status:
            normalized_status = "zoho online consultation"
        elif 'zoho' in status and 'revisit' in status:
            normalized_status = "zoho online revisit"
        elif 'whatsapp' in status and 'revisit' in status:
            normalized_status = "whatsapp revisit"
        elif 'whatsapp' in status:
            normalized_status = "whatsapp"
        elif 'treatment' in status and 'revisit' in status:
            normalized_status = "treatment revisit"  # NEW: Treatment Revisit
        elif status == 'online':
            normalized_status = "online"  # Keep old "online" status separate
        elif status in appointment_fees_by_status:
            normalized_status = status
        else:
            normalized_status = ""

        if normalized_status in appointment_fees_by_status:
            appointment_fees_by_status[normalized_status] += fee
        else:
            appointment_fees_by_status[""] += fee

        invoice.appointment_status = appt.status or "N/A"
        appointment_invoices.append(invoice)

    # =====================================================
    # 3️⃣ PAYMENT MODE TOTALS (for paid appointments)
    # =====================================================
    appointment_totals = {
        "cash": 0,
        "gpay": 0,
        "card": 0,
        "total": 0
    }

    for inv in appointment_invoices:
        fee = float(inv.total or 0)
        mode = (inv.payementmode or "").lower()

        if "cash" in mode:
            appointment_totals["cash"] += fee
        elif "gpay" in mode or "google" in mode or "upi" in mode:
            appointment_totals["gpay"] += fee
        elif "card" in mode:
            appointment_totals["card"] += fee

        appointment_totals["total"] += fee

    # =====================================================
    # 4️⃣ TOTAL VISITS
    # =====================================================
    total_visits = sum(appointment_counts_by_status.values())

    # =====================================================
    # 5️⃣ PHARMACY TRANSACTIONS (ONLY FOR SUPERADMIN)
    # =====================================================
    pharmacy_totals = {
        "cash": 0,
        "gpay": 0,
        "card": 0,
        "total": 0
    }
    pharmacy_page = []

    if is_superadmin:
        pharmacy_qs = newInvoiceMaster.objects.filter(
            currentdate__range=(start_date, end_date),
            restockstatus=True
        ).filter(branch_filter).select_related('branch', 'Mrno')

        pharmacy_totals_agg = pharmacy_qs.aggregate(
            cash=Sum('cash_amount'),
            gpay=Sum('gpay_amount'),
            card=Sum('card_amount'),
        )

        pharmacy_totals['cash'] = pharmacy_totals_agg['cash'] or 0
        pharmacy_totals['gpay'] = pharmacy_totals_agg['gpay'] or 0
        pharmacy_totals['card'] = pharmacy_totals_agg['card'] or 0
        pharmacy_totals['total'] = (
            pharmacy_totals['cash'] +
            pharmacy_totals['gpay'] +
            pharmacy_totals['card']
        )
        
        pharmacy_page = pharmacy_qs

    # =====================================================
    # 6️⃣ LAB REVENUE (ONLY FOR SUPERADMIN)
    # =====================================================
    lab_bills = []
    enhanced_lab_bills = []
    total_lab_amount = 0
    daily_lab_breakdown = []
    doctor_lab_breakdown = []
    branch_lab_breakdown = []

    if is_superadmin:
        # Get all lab bills for the selected date range
        lab_bills_query = casehistorylabbill.objects.filter(
            created_at__date__range=[start_date, end_date]
        ).select_related('patient', 'preparedby')

        # Apply branch filter based on doctor's branch
        if selected_branch_id and selected_branch_id.isdigit():
            lab_bills_query = lab_bills_query.filter(
                preparedby__staffallocation__Branch_Name_id=int(selected_branch_id)
            )

        # Apply doctor filter if specified
        if selected_doctor_id and selected_doctor_id.isdigit():
            lab_bills_query = lab_bills_query.filter(preparedby_id=int(selected_doctor_id))

        # Order by most recent first
        lab_bills_query = lab_bills_query.order_by('-created_at')

        # Calculate totals
        total_lab_amount = lab_bills_query.aggregate(total=Sum('total_amount'))['total'] or 0

        # Enhance lab bills with branch info
        for bill in lab_bills_query:
            doctor_branch = "Unknown"
            if bill.preparedby:
                staff_alloc = Staffallocation.objects.filter(
                    Staff=bill.preparedby,
                    Status='Active'
                ).select_related('Branch_Name').first()
                if staff_alloc and staff_alloc.Branch_Name:
                    doctor_branch = staff_alloc.Branch_Name.Branch_Name
            
            enhanced_lab_bills.append({
                'bill': bill,
                'doctor_branch': doctor_branch
            })
            
            lab_bills.append(bill)

        # Group by date for daily breakdown
        if lab_bills_query.exists():
            # Daily breakdown
            from django.db.models.functions import TruncDate
            daily_lab_breakdown = (
                lab_bills_query.annotate(date=TruncDate('created_at'))
                .values('date')
                .annotate(
                    total_bills=Count('id'),
                    total_revenue=Sum('total_amount')
                )
                .order_by('date')
            )

            # Group by doctor
            doctor_data = {}
            for bill in lab_bills_query:
                if bill.preparedby:
                    doctor_id_val = bill.preparedby.id
                    if doctor_id_val not in doctor_data:
                        staff_alloc = Staffallocation.objects.filter(
                            Staff=bill.preparedby,
                            Status='Active'
                        ).select_related('Branch_Name').first()
                        
                        doctor_data[doctor_id_val] = {
                            'doctor_id': doctor_id_val,
                            'doctor_name': bill.preparedby.Staff_firstname,
                            'doctor_lastname': bill.preparedby.Staff_lastname or '',
                            'branch_name': staff_alloc.Branch_Name.Branch_Name if staff_alloc and staff_alloc.Branch_Name else 'Unknown',
                            'total_bills': 0,
                            'total_revenue': 0
                        }
                    
                    doctor_data[doctor_id_val]['total_bills'] += 1
                    doctor_data[doctor_id_val]['total_revenue'] += float(bill.total_amount or 0)
            
            doctor_lab_breakdown = list(doctor_data.values())
            for doc in doctor_lab_breakdown:
                doc['full_name'] = f"{doc['doctor_name']} {doc['doctor_lastname']}".strip()
            
            # Sort by revenue descending
            doctor_lab_breakdown.sort(key=lambda x: x['total_revenue'], reverse=True)

            # Group by branch
            branch_data = {}
            for bill in lab_bills_query:
                if bill.preparedby:
                    staff_alloc = Staffallocation.objects.filter(
                        Staff=bill.preparedby,
                        Status='Active'
                    ).select_related('Branch_Name').first()
                    
                    if staff_alloc and staff_alloc.Branch_Name:
                        branch_name = staff_alloc.Branch_Name.Branch_Name
                        if branch_name not in branch_data:
                            branch_data[branch_name] = {
                                'branch_name': branch_name,
                                'total_bills': 0,
                                'total_revenue': 0
                            }
                        branch_data[branch_name]['total_bills'] += 1
                        branch_data[branch_name]['total_revenue'] += float(bill.total_amount or 0)
            
            branch_lab_breakdown = list(branch_data.values())
            branch_lab_breakdown.sort(key=lambda x: x['total_revenue'], reverse=True)

    # =====================================================
    # 7️⃣ ACTIVE BRANCHES ONLY
    # =====================================================
    branches = (
        Branch.objects.filter(inactive=False)
        if is_superadmin
        else Branch.objects.filter(id=staff_branch_id, inactive=False)
    )

    # =====================================================
    # 8️⃣ DOCTORS BY ACTIVE BRANCH
    # =====================================================
    doctors_by_branch = {}
    if is_superadmin:
        for branch in branches:
            staff_allocations = Staffallocation.objects.filter(
                Branch_Name_id=branch.id,
                Status='Active'
            ).select_related('Staff', 'Designation_Name')

            doctors_by_branch[branch.id] = [
                {
                    "id": alloc.Staff.id,
                    "name": f"{alloc.Staff.Staff_firstname} {alloc.Staff.Staff_lastname}",
                    "designation_id": alloc.Designation_Name_id if alloc.Designation_Name else None
                }
                for alloc in staff_allocations
                if alloc.Designation_Name and alloc.Designation_Name.Designation_Name.lower() in [
                    "cmo", "chief medical officer", "associate doctor", "doctor","associate doctors"
                ]
            ]

    # ---------- CURRENT BRANCH DOCTORS ----------
    if selected_branch_id and selected_branch_id.isdigit():
        current_branch_doctors = doctors_by_branch.get(int(selected_branch_id), [])
    elif not is_superadmin:
        current_branch_doctors = doctors_by_branch.get(staff_branch_id, [])
    else:
        # For superadmin with no branch selected, collect all doctors from all branches
        current_branch_doctors = []
        for branch_doctors in doctors_by_branch.values():
            current_branch_doctors.extend(branch_doctors)

    # =====================================================
    # CONTEXT
    # =====================================================
    context = {
        "start_date": start_date,
        "end_date": end_date,
        "is_superadmin": is_superadmin,
        "is_doctor": is_doctor,
        "branches": branches,
        "doctors_by_branch_json": json.dumps(doctors_by_branch) if is_superadmin else json.dumps({}),
        "current_branch_doctors": current_branch_doctors,
        "selected_branch_id": int(selected_branch_id) if selected_branch_id and selected_branch_id.isdigit() else None,
        "selected_doctor_id": int(selected_doctor_id) if selected_doctor_id and selected_doctor_id.isdigit() else None,
        "doctor_id": doctor_id,
        "doctor_name": doctor_name,
        "appointment_page": appointment_invoices,
        "appointment_totals": appointment_totals,

        # Visit counts (keeping OLD "online" separate from new statuses)
        "total_visits": total_visits,
        "consultation_count": appointment_counts_by_status["consultation"],
        "followup_count": appointment_counts_by_status["followup"],
        "revisit_count": appointment_counts_by_status["revisit"],
        "whatsapp_count": appointment_counts_by_status["whatsapp"],
        "whatsapp_revisit_count": appointment_counts_by_status["whatsapp revisit"],
        "zoho_online_count": appointment_counts_by_status["zoho online consultation"],
        "zoho_revisit_count": appointment_counts_by_status["zoho online revisit"],
        "camp_count": appointment_counts_by_status["camp"],
        "treatment_count": appointment_counts_by_status["treatment"],
        "treatment_revisit_count": appointment_counts_by_status["treatment revisit"],  # NEW: Treatment Revisit count
        "online_count": appointment_counts_by_status["online"],  # OLD "Online" status
        
        # Fees (keeping OLD "online" separate from new statuses)
        "consultation_fee": appointment_fees_by_status["consultation"],
        "followup_fee": appointment_fees_by_status["followup"],
        "revisit_fee": appointment_fees_by_status["revisit"],
        "whatsapp_fee": appointment_fees_by_status["whatsapp"],
        "whatsapp_revisit_fee": appointment_fees_by_status["whatsapp revisit"],
        "zoho_online_fee": appointment_fees_by_status["zoho online consultation"],
        "zoho_revisit_fee": appointment_fees_by_status["zoho online revisit"],
        "camp_fee": appointment_fees_by_status["camp"],
        "treatment_fee": appointment_fees_by_status["treatment"],
        "treatment_revisit_fee": appointment_fees_by_status["treatment revisit"],  # NEW: Treatment Revisit fee
        "online_fee": appointment_fees_by_status["online"], 

        "other_count": appointment_counts_by_status[""],
        "other_fee": appointment_fees_by_status[""],
        
        # Pharmacy data (only for superadmin)
        "pharmacy_totals": pharmacy_totals,
        "pharmacy_page": pharmacy_page,
        
        # Lab data (only for superadmin)
        "lab_bills": lab_bills,
        "enhanced_lab_bills": enhanced_lab_bills,
        "total_lab_amount": total_lab_amount,
        "daily_lab_breakdown": daily_lab_breakdown,
        "doctor_lab_breakdown": doctor_lab_breakdown,
        "branch_lab_breakdown": branch_lab_breakdown,
    }

    return render(request, "doctor_visit_report.html", context)



from dateutil.relativedelta import relativedelta
from django.db.models import Q, Count, F
from datetime import date
import json


def labcountreport(request):
    # ---------- SESSION ----------
    staff_design_id = request.session.get('loginstaffdesign')
    staff_id = request.session.get('loginstaff')

    if not staff_design_id or not staff_id:
        return redirect('staff_login')

    try:
        staff_allocation = Staffallocation.objects.select_related(
            'Branch_Name', 'Staff'
        ).get(id=staff_id)
    except Staffallocation.DoesNotExist:
        return redirect('staff_login')

    staff_branch_id = staff_allocation.Branch_Name_id
    staff_details_id = staff_allocation.Staff_id  # Staffdetails ID

    designation = Designation.objects.filter(id=staff_design_id).first()
    is_superadmin = designation and designation.Designation_Name.lower() == "superadmin"
    is_doctor = designation and designation.Designation_Name.lower() in [
        "cmo",
        "chief medical officer",
        "associate doctor",
        "associate doctors"
    ]

    # ---------- FILTER CHECK ----------
    has_filters = any([
        request.GET.get('start_date'),
        request.GET.get('end_date'),
        request.GET.get('branch'),
        request.GET.get('doctor')
    ])

    # ---------- AUTO LOAD FOR DOCTOR ----------
    auto_load_doctor = is_doctor and not has_filters

    # ---------- DATE RANGE ----------
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')

    if start_date and end_date:
        start_date = date.fromisoformat(start_date)
        end_date = date.fromisoformat(end_date)
    else:
        start_date = date.today()
        end_date = date.today()

    # ---------- FILTER VALUES ----------
    selected_branch_id = request.GET.get('branch')
    selected_doctor_id = request.GET.get('doctor')

    lab_requisitions = casehistorylabtestrequisition.objects.none()
    total_lab_tests = 0

    # =====================================================
    # PROCESS DATA
    # =====================================================
    if has_filters or auto_load_doctor:

        # ---------- DOCTOR LOGIC ----------
        if is_superadmin:
            doctor_id = int(selected_doctor_id) if selected_doctor_id and selected_doctor_id.isdigit() else None
        elif is_doctor:
            doctor_id = staff_details_id
            selected_doctor_id = str(staff_details_id)
        else:
            doctor_id = int(selected_doctor_id) if selected_doctor_id and selected_doctor_id.isdigit() else None

        # ---------- BRANCH LOGIC ----------
        if is_superadmin:
            branch_id = int(selected_branch_id) if selected_branch_id and selected_branch_id.isdigit() else None
        else:
            branch_id = staff_branch_id
            selected_branch_id = str(staff_branch_id)

        # ---------- QUERY ----------
        lab_requisitions = casehistorylabtestrequisition.objects.filter(
            created_at__range=(start_date, end_date)
        ).select_related(
            'patient__Branch_Name',
            'case_history__patient__Branch_Name',
            'labtestchild__group',
            'handledbystaff'
        )

        if doctor_id:
            lab_requisitions = lab_requisitions.filter(handledbystaff_id=doctor_id)

        if is_superadmin:
            if branch_id and not doctor_id:
                lab_requisitions = lab_requisitions.filter(
                    Q(patient__Branch_Name_id=branch_id) |
                    Q(case_history__patient__Branch_Name_id=branch_id)
                )
        else:
            if not doctor_id:
                lab_requisitions = lab_requisitions.filter(
                    Q(patient__Branch_Name_id=branch_id) |
                    Q(case_history__patient__Branch_Name_id=branch_id)
                )

        total_lab_tests = lab_requisitions.count()

        # ---------- DOCTOR NAME ----------
        if doctor_id:
            try:
                doc = Staffdetails.objects.get(id=doctor_id)
                doctor_name = f"{doc.Staff_firstname} {doc.Staff_lastname}"
            except Staffdetails.DoesNotExist:
                doctor_name = "Unknown Doctor"
        else:
            doctor_name = "All Doctors"

    else:
        doctor_name = (
            f"{staff_allocation.Staff.Staff_firstname} {staff_allocation.Staff.Staff_lastname}"
            if is_doctor else "Select filters to view report"
        )
        doctor_id = None
        branch_id = None

    # =====================================================
    # BRANCHES & DOCTORS
    # =====================================================
    if is_superadmin:
        branches = Branch.objects.filter(inactive=False).order_by('Branch_Name')
    else:
        branches = Branch.objects.filter(id=staff_branch_id, inactive=False)

    doctors_by_branch = {}

    staff_allocations = Staffallocation.objects.filter(
        Status='Active'
    ).select_related('Staff', 'Designation_Name', 'Branch_Name')

    for alloc in staff_allocations:
        desig = alloc.Designation_Name.Designation_Name.lower() if alloc.Designation_Name else ""
        if "cmo" in desig or "chief medical officer" in desig or "associate doctor" in desig:
            doctors_by_branch.setdefault(alloc.Branch_Name_id, []).append({
                'id': alloc.Staff.id,
                'name': f"{alloc.Staff.Staff_firstname} {alloc.Staff.Staff_lastname}",
                'designation_id': alloc.Designation_Name_id
            })

    current_branch_doctors = (
        doctors_by_branch.get(int(selected_branch_id), [])
        if selected_branch_id and selected_branch_id.isdigit()
        else doctors_by_branch.get(staff_branch_id, [])
    )

    # =====================================================
    # ANALYTICS
    # =====================================================
    group_details = {}
    top_tests = []
    doctor_breakdown = []
    branch_breakdown = []

    if (has_filters or auto_load_doctor) and total_lab_tests > 0:

        # ---------- GROUP DETAILS ----------
        lab_groups = labtestmaster.objects.filter(status=True)
        for group in lab_groups:
            qs = lab_requisitions.filter(labtestchild__group=group)
            if qs.exists():
                group_details[group.groupname] = {
                    'total': qs.count(),
                    'tests': qs.values_list(
                        'labtestchild__testname', flat=True
                    ).annotate(c=Count('id'))
                }

        # ---------- BRANCH BREAKDOWN (YOUR SQL EQUIVALENT) ----------
        branch_breakdown = (
            lab_requisitions
            .filter(patient__Branch_Name__isnull=False)
            .values(
                branch_name=F('patient__Branch_Name__Branch_Name')
            )
            .annotate(total_test_count=Count('id'))
            .order_by('-total_test_count')
        )

    # =====================================================
    # CONTEXT
    # =====================================================
    context = {
        "start_date": start_date,
        "end_date": end_date,
        "has_filters": has_filters or auto_load_doctor,
        "is_superadmin": is_superadmin,
        "is_doctor": is_doctor,
        "branches": branches,
        "doctors_by_branch_json": json.dumps(doctors_by_branch) if is_superadmin else json.dumps({}),
        "current_branch_doctors": current_branch_doctors,
        "selected_branch_id": selected_branch_id,
        "selected_doctor_id": selected_doctor_id,
        "doctor_id": doctor_id,
        "doctor_name": doctor_name,
        "staff": staff_allocation,
        "staff_branch_id": staff_branch_id,
        "staff_details_id": staff_details_id if is_doctor else None,
        "total_lab_tests": total_lab_tests,
        "group_details": group_details,
        "top_tests": top_tests,
        "doctor_breakdown": doctor_breakdown,
        "branch_breakdown": branch_breakdown,
        "lab_requisitions": lab_requisitions,
    }

    return render(request, "labcountreport.html", context)



