@require_GET
def get_appointment_fee_ajax(request):
    """AJAX endpoint to fetch appointment fee based on branch, doctor, and status"""
    branch_id = request.GET.get('branch_id')
    doctor_id = request.GET.get('doctor_id')
    visit_type = request.GET.get('visit_type')
    
    if not all([branch_id, doctor_id, visit_type]):
        return JsonResponse({'error': 'Missing required parameters'}, status=400)
    
    try:
        fee = AppointmentFee.objects.filter(
            branch_id=branch_id,
            doctor_id=doctor_id,
            visit_type=visit_type,
            is_active=True
        ).first()
        
        if fee:
            return JsonResponse({
                'success': True,
                'fee_amount': float(fee.fee_amount),
                'fee_id': fee.id
            })
        else:
            # Return default fee or 0 if not found
            return JsonResponse({
                'success': True,
                'fee_amount': 0.00,
                'fee_id': None,
                'message': 'No specific fee found, using default'
            })
            
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)


