# ============ Proforma Invoice Functions ============

def generate_so_number(branch):
    """
    Generate Sales Order (Pro-forma) number with format: SOHO/00001/2627
    Based on location-wise document codes
    """
    # Branch-specific configurations based on the document numbering system
    branch_configs = {
        "JOHNMARIANS WELLNESS CLINIC": {"code": "SOHO", "digits": 5},
        "ALAPPUZHA": {"code": "SOAL1", "digits": 5},
        "KAKKANAD": {"code": "SOKD1", "digits": 5},
        "KANNUR": {"code": "SOKR1", "digits": 5},
        "KANNUR - 2": {"code": "SOKR2", "digits": 5},
        "KOTTAYAM": {"code": "SOKM1", "digits": 5},
        "PERUMBAVOOR": {"code": "SOPR1", "digits": 5},
        "THRISSUR": {"code": "SOTR1", "digits": 5},
        "WAYANAD": {"code": "SOWD1", "digits": 5},
        "JOHNMARIANS HEALTH CARE PVT LTD": {"code": "SOHC", "digits": 5},
        "PALA": {"code": "SOJH", "digits": 5},
        "SMILEE KANNUR": {"code": "SOKR2", "digits": 5},  # Kannur - 2
    }
    
    branch_name = branch.Branch_Name.upper()
    config = branch_configs.get(branch_name, {"code": "SO", "digits": 5})
    branch_code = config["code"]
    digits = config["digits"]
    current_year = "2627"  # FY 2026-27
    
    # Get last SO for this branch in current financial year
    last_so = ProformaInvoice.objects.filter(
        branch=branch,
        invoice_date__year=date.today().year
    ).order_by('-id').first()
    
    if last_so and last_so.voucher_no:
        try:
            # Format: SOHO/00001/2627
            parts = last_so.voucher_no.split('/')
            if len(parts) >= 2:
                last_num_str = parts[1]
                last_num = int(last_num_str) if last_num_str.isdigit() else 0
                new_num = last_num + 1
            else:
                new_num = 1
        except (ValueError, IndexError):
            new_num = 1
    else:
        new_num = 1
    
    return f"{branch_code}/{new_num:0{digits}d}/{current_year}"


