from django.db.models import F
from decimal import Decimal
import json

def proforma_invoice_create(request):
    """Create new proforma invoice with stock reduction from SOURCE branch"""
    if request.method == 'POST':
        try:
            with transaction.atomic():
                # Get branch details (this is the SOURCE branch where stock exists)
                branch_id = request.POST.get('branch')
                source_branch = Branch.objects.get(id=branch_id)
                
                # Get PO ID to know destination branch
                po_id = request.POST.get('po_id', '')
                purchase_order = None
                destination_branch = None
                
                if po_id:
                    purchase_order = PurchaseOrder.objects.get(id=po_id)
                    destination_branch = purchase_order.destination_branch
                
                # Generate SO number
                voucher_no = generate_so_number(source_branch)
                
                # Get form data
                invoice_date = request.POST.get('invoice_date')
                buyer_name = request.POST.get('buyer_name')
                buyer_address = request.POST.get('buyer_address')
                buyer_gstin = request.POST.get('buyer_gstin', '')
                items_count = int(request.POST.get('items_count', 0))
                
                # Validate required fields
                if not all([invoice_date, branch_id, buyer_name, buyer_address]):
                    messages.error(request, 'All required fields must be filled')
                    return redirect('proforma_invoice_create')
                
                if items_count == 0:
                    messages.error(request, 'Please add at least one item')
                    return redirect('proforma_invoice_create')
                
                # Create proforma invoice
                proforma = ProformaInvoice.objects.create(
                    purchase_order=purchase_order,
                    voucher_no=voucher_no,
                    invoice_date=invoice_date,
                    buyer_name=buyer_name,
                    buyer_address=buyer_address,
                    buyer_gstin=buyer_gstin,
                    branch=source_branch,
                    created_by=request.session.get('loginstaff'),
                )
                
                # Process items
                subtotal = Decimal('0.00')
                gst_total = Decimal('0.00')
                
                # Track stock errors and successful reductions
                stock_errors = []
                stock_updates = []
                
                for i in range(1, items_count + 1):
                    description = request.POST.get(f'items[{i}][description]', '')
                    if not description:
                        continue
                    
                    quantity = Decimal(request.POST.get(f'items[{i}][qty]', '0'))
                    unit = request.POST.get(f'items[{i}][unit]', 'BTL')
                    rate = Decimal(request.POST.get(f'items[{i}][rate]', '0'))
                    gst_percent = Decimal(request.POST.get(f'items[{i}][gst]', '18'))
                    hsn_code = request.POST.get(f'items[{i}][hsn]', '')
                    batch_no = request.POST.get(f'items[{i}][batch_no]', '')
                    stock_id = request.POST.get(f'items[{i}][stock_id]', '')
                    expiry_date = request.POST.get(f'items[{i}][expiry_date]', '')
                    manufacturer_date = request.POST.get(f'items[{i}][manufacturer_date]', '')
                    company_name = request.POST.get(f'items[{i}][company_name]', '')
                    company_id = request.POST.get(f'items[{i}][company_id]', '')
                    supplier_id = request.POST.get(f'items[{i}][supplier_id]', '')
                    medicine_master_id = request.POST.get(f'items[{i}][medicine_master_id]', '')
                    unit_id = request.POST.get(f'items[{i}][unit_id]', '')
                    
                    if quantity <= 0 or rate <= 0:
                        continue
                    
                    # Calculate amounts
                    base_amount = quantity * rate
                    gst_amount = base_amount * (gst_percent / Decimal('100'))
                    total_amount = base_amount + gst_amount
                    
                    # Create ProformaItem
                    ProformaItem.objects.create(
                        proforma=proforma,
                        sl_no=i,
                        description=description,
                        batch_info=batch_no,
                        quantity=quantity,
                        unit=unit,
                        rate=rate,
                        gst_percent=gst_percent,
                        hsn_code=hsn_code,
                        amount=total_amount
                    )
                    
                    subtotal += base_amount
                    gst_total += gst_amount
                    
                    # ============ REDUCE STOCK FROM SOURCE BRANCH ============
                    if batch_no and branch_id:
                        try:
                            # Build filter for stock lookup
                            stock_filter = {
                                'Batch_no': batch_no,
                                'stockbranch_id': branch_id,
                                'itemnm__itemnm__iexact': description,
                                'deleted': False
                            }
                            
                            # Add optional filters if provided
                            if stock_id:
                                stock_filter['id'] = stock_id
                            if company_id:
                                stock_filter['Comapany_name_id'] = company_id
                            if supplier_id:
                                stock_filter['suppliernm_id'] = supplier_id
                            if unit_id:
                                stock_filter['unt_id'] = unit_id
                            if expiry_date:
                                stock_filter['Expiry_date'] = expiry_date
                            if manufacturer_date:
                                stock_filter['Manufacturer_date'] = manufacturer_date
                            
                            # Find stock item
                            stock_item = None
                            
                            if stock_id:
                                try:
                                    stock_item = Physicalstockdetails.objects.get(
                                        id=stock_id,
                                        deleted=False,
                                        stockbranch_id=branch_id
                                    )
                                except Physicalstockdetails.DoesNotExist:
                                    stock_item = None
                            
                            if not stock_item:
                                stock_item = Physicalstockdetails.objects.filter(
                                    Batch_no=batch_no,
                                    stockbranch_id=branch_id,
                                    itemnm__itemnm__iexact=description,
                                    deleted=False
                                ).first()
                            
                            if not stock_item:
                                stock_item = Physicalstockdetails.objects.filter(**stock_filter).first()
                            
                            if stock_item:
                                qty_to_reduce = int(quantity)
                                
                                if stock_item.qty >= qty_to_reduce:
                                    original_qty = stock_item.qty
                                    
                                    # REDUCE from source branch
                                    stock_item.qty = F('qty') - qty_to_reduce
                                    stock_item.save()
                                    stock_item.refresh_from_db()
                                    
                                    stock_updates.append({
                                        'item': description,
                                        'batch': batch_no,
                                        'reduced_qty': qty_to_reduce,
                                        'original_qty': original_qty,
                                        'new_qty': stock_item.qty,
                                        'stock_id': stock_item.id,
                                        'source_branch': source_branch.Branch_Name
                                    })
                                    
                                    # Log stock reduction
                                    StockAuditLog.objects.create(
                                        stock=stock_item,
                                        action="SALE",
                                        staff_id=request.session.get('loginstaff'),
                                        branch_id=branch_id,
                                        store=stock_item.storenm,
                                        item=stock_item.itemnm,
                                        qty=qty_to_reduce,
                                        action_date=timezone.now().date(),
                                        action_time=timezone.now().time(),
                                        remarks=f"Stock reduced for Proforma Invoice {voucher_no} | Batch: {batch_no} | Qty: {qty_to_reduce} | Destination: {destination_branch.Branch_Name if destination_branch else 'N/A'}"
                                    )
                                else:
                                    stock_errors.append(
                                        f"Item '{description}' (Batch: {batch_no}): "
                                        f"Available stock: {stock_item.qty}, Requested: {qty_to_reduce}"
                                    )
                            else:
                                stock_errors.append(
                                    f"Item '{description}' with batch '{batch_no}' not found in stock for source branch {source_branch.Branch_Name}"
                                )
                                
                        except Exception as e:
                            print(f"Error updating stock for {description}: {e}")
                            stock_errors.append(f"Error processing stock for '{description}': {str(e)}")
                
                # Check if there were stock errors
                if stock_errors:
                    proforma.delete()
                    for error in stock_errors:
                        messages.error(request, error)
                    return redirect('proforma_invoice_create')
                
                # Log successful stock updates
                if stock_updates:
                    print(f"\n=== STOCK REDUCTION for Proforma Invoice {voucher_no} ===")
                    print(f"Source Branch: {source_branch.Branch_Name}")
                    print(f"Destination Branch: {destination_branch.Branch_Name if destination_branch else 'Customer Sale'}")
                    for update in stock_updates:
                        print(f"  - {update['item']}: -{update['reduced_qty']} units from batch {update['batch']}")
                    print("=" * 50)
                
                # Update totals
                grand_total = subtotal + gst_total
                proforma.subtotal = subtotal
                proforma.gst_total = gst_total
                proforma.grand_total = grand_total
                proforma.amount_in_words = number_to_words(grand_total) + ' Only'
                proforma.save()
                
                messages.success(request, f'Proforma Invoice {voucher_no} created successfully! Stock reduced from {source_branch.Branch_Name} branch.')
                
                # If this is a stock transfer (has destination branch), redirect to B2B invoice creation
                if destination_branch:
                    messages.info(request, f'Please create B2B Invoice to complete stock transfer to {destination_branch.Branch_Name}')
                    return redirect('b2b_invoice_create', proforma_id=proforma.id)
                
                return redirect('proforma_invoice_list')
                
        except Exception as e:
            messages.error(request, f'Error creating proforma invoice: {str(e)}')
            return redirect('proforma_invoice')
    
    # GET request - display form (same as before)
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    objhospt = Hospitaldetails.objects.all()
    
    st_id = request.session.get('loginstaff')
    staff_alloc = Staffallocation.objects.filter(id=st_id).first()
    
    if staff_alloc:
        stbtachid = staff_alloc.Branch_Name_id
        brname = Branch.objects.filter(id=stbtachid)
    else:
        brname = Branch.objects.none()
    
    branches = Branch.objects.filter(inactive=False)
    purchase_orders = PurchaseOrder.objects.filter(created_by=st_id).order_by('-po_date')
    
    context = {
        'objhospt': objhospt,
        'brname': brname,
        'branches': branches,
        'purchase_orders': purchase_orders,
        'stdesign': stdesign,
    }
    return render(request, 'proforma_invoice_create.html', context)

    
