def generate_po_number(branch):
    """
    Generate Purchase Order number with format: POHO/00001/2627
    Based on location-wise document codes
    """
    # Branch-specific configurations based on the document numbering system
    branch_configs = {
        "JOHNMARIANS WELLNESS CLINIC": {"code": "POHO", "digits": 5},
        "ALAPPUZHA": {"code": "POAL1", "digits": 5},
        "KAKKANAD": {"code": "POKD1", "digits": 5},
        "KANNUR": {"code": "POKR1", "digits": 5},
        "KOTTAYAM": {"code": "POKM1", "digits": 5},
        "PERUMBAVOOR": {"code": "POPR1", "digits": 5},
        "THRISSUR": {"code": "POTR1", "digits": 5},
        "WAYANAD": {"code": "POWD1", "digits": 5},
        "JOHNMARIANS HEALTH CARE PVT LTD": {"code": "POHC", "digits": 5},
        "PALA": {"code": "POJH", "digits": 5},
        "SMILEE KANNUR": {"code": "POKR2", "digits": 5},  # Kannur - 2
    }
    
    branch_name = branch.Branch_Name.upper()
    config = branch_configs.get(branch_name, {"code": "PO", "digits": 5})
    branch_code = config["code"]
    digits = config["digits"]
    current_year = "2627"  # FY 2026-27
    
    # Get last PO for this branch in current financial year
    last_po = PurchaseOrder.objects.filter(
        branch=branch,
        po_date__year=date.today().year
    ).order_by('-id').first()
    
    if last_po and last_po.po_number:
        try:
            # Format: POHO/00001/2627
            parts = last_po.po_number.split('/')
            if len(parts) >= 2:
                last_num_str = parts[1]
                last_num = int(last_num_str) if last_num_str.isdigit() else 0
                new_num = last_num + 1
            else:
                new_num = 1
        except (ValueError, IndexError):
            new_num = 1
    else:
        new_num = 1
    
    return f"{branch_code}/{new_num:0{digits}d}/{current_year}"


def purchase_order_create(request):
    """Create new purchase order"""
    if request.method == 'POST':
        try:
            with transaction.atomic():
                # Get branch details
                branch_id = request.POST.get('branch')
                branch = Branch.objects.get(id=branch_id)
                
                # Generate PO number instead of using user input
                po_number = generate_po_number(branch)
                
                # Get form data
                po_date = request.POST.get('po_date')
                supplier_name = request.POST.get('supplier_name')
                supplier_address = request.POST.get('supplier_address')
                delivery_date = request.POST.get('delivery_date')
                payment_terms = request.POST.get('payment_terms')
                transport = request.POST.get('transport')
                gst_applicable = request.POST.get('gst_applicable') == 'yes'
                prepared_by = request.POST.get('prepared_by', '')
                checked_by = request.POST.get('checked_by', '')
                approved_by = request.POST.get('approved_by', '')
                approver_designation = request.POST.get('approver_designation', '')
                items_count = int(request.POST.get('items_count', 0))
                
                # Validate required fields
                if not all([po_date, branch_id, supplier_name, supplier_address, payment_terms]):
                    messages.error(request, 'All required fields must be filled')
                    return redirect('purchase_order_create')
                
                if items_count == 0:
                    messages.error(request, 'Please add at least one item')
                    return redirect('purchase_order_create')
                print("request.session.get('branchid')",request.session.get('branchid'))
                # Create purchase order with generated number
                po = PurchaseOrder.objects.create(
                    po_number=po_number,
                    po_date=po_date,
                    branch=branch,
                    supplier_name=supplier_name,
                    supplier_address=supplier_address,
                    expected_delivery_date=delivery_date if delivery_date else None,
                    payment_terms=payment_terms,
                    transport_mode=transport,
                    gst_applicable=gst_applicable,
                    prepared_by=prepared_by,
                    checked_by=checked_by,
                    approved_by=approved_by,
                    approver_designation=approver_designation,
                    created_by=request.session.get('loginstaff'),
                    destination_branch_id=request.session.get('branchid')
                )
                
                # Process items
                subtotal = Decimal('0.00')
                
                for i in range(1, items_count + 1):
                    item_name = request.POST.get(f'items[{i}][description]', '')
                    if not item_name:
                        continue
                    
                    quantity = Decimal(request.POST.get(f'items[{i}][qty]', '0'))
                    unit = request.POST.get(f'items[{i}][unit]', 'BTL')
                    unit_rate = Decimal(request.POST.get(f'items[{i}][rate]', '0'))
                    total_amount = quantity * unit_rate
                    
                    if quantity <= 0 or unit_rate <= 0:
                        continue
                    
                    POItem.objects.create(
                        purchase_order=po,
                        sl_no=i,
                        item_name=item_name,
                        quantity=quantity,
                        unit=unit,
                        unit_rate=unit_rate,
                        total_amount=total_amount
                    )
                    
                    subtotal += total_amount
                
                # Update totals
                po.subtotal = subtotal
                po.grand_total = subtotal
                po.amount_in_words = number_to_words(subtotal) + ' Only'
                po.save()
                
                messages.success(request, f'Purchase Order {po_number} created successfully!')
                
                # Redirect to purchase order list
                return redirect('purchase_order_list')
                
        except Exception as e:
            messages.error(request, f'Error creating purchase order: {str(e)}')
            return redirect('purchase_order')
    
    # GET request - display form
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    objhospt = Hospitaldetails.objects.all()
    
    st_id = request.session.get('loginstaff')
    staff_alloc = Staffallocation.objects.filter(id=st_id).first()
    
    if staff_alloc:
        stbtachid = staff_alloc.Branch_Name_id
        brname = Branch.objects.filter(id=stbtachid)
    else:
        brname = Branch.objects.none()
    
    # Get branches for dropdown
    branches = Branch.objects.filter(inactive=False)
    
    context = {
        'objhospt': objhospt,
        'brname': brname,
        'branches': branches,
        'stdesign': stdesign,
    }
    return render(request, 'purchase_order_create.html', context)


