def purchase_order_edit(request, pk):
    """Edit purchase order"""
    po = get_object_or_404(PurchaseOrder, id=pk)
    
    if request.method == 'POST':
        try:
            with transaction.atomic():
                # Get branch first
                branch_id = request.POST.get('branch')
                if branch_id:
                    try:
                        branch = Branch.objects.get(id=branch_id, inactive=False)
                        po.branch = branch
                    except Branch.DoesNotExist:
                        messages.error(request, 'Selected branch does not exist')
                        return redirect('purchase_order_edit', pk=pk)
                else:
                    messages.error(request, 'Branch is required')
                    return redirect('purchase_order_edit', pk=pk)
                
                # Update header fields
                po.po_number = request.POST.get('po_number', po.po_number)
                po.po_date = request.POST.get('po_date') or po.po_date
                po.supplier_name = request.POST.get('supplier_name', '').strip()
                po.supplier_address = request.POST.get('supplier_address', '').strip()
                po.proforma_reference = request.POST.get('proforma_ref', '').strip() or None
                po.expected_delivery_date = request.POST.get('delivery_date') or None
                po.payment_terms = request.POST.get('payment_terms', '')
                po.transport_mode = request.POST.get('transport', '').strip()
                po.gst_applicable = request.POST.get('gst_applicable') == 'yes'
                po.prepared_by = request.POST.get('prepared_by', '').strip()
                po.checked_by = request.POST.get('checked_by', '').strip()
                po.approved_by = request.POST.get('approved_by', '').strip()
                po.approver_designation = request.POST.get('approver_designation', '').strip()
                
                # Validate required fields
                if not po.supplier_name:
                    messages.error(request, 'Supplier name is required')
                    return redirect('purchase_order_edit', pk=pk)
                
                if not po.supplier_address:
                    messages.error(request, 'Supplier address is required')
                    return redirect('purchase_order_edit', pk=pk)
                
                if not po.payment_terms:
                    messages.error(request, 'Payment terms are required')
                    return redirect('purchase_order_edit', pk=pk)
                
                items_count = int(request.POST.get('items_count', 0))
                
                if items_count == 0:
                    messages.error(request, 'Please add at least one item')
                    return redirect('purchase_order_edit', pk=pk)
                
                # Delete existing items
                po.items.all().delete()
                
                # Process new items
                subtotal = Decimal('0.00')
                created_items = []
                
                for i in range(1, items_count + 1):
                    item_name = request.POST.get(f'items[{i}][description]', '').strip()
                    if not item_name:
                        continue
                    
                    try:
                        quantity = Decimal(request.POST.get(f'items[{i}][qty]', '0'))
                        unit_rate = Decimal(request.POST.get(f'items[{i}][rate]', '0'))
                    except (ValueError, TypeError, Decimal.InvalidOperation):
                        continue
                    
                    unit = request.POST.get(f'items[{i}][unit]', 'BTL').strip()
                    
                    if quantity <= 0 or unit_rate < 0:
                        continue
                    
                    total_amount = quantity * unit_rate
                    
                    # Create PO item
                    po_item = POItem.objects.create(
                        purchase_order=po,
                        sl_no=i,
                        item_name=item_name,
                        quantity=quantity,
                        unit=unit,
                        unit_rate=unit_rate,
                        total_amount=total_amount
                    )
                    
                    created_items.append(po_item)
                    subtotal += total_amount
                
                if len(created_items) == 0:
                    messages.error(request, 'No valid items were added')
                    return redirect('purchase_order_edit', pk=pk)
                
                # Update totals
                po.subtotal = subtotal
                po.grand_total = subtotal
                po.amount_in_words = number_to_words(subtotal) + ' Only'
                po.save()
                
                messages.success(request, f'Purchase Order updated successfully! {len(created_items)} items processed.')
                return redirect('purchase_order_list')
                
        except Exception as e:
            import traceback
            traceback.print_exc()
            messages.error(request, f'Error updating purchase order: {str(e)}')
            return redirect('purchase_order_edit', pk=pk)
    
    # GET request
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    items = po.items.all().order_by('sl_no')
    objhospt = Hospitaldetails.objects.all()
    
    st_id = request.session.get('loginstaff')
    staff_alloc = Staffallocation.objects.filter(id=st_id).first()
    
    if staff_alloc:
        stbtachid = staff_alloc.Branch_Name_id
        brname = Branch.objects.filter(id=stbtachid)
    else:
        brname = Branch.objects.none()
    
    # Get branches for dropdown
    branches = Branch.objects.filter(inactive=False)
    
    context = {
        'po': po,
        'items': items,
        'objhospt': objhospt,
        'brname': brname,
        'branches': branches,
        'stdesign': stdesign,
    }
    return render(request, 'purchase_order_edit.html', context)


def purchase_order_delete(request, pk):
    """Delete purchase order"""
    if request.method == 'POST':
        po = get_object_or_404(PurchaseOrder, id=pk)
        po_number = po.po_number
        po.delete()
        messages.success(request, f'Purchase Order {po_number} deleted successfully!')
        return JsonResponse({'success': True})
    
    return JsonResponse({'success': False, 'error': 'Invalid request method'})

