@require_GET
def search_medicines_for_proforma(request):
    """Search medicines for proforma invoice with rate and batch info"""
    term = request.GET.get('term', '').strip()
    branch_id = request.GET.get('branch_id', '')
    
    if not term:
        return JsonResponse([], safe=False)
    
    # Get medicines matching search term
    medicines = medicinemaster.objects.filter(
        itemnm__icontains=term
    ).order_by('itemnm')[:20]
    
    results = []
    for med in medicines:
        # Get medicine rate for specific branch
        rate = None
        try:
            medicine_rate = medicinemasterrate.objects.filter(
                itemid__itemnm=med.itemnm,  # Link to medicinemaster_new
                branchid_id=branch_id
            ).first()
            if medicine_rate and medicine_rate.mrp:
                rate = float(medicine_rate.mrp)
        except Exception as e:
            print(f"Error fetching rate: {e}")
        
        # Get available batches from stock
        batches = []
        try:
            stock_items = Physicalstockdetails.objects.filter(
                itemnm=med,
                stockbranch_id=branch_id,
                deleted=False,
                qty__gt=0  # Only show batches with stock
            ).order_by('Expiry_date')[:5]  # Get 5 most recent batches
            
            for stock in stock_items:
                batches.append({
                    'batch_no': stock.Batch_no,
                    'expiry_date': stock.Expiry_date.strftime('%d-%m-%Y') if stock.Expiry_date else '',
                    'rate': float(stock.Rate) if stock.Rate else rate,
                    'qty': stock.qty
                })
        except Exception as e:
            print(f"Error fetching batches: {e}")
        
        # If no stock available, create a default entry
        if not batches:
            batches.append({
                'batch_no': '',
                'expiry_date': '',
                'rate': rate if rate else 0,
                'qty': 0
            })
        
        results.append({
            'id': med.id,
            'item_name': med.itemnm,
            'hsncode': med.hsncode or '',
            'tax': float(med.taxpercentage.taxrate) if med.taxpercentage else 0,
            'unit': med.bsuntid.unit if med.bsuntid else 'BTL',
            'rate': rate if rate else 0,
            'batches': batches
        })
    
    return JsonResponse(results, safe=False)
    
@require_GET
def get_proforma_items(request):
    """Get items from proforma invoice for purchase order"""
    proforma_ref = request.GET.get('proforma_ref', '')
    
    if not proforma_ref:
        return JsonResponse({'items': []})
    
    try:
        proforma = ProformaInvoice.objects.filter(voucher_no=proforma_ref).first()
        if not proforma:
            return JsonResponse({'items': []})
        
        items = proforma.items.all().order_by('sl_no')
        
        items_data = []
        for item in items:
            items_data.append({
                'description': item.description,
                'quantity': float(item.quantity),
                'unit': item.unit,
                'unit_rate': float(item.rate),
                'total_amount': float(item.amount)
            })
        
        return JsonResponse({
            'items': items_data,
            'supplier_name': proforma.buyer_name,
            'supplier_address': proforma.buyer_address
        })
        
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)


@require_GET
def get_po_items_with_stock(request):
    """Get items from purchase order with stock availability and batch information"""
    po_id = request.GET.get('po_id', '')
    branch_id = request.GET.get('branch_id', '')
    include_batches = request.GET.get('include_batches', 'true') == 'true'
    
    if not po_id:
        return JsonResponse({'items': []})
    
    try:
        po = PurchaseOrder.objects.get(id=po_id)
        items = po.items.all().order_by('sl_no')
        
        items_data = []
        for item in items:
            # 🔴 FIX: Get HSN code from medicinemaster model
            hsn_code = ''
            gst_percent = 18
            medicine_master_id = None
            
            # Try to find the medicine in medicinemaster or medicinemaster_new
            try:
                medicine = medicinemaster.objects.filter(itemnm__iexact=item.item_name).first()
                if medicine:
                    hsn_code = medicine.hsncode or ''
                    if medicine.taxpercentage:
                        gst_percent = float(medicine.taxpercentage.taxrate)
                    medicine_master_id = medicine.id
            except Exception as e:
                print(f"Error fetching medicine details: {e}")
            
            # Get stock items with batch details for this medicine at the branch
            stock_items = []
            stock_qty = 0
            
            if branch_id and include_batches:
                # Fetch all physical stock details for this item at the branch
                stock_items = Physicalstockdetails.objects.filter(
                    itemnm__itemnm__iexact=item.item_name,
                    stockbranch_id=branch_id,
                    deleted=False,
                    qty__gt=0
                ).select_related('Comapany_name', 'suppliernm', 'unt', 'itemnm')
                
                # Calculate total stock quantity
                stock_qty = sum(stock.qty for stock in stock_items)
                
                # Prepare batch information for each stock item
                batches = []
                for stock in stock_items:
                    # Get rates for this medicine
                    rates = []
                    try:
                        med_rates = medicinemasterrate.objects.filter(
                            itemid=stock.itemnm.id,
                            branchid=branch_id
                        )
                        rates = [
                            {
                                "rate_id": r.id,
                                "mrp": float(r.mrp)
                            } for r in med_rates
                        ]
                    except:
                        rates = [{"rate_id": None, "mrp": float(stock.Rate) if stock.Rate else 0}]
                    
                    batches.append({
                        "id": stock.id,
                        "stock_id": stock.id,
                        "Batch_no": stock.Batch_no or "N/A",
                        "Expiry_date": stock.Expiry_date.strftime("%Y-%m-%d") if stock.Expiry_date else "N/A",
                        "Manufacturer_date": stock.Manufacturer_date.strftime("%Y-%m-%d") if stock.Manufacturer_date else "N/A",
                        "qty": stock.qty,
                        "rate": float(stock.Rate) if stock.Rate else item.unit_rate,
                        "compid": stock.Comapany_name.id if stock.Comapany_name else None,
                        "compname": stock.Comapany_name.Comapany_name if stock.Comapany_name else "N/A",
                        "suppid": stock.suppliernm.id if stock.suppliernm else None,
                        "supplier_name": stock.suppliernm.shopname if stock.suppliernm else "N/A",
                        "unit": stock.unt.unitname if stock.unt else item.unit,
                        "unit_id": stock.unt.id if stock.unt else None,
                        "rates": rates
                    })
                
                # Determine stock status
                if stock_qty >= item.quantity:
                    stock_status = 'available'
                elif stock_qty > 0:
                    stock_status = 'low'
                else:
                    stock_status = 'out'
            else:
                # Simple stock check without batch details
                stock_status = 'unknown'
                if branch_id:
                    stock_items_qty = Physicalstockdetails.objects.filter(
                        itemnm__itemnm__iexact=item.item_name,
                        stockbranch_id=branch_id,
                        deleted=False,
                        qty__gt=0
                    ).aggregate(total=models.Sum('qty'))['total'] or 0
                    
                    if stock_items_qty >= item.quantity:
                        stock_status = 'available'
                    elif stock_items_qty > 0:
                        stock_status = 'low'
                    else:
                        stock_status = 'out'
                    stock_qty = stock_items_qty
                batches = []
            
            items_data.append({
                'id': item.id,
                'medicine_master_id': medicine_master_id,
                'item_name': item.item_name,
                'quantity': float(item.quantity),
                'unit': item.unit,
                'unit_rate': float(item.unit_rate),
                'total_amount': float(item.total_amount),
                'stock_qty': stock_qty,
                'stock_status': stock_status,
                'hsncode': hsn_code,  # 🔴 FIXED: Now gets HSN from medicine master
                'gst_percent': gst_percent,
                'batches': batches
            })
        
        return JsonResponse({
            'items': items_data,
            'supplier_name': po.supplier_name,
            'supplier_address': po.supplier_address,
            'po_number': po.po_number
        })
        
    except PurchaseOrder.DoesNotExist:
        return JsonResponse({'error': 'Purchase order not found'}, status=404)
    except Exception as e:
        import traceback
        traceback.print_exc()
        return JsonResponse({'error': str(e)}, status=500)



@require_GET
def check_stock_availability(request):
    """Check stock availability for a specific medicine"""
    medicine_name = request.GET.get('medicine', '')
    branch_id = request.GET.get('branch_id', '')
    required_qty = int(request.GET.get('qty', 1))
    
    if not medicine_name or not branch_id:
        return JsonResponse({'available': False, 'stock_qty': 0, 'status': 'error'})
    
    try:
        stock_items = Physicalstockdetails.objects.filter(
            itemnm__itemnm=medicine_name,
            stockbranch_id=branch_id,
            deleted=False,
            qty__gt=0
        )
        
        total_stock = sum(stock.qty for stock in stock_items)
        
        if total_stock >= required_qty:
            status = 'available'
        elif total_stock > 0:
            status = 'low'
        else:
            status = 'out'
        
        return JsonResponse({
            'available': total_stock >= required_qty,
            'stock_qty': total_stock,
            'status': status
        })
        
    except Exception as e:
        return JsonResponse({'available': False, 'stock_qty': 0, 'status': 'error', 'error': str(e)})

# ==================== HELPER FUNCTIONS ====================

def number_to_words(num):
    """Convert number to words (Indian Rupees format)"""
    if num == 0:
        return 'Zero'
    
    num = int(num)  # Convert to integer for words
    
    ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine']
    teens = ['Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']
    tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']
    
    def convert_hundreds(n):
        str_val = ''
        if n >= 100:
            str_val += ones[n // 100] + ' Hundred '
            n %= 100
        if n >= 20:
            str_val += tens[n // 10] + ' '
            n %= 10
        elif n >= 10:
            str_val += teens[n - 10] + ' '
            n = 0
        if n > 0:
            str_val += ones[n] + ' '
        return str_val.strip()
    
    words = ''
    crore = num // 10000000
    num %= 10000000
    lakh = num // 100000
    num %= 100000
    thousand = num // 1000
    num %= 1000
    
    if crore > 0:
        words += convert_hundreds(crore) + ' Crore '
    if lakh > 0:
        words += convert_hundreds(lakh) + ' Lakh '
    if thousand > 0:
        words += convert_hundreds(thousand) + ' Thousand '
    if num > 0:
        words += convert_hundreds(num)
    
    return words.strip()

def update_proforma_payment_status(request, pk):
    """Update payment status of proforma invoice"""
    if request.method == 'POST':
        try:
            proforma = get_object_or_404(ProformaInvoice, id=pk)
            payment_status = request.POST.get('payment_status')
            
            if payment_status in ['Unpaid', 'Paid', 'Credit']:
                proforma.payment_status = payment_status
                staff_id = request.session.get('staffid')
                
                # Update payment details based on status
                if payment_status == 'Paid':
                    proforma.payment_date = timezone.now()
                    proforma.payment_updated_by_id = staff_id
                elif payment_status == 'Credit':
                    # For Credit, also set payment_date to current time
                    proforma.payment_date = timezone.now()
                    proforma.payment_updated_by_id = staff_id
                else:  # Unpaid
                    # For Unpaid, clear payment date and updated_by
                    proforma.payment_date = None
                    proforma.payment_updated_by_id = None
                
                proforma.save()
                
                return JsonResponse({
                    'success': True,
                    'payment_status': proforma.payment_status,
                    'payment_date': proforma.payment_date.strftime('%d-%m-%Y %H:%M') if proforma.payment_date else None,
                    'payment_updated_by': staff_id
                })
            else:
                return JsonResponse({'success': False, 'error': 'Invalid payment status'})
                
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
    
    return JsonResponse({'success': False, 'error': 'Invalid request method'})


# ==================== B2B & B2C section ====================

def get_financial_year():
    """
    Returns the current financial year in the format '25/26'
    based on today's date.
    Financial year starts in April and ends in March.
    """
    today = date.today()
    year = today.year % 100  # Get last two digits of the year
    if today.month >= 4:  # April or later -> current FY starts this year
        return f"{year}/{year + 1}"
    else:  # Jan–Mar -> FY belongs to previous year
        return f"{year - 1}/{year}"

def generate_b2b_invoice_number(branch):
    """
    Generate B2B invoice number with format: HOB/00001/2627
    Based on location-wise document codes
    """
    # Branch-specific configurations based on the document numbering system
    branch_configs = {
        "JOHNMARIANS WELLNESS CLINIC": {"code": "HOB", "digits": 5},  # B2B Sales at HO
        "ALAPPUZHA": {"code": "AL1B", "digits": 5},
        "KAKKANAD": {"code": "KD1A", "digits": 5},
        "KANNUR": {"code": "KR1B", "digits": 5},
       
        "KOTTAYAM": {"code": "KM1B", "digits": 5},
        "PERUMBAVOOR": {"code": "PR1B", "digits": 5},
        "THRISSUR": {"code": "TR1B", "digits": 5},
        "WAYANAD": {"code": "WD1B", "digits": 5},
        "JOHNMARIANS HEALTH CARE PVT LTD": {"code": "HCB", "digits": 5},
        "PALA": {"code": "JHB", "digits": 5},
        "SMILEE KANNUR": {"code": "KR2B", "digits": 5},  # Kannur - 2
    }
    
    branch_name = branch.Branch_Name.upper()
    config = branch_configs.get(branch_name, {"code": "B2B", "digits": 5})
    branch_code = config["code"]
    digits = config["digits"]
    current_year = "2627"  # FY 2026-27
    
    # Get last invoice for this branch in current financial year
    last_invoice = B2BInvoice.objects.filter(
        branch=branch,
        invoice_date__year=date.today().year
    ).order_by('-id').first()
    
    if last_invoice and last_invoice.invoicenumber:
        try:
            # Format: HOB/00001/2627
            parts = last_invoice.invoicenumber.split('/')
            if len(parts) >= 2:
                last_num_str = parts[1]
                last_num = int(last_num_str) if last_num_str.isdigit() else 0
                new_num = last_num + 1
            else:
                new_num = 1
        except (ValueError, IndexError):
            new_num = 1
    else:
        new_num = 1
    
    return f"{branch_code}/{new_num:0{digits}d}/{current_year}"


