def extract_state_from_address(address):
    """Extract state from address string"""
    if not address:
        return 'Kerala'
    parts = address.split(',')
    if len(parts) > 0:
        last_part = parts[-1].strip()
        # Remove pin code if present (6 digits)
        state = re.sub(r'\d{6}', '', last_part).strip()
        # Remove extra whitespace
        state = ' '.join(state.split())
        return state if state else 'Kerala'
    return 'Kerala'


def number_to_words(num):
    """Convert number to words (Indian Rupees format)"""
    if num == 0:
        return 'Zero'
    
    num = int(round(num))
    
    ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine']
    teens = ['Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']
    tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']
    
    def convert_hundreds(n):
        str_val = ''
        if n >= 100:
            str_val += ones[n // 100] + ' Hundred '
            n %= 100
        if n >= 20:
            str_val += tens[n // 10] + ' '
            n %= 10
        elif n >= 10:
            str_val += teens[n - 10] + ' '
            n = 0
        if n > 0:
            str_val += ones[n] + ' '
        return str_val.strip()
    
    words = ''
    crore = num // 10000000
    num %= 10000000
    lakh = num // 100000
    num %= 100000
    thousand = num // 1000
    num %= 1000
    
    if crore > 0:
        words += convert_hundreds(crore) + ' Crore '
    if lakh > 0:
        words += convert_hundreds(lakh) + ' Lakh '
    if thousand > 0:
        words += convert_hundreds(thousand) + ' Thousand '
    if num > 0:
        words += convert_hundreds(num)
    
    words = ' '.join(words.split())
    return words + ' Rupees' if words else 'Zero Rupees'

def get_b2b_context(proforma, request, destination_branch=None):
    """Helper function to get context for B2B invoice form"""
    items = proforma.items.all()
    
    # Extract branch state from address
    branch_state = ""
    if proforma.branch and proforma.branch.Branch_Address:
        branch_state = extract_state_from_address(proforma.branch.Branch_Address)
    
    return {
        'proforma': proforma,
        'items': items,
        'branch_state': branch_state,
        'objhospt': Hospitaldetails.objects.all(),
        'brname': Branch.objects.filter(id=proforma.branch.id) if proforma.branch else None,
        'stdesign': request.session.get('loginstaffdesign'),
        'today': date.today(),
        'destination_branch': destination_branch,
        'is_stock_transfer': destination_branch is not None,
        'source_branch': proforma.branch,
    }


def get_b2c_context(proforma, request):
    """Helper function to get context for B2C invoice form"""
    items = proforma.items.all()
    
    return {
        'proforma': proforma,
        'items': items,
        'objhospt': Hospitaldetails.objects.all(),
        'brname': Branch.objects.filter(id=proforma.branch.id) if proforma.branch else None,
        'stdesign': request.session.get('loginstaffdesign'),
        'today': date.today(),
    }


