# ==================== B2B INVOICE VIEWS ====================
def b2b_invoice_create(request, proforma_id):
    proforma = get_object_or_404(ProformaInvoice, id=proforma_id)
    
    # Check payment status
    if proforma.payment_status not in ['Paid', 'Credit']:
        messages.error(request, "Cannot create B2B Invoice: Payment is not completed.")
        return redirect('proforma_invoice_view', pk=proforma_id)
    
    # Check if invoice already exists
    if B2BInvoice.objects.filter(proforma_reference=proforma.voucher_no).exists():
        messages.error(request, f"B2B Invoice already exists for Proforma Invoice {proforma.voucher_no}")
        return redirect('b2b_invoice_list')
    
    # Get source and destination branches from proforma and its associated PO
    source_branch = proforma.branch
    destination_branch = None
    
    # Get the purchase order linked to this proforma
    purchase_order = proforma.purchase_order
    
    if purchase_order and purchase_order.destination_branch:
        # Get the actual Branch object, not just the ID
        destination_branch = purchase_order.destination_branch
        print(f"✅ Stock transfer detected: {source_branch.Branch_Name} → {destination_branch.Branch_Name}")
    else:
        print(f"⚠️ No destination branch found for Proforma {proforma.voucher_no}")
    
    if request.method == 'POST':
        try:
            with transaction.atomic():
                hospital = Hospitaldetails.objects.first()
                if not hospital:
                    messages.error(request, "No hospital details found.")
                    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
                
                # Get buyer details from POST
                buyer_name = request.POST.get('buyer_name', '').strip()
                buyer_address = request.POST.get('buyer_address', '').strip()
                buyer_gstin = request.POST.get('buyer_gstin', '').strip()
                buyer_state = request.POST.get('buyer_state', '').strip()
                buyer_state_code = request.POST.get('buyer_state_code', '32').strip()
                
                # Get consignee details
                consignee_name = request.POST.get('consignee_name', buyer_name).strip()
                consignee_address = request.POST.get('consignee_address', buyer_address).strip()
                consignee_gstin = request.POST.get('consignee_gstin', buyer_gstin).strip()
                consignee_state = request.POST.get('consignee_state', '').strip()
                consignee_state_code = request.POST.get('consignee_state_code', '32').strip()
                
                # Get dispatch details
                buyers_order_no = request.POST.get('buyers_order_no', '').strip()
                buyers_order_date = request.POST.get('buyers_order_date') or None
                dispatch_doc_no = request.POST.get('dispatch_doc_no', '').strip()
                delivery_note_date = request.POST.get('delivery_note_date') or None
                dispatched_through = request.POST.get('dispatched_through', 'By Road').strip()
                destination = request.POST.get('destination', '').strip()
                terms_of_delivery = request.POST.get('terms_of_delivery', 'F.O.R. Destination').strip()
                payment_mode = request.POST.get('payment_mode', 'Cash').strip()
                
                # Validate required fields
                if not buyer_name:
                    messages.error(request, "Buyer Name is required.")
                    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
                if not buyer_address:
                    messages.error(request, "Buyer Address is required.")
                    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
                if not consignee_name:
                    messages.error(request, "Consignee Name is required.")
                    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
                if not consignee_address:
                    messages.error(request, "Consignee Address is required.")
                    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
                
                # Set default state if not provided
                if not buyer_state:
                    buyer_state = extract_state_from_address(buyer_address)
                if not consignee_state:
                    consignee_state = extract_state_from_address(consignee_address)
                
                # Generate invoice number
                invoice_number = generate_b2b_invoice_number(source_branch)
                
                # Create B2B Invoice
                b2b_invoice = B2BInvoice.objects.create(
                    hospitalname=hospital,
                    branch=source_branch,
                    invoicenumber=invoice_number,
                    invoice_date=date.today(),
                    proforma_reference=proforma.voucher_no,
                    buyer_name=buyer_name,
                    buyer_address=buyer_address,
                    buyer_gstin=buyer_gstin,
                    buyer_state=buyer_state,
                    buyer_state_code=buyer_state_code,
                    consignee_name=consignee_name,
                    consignee_address=consignee_address,
                    consignee_gstin=consignee_gstin,
                    consignee_state=consignee_state,
                    consignee_state_code=consignee_state_code,
                    buyers_order_no=buyers_order_no,
                    buyers_order_date=buyers_order_date,
                    dispatch_doc_no=dispatch_doc_no,
                    delivery_note_date=delivery_note_date,
                    dispatched_through=dispatched_through,
                    destination=destination,
                    terms_of_delivery=terms_of_delivery,
                    payment_mode=payment_mode,
                    created_by=request.session.get('loginstaff'),
                )
                
                # Process items from proforma
                proforma_items = proforma.items.all()
                subtotal = Decimal('0.00')
                cgst_total = Decimal('0.00')
                sgst_total = Decimal('0.00')
                igst_total = Decimal('0.00')
                
                # Determine if intra-state or inter-state
                branch_state = extract_state_from_address(source_branch.Branch_Address) if source_branch.Branch_Address else 'Kerala'
                is_intra_state = buyer_state and branch_state and buyer_state.lower() == branch_state.lower()
                
                stock_transfer_updates = []
                stock_errors = []
                
                print(f"\n{'='*60}")
                print(f"🚀 Starting B2B Invoice {invoice_number}")
                print(f"Source Branch: {source_branch.Branch_Name}")
                print(f"Destination Branch: {destination_branch.Branch_Name if destination_branch else 'None (Customer Sale)'}")
                print(f"{'='*60}")
                
                # Store before and after stock values for verification
                before_destination_stocks = {}
                after_destination_stocks = {}
                
                # Check destination stock BEFORE transfer
                if destination_branch:
                    for item in proforma_items:
                        dest_stock_before = Physicalstockdetails.objects.filter(
                            itemnm__itemnm=item.description,
                            Batch_no=item.batch_info,
                            stockbranch_id=destination_branch.id,
                            deleted=False
                        ).first()
                        before_destination_stocks[f"{item.description}_{item.batch_info}"] = dest_stock_before.qty if dest_stock_before else 0
                        print(f"📊 BEFORE - {item.description} (Batch: {item.batch_info}) in {destination_branch.Branch_Name}: {before_destination_stocks[f'{item.description}_{item.batch_info}']} units")
                
                for idx, item in enumerate(proforma_items, start=1):
                    quantity = Decimal(str(item.quantity))
                    rate = Decimal(str(item.rate))
                    taxable_value = quantity * rate
                    gst_percent = Decimal(str(item.gst_percent))
                    gst_amount = taxable_value * (gst_percent / Decimal('100'))
                    
                    if is_intra_state:
                        cgst = (gst_amount / Decimal('2')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                        sgst = (gst_amount / Decimal('2')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                        igst = Decimal('0.00')
                    else:
                        cgst = Decimal('0.00')
                        sgst = Decimal('0.00')
                        igst = gst_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                    
                    total_amount = taxable_value + cgst + sgst + igst
                    
                    # Initialize source_stock as None
                    source_stock = None
                    
                    # ============ STOCK TRANSFER LOGIC (ONLY IF DESTINATION BRANCH EXISTS) ============
                    if destination_branch:
                        print(f"\n🔄 Processing item {idx}: {item.description}")
                        print(f"   Batch: {item.batch_info}")
                        print(f"   Quantity: {quantity}")
                        
                        # Find the stock that was reduced from source branch
                        source_stock = Physicalstockdetails.objects.filter(
                            itemnm__itemnm=item.description,
                            Batch_no=item.batch_info,
                            stockbranch_id=source_branch.id,
                            deleted=False
                        ).first()
                        
                        if source_stock:
                            qty_to_transfer = int(quantity)
                            print(f"   ✅ Found source stock: ID={source_stock.id}, Available Qty={source_stock.qty}")
                            
                            # Check if same batch already exists in destination branch
                            dest_stock = Physicalstockdetails.objects.filter(
                                itemnm__itemnm=item.description,
                                Batch_no=item.batch_info,
                                stockbranch_id=destination_branch.id,
                                deleted=False
                            ).first()
                            print(f"   🔍 Checking destination stock... {'Found' if dest_stock else 'Not Found'}")
                            
                            if dest_stock:
                                # ADD to existing stock in destination branch
                                old_qty = dest_stock.qty
                                dest_stock.qty = F('qty') + qty_to_transfer
                                dest_stock.save()
                                dest_stock.refresh_from_db()
                                
                                print(f"   ✅ Destination stock updated: {old_qty} → {dest_stock.qty} (+{qty_to_transfer})")
                                
                                # Store after value
                                after_destination_stocks[f"{item.description}_{item.batch_info}"] = dest_stock.qty
                                
                                stock_transfer_updates.append({
                                    'item': item.description,
                                    'batch': item.batch_info,
                                    'source_branch': source_branch.Branch_Name,
                                    'destination_branch': destination_branch.Branch_Name,
                                    'transferred_qty': qty_to_transfer,
                                    'action': 'added to existing stock',
                                    'old_qty': old_qty,
                                    'new_qty': dest_stock.qty
                                })
                                
                                # Log stock addition in destination
                                StockAuditLog.objects.create(
                                    stock=dest_stock,
                                    action="UPDATE",
                                    staff_id=request.session.get('loginstaff'),
                                    branch_id=destination_branch.id,
                                    item=dest_stock.itemnm,
                                    qty=qty_to_transfer,
                                    action_date=timezone.now().date(),
                                    action_time=timezone.now().time(),
                                    remarks=f"Stock received from {source_branch.Branch_Name} via B2B Invoice {invoice_number} (Proforma: {proforma.voucher_no}) | Batch: {item.batch_info}"
                                )
                            else:
                                # Create new stock in destination branch
                                print(f"   ✅ Creating new stock in destination with {qty_to_transfer} units")
                                dest_stock = Physicalstockdetails.objects.create(
                                    storenm=source_stock.storenm,
                                    itemnm=source_stock.itemnm,
                                    unt=source_stock.unt,
                                    suppliernm=source_stock.suppliernm,
                                    Comapany_name=source_stock.Comapany_name,
                                    Manufacturer_date=source_stock.Manufacturer_date,
                                    Expiry_date=source_stock.Expiry_date,
                                    Batch_no=source_stock.Batch_no,
                                    Rate=source_stock.Rate,
                                    qty=qty_to_transfer,
                                    insertedstaffid_id=request.session.get('loginstaff'),
                                    stockbranch=destination_branch,
                                    lastupdatedate=timezone.now().date()
                                )
                                
                                # Store after value
                                after_destination_stocks[f"{item.description}_{item.batch_info}"] = qty_to_transfer
                                
                                stock_transfer_updates.append({
                                    'item': item.description,
                                    'batch': item.batch_info,
                                    'source_branch': source_branch.Branch_Name,
                                    'destination_branch': destination_branch.Branch_Name,
                                    'transferred_qty': qty_to_transfer,
                                    'action': 'new stock created',
                                    'new_qty': qty_to_transfer
                                })
                                
                                # Log new stock creation
                                StockAuditLog.objects.create(
                                    stock=dest_stock,
                                    action="INSERT",
                                    staff_id=request.session.get('loginstaff'),
                                    branch_id=destination_branch.id,
                                    item=dest_stock.itemnm,
                                    qty=qty_to_transfer,
                                    action_date=timezone.now().date(),
                                    action_time=timezone.now().time(),
                                    remarks=f"New stock created from transfer from {source_branch.Branch_Name} via B2B Invoice {invoice_number} | Batch: {item.batch_info}"
                                )
                        else:
                            error_msg = f"❌ Source stock not found for {item.description} (Batch: {item.batch_info}) in {source_branch.Branch_Name}"
                            print(error_msg)
                            stock_errors.append(error_msg)
                    else:
                        print(f"\n📝 Item {idx}: {item.description} - Customer sale, no stock transfer needed")
                    
                    # Create invoice item record
                    B2BInvoiceItem.objects.create(
                        invoice=b2b_invoice,
                        sl_no=idx,
                        description=item.description,
                        batch_info=item.batch_info or '',
                        quantity=quantity,
                        unit=item.unit,
                        rate=rate,
                        gst_percent=gst_percent,
                        hsn_code=item.hsn_code or '',
                        taxable_value=taxable_value,
                        cgst=cgst,
                        sgst=sgst,
                        igst=igst,
                        total_amount=total_amount,
                        physical_stock_id=source_stock.id if source_stock else None,
                        medicine_master_id=getattr(item, 'medicine_master_id', None),
                        batch_no=item.batch_info,
                        expiry_date=getattr(item, 'expiry_date', None),
                        manufacturer_date=getattr(item, 'manufacturer_date', None),
                        company_id=getattr(item, 'company_id', None),
                        supplier_id=getattr(item, 'supplier_id', None),
                        unit_id=getattr(item, 'unit_id', None)
                    )
                    
                    subtotal += taxable_value
                    cgst_total += cgst
                    sgst_total += sgst
                    igst_total += igst
                
                # Verify destination stock AFTER transfer
                if destination_branch and stock_transfer_updates:
                    print(f"\n{'='*60}")
                    print(f"📊 STOCK VERIFICATION AFTER TRANSFER")
                    print(f"{'='*60}")
                    for item in proforma_items:
                        dest_stock_after = Physicalstockdetails.objects.filter(
                            itemnm__itemnm=item.description,
                            Batch_no=item.batch_info,
                            stockbranch_id=destination_branch.id,
                            deleted=False
                        ).first()
                        after_qty = dest_stock_after.qty if dest_stock_after else 0
                        before_qty = before_destination_stocks.get(f"{item.description}_{item.batch_info}", 0)
                        expected_qty = before_qty + int(item.quantity)
                        print(f"   {item.description} (Batch: {item.batch_info})")
                        print(f"      Before: {before_qty} → After: {after_qty} (Expected: {expected_qty})")
                        if after_qty != expected_qty:
                            print(f"      ⚠️ WARNING: After quantity ({after_qty}) does not match expected ({expected_qty})!")
                    print(f"{'='*60}\n")
                
                # Check for stock errors
                if stock_errors:
                    # Delete the B2B invoice if there are stock errors
                    b2b_invoice.delete()
                    for error in stock_errors:
                        messages.error(request, error)
                    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
                
                # Log stock transfer summary
                if stock_transfer_updates:
                    print(f"\n{'='*60}")
                    print(f"✅ STOCK TRANSFER SUMMARY for B2B Invoice {invoice_number}")
                    print(f"{'='*60}")
                    print(f"From: {source_branch.Branch_Name}")
                    print(f"To: {destination_branch.Branch_Name}")
                    for update in stock_transfer_updates:
                        print(f"  - {update['item']}: +{update['transferred_qty']} units (Batch: {update['batch']})")
                        if 'old_qty' in update:
                            print(f"    Old Qty: {update['old_qty']} → New Qty: {update['new_qty']}")
                    print(f"{'='*60}\n")
                    
                    messages.success(request, f'✅ Stock transferred from {source_branch.Branch_Name} to {destination_branch.Branch_Name} successfully!')
                elif destination_branch:
                    messages.warning(request, f'⚠️ B2B Invoice created, but NO STOCK was transferred to {destination_branch.Branch_Name}. This may indicate the stock was not found in source branch.')
                else:
                    # Regular customer sale - no stock movement needed (already reduced in proforma)
                    print(f"📄 B2B Invoice {invoice_number} created for customer sale. Stock already reduced in proforma.")
                    messages.info(request, f'B2B Invoice created for customer sale. Stock was already reduced in Proforma Invoice.')
                
                # Update invoice totals
                b2b_invoice.subtotal = subtotal
                b2b_invoice.cgst_total = cgst_total
                b2b_invoice.sgst_total = sgst_total
                b2b_invoice.igst_total = igst_total
                b2b_invoice.grand_total = subtotal + cgst_total + sgst_total + igst_total
                b2b_invoice.amount_in_words = number_to_words(b2b_invoice.grand_total)
                b2b_invoice.save()
                
                messages.success(request, f'✅ B2B Invoice {invoice_number} created successfully!')
                return redirect('b2b_invoice_list')
                
        except Exception as e:
            messages.error(request, f'❌ Error creating B2B Invoice: {str(e)}')
            import traceback
            traceback.print_exc()
            return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
    
    return render(request, 'b2b_invoice_create.html', get_b2b_context(proforma, request, destination_branch))
