def b2c_invoice_create(request, proforma_id):
    """Create B2C Invoice from Proforma Invoice"""
    proforma = get_object_or_404(ProformaInvoice, id=proforma_id)
    
    # Check payment status
    if proforma.payment_status not in ['Paid', 'Credit']:
        messages.error(request, "Cannot create B2C Invoice: Payment is not completed.")
        return redirect('proforma_invoice_view', pk=proforma_id)
    
    # Check if invoice already exists
    if B2CInvoice.objects.filter(proforma_reference=proforma.voucher_no).exists():
        messages.error(request, f"B2C Invoice already exists for Proforma Invoice {proforma.voucher_no}")
        return redirect('b2c_invoice_list')
    
    if request.method == 'POST':
        try:
            with transaction.atomic():
                branch = proforma.branch
                hospital = Hospitaldetails.objects.first()
                if not hospital:
                    messages.error(request, "No hospital details found.")
                    return render(request, 'b2c_invoice_create.html', get_b2c_context(proforma, request))
                
                # Get customer details
                customer_name = request.POST.get('customer_name', '').strip()
                customer_address = request.POST.get('customer_address', '').strip()
                customer_state = request.POST.get('customer_state', '').strip()
                customer_state_code = request.POST.get('customer_state_code', '32').strip()
                customer_gstin = request.POST.get('customer_gstin', '').strip()
                transport_mode = request.POST.get('transport_mode', 'By Road').strip()
                place_of_supply = request.POST.get('place_of_supply', '').strip()
                
                # Validate required fields
                if not customer_name:
                    messages.error(request, "Customer Name is required.")
                    return render(request, 'b2c_invoice_create.html', get_b2c_context(proforma, request))
                if not customer_address:
                    messages.error(request, "Customer Address is required.")
                    return render(request, 'b2c_invoice_create.html', get_b2c_context(proforma, request))
                
                # Set default state if not provided
                if not customer_state:
                    customer_state = extract_state_from_address(customer_address)
                if not place_of_supply:
                    place_of_supply = customer_state
                
                # Generate invoice number
                invoice_number = generate_b2c_invoice_number(branch)
                
                # Create B2C Invoice
                b2c_invoice = B2CInvoice.objects.create(
                    hospitalname=hospital,
                    branch=branch,
                    invoicenumber=invoice_number,
                    invoice_date=date.today(),
                    proforma_reference=proforma.voucher_no,
                    customer_name=customer_name,
                    customer_address=customer_address,
                    customer_state=customer_state,
                    customer_state_code=customer_state_code,
                    customer_gstin=customer_gstin,
                    bill_to_name=customer_name,
                    bill_to_address=customer_address,
                    transport_mode=transport_mode,
                    place_of_supply=place_of_supply,
                    created_by=request.session.get('loginstaff'),
                )
                
                # Process items from proforma
                proforma_items = proforma.items.all()
                subtotal = Decimal('0.00')
                cgst_total = Decimal('0.00')
                sgst_total = Decimal('0.00')
                
                for idx, item in enumerate(proforma_items, start=1):
                    quantity = Decimal(str(item.quantity))
                    rate = Decimal(str(item.rate))
                    taxable_value = quantity * rate
                    gst_percent = Decimal(str(item.gst_percent))
                    gst_amount = taxable_value * (gst_percent / Decimal('100'))
                    
                    # For B2C, always split into CGST + SGST
                    cgst = (gst_amount / Decimal('2')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                    sgst = (gst_amount / Decimal('2')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
                    total_amount = taxable_value + cgst + sgst
                    
                    B2CInvoiceItem.objects.create(
                        invoice=b2c_invoice,
                        sl_no=idx,
                        description=item.description,
                        batch_info=item.batch_info or '',
                        quantity=quantity,
                        unit=item.unit,
                        rate=rate,
                        gst_percent=gst_percent,
                        hsn_code=item.hsn_code or '',
                        taxable_value=taxable_value,
                        cgst=cgst,
                        sgst=sgst,
                        total_amount=total_amount
                    )
                    
                    subtotal += taxable_value
                    cgst_total += cgst
                    sgst_total += sgst
                
                # Update invoice totals
                b2c_invoice.subtotal = subtotal
                b2c_invoice.cgst_total = cgst_total
                b2c_invoice.sgst_total = sgst_total
                b2c_invoice.grand_total = subtotal + cgst_total + sgst_total
                b2c_invoice.amount_in_words = number_to_words(b2c_invoice.grand_total)
                b2c_invoice.save()
                
                messages.success(request, f'B2C Invoice {invoice_number} created successfully!')
                return redirect('b2c_invoice_list')
                
        except Exception as e:
            messages.error(request, f'Error creating B2C Invoice: {str(e)}')
            return render(request, 'b2c_invoice_create.html', get_b2c_context(proforma, request))
    
    return render(request, 'b2c_invoice_create.html', get_b2c_context(proforma, request))


