def purchaseorderlistforownbranch(request):
    """List all purchase orders for non-franchise branches"""
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    staff_id = request.session.get('loginstaff')
    
    # Get filter parameters
    search = request.GET.get('search', '')
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    # Base queryset - filter by created_by AND branch where is_franchise=False
    pos = PurchaseOrder.objects.filter(
        branch__is_franchise=False  # Only include non-franchise branches
    )
    # Apply filters
    if search:
        pos = pos.filter(
            Q(po_number__icontains=search) |
            Q(supplier_name__icontains=search)
        )
    if from_date:
        pos = pos.filter(po_date__gte=from_date)
    if to_date:
        pos = pos.filter(po_date__lte=to_date)
    pos = pos.order_by('-po_date', '-created_at')
    # Pagination
    paginator = Paginator(pos, 20)
    page_number = request.GET.get('page')
    page_obj = paginator.get_page(page_number)
    context = {
        'page_obj': page_obj,
        'stdesign': stdesign,
        'search': search,
        'from_date': from_date,
        'to_date': to_date,
    }
    return render(request, 'purchaseorderlistforownbranch.html', context)


from django.shortcuts import render, get_object_or_404, redirect
from django.contrib import messages
from django.db import transaction
from django.utils import timezone
from django.core.paginator import Paginator
from django.db.models import Q, Sum
from django.http import JsonResponse
from django.contrib.auth.decorators import login_required

from .models import (
    PurchaseOrder, POItem, Branch, Physicalstockdetails, 
    StockAuditLog, Staffdetails, storedetails, unitdt,
    StockTransfer, StockTransferItem, StockTransferLog
)
def create_stock_transfer_from_po(request, po_id):
    """
    View to create stock transfer from purchase order with batch selection
    """
    staff_id = request.session.get('loginstaff')
    if not staff_id:
        return redirect('staff_login')
    
    purchase_order = get_object_or_404(PurchaseOrder, id=po_id)
    
    # Get all branches except the source branch for destination selection
    branches = Branch.objects.get(inactive=False,id=purchase_order.destination_branch_id)
    print(branches)
    # Prepare items for transfer with available batches
    items_for_transfer = []
    po_items = purchase_order.items.all()
    
    for po_item in po_items:
        # Find available stock for this item in the source branch
        available_stocks = Physicalstockdetails.objects.filter(
            itemnm__itemnm=po_item.item_name,
            stockbranch=purchase_order.branch,
            deleted=False,
            qty__gt=0
        ).select_related('itemnm', 'unt', 'storenm').order_by('Expiry_date')
        # Get unique batches with their details
        available_batches = []
        for stock in available_stocks:
            available_batches.append({
                'id': stock.id,
                'Batch_no': stock.Batch_no,
                'Expiry_date': stock.Expiry_date,
                'Rate': stock.Rate,
                'qty': stock.qty,
                'Manufacturer_date': stock.Manufacturer_date,
            })
        # Get the unit for display
        unit = None
        if po_item.unit:
            try:
                unit = unitdt.objects.get(unitname=po_item.unit)
            except unitdt.DoesNotExist:
                unit = None
        
        # Get the best available stock
        best_stock = available_stocks.first()
        items_for_transfer.append({
            'po_item': po_item,
            'stock': best_stock,
            'available_batches': available_batches,
            'available_qty': best_stock.qty if best_stock else 0,
            'batch_no': best_stock.Batch_no if best_stock else None,
            'expiry_date': best_stock.Expiry_date if best_stock else None,
            'rate': best_stock.Rate if best_stock else 0,
            'unit': unit,
            'transfer_qty': min(po_item.quantity, best_stock.qty) if best_stock else 0,
        })
    context = {
        'purchase_order': purchase_order,
        'branches': branches,
        'items_for_transfer': items_for_transfer,
        'today': timezone.now().date(),
    }
    return render(request, 'stock_transfer_create.html', context)


@transaction.atomic
def process_stock_transfer(request):
    """
    Process the stock transfer form submission.
    - Creates StockTransfer + StockTransferItem records
    - Deducts qty from source branch Physicalstockdetails immediately
    - Logs every deduction in StockAuditLog
    - Stores transfer summary in session for success page
    """
    if request.method != 'POST':
        return redirect('purchaseorderlistforownbranch')
    try:
        # ----------------------------------------------------------------
        # 1. Read POST data
        # ----------------------------------------------------------------
        po_id                  = request.POST.get('po_id')
        to_branch_id           = request.POST.get('to_branch')
        expected_delivery_date = request.POST.get('expected_delivery_date') or None
        remarks                = request.POST.get('remarks', '')
        if not po_id or not to_branch_id:
            messages.error(request, 'Missing required information.')
            return redirect('purchaseorderlistforownbranch')
        # ----------------------------------------------------------------
        # 2. Resolve objects
        # ----------------------------------------------------------------
        purchase_order = get_object_or_404(PurchaseOrder, id=po_id)
        to_branch      = get_object_or_404(Branch, id=to_branch_id)
        from_branch    = purchase_order.branch
        # Staff from session  (key: 'loginstaff')
        staff_id = request.session.get('loginstaff')
        if not staff_id:
            messages.error(request, 'Staff details not found. Please log in again.')
            return redirect('staff_login')

        staff = get_object_or_404(Staffdetails, id=staff_id, deleted=False)

        # ----------------------------------------------------------------
        # 3. Generate a race-condition-safe transfer number
        #    Uses select_for_update on the last record so concurrent
        #    requests cannot produce duplicate numbers.
        # ----------------------------------------------------------------
        today = timezone.now().strftime('%Y%m%d')
        prefix = f'TRF{today}'

        # Lock the latest transfer row for this date
        last_transfer = (
            StockTransfer.objects
            .select_for_update()
            .filter(transfer_number__startswith=prefix)
            .order_by('-transfer_number')
            .first()
        )

        if last_transfer:
            try:
                last_number = int(last_transfer.transfer_number[-4:])
            except ValueError:
                last_number = 0
            new_number = last_number + 1
        else:
            new_number = 1

        transfer_number = f'{prefix}{new_number:04d}'

        # ----------------------------------------------------------------
        # 4. Create the StockTransfer header
        # ----------------------------------------------------------------
        stock_transfer = StockTransfer.objects.create(
            transfer_number=transfer_number,
            purchase_order=purchase_order,
            from_branch=from_branch,
            to_branch=to_branch,
            expected_delivery_date=expected_delivery_date,
            remarks=remarks,
            created_by=staff_id,
            status='pending',
        )

        # Default store for audit log (get or create safely)
        store, _ = storedetails.objects.get_or_create(storename='Main Store')

        # ----------------------------------------------------------------
        # 5. Process each PO item
        # ----------------------------------------------------------------
        transferred_items      = []
        total_transferred_qty  = 0
        items_created          = 0
        po_items = purchase_order.items.all()
        for po_item in po_items:
            # --- Read per-item POST fields ---
            transfer_qty_raw = request.POST.get(f'transfer_qty_{po_item.id}')

            # Skip items with no quantity entered
            if not transfer_qty_raw:
                continue
            try:
                transfer_qty = int(float(transfer_qty_raw))
            except (ValueError, TypeError):
                continue
            if transfer_qty <= 0:
                continue
            batch_no  = request.POST.get(f'batch_{po_item.id}', '').strip()
            stock_id  = request.POST.get(f'stock_id_{po_item.id}', '').strip()
            expiry_raw = request.POST.get(f'expiry_{po_item.id}', '').strip()
            rate_raw  = request.POST.get(f'rate_{po_item.id}', '').strip()

            if not batch_no or not stock_id:
                messages.error(
                    request,
                    f'Please select a batch for item: {po_item.item_name}'
                )
                stock_transfer.delete()
                return redirect('create_stock_transfer_from_po', po_id=po_id)

            # --- Validate source stock ---
            source_stock = get_object_or_404(Physicalstockdetails, id=stock_id)

            if source_stock.stockbranch != from_branch:
                messages.error(
                    request,
                    f'Invalid stock branch for item: {po_item.item_name}'
                )
                stock_transfer.delete()
                return redirect('create_stock_transfer_from_po', po_id=po_id)

            if source_stock.deleted:
                messages.error(
                    request,
                    f'Stock record is deleted for item: {po_item.item_name}'
                )
                stock_transfer.delete()
                return redirect('create_stock_transfer_from_po', po_id=po_id)

            if source_stock.qty < transfer_qty:
                messages.error(
                    request,
                    f'Insufficient stock for "{po_item.item_name}". '
                    f'Available: {source_stock.qty}, Requested: {transfer_qty}.'
                )
                stock_transfer.delete()
                return redirect('create_stock_transfer_from_po', po_id=po_id)

            # --- Resolve unit ---
            unit = None
            if po_item.unit:
                unit = unitdt.objects.filter(unitname=po_item.unit).first()

            # --- Financials ---
            try:
                rate_value = float(rate_raw) if rate_raw else float(source_stock.Rate or 0)
            except (ValueError, TypeError):
                rate_value = float(source_stock.Rate or 0)

            total_amount = transfer_qty * rate_value

            # --- Resolve expiry date ---
            expiry_date = expiry_raw if expiry_raw else source_stock.Expiry_date

            # ----------------------------------------------------------------
            # 6. Create StockTransferItem
            #    transferred_quantity = transfer_qty because stock is
            #    already physically deducted from source at this step.
            # ----------------------------------------------------------------
            print("po_item.quantity",po_item.quantity)
            StockTransferItem.objects.create(
                stock_transfer=stock_transfer,
                item=source_stock.itemnm,
                requested_quantity=int(po_item.quantity),
                quantity=transfer_qty,
                transferred_quantity=transfer_qty,   # already deducted
                batch_no=batch_no,
                expiry_date=expiry_date,
                manufacturer_date=source_stock.Manufacturer_date,
                rate=rate_value,
                total_amount=total_amount,
                unit=unit,
                source_stock=source_stock,
                status='pending',
            )

            # ----------------------------------------------------------------
            # 7. Deduct stock from source branch
            # ----------------------------------------------------------------
            source_stock.qty           -= transfer_qty
            source_stock.lastupdatedate = timezone.now().date()
            source_stock.save()

            # ----------------------------------------------------------------
            # 8. Audit log for the deduction
            # ----------------------------------------------------------------
            StockAuditLog.objects.create(
                stock=source_stock,
                action='UPDATE',
                staff=staff,
                branch=from_branch,
                store=source_stock.storenm,
                item=source_stock.itemnm,
                qty=transfer_qty,
                action_date=timezone.now().date(),
                action_time=timezone.now().time(),
                remarks=(
                    f'Stock deducted for transfer {transfer_number} '
                    f'to branch: {to_branch.Branch_Name}. '
                    f'Batch: {batch_no}.'
                ),
            )

            # ----------------------------------------------------------------
            # 9. Accumulate summary data
            # ----------------------------------------------------------------
            transferred_items.append({
                'item'        : po_item.item_name,
                'batch'       : batch_no,
                'quantity'    : transfer_qty,
                'rate'        : rate_value,
                'total_amount': total_amount,
            })

            total_transferred_qty += transfer_qty
            items_created         += 1

        # ----------------------------------------------------------------
        # 10. Guard: nothing was actually transferred
        # ----------------------------------------------------------------
        if items_created == 0:
            messages.error(request, 'No items were selected for transfer.')
            stock_transfer.delete()
            return redirect('create_stock_transfer_from_po', po_id=po_id)

        # ----------------------------------------------------------------
        # 11. Update transfer totals
        # ----------------------------------------------------------------
        stock_transfer.total_items    = items_created
        stock_transfer.total_quantity = total_transferred_qty
        stock_transfer.save()

        # ----------------------------------------------------------------
        # 12. Transfer creation log
        # ----------------------------------------------------------------
        StockTransferLog.objects.create(
            stock_transfer=stock_transfer,
            action='CREATE',
            new_status='pending',
            staff_id=staff_id,
            remarks=f'Created from Purchase Order {purchase_order.po_number}.',
        )

        # ----------------------------------------------------------------
        # 13. Store summary in session for success page
        # ----------------------------------------------------------------
        staff_fullname = f'{staff.Staff_firstname} {staff.Staff_lastname}'.strip()

        request.session['transfer_summary'] = {
            'transfer_number'       : transfer_number,
            'transfer_id'           : stock_transfer.id,
            'po_number'             : purchase_order.po_number,
            'from_branch'           : from_branch.Branch_Name,
            'to_branch'             : to_branch.Branch_Name,
            'expected_delivery_date': expected_delivery_date or '-',
            'remarks'               : remarks,
            'items'                 : transferred_items,
            'total_quantity'        : total_transferred_qty,
            'total_items'           : items_created,
            'total_amount'          : sum(i['total_amount'] for i in transferred_items),
            'created_by'            : staff_fullname,
            'created_date'          : timezone.now().strftime('%Y-%m-%d %H:%M:%S'),
        }

        messages.success(
            request,
            f'Stock Transfer {transfer_number} created successfully! '
            f'{items_created} item(s), total qty: {total_transferred_qty}.'
        )
        return redirect('stock_transfer_success')

    except Exception as e:
        messages.error(request, f'Error processing transfer: {str(e)}')
        return redirect('purchaseorderlistforownbranch')

def stock_transfer_success(request):
    """
    Displays the transfer summary stored in session by process_stock_transfer.
    Pops the session key so refreshing the page redirects to the list.
    """
    summary = request.session.pop('transfer_summary', None)
 
    if not summary:
        messages.warning(request, "No transfer summary found.")
        return redirect('stock_transfer_list')
 
    return render(request, 'stock_transfer_success.html', {'summary': summary})
 

