def get_item_stock(request):
    """
    GET ?item_id=<medicinemaster.id>
    Returns available stock batches for the item in the logged-in branch.
    Used in the create-transfer form to populate batch/qty fields dynamically.
    """
    staff=request.session.get('staffid')
    branch = request.session.get('branchid')
 
    item_id       = request.GET.get('item_id', '').strip()
 
    if not item_id:
        return JsonResponse({'error': 'item_id is required.'}, status=400)
 
    stocks = Physicalstockdetails.objects.filter(
        itemnm_id=item_id,
        stockbranch=branch,
        deleted=False,
        qty__gt=0,
    ).select_related('unt', 'storenm')
 
    data = [
        {
            'stock_id'         : s.id,
            'batch_no'         : s.Batch_no,
            'available_qty'    : s.qty,
            'rate'             : str(s.Rate or '0'),
            'expiry_date'      : str(s.Expiry_date)       if s.Expiry_date       else '',
            'manufacturer_date': str(s.Manufacturer_date) if s.Manufacturer_date else '',
            'unit'             : s.unt.unitname            if s.unt               else '',
            'store'            : s.storenm.storename       if s.storenm           else '',
        }
        for s in stocks
    ]
 
    return JsonResponse({'stocks': data})
from django.shortcuts import render, get_object_or_404, redirect
from django.contrib.auth.decorators import login_required
from django.db import transaction
from django.db.models import Sum
from django.core.paginator import Paginator
from django.contrib import messages
from django.utils import timezone
from datetime import datetime

# ========================================
# STOCK TRANSFER VERIFICATION VIEW
# ========================================
@transaction.atomic
def stock_transfer_verify(request): 
    transfer_id=request.GET.get("transferid") # Changed from 'pk' to 'transfer_id' for consistency
    """
    Verify stock transfer items - Verifier checks and confirms quantities
    """
    transfer = get_object_or_404(StockTransfer, id=transfer_id)  # Changed from pk to transfer_id
    
    if transfer.status != 'pending':
        messages.error(request, f'This transfer cannot be verified. Current status: {transfer.status}')
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")
  # Changed parameter
    
    if request.method == 'POST':
        selected_items = request.POST.getlist('selected_items')
        remarks = request.POST.get('remarks', '')
        
        if not selected_items:
            messages.error(request, 'Please select at least one item to verify')
            return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

        
        try:
            with transaction.atomic():
                total_verified_quantity = 0
                
                for item_id in selected_items:
                    transfer_item = get_object_or_404(StockTransferItem, id=item_id, stock_transfer=transfer)
                    
                    verified_qty_key = f'verified_qty_{transfer_item.id}'
                    verified_qty_str = request.POST.get(verified_qty_key, '0')
                    
                    # Handle empty or invalid values
                    try:
                        verified_qty = int(verified_qty_str) if verified_qty_str else 0
                    except ValueError:
                        verified_qty = 0
                    
                    max_qty = transfer_item.requested_quantity or transfer_item.quantity
                    
                    if verified_qty < 0:
                        messages.error(request, f'Verified quantity cannot be negative for {transfer_item.item.itemnm}')
                        return redirect('stock_transfer_detail', pk=transfer.id)
                    
                    if verified_qty > max_qty:
                        messages.error(request, f'Verified quantity ({verified_qty}) cannot exceed requested quantity ({max_qty}) for {transfer_item.item.itemnm}')
                        return redirect('stock_transfer_detail', pk=transfer.id)
                    
                    # Only update if verified_qty > 0
                    if verified_qty > 0:
                        transfer_item.verified_quantity = verified_qty
                        transfer_item.status = 'verified'
                        transfer_item.verification_remarks = remarks
                        transfer_item.save()
                        
                        total_verified_quantity += verified_qty
                        
                        # Update POItem transferred and pending quantities
                        if transfer_item.po_item:
                            po_item = transfer_item.po_item
                            
                            total_verified_for_po = StockTransferItem.objects.filter(
                                po_item=po_item,
                                stock_transfer__status__in=['verified', 'approved', 'in_transit', 'completed']
                            ).aggregate(total=Sum('verified_quantity'))['total'] or 0
                            
                            po_item.transferred_quantity = total_verified_for_po
                            po_item.pending_quantity = po_item.quantity - total_verified_for_po
                            po_item.save()
                    else:
                        # If verified_qty is 0, mark as cancelled
                        transfer_item.verified_quantity = 0
                        transfer_item.status = 'cancelled'
                        transfer_item.verification_remarks = remarks
                        transfer_item.save()
                
                # Only update transfer status if at least one item was verified
                if total_verified_quantity > 0:
                    transfer.status = 'verified'
                    transfer.verified_by = request.user.id
                    transfer.verified_at = timezone.now()
                    transfer.verified_remarks = remarks
                    transfer.save()
                    
                    StockTransferLog.objects.create(
                        stock_transfer=transfer,
                        action='VERIFIED',
                        old_status='pending',
                        new_status='verified',
                        staff_id=request.user.id,
                        remarks=f'Verified {len(selected_items)} items. Total: {total_verified_quantity}'
                    )
                    
                    messages.success(request, f'Successfully verified {len(selected_items)} items with total quantity {total_verified_quantity}')
                else:
                    messages.warning(request, 'No items were verified. Transfer status remains pending.')
                
        except Exception as e:
            messages.error(request, f'Error during verification: {str(e)}')
            import traceback
            traceback.print_exc()
        
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

@transaction.atomic
def stock_transfer_approve(request):
    transfer_id=request.GET.get("transferid")
    """
    Approve stock transfer items - ONLY HERE stock is reduced from source and added to destination
    Stock is NOT reduced at creation time
    Allows partial approval - can approve items one by one
    """
    transfer = get_object_or_404(StockTransfer, id=transfer_id)
    
    # Allow approval for pending status only (keep as pending until all items done)
    if transfer.status != 'pending':
        messages.error(request, f'This transfer cannot be approved. Current status: {transfer.status}')
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    if request.method == 'POST':
        selected_items = request.POST.getlist('selected_items')
        remarks = request.POST.get('remarks', '')
        
        if not selected_items:
            messages.error(request, 'Please select at least one item to approve')
            return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

        
        try:
            with transaction.atomic():
                total_approved_quantity = 0
                approved_items_count = 0
                
                for item_id in selected_items:
                    transfer_item = get_object_or_404(StockTransferItem, id=item_id, stock_transfer=transfer)
                    
                    # Skip if already approved
                    if transfer_item.status == 'approved':
                        continue
                    
                    # Get approved quantity from form
                    approved_qty_key = f'approved_qty_{transfer_item.id}'
                    approved_qty_str = request.POST.get(approved_qty_key, '0')
                    
                    try:
                        approved_qty = int(approved_qty_str) if approved_qty_str else 0
                    except ValueError:
                        approved_qty = 0
                    
                    # Max quantity is the requested quantity
                    max_qty = transfer_item.requested_quantity or transfer_item.quantity
                    
                    if approved_qty < 0:
                        messages.error(request, f'Approved quantity cannot be negative for {transfer_item.item.itemnm}')
                        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

                    
                    if approved_qty > max_qty:
                        messages.error(request, f'Approved quantity ({approved_qty}) cannot exceed requested quantity ({max_qty}) for {transfer_item.item.itemnm}')
                        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

                    
                    # Check source stock availability at APPROVAL time
                    
                    source_stock = transfer_item.source_stock
                    
                    # Process stock movement ONLY at approval time
                    if approved_qty > 0:
                       
                        # 2. Get unit ID
                        unit_id = None
                        if transfer_item.unit:
                            unit_id = transfer_item.unit.id
                        elif source_stock and hasattr(source_stock, 'unt_id'):
                            unit_id = source_stock.unt_id
                        
                        if not unit_id:
                           
                            default_unit, created = unitdt.objects.get_or_create(
                                unitname='Pcs',
                                defaults={'unitname': 'Pcs'}
                            )
                            unit_id = default_unit.id
                        print("Branch ID:", transfer.to_branch.id)
                        print("Item:", transfer_item.item)
                        print("Batch No:", transfer_item.batch_no)
                        print("Company Name:", transfer_item.source_stock.Comapany_name)
                        print("Manufacturer Date:", transfer_item.manufacturer_date)
                        print("Expiry Date:", transfer_item.expiry_date)
                        print("Supplier ID:", transfer_item.source_stock.suppliernm.id)
                        # 3. ADD to destination branch stock
                        dest_stock = Physicalstockdetails.objects.filter(
                            stockbranch_id=transfer.to_branch.id,
                            itemnm=transfer_item.item,
                            Batch_no=transfer_item.batch_no,
                            Comapany_name=transfer_item.source_stock.Comapany_name.id,
                            Manufacturer_date=transfer_item.manufacturer_date,
                            Expiry_date=transfer_item.expiry_date,
                            suppliernm_id=transfer_item.source_stock.suppliernm.id

                        ).first()
                        print(dest_stock)
                        if dest_stock:
                            dest_stock.qty += approved_qty
                            dest_stock.save()
                        else:
                            dest_stock = Physicalstockdetails.objects.create(
                                stockbranch_id=transfer.to_branch.id,
                                itemnm=transfer_item.item,
                                Batch_no=transfer_item.batch_no,
                                Rate=transfer_item.rate,
                                Expiry_date=transfer_item.expiry_date,
                                qty=approved_qty,
                                unt_id=unit_id,
Comapany_name=transfer_item.source_stock.Comapany_name,
                             Manufacturer_date=transfer_item.manufacturer_date,
                           
                                suppliernm_id=transfer_item.source_stock.suppliernm.id


                            )
                        
                        transfer_item.destination_stock = dest_stock
                        approved_items_count += 1
                    
                    # Update transfer item
                    transfer_item.approved_quantity = approved_qty
                    transfer_item.status = 'approved' if approved_qty > 0 else 'cancelled'
                    transfer_item.notes = remarks
                    transfer_item.save()
                    
                    total_approved_quantity += approved_qty
                    
                    # Update POItem
                    if transfer_item.po_item:
                        po_item = transfer_item.po_item
                        
                        total_approved_for_po = StockTransferItem.objects.filter(
                            po_item=po_item,
                            stock_transfer__status__in=['approved', 'in_transit', 'completed']
                        ).exclude(id=transfer_item.id).aggregate(total=Sum('approved_quantity'))['total'] or 0
                        
                        total_approved_for_po += approved_qty
                        
                        po_item.transferred_quantity = total_approved_for_po
                        po_item.pending_quantity = po_item.quantity - total_approved_for_po
                        po_item.save()
                
                # CRITICAL: Check if ALL items are either approved or cancelled
                pending_items_count = transfer.items.filter(status='pending').count()
                all_items_processed = pending_items_count == 0
                
                # ONLY change transfer status to approved when ALL items are processed
                if all_items_processed and total_approved_quantity > 0:
                    transfer.status = 'approved'
                    transfer.approved_by = request.user.id
                    transfer.approved_at = timezone.now()
                    transfer.approved_remarks = remarks
                    transfer.total_quantity = total_approved_quantity
                    transfer.total_items = approved_items_count
                    transfer.save()
                    
                    StockTransferLog.objects.create(
                        stock_transfer=transfer,
                        action='APPROVED',
                        old_status='pending',
                        new_status='approved',
                        staff_id=request.user.id,
                        remarks=f'All items approved. Total quantity: {total_approved_quantity}'
                    )
                    
                    messages.success(request, f'All items have been approved! Total quantity: {total_approved_quantity}')
                elif total_approved_quantity > 0:
                    # Keep transfer as pending for remaining items
                    StockTransferLog.objects.create(
                        stock_transfer=transfer,
                        action='APPROVED',
                        old_status='pending',
                        new_status='pending',
                        staff_id=request.user.id,
                        remarks=f'Partially approved {approved_items_count} item(s). {pending_items_count} item(s) remaining.'
                    )
                    
                    messages.info(
                        request, 
                        f'Approved {approved_items_count} item(s) with total quantity {total_approved_quantity}. '
                        f'{pending_items_count} item(s) still pending approval.'
                    )
                else:
                    messages.warning(request, 'No items were approved.')
                
        except Exception as e:
            messages.error(request, f'Error during approval: {str(e)}')
            import traceback
            traceback.print_exc()
        
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

# ========================================
# STOCK TRANSFER REJECT VIEW
# ========================================

@transaction.atomic
def stock_transfer_reject(request):
    transfer_id=request.GET.get("transferid")
    """Reject stock transfer"""
    transfer = get_object_or_404(StockTransfer, id=transfer_id)
    
    if transfer.status not in ['pending', 'verified', 'approved']:
        messages.error(request, f'This transfer cannot be rejected')
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    if request.method == 'POST':
        rejection_reason = request.POST.get('rejection_reason', '')
        
        if not rejection_reason:
            messages.error(request, 'Please provide a rejection reason')
            return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

        
        try:
            with transaction.atomic():
                old_status = transfer.status
                transfer.status = 'rejected'
                transfer.rejection_reason = rejection_reason
                transfer.save()
                
                transfer.items.update(status='cancelled')
                
                StockTransferLog.objects.create(
                    stock_transfer=transfer,
                    action='REJECTED',
                    old_status=old_status,
                    new_status='rejected',
                    staff_id=request.user.id,
                    remarks=rejection_reason
                )
                
                messages.success(request, 'Stock transfer rejected')
                
        except Exception as e:
            messages.error(request, f'Error: {str(e)}')
        
        return redirect('stock_transfer_list')
    
    return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")



# ========================================
# STOCK TRANSFER CANCEL VIEW
# ========================================

@transaction.atomic
def stock_transfer_cancel(request):
    """Cancel stock transfer"""
    transfer_id=request.GET.get("transferid")
    transfer = get_object_or_404(StockTransfer, id=transfer_id)
    
    if transfer.status in ['in_transit', 'delivered', 'completed']:
        messages.error(request, f'This transfer cannot be cancelled')
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    if request.method == 'POST':
        cancel_reason = request.POST.get('cancel_reason', '')
        
        if not cancel_reason:
            messages.error(request, 'Please provide a cancellation reason')
            return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

        
        try:
            with transaction.atomic():
                old_status = transfer.status
                transfer.status = 'cancelled'
                transfer.remarks = cancel_reason
                transfer.save()
                
                transfer.items.update(status='cancelled')
                
                # Restore stock if was approved
                if old_status == 'approved':
                    for item in transfer.items.all():
                        if item.approved_quantity > 0 and item.source_stock:
                            item.source_stock.qty += item.approved_quantity
                            item.source_stock.save()
                
                StockTransferLog.objects.create(
                    stock_transfer=transfer,
                    action='CANCELLED',
                    old_status=old_status,
                    new_status='cancelled',
                    staff_id=request.user.id,
                    remarks=cancel_reason
                )
                
                messages.success(request, 'Stock transfer cancelled')
                
        except Exception as e:
            messages.error(request, f'Error: {str(e)}')
        
        return redirect('stock_transfer_list')
    
    return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")



# ========================================
# STOCK TRANSFER DETAIL VIEW
# ========================================
def stock_transfer_detail(request):
    transfer_id=request.GET.get("transferid")
    """Display stock transfer details with partial approval support"""
    transfer = get_object_or_404(StockTransfer, id=transfer_id)
    items = transfer.items.select_related('item', 'unit', 'source_stock', 'destination_stock').all()
    logs = StockTransferLog.objects.filter(stock_transfer=transfer)
    
    # Calculate totals
    total_requested = sum(item.requested_quantity or item.quantity for item in items)
    total_approved = sum(item.approved_quantity for item in items if item.approved_quantity)
    total_received = sum(item.received_quantity for item in items if item.received_quantity)
    
    # CRITICAL: Count pending items for UI display
    pending_items_count = items.filter(status='pending').count()
    approved_items_count = items.filter(status='approved').count()
    
    user_branch = getattr(request.user, 'branch_id', None)
    
    context = {
        'transfer': transfer,
        'items': items,
        'logs': logs,
        'total_requested': total_requested,
        'total_approved': total_approved,
        'total_received': total_received,
        'pending_items_count': pending_items_count,
        'approved_items_count': approved_items_count,
        'can_approve': transfer.status == 'pending' and pending_items_count > 0,
        'can_dispatch': transfer.status == 'approved' and transfer.from_branch and transfer.from_branch.id == user_branch,
        'can_receive': transfer.status == 'in_transit' and transfer.to_branch and transfer.to_branch.id == user_branch,
        'can_reject': transfer.status == 'pending',
        'can_cancel': transfer.status not in ['in_transit', 'delivered', 'completed', 'rejected', 'cancelled'],
    }
    
    return render(request, 'stock_transfer_detail.html', context)


# ========================================
# STOCK TRANSFER LIST VIEW
# ========================================

def stock_transfer_list(request):
    """List all stock transfers with filters"""
    transfers = StockTransfer.objects.select_related('from_branch', 'to_branch', 'purchase_order').all()
    
    # Filters
    transfer_type = request.GET.get('type', '')
    status = request.GET.get('status', '')
    search = request.GET.get('search', '')
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    
    if transfer_type == 'sent':
        transfers = transfers.filter(from_branch=request.user.branch)
    elif transfer_type == 'received':
        transfers = transfers.filter(to_branch=request.user.branch)
    
    if status:
        transfers = transfers.filter(status=status)
    
    if search:
        transfers = transfers.filter(
            Q(transfer_number__icontains=search) |
            Q(from_branch__Branch_Name__icontains=search) |
            Q(to_branch__Branch_Name__icontains=search)
        )
    
    if from_date:
        transfers = transfers.filter(created_at__date__gte=from_date)
    
    if to_date:
        transfers = transfers.filter(created_at__date__lte=to_date)
    
    # Statistics
    stats = {
        'pending': transfers.filter(status='pending').count(),
        'verified': transfers.filter(status='verified').count(),
        'approved': transfers.filter(status='approved').count(),
        'delivered': transfers.filter(status='completed').count(),
        'rejected': transfers.filter(status='rejected').count(),
        'total_quantity': transfers.aggregate(total=Sum('total_quantity'))['total'] or 0,
    }
    
    # Pagination
    paginator = Paginator(transfers, 20)
    page_number = request.GET.get('page')
    page_obj = paginator.get_page(page_number)
    
    context = {
        'page_obj': page_obj,
        'stats': stats,
        'transfer_type': transfer_type,
        'status': status,
        'search': search,
        'from_date': from_date,
        'to_date': to_date,
    }
    
    return render(request, 'stock_transfer_list.html', context)
# STOCK TRANSFER DISPATCH VIEW
# ========================================

@transaction.atomic
def stock_transfer_dispatch(request):
    transfer_id=request.GET.get("transferid")
    """Mark stock transfer as dispatched/in transit"""
    transfer = get_object_or_404(StockTransfer, id=transfer_id)
    
    if transfer.status != 'approved':
        messages.error(request, f'This transfer cannot be dispatched. Current status: {transfer.status}')
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    if request.method == 'POST':
        remarks = request.POST.get('remarks', '')
        
        try:
            with transaction.atomic():
                transfer.status = 'in_transit'
                transfer.dispatched_by = request.user.id
                transfer.dispatched_at = timezone.now()
                transfer.remarks = remarks
                transfer.save()
                
                transfer.items.update(status='transferred')
                
                StockTransferLog.objects.create(
                    stock_transfer=transfer,
                    action='DISPATCHED',
                    old_status='approved',
                    new_status='in_transit',
                    staff_id=request.user.id,
                    remarks=remarks
                )
                
                messages.success(request, 'Stock transfer marked as dispatched')
                
        except Exception as e:
            messages.error(request, f'Error: {str(e)}')
        
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")


# ========================================
# STOCK TRANSFER RECEIVE VIEW
# ================
@transaction.atomic
def stock_transfer_receive(request):
    transfer_id=request.GET.get("transferid")
    """Receive stock transfer at destination branch"""
    transfer = get_object_or_404(StockTransfer, id=transfer_id)
    
    if transfer.status != 'in_transit':
        messages.error(request, f'This transfer cannot be received. Current status: {transfer.status}')
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    if request.method == 'POST':
        selected_items = request.POST.getlist('selected_items')
        remarks = request.POST.get('remarks', '')
        
        if not selected_items:
            messages.error(request, 'Please select at least one item to receive')
            return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

        
        try:
            with transaction.atomic():
                for item_id in selected_items:
                    transfer_item = get_object_or_404(StockTransferItem, id=item_id, stock_transfer=transfer)
                    
                    received_qty_key = f'received_qty_{transfer_item.id}'
                    received_qty = int(request.POST.get(received_qty_key, 0))
                    
                    max_qty = transfer_item.approved_quantity
                    
                    if received_qty < 0 or received_qty > max_qty:
                        messages.error(request, f'Invalid received quantity for {transfer_item.item.itemnm}')
                        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

                    
                    transfer_item.received_quantity = received_qty
                    
                    if received_qty == 0:
                        transfer_item.status = 'cancelled'
                    elif received_qty < transfer_item.approved_quantity:
                        transfer_item.status = 'short_received'
                    else:
                        transfer_item.status = 'completed'
                    
                    transfer_item.save()
                    
                    # Update destination stock if needed
                    if transfer_item.destination_stock and received_qty < transfer_item.approved_quantity:
                        difference = transfer_item.approved_quantity - received_qty
                        transfer_item.destination_stock.qty -= difference
                        transfer_item.destination_stock.save()
                
                transfer.status = 'completed'
                transfer.received_by = request.user.id
                transfer.received_at = timezone.now()
                transfer.actual_delivery_date = timezone.now().date()
                transfer.remarks = remarks
                transfer.save()
                
                StockTransferLog.objects.create(
                    stock_transfer=transfer,
                    action='RECEIVED',
                    old_status='in_transit',
                    new_status='completed',
                    staff_id=request.user.id,
                    remarks=f'Received {len(selected_items)} items'
                )
                
                messages.success(request, 'Stock transfer completed successfully')
                
        except Exception as e:
            messages.error(request, f'Error: {str(e)}')
        
        return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")

    
    return redirect(f"{reverse('stock_transfer_detail')}?transferid={transfer.id}")



