def lab_invoice_payment(request):
    st=request.session.get('loginstaff')
    if not st:
        return redirect("staff_login")
    # Get invoice_id from GET or POST
    invoice_id = request.GET.get('invoice_id') or request.POST.get('invoice_id')
    
    if not invoice_id:
        messages.error(request, "Invoice ID not provided")
        return redirect('lab_invoice_list')
    
    try:
        invoice = get_object_or_404(LabInvoiceMaster, id=invoice_id)
        
        # Only allow credit invoices
        if invoice.payment_status != "Credit":
            messages.warning(request, "This invoice is already paid or not a credit invoice")
            return redirect('lab_invoice_list')
        
        # Handle POST request (Update Payment)
        if request.method == 'POST':
            # Get payment amounts
            cash_amount = float(request.POST.get('cash_amount') or 0)
            gpay_amount = float(request.POST.get('gpay_amount') or 0)
            card_amount = float(request.POST.get('card_amount') or 0)
            
            total_paid = cash_amount + gpay_amount + card_amount
            
            # Convert invoice.total from Decimal to float for comparison
            invoice_total = float(invoice.total)
            
            # Validate payment matches invoice total
            if total_paid <= 0:
                messages.error(request, "Please enter at least one payment amount")
                return redirect(f"{reverse('lab_invoice_payment')}?invoice_id={invoice_id}")
            
            if abs(total_paid - invoice_total) > 0.01:
                messages.error(request, f"Payment amount (₹{total_paid:.2f}) does not match invoice total (₹{invoice_total:.2f})")
                return redirect(f"{reverse('lab_invoice_payment')}?invoice_id={invoice_id}")
            
            # Update invoice with payment details (use Decimal for Decimal fields)
            invoice.cash_amount = Decimal(str(cash_amount))
            invoice.gpay_amount = Decimal(str(gpay_amount))
            invoice.card_amount = Decimal(str(card_amount))
            invoice.credit_amount = Decimal('0')
            invoice.is_credit = False
            invoice.payment_status = "Paid"
            invoice.save()
            
            messages.success(request, f"Payment completed successfully for invoice {invoice.invoiceno}!")
            
            # Redirect to print page
            return redirect(reverse('lab_invoice_print_option') + f"?invid={invoice.id}")
        
        # Handle GET request (Display Form)
        context = {
            'invoice': invoice,
        }
        return render(request, 'lab_invoice_payment.html', context)
        
    except Exception as e:
        messages.error(request, f"Error: {str(e)}")
        return redirect('lab_invoice_list')

