def procedure_master_add(request):
    """Add new procedure item (GET and POST in single function)"""
    branch_id = request.session.get('branch_id')
    staff_name = request.session.get('loginstaff_name1', 'Admin')
    print(branch_id)
    if request.method == 'POST':
        name = request.POST.get('name')
        rate = request.POST.get('rate')
        description = request.POST.get('description')
        
        # Validation
        if not name:
            messages.error(request, "Procedure name is required")
            return redirect('procedure_master_add')
        
        if not rate:
            rate = 0
        else:
            try:
                rate = float(rate)
            except ValueError:
                rate = 0
        existing_procedure = ProcedureMaster.objects.filter(name__iexact=name.strip())
        if existing_procedure.exists():
            messages.error(request, f"Procedure '{name}' already exists! Please use a different name.")
            return redirect('procedure_master_add')
        else:
            # Create procedure
            ProcedureMaster.objects.create(
            name=name,
            rate=rate,
            description=description,
            created_by=staff_name,
            branch_id_id=Branch.objects.get(id=branch_id).id if branch_id else None,
            is_active=True
        )
        
        messages.success(request, f"Procedure '{name}' added successfully!")
        return redirect('procedure_master_list')
    
    context = {
        'branch_id': branch_id,
    }
    return render(request, 'procedure_master_add.html', context)


