def generate_debit_note_number():
    today = timezone.now().date()
    
    # Financial year calculation (India)
    if today.month >= 4:
        start_year = today.year % 100
        end_year = (today.year + 1) % 100
    else:
        start_year = (today.year - 1) % 100
        end_year = today.year % 100

    year_prefix = f"{start_year:02d}/{end_year:02d}"
    
    last_note = DebitNote.objects.filter(
        debit_note_number__startswith=f"DN{year_prefix}"
    ).order_by('-id').first()
    
    if last_note and last_note.debit_note_number:
        last_number = last_note.debit_note_number
        
        without_dn = last_number[2:]  
        
        if '/' in without_dn:
            parts = without_dn.split('/')
            if len(parts) >= 2:
                sequence_part = parts[1]
                sequence = int(sequence_part[-4:]) if sequence_part else 0
                new_seq = sequence + 1
            else:
                new_seq = 1
        else:
            new_seq = 1
    else:
        new_seq = 1
    
    result = f"DN{year_prefix}{new_seq:04d}"
    return result

