def debit_note_create(request):
    if request.method == 'POST':
        try:
            with transaction.atomic():
                staff_id = request.session.get('staff_id') or 1
                try:
                    staff = Staffdetails.objects.get(id=staff_id)
                except Staffdetails.DoesNotExist:
                    staff = Staffdetails.objects.first()

                data = json.loads(request.POST.get('data', '{}'))
                if not data:
                    return JsonResponse({'success': False, 'message': 'No data provided'})

                supplier_id = data.get('supplier_id')
                supplier_instance = None
                if supplier_id:
                    from .models import supplier
                    try:
                        supplier_instance = supplier.objects.get(id=supplier_id)
                    except supplier.DoesNotExist:
                        pass
                
                # Create Debit Note
                debit_note = DebitNote.objects.create(
                    debit_note_number=generate_debit_note_number(),
                    debit_note_date=timezone.now().date(),
                    supplier=supplier_instance, # Assuming we set a single supplier, though UI might just use the first item's supplier
                    total_before_tax=data.get('total_before_tax', 0),
                    total_tax_amount=data.get('total_tax_amount', 0),
                    grand_total=data.get('grand_total', 0),
                    remarks=data.get('remarks', ''),
                    created_by=staff
                )
                
                items = data.get('items', [])
                if not items:
                    raise ValueError("No items in debit note")

                for item in items:
                    stock_id = item.get('stock_id')
                    return_qty = int(item.get('return_qty', 0))
                    remarks = item.get('remarks') or ''
                    stock = Physicalstockdetails.objects.select_for_update().get(id=stock_id)
                    if return_qty > stock.qty:
                        raise ValueError(f"Return quantity ({return_qty}) exceeds available stock ({stock.qty}) for {stock.itemnm.itemnm}")
                    
                    # Reduce stock
                    stock.qty -= return_qty
                    stock.save()
                    
                    if not debit_note.supplier and stock.suppliernm:
                        debit_note.supplier = stock.suppliernm
                        debit_note.save()

                    DebitNoteItem.objects.create(
                        debit_note=debit_note,
                        stock_item=stock,
                        medicine_name=stock.itemnm.itemnm,
                        batch_no=stock.Batch_no,
                        available_qty=stock.qty + return_qty, # original
                        return_qty=return_qty,
                        mrp=item.get('mrp', 0),
                        tax_percentage=item.get('tax_percentage', 0),
                        before_tax_amount=item.get('before_tax_amount', 0),
                        tax_amount=item.get('tax_amount', 0),
                        total_amount=item.get('total_amount', 0),
                        remarks=remarks
                    )
                
                return JsonResponse({
                    'success': True, 
                    'message': 'Debit Note created successfully',
                    'redirect_url': f'/debit-note-print/{debit_note.id}/'
                })
        except Exception as e:
            return JsonResponse({'success': False, 'message': str(e)})
    stocks = Physicalstockdetails.objects.filter(qty__gt=0,suppliernm__isnull=False, deleted=False).select_related('itemnm', 'suppliernm', 'stockbranch')
    from .models import supplier
    suppliers = supplier.objects.filter(id__in=stocks.values_list('suppliernm_id', flat=True).distinct())
    return render(request, 'debit_note_create.html', {'stocks': stocks,"suppliers":suppliers})

