def debit_note_delete(request, id):
    debit_note = get_object_or_404(DebitNote, id=id)
    try:
        with transaction.atomic():
            for item in debit_note.items.all():
                if item.stock_item:
                    stock = item.stock_item
                    stock.qty += item.return_qty
                    stock.save()
            debit_note.delete()
        from django.contrib import messages
        messages.success(request, 'Debit Note deleted successfully.')
    except Exception as e:
        from django.contrib import messages
        messages.error(request, f'Error deleting Debit Note: {str(e)}')
    return redirect('debit_note_list')


