def generate_purchase_invoice_number(branch_id):
    if not branch_id:
        raise ValueError("Branch ID is required")

    # 👇 Define branch codes manually here
    BRANCH_CODE_MAP = {
        5: "PLK",
        31: "JH",
     
    }

    # Get code from map (fallback if not found)
    branch_code = BRANCH_CODE_MAP.get(branch_id, f"BR{branch_id}")

    with transaction.atomic():
        fin_year = get_financial_year()
        prefix = f"PI/{branch_code}/{fin_year}/"

        last_invoice = PurchaseInvoice.objects.select_for_update().filter(
            branch_id=branch_id,
            invoice_number__startswith=prefix
        ).order_by('-id').first()

        if last_invoice:
            last_no = int(last_invoice.invoice_number.split('/')[-1])
            new_no = last_no + 1
        else:
            new_no = 1

        return f"{prefix}{str(new_no).zfill(4)}"


