@transaction.atomic
def save_purchase_invoice(request):
    """Save purchase invoice and optionally update stock based on user choice"""
    if request.method != 'POST':
        return JsonResponse({'error': 'Method not allowed'}, status=405)
    try:
        data = json.loads(request.body)
        # Debug print to see what data is coming
        print("Received data:", data)
        # Get add_to_stock flag from frontend (default to True for backward compatibility)
        add_to_stock = data.get('add_to_stock', True)
        print(f"Add to stock: {add_to_stock}")
        # Get or create staff
        try:
            staff = request.session.get('loginstaff')
        except Staffdetails.DoesNotExist:
            staff = request.session.get('loginstaff')
        if not staff:
            return JsonResponse({'error': 'Staff not found'}, status=400)
        # Get branch from session
        branch_id = request.session.get('branchid')
        invoice_number = generate_purchase_invoice_number(branch_id)
        branch = None
        if branch_id:
            try:
                branch = Branch.objects.get(id=branch_id)
            except Branch.DoesNotExist:
                branch = None
        def safe_decimal(value, default=Decimal('0')):
            """Safely convert value to Decimal, handling None and empty values"""
            if value is None:
                return default
            if isinstance(value, (int, float)):
                return Decimal(str(value))
            if isinstance(value, str) and value.strip() == '':
                return default
            try:
                return Decimal(str(value))
            except (ValueError, TypeError, decimal.InvalidOperation):
                return default
        subtotal = safe_decimal(data.get('subtotal', 0))
        discount_percent = safe_decimal(data.get('discount', 0))
        total_discount = (subtotal * discount_percent) / Decimal('100')
        with transaction.atomic():
            # Create Purchase Invoice
            invoice = PurchaseInvoice.objects.create(
                invoice_number=data['invoice_no'],
                invoice_date=data['invoice_date'],
                supplier_id=data['supplier_id'],
                store_id=data['store_id'],
                branch=branch,
                supplier_bill_number=data.get('bill_number', ''),
                supplier_bill_date=data.get('bill_date') or None,
                payment_terms=data.get('payment_terms', 'Net 30'),
                subtotal=Decimal(str(data.get('subtotal', 0))),
                total_discount=total_discount,
                total_gst=Decimal(str(data.get('total_gst', 0))),
                shipping_charge=Decimal(str(data.get('shipping_charge', 0))),
                other_charge=Decimal(str(data.get('other_charge', 0))),
                grand_total=Decimal(str(data.get('grand_total', 0))),
                notes=data.get('notes', ''),
                created_by_id=request.session.get('loginstaff'),
                # amount_in_words=data.get('amount_in_words'),
            )
            # Get supplier and store objects
            supplier_obj = supplier.objects.get(id=data['supplier_id'])
            store_obj = storedetails.objects.get(id=data['store_id'])

            # Helper function for safe Decimal conversion
            def safe_decimal(value, default=Decimal('0')):
                """Safely convert value to Decimal, handling None and empty values"""
                if value is None:
                    return default
                if isinstance(value, (int, float)):
                    return Decimal(str(value))
                if isinstance(value, str) and value.strip() == '':
                    return default
                try:
                    return Decimal(str(value))
                except (ValueError, TypeError, decimal.InvalidOperation):
                    return default
            
            # Save invoice items and optionally update stock
            for item in data['items']:
                # Get company_id from item if present, otherwise from main data
                item_company_id = item.get('company_id')
                
                # Safely get all decimal values
                purchase_rate = safe_decimal(item.get('purchase_rate', 0))
                wholesale_rate = safe_decimal(item.get('wholesale_rate', 0))
                retail_rate = safe_decimal(item.get('retail_rate', 0))
                # Calculate discount amount (if any)
                discount_percent = safe_decimal(item.get('discount', 0))
                discount_amount = Decimal('0')
                if discount_percent > 0:
                    discount_amount = purchase_rate * discount_percent / 100
                # Calculate GST amount
                gst_percent = safe_decimal(item.get('gst_percent', 0))
                gst_amount = purchase_rate * gst_percent / 100
                base_quantity = safe_decimal(item.get('base_quantity',0))
                base_rate = safe_decimal(item.get('base_rate',0))
                # Create invoice item
                PurchaseInvoiceItem.objects.create(
                    invoice=invoice,
                    medicine_id=item['medicine_id'],
                    company_id=item_company_id,
                    batch_no=item['batch_no'],
                    manufacturer_date=item.get('manufacture_date'),
                    expiry_date=item.get('expiry_date') or None,
                    hsn_code=item.get('hsn', ''),
                    quantity=item['qty'],
                    unt_id=item.get('unit_id'),
                    base_quantity=base_quantity,
                    total_base_quantity=item.get('total_base_quantity') or 0,
                    base_rate=base_rate,
                    free_quantity=item.get('free_qty', 0),
                    unit_price=purchase_rate,
                    discount_percent=discount_percent,
                    discount_amount=discount_amount,
                    gst_percent=gst_percent or 0,
                    gst_amount=gst_amount or 0,
                    total_amount=safe_decimal(item['total'], Decimal('0')),
                    wholesalerate=wholesale_rate,
                    retalrate=retail_rate
                )
                # Update or create stock ONLY if add_to_stock is True
                if add_to_stock:
                    medicine = medicinemaster.objects.get(id=item['medicine_id'])
                    total_qty = item['qty'] + item.get('free_qty', 0)
                    # Get unit for stock
                    unit = None
                    unit_id = item.get('unit_id')
                    if unit_id:
                        try:
                            from .models import unitdt
                            unit = unitdt.objects.filter(id=unit_id).first()
                        except:
                            pass
                    # Try to get existing stock or create new
                    stock, created = Physicalstockdetails.objects.get_or_create(
                        itemnm=medicine,
                        Batch_no=item['batch_no'],
                        suppliernm=supplier_obj,
                        storenm=store_obj,
                        defaults={
                            'unt': unit,
                            'Comapany_name_id': item_company_id,
                            'Manufacturer_date': item.get('manufacture_date') or None,
                            'Expiry_date': item.get('expiry_date') or None,
                            'purchase_rate': purchase_rate,
                            'wholesale_rate': wholesale_rate,
                            # 'total_base_quantity':item.get('total_base_quantity') or 0,
                            'Rate':Decimal(str(item['retail_rate'])) if item['retail_rate'] else purchase_rate,
                            'base_quantity':base_quantity,
                            'qty': item.get('total_base_quantity') if item.get('total_base_quantity') else  total_qty,
                            'base_rate':base_rate,
                            'lastupdatedate': timezone.now(),
                            'insertedstaffid_id': request.session.get('staffid'),
                            'stockbranch': branch,
                            'deleted': False,
                        }
                    )
                    if not created:
                        # stock.total_base_quantity += base_quantity*total_qty
                        stock.qty += base_quantity*total_qty if base_quantity else total_qty
                        stock.purchase_rate = purchase_rate
                        stock.wholesale_rate = wholesale_rate
                        stock.lastupdatedate = timezone.now()
                        stock.save()
                    # Create audit log
                    StockAuditLog.objects.create(
                        stock=stock,
                        action="PURCHASE",
                        staff_id=request.session.get('staffid'),
                        branch=branch,
                        store=store_obj,
                        item=medicine,
                        qty=total_qty,
                        action_date=timezone.now().date(),
                        action_time=timezone.now().time(),
                        remarks=f"Invoice: {invoice.invoice_number} | Supplier Bill: {data.get('bill_number', '')} | Batch: {item['batch_no']}"
                    )
                else:
                    # Stock not updated
                    print(f"Stock NOT updated for Invoice: {invoice.invoice_number} - Medicine: {item.get('medicine_name')}, Batch: {item['batch_no']}")
            # ✅ If we reach here, everything succeeded
            # Return success response with stock update status
            stock_message = "Stock has been updated." if add_to_stock else "Stock was not updated. You can add stock later."
        
        return JsonResponse({
            'success': True,
            'message': f'Invoice {invoice.invoice_number} saved successfully! {stock_message}',
            'invoice_id': invoice.id,
            'invoice_number': invoice.invoice_number,
            'stock_updated': add_to_stock
        })
        
    except supplier.DoesNotExist:
        return JsonResponse({'error': 'Supplier not found'}, status=400)
    except storedetails.DoesNotExist:
        return JsonResponse({'error': 'Store not found'}, status=400)
    except medicinemaster.DoesNotExist as e:
        return JsonResponse({'error': f'Medicine not found: {str(e)}'}, status=400)
    except Exception as e:
        import traceback
        traceback.print_exc()
        return JsonResponse({'error': str(e)}, status=500)

def search_medicines(request):
    """AJAX view to search medicines"""
    query = request.GET.get('q', '').strip()
    print(f"Search query: '{query}'")  # Debug log
    if len(query) < 2:
        return JsonResponse({'medicines': [], 'count': 0})
    try:
        # Search in medicinemaster
        medicines = medicinemaster.objects.filter(
            Q(itemnm__icontains=query) |
            Q(Generic_name__icontains=query) |
            Q(itemcode__icontains=query)
        ).select_related('taxpercentage', 'bsuntid')[:20]
        
        print(f"Found {medicines.count()} medicines")  # Debug log
        
        medicine_list = []
        for med in medicines:
            # Safely get tax rate
            tax_rate = '6'
            if med.taxpercentage:
                try:
                    tax_rate = str(med.taxpercentage.taxrate) if med.taxpercentage.taxrate else '6'
                except:
                    tax_rate = '6'
            
            # Safely get base unit
            base_unit = ''
            if med.bsuntid:
                try:
                    base_unit = med.bsuntid.unit if med.bsuntid.unit else ''
                except:
                    base_unit = ''
            
            medicine_list.append({
                'id': med.id,
                'itemnm': med.itemnm or '',
                'itemcode': med.itemcode or '',
                'Generic_name': med.Generic_name or '',
                'hsncode': med.hsncode or '',
                'taxpercentage__taxrate': tax_rate,
                'baseunit': base_unit,
            })
        
        return JsonResponse({
            'medicines': medicine_list,
            'count': len(medicine_list),
            'query': query
        })
        
    except Exception as e:
        print(f"Error in search_medicines: {str(e)}")
        import traceback
        traceback.print_exc()
        return JsonResponse({
            'medicines': [],
            'error': str(e),
            'query': query
        }, status=500)


def get_medicine_batches(request):
    """Get available batches for a medicine"""
    medicine_id = request.GET.get('medicine_id')
    
    if not medicine_id:
        return JsonResponse({'batches': []})
    
    batches = Physicalstockdetails.objects.filter(
        itemnm_id=medicine_id,
        deleted=False,
        qty__gt=0
    ).values('Batch_no', 'Expiry_date', 'purchase_rate', 'wholesale_rate').distinct()
    
    batch_list = []
    for batch in batches:
        batch_list.append({
            'Batch_no': batch['Batch_no'],
            'Expiry_date': batch['Expiry_date'].strftime('%Y-%m-%d') if batch['Expiry_date'] else '',
            'purchase_rate': str(batch['purchase_rate']) if batch['purchase_rate'] else '0',
            'wholesale_rate': str(batch['wholesale_rate']) if batch['wholesale_rate'] else '0',
        })
    
    return JsonResponse({'batches': batch_list})


