def purchase_invoice_list(request):
    """List all purchase invoices with totals - handles both initial load and AJAX"""
    
    # Get filter parameters
    from_date = request.GET.get('from_date')
    to_date = request.GET.get('to_date')
    is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest'
    
    # Start with all invoices
    invoices = PurchaseInvoice.objects.select_related('supplier', 'store', 'created_by').all().order_by('-id')
    
    # Apply date filters
    if from_date:
        invoices = invoices.filter(invoice_date__gte=from_date)
    if to_date:
        invoices = invoices.filter(invoice_date__lte=to_date)
    
    # Calculate totals from filtered data
    totals = invoices.aggregate(
        total_subtotal=Sum('subtotal'),
        total_gst=Sum('total_gst'),
        total_grand_total=Sum('grand_total')
    )
    
    # If AJAX request, return JSON
    if is_ajax:
        data = []
        for invoice in invoices:
            data.append({
                'id': invoice.id,
                'sl_no': invoice.id,
                'invoice_number': invoice.invoice_number,
                'invoice_date': invoice.invoice_date.strftime('%d-%m-%Y'),
                'supplier': invoice.supplier.shopname,
                'store': invoice.store.storename,
                'supplier_bill': invoice.supplier_bill_number or '-',
                'subtotal': float(invoice.subtotal),
                'gst': float(invoice.total_gst),
                'grand_total': float(invoice.grand_total),
                'created_by': f"{invoice.created_by.Staff.Staff_firstname or '-'} {invoice.created_by.Staff.Staff_lastname or ''}",
                'detail_url': f"/purchase-invoice/detail/?ids={invoice.id}"
            })
        
        return JsonResponse({
            'success': True,
            'data': data,
            'totals': {
                'total_subtotal': float(totals['total_subtotal'] or 0),
                'total_gst': float(totals['total_gst'] or 0),
                'total_grand_total': float(totals['total_grand_total'] or 0),
            }
        })
    
    # Regular page load
    context = {
        'invoices': invoices,
        'total_subtotal': totals['total_subtotal'] or 0,
        'total_gst': totals['total_gst'] or 0,
        'total_grand_total': totals['total_grand_total'] or 0,
        'from_date': from_date or '',
        'to_date': to_date or '',
    }
    return render(request, 'purchase_invoice_list.html', context)
