def testmaster_delete(request):
    """Soft delete a test group and its associated tests"""
    if request.method == 'POST':
        test_id = request.POST.get('test_id')
        
        if not test_id:
            return JsonResponse({'success': False, 'error': 'Test ID is required'})
        
        try:
            # Get the test group
            test_group = get_object_or_404(labtestmaster, id=test_id)
            
            # Store name for response message
            group_name = test_group.groupname
            
            # Check if there are any child tests
            child_count = labtestchild.objects.filter(group_id=test_group.id, status=True).count()
            
            # Soft delete the test group
            if hasattr(test_group, 'status'):
                test_group.status = False
                test_group.save()
            
            # Also soft delete all associated child tests
            child_tests = labtestchild.objects.filter(group_id=test_group.id, status=True)
            child_deleted_count = 0
            for child in child_tests:
                if hasattr(child, 'status'):
                    child.status = False
                    child.save()
                    child_deleted_count += 1
            
            return JsonResponse({
                'success': True, 
                'message': f'Test group "{group_name}" and {child_deleted_count} associated test(s) deleted successfully.',
                'deleted_count': child_deleted_count
            })
            
        except labtestmaster.DoesNotExist:
            return JsonResponse({'success': False, 'error': 'Test group not found.'})
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)})
    
    return JsonResponse({'success': False, 'error': 'Invalid request method.'})


# @login_required
def advance_register_ip(request):
    """Advance Register (IP) - Shows IP advance payments"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    from datetime import datetime, date
    
    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # Get all doctors from staff allocation
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ========== FETCH IP BILLS ==========
    records_query = IPBill.objects.select_related(
        'ip_admission',
        'ip_admission__MR_Number',
        'billingstaff',
        'billingstaff__Staff'
    ).all().order_by('-billing_date')
    
    # Apply date filter
    if from_date and to_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            records_query = records_query.filter(billing_date__range=[from_date_obj, to_date_obj])
        except ValueError:
            pass
    elif from_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            records_query = records_query.filter(billing_date__gte=from_date_obj)
        except ValueError:
            pass
    elif to_date:
        try:
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            records_query = records_query.filter(billing_date__lte=to_date_obj)
        except ValueError:
            pass
    
    # Apply doctor filter
    if doctor_id:
        records_query = records_query.filter(
            ip_admission__ippatientroombooking__admitteddoctor__Staff_id=doctor_id
        )
    
    # ========== BUILD RECORDS ==========
    records = []
    total_amount = 0
    
    for bill in records_query:
        admission = bill.ip_admission
        patient = admission.MR_Number if admission else None
        
        # Get IP number from admission
        ip_number = admission.ipnumber if admission and admission.ipnumber else "N/A"
        
        # Get billing staff name
        billing_staff_name = "N/A"
        if bill.billingstaff and bill.billingstaff.Staff:
            billing_staff_name = f"{bill.billingstaff.Staff.Staff_firstname} {bill.billingstaff.Staff.Staff_lastname}".strip()
        
        records.append({
            'id': bill.id,
            'date': bill.billing_date,
            'receipt_no': bill.ipinvoicenumber or f"REC-{bill.id}",
            'ip_number': ip_number,
            'patient_name': patient.Patient_Name if patient else "N/A",
            'amount': float(bill.advance_paid or 0),
            'billing_staff_name': billing_staff_name,
        })
        total_amount += float(bill.advance_paid or 0)
    
    # Format dates for display
    display_from_date = from_date
    display_to_date = to_date
    
    if not from_date and not to_date:
        today = date.today()
    else:
        if from_date:
            try:
                display_from_date = datetime.strptime(from_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_from_date = from_date
        if to_date:
            try:
                display_to_date = datetime.strptime(to_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date
    
    context = {
        'from_date': from_date,
        'to_date': to_date,
        'doctor_name': doctor_id,
        'doctors': doctor_list,
        'records': records,
        'total_amount': total_amount,
        'display_from_date': display_from_date,
        'display_to_date': display_to_date,
        'stdesign': staff_design_id,
    }
    return render(request, 'advance_register_ip.html', context)


