# @login_required
def admission_discharge_bill_register(request):
    """Admission Discharge Bill Register - Shows IP bills"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    from datetime import datetime, date
    from .models import IPBill, ippatientadmission, ippatientroombooking, PatientDischarge, Staffallocation
    
    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # ========== GET DOCTORS FOR DROPDOWN ==========
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],  # CMO, Associate Doctor, Doctor
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ========== FETCH IP BILLS ==========
    bills_query = IPBill.objects.select_related(
        'ip_admission',
        'ip_admission__MR_Number',
        'discharge',
        'billingstaff',
        'billingstaff__Staff'
    ).all()
    
    # Apply date filter
    if from_date and to_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            bills_query = bills_query.filter(billing_date__range=[from_date_obj, to_date_obj])
        except ValueError:
            pass
    elif from_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            bills_query = bills_query.filter(billing_date__gte=from_date_obj)
        except ValueError:
            pass
    elif to_date:
        try:
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            bills_query = bills_query.filter(billing_date__lte=to_date_obj)
        except ValueError:
            pass
    
    # Apply doctor filter
    if doctor_id:
        bills_query = bills_query.filter(
            ip_admission__ippatientroombooking__admitteddoctor__Staff_id=doctor_id
        )
    
    # ========== BUILD BILLS LIST WITH ALL DETAILS ==========
    bills = []
    for bill in bills_query.order_by('-billing_date'):
        admission = bill.ip_admission
        patient = admission.MR_Number if admission else None
        
        # Get room booking
        room_booking = None
        if admission:
            room_booking = ippatientroombooking.objects.filter(ipno=admission).first()
        
        # Get discharge details
        discharge = bill.discharge
        
        # Build bill record
        bill_data = {
            'id': bill.id,
            'ip_number': admission.ipnumber if admission else "N/A",
            'admission_date': admission.Current_Date if admission else None,
            'admission_time': room_booking.admissiontime if room_booking else None,
            'patient_name': patient.Patient_Name if patient else "N/A",
            'patient_address': patient.address if patient else "",
            'room': room_booking.room_number.Roomno if room_booking and room_booking.room_number else 
                    room_booking.bed_number.wardbedno if room_booking and room_booking.bed_number else "N/A",
            'discharge_date': discharge.discharged_date if discharge else None,
            'bill_no': bill.ipinvoicenumber if bill.ipinvoicenumber else "-",
            'total_amount': float(bill.total_amount or 0),
            'billing_staff': bill.billingstaff,
            'billing_staff_name': f"{bill.billingstaff.Staff.Staff_firstname} {bill.billingstaff.Staff.Staff_lastname}".strip() if bill.billingstaff and bill.billingstaff.Staff else "N/A",
        }
        bills.append(bill_data)
    
    # ========== FORMAT DATES FOR DISPLAY ==========
    display_from_date = from_date
    display_to_date = to_date
    
    if  from_date or  to_date:
        today = date.today()
        if from_date:
            try:
                display_from_date = datetime.strptime(from_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_from_date = from_date
        if to_date:
            try:
                display_to_date = datetime.strptime(to_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date
        
        if not to_date:
            try:
                display_to_date = today.strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date
    
    context = {
        'bills': bills,
        'from_date': from_date,
        'to_date': to_date,
        'display_from_date': display_from_date,
        'display_to_date': display_to_date,
        'doctor_name': doctor_id,
        'doctors': doctor_list,
        'stdesign': staff_design_id,
    }
    return render(request, 'admission_discharge_bill.html', context)


