def admission_register(request):
    """Admission Register - Shows all patient admissions"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
  
    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # ========== GET DOCTORS FOR DROPDOWN ==========
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],  # CMO, Associate Doctor, Doctor
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ========== FETCH ADMISSIONS ==========
    # Get all admitted patients (both active and discharged)
    patients_query = ippatientadmission.objects.select_related(
        'MR_Number',
        'admittedbranch'
    ).all().order_by('-Current_Date')
    
    # Apply date filter
    if from_date and to_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            patients_query = patients_query.filter(Current_Date__range=[from_date_obj, to_date_obj])
        except ValueError:
            pass
    elif from_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            patients_query = patients_query.filter(Current_Date__gte=from_date_obj)
        except ValueError:
            pass
    elif to_date:
        try:
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            patients_query = patients_query.filter(Current_Date__lte=to_date_obj)
        except ValueError:
            pass
    
    # Apply doctor filter
    if doctor_id:
        patients_query = patients_query.filter(
            ippatientroombooking__admitteddoctor__Staff_id=doctor_id
        )
    
    # ========== BUILD PATIENTS LIST WITH ALL DETAILS ==========
    patients = []
    sl_no = 1
    
    for admission in patients_query:
        patient = admission.MR_Number
        
        # Get room booking details
        room_booking = ippatientroombooking.objects.filter(ipno=admission).first()
        
        # Get discharge details if any
        discharge = PatientDischarge.objects.filter(ipptno=admission).first()
        
        # Get doctor name from room booking
        doctor_name_display = "N/A"
        if admission and admission.admitted_doctor:
            doctor_name_display = f"{admission.admitted_doctor.Staff.Staff_firstname} {admission.admitted_doctor.Staff.Staff_lastname}".strip()
        
        # Get room details
        room_display = "N/A"
        if room_booking:
            if room_booking.room_number:
                room_display = room_booking.room_number.Roomno
            elif room_booking.bed_number:
                room_display = room_booking.bed_number.wardbedno
            elif room_booking.roomdt:
                room_display = room_booking.roomdt.Roomno
        
        # Build patient details string
        patient_details = f"{patient.Patient_Name if patient else 'N/A'}"
        if patient and patient.address:
            patient_details += f"<br>{patient.address}"
        if patient and patient.contactno:
            patient_details += f"<br>+{patient.contactno}"
        
        # Build doctor/complaint string
        patient_credentials = ""
        if patient:
            gender_age = ""
            if patient.Gender:
                gender_age += patient.Gender
            if admission.age:
                gender_age += f"/{admission.age}" if gender_age else f"{admission.age}"
            patient_credentials = gender_age if gender_age else ""
        
        # Determine discharge status
        discharge_status = "Discharged" if discharge else "Active"
        discharge_date = discharge.discharged_date.strftime('%d/%m/%Y') if discharge else "Active"
        
        # Get user (admitted by)
        user_name = "N/A"
        # You can get this from admission.created_by if available
        if admission and admission.admitted_doctor_id:
            user_name= f"{admission.admitted_doctor.Staff.Staff_firstname} {admission.admitted_doctor.Staff.Staff_lastname}"
        # Build patient record
        patient_record = {
            'sl_no': sl_no,
            'date': admission.Current_Date,
            'ip_number': admission.ipnumber if admission else "N/A",
            'mr_number': patient.Medical_Record_Number if patient else "N/A",
            'patient_name': patient.Patient_Name if patient else "N/A",
            'patient_details': patient_details,
            'patient_credentials': patient_credentials,
            'room': room_display,
            'discharge': discharge_date,
            'user': user_name,
            'admission_id': admission.id,
        }
        patients.append(patient_record)
        sl_no += 1
    
    # ========== FORMAT DATES FOR DISPLAY ==========
    display_from_date = from_date
    display_to_date = to_date
    
    if not from_date and not to_date:
        today = date.today()
    else:
        today = date.today()
        if from_date:
            try:
                display_from_date = datetime.strptime(from_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_from_date = from_date
        if to_date:
            try:
                display_to_date = datetime.strptime(to_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date

        if not to_date:
            try:
                display_to_date = today.strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date
    
    context = {
        'patients': patients,
        'from_date': from_date,
        'to_date': to_date,
        'display_from_date': display_from_date,
        'display_to_date': display_to_date,
        'doctor_name': doctor_id,
        'doctors': doctor_list,
        'stdesign': staff_design_id,
    }
    return render(request, 'admission_register.html', context)


# ==================== CANCELLED BILLS REPORT ====================
# @login_required
def cancelled_bills_report(request):
    """Cancelled Bills Report - Shows cancelled invoices from newInvoiceMaster"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    

    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # Get all doctors for dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ========== FETCH CANCELLED INVOICES ==========
    # Get cancelled invoices (restockstatus=False means cancelled)
    invoices_query = newInvoiceMaster.objects.filter(restockstatus__in=[1]).select_related(
        'Mrno',
        'branch',
        'preparedby',
        'preparedby__Staff'
    ).order_by('-currentdate')
    
    if from_date and to_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            invoices_query = invoices_query.filter(currentdate__range=[from_date_obj, to_date_obj])
        except ValueError:
            pass
    elif from_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj= date.today()
            invoices_query = invoices_query.filter(currentdate__gte=from_date_obj)
        except ValueError:
            pass
    elif to_date:
        try:
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            invoices_query = invoices_query.filter(currentdate__lte=to_date_obj)
        except ValueError:
            pass
    
    # Apply doctor filter
    if doctor_id:
        invoices_query = invoices_query.filter(preparedby__Staff_id=doctor_id)
    
    # ========== BUILD INVOICES LIST ==========
    invoices = []
    sl_no = 1
    total_original = 0
    total_cancelled = 0
    total_refund = 0
    
    for invoice in invoices_query:
        # Get patient name
        patient_name = "N/A"
        if invoice.Mrno:
            patient_name = invoice.Mrno.Patient_Name
        else:
            patient_name=invoice.patientname
        
        # Get cancelled by (prepared by)
        cancelled_by = "N/A"
        if invoice.preparedby and invoice.preparedby.Staff:
            cancelled_by = f"{invoice.preparedby.Staff.Staff_firstname} {invoice.preparedby.Staff.Staff_lastname}".strip()
        
        # Calculate amounts
        cancelled_amount = 0
        refund_amount = 0
        original_amount = 0
        if invoice.restockstatus == 0:  # Active invoice (restockstatus = False/0)
            cancelled_amount = 0
            refund_amount = 0
            original_amount = float(invoice.total or 0)
            total_original += original_amount
        else:  
            cancelled_amount = float(invoice.total or 0)
            refund_amount = float(invoice.total or 0)
            original_amount=0
            total_cancelled += float(invoice.total or 0)
            total_refund += float(invoice.total or 0)

        total_original += original_amount
        total_cancelled += cancelled_amount
        total_refund += refund_amount
        
        invoices.append({
            'id':invoice.id,
            'sl_no': sl_no,
            'bill_no': invoice.Invoicenumber or f"BILL-{invoice.id}",
            'patient_name': patient_name,
            'bill_date': invoice.currentdate,
            'original_amount': original_amount,
            'cancelled_amount': cancelled_amount,
            'refund_amount': refund_amount,
            'cancelled_by': cancelled_by,
        })
        sl_no += 1
    
    # Format dates for display
    display_from_date = from_date
    display_to_date = to_date
    
    display_from_date = from_date
    display_to_date = to_date
    
    if not from_date and not to_date:
        today = date.today()
    else:
        today = date.today()
        if from_date:
            try:
                display_from_date = datetime.strptime(from_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_from_date = from_date
        if to_date:
            try:
                display_to_date = datetime.strptime(to_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date

        if not to_date:
            try:
                display_to_date = today.strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date
    
    context = {
        'from_date': from_date,
        'to_date': to_date,
        'display_from_date': display_from_date,
        'display_to_date': display_to_date,
        'doctor_name': doctor_id,
        'doctors': doctor_list,
        'invoices': invoices,
        'total_original': total_original,
        'total_cancelled': total_cancelled,
        'total_refund': total_refund,
        'stdesign': staff_design_id,
    }
    return render(request, 'cancelled_billdetails.html', context)


# ==================== PATIENT REGISTER REPORT ====================
# @login_required
def patient_register_report(request):
    """Birth Register Report - Shows birth registration records"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    gender = request.GET.get('gender', '')
    
    # Get birth registrations
    birth_records = BirthRegister.objects.select_related('mother', 'created_by').all()
    
    # Apply date filters
    if from_date:
        birth_records = birth_records.filter(created_at__date__gte=from_date)
    if to_date:
        birth_records = birth_records.filter(created_at__date__lte=to_date)
    
    # Apply gender filter
    if gender:
        birth_records = birth_records.filter(gender=gender)
    
    # Order by created_at descending
    birth_records = birth_records.order_by('-id')
    
    # Prepare data for template
    birth_data = []
    for record in birth_records:
        # Get mother's OP number (Medical_Record_Number)
        mother_op = record.mother.Medical_Record_Number if record.mother else 'N/A'
        mother_name = record.mother.Patient_Name if record.mother else 'N/A'
        
        # Get mother's address
        mother_address = record.mother.address if record.mother else 'N/A'
        if record.guardian_address:
            mother_address = record.guardian_address
        
        
        
        birth_data.append({
            'id': record.id,
            'child_op': record.child_op,
            'child_name': f"Baby of {mother_name}",
            'birth_time': record.date_time_of_birth.strftime('%H:%M:%S') if record.date_time_of_birth else 'N/A',
            'birth_date': record.date_time_of_birth.strftime('%d-%m-%Y') if record.date_time_of_birth else 'N/A',
            'weight': record.weight or 'N/A',
            'mother_op': mother_op,
            'mother_name': mother_name,
            'address': mother_address,
            'gender': record.gender or 'N/A',
            'area': mother_address,
            'blood_group': record.blood_group or 'N/A',
            'guardian_phone': record.guardian_phone or 'N/A',
            'created_by': f"{record.created_by.Staff_firstname} {record.created_by.Staff_lastname}" if record.created_by else 'System',
            'created_at': record.created_at.strftime('%d-%m-%Y %H:%M')
        })
    
    context = {
        'birth_data': birth_data,
        'from_date': from_date,
        'to_date': to_date,
        'gender': gender,
        'total_records': len(birth_data),
        'stdesign': staff_design_id,
    }
    return render(request, 'birth_register_report.html', context)


# ==================== DISCHARGE REGISTER ====================
# @login_required
def discharge_register(request):
    """Discharge Register - Shows discharged patients with pagination and print"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    from datetime import datetime, date
    
    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # Get all doctors for dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ========== FETCH DISCHARGES ==========
    discharges = PatientDischarge.objects.select_related(
        'ipptno',
        'ipptno__MR_Number',
        'dischargedstaff',
        'dischargedstaff__Staff'
    ).annotate(
        days_stayed=ExpressionWrapper(
            F('discharged_date') - F('ipptno__Current_Date'),
            output_field=fields.DurationField()
        )
    ).all().order_by('-discharged_date')
    
    # Apply date filter
    if from_date and to_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            discharges = discharges.filter(discharged_date__range=[from_date_obj, to_date_obj])
        except ValueError:
            pass
    elif from_date:
        try:
            from_date_obj = datetime.strptime(from_date, '%Y-%m-%d').date()
            discharges = discharges.filter(discharged_date__gte=from_date_obj)
        except ValueError:
            pass
    elif to_date:
        try:
            to_date_obj = datetime.strptime(to_date, '%Y-%m-%d').date()
            discharges = discharges.filter(discharged_date__lte=to_date_obj)
        except ValueError:
            pass
    
    # Apply doctor filter
    if doctor_id:
        discharges = discharges.filter(dischargedstaff__Staff_id=doctor_id)
    
    # Build discharge data list
    discharge_data = []
    for discharge in discharges:
        # Get room number
        room_booking = ippatientroombooking.objects.filter(ipno=discharge.ipptno).first()
        room_no = room_booking.room_number.Roomno if room_booking and room_booking.room_number else '-'
        
        # Calculate days stayed
        days_stayed = (discharge.discharged_date - discharge.ipptno.Current_Date).days if discharge.ipptno.Current_Date else 0
        
        discharge_data.append({
            'discharged_date': discharge.discharged_date,
            'sl_no': discharge.id,
            'room': room_no,
            'ip_number': discharge.ipptno.ipnumber if discharge.ipptno else '-',
            'patient_name': discharge.ipptno.MR_Number.Patient_Name if discharge.ipptno and discharge.ipptno.MR_Number else 'N/A',
            'address': discharge.ipptno.MR_Number.address if discharge.ipptno and discharge.ipptno.MR_Number else '',
            'admission_date': discharge.ipptno.Current_Date if discharge.ipptno else None,
            'days_stayed': days_stayed,
            'remarks': discharge.additional_notes or '-'
        })
    
    # Get hospital details
    hospital = Hospitaldetails.objects.first()
    
    # All data for print
    all_discharge_data = discharge_data.copy()
    
    # Pagination - 20 items per page
    paginator = Paginator(discharge_data, 10)
    page = request.GET.get('page', 1)
    
    try:
        discharge_data_page = paginator.page(page)
    except PageNotAnInteger:
        discharge_data_page = paginator.page(1)
    except EmptyPage:
        discharge_data_page = paginator.page(paginator.num_pages)
    
    # Format dates for display
    display_from_date = from_date
    display_to_date = to_date
    
    if not from_date and not to_date:
        today = date.today()
    else:
        if from_date:
            try:
                display_from_date = datetime.strptime(from_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_from_date = from_date
        if to_date:
            try:
                display_to_date = datetime.strptime(to_date, '%Y-%m-%d').strftime('%d/%m/%Y')
            except ValueError:
                display_to_date = to_date
    
    context = {
        'discharge_data': discharge_data_page,
        'all_discharge_data': all_discharge_data,
        'total_count': len(discharge_data),
        'from_date': from_date,
        'to_date': to_date,
        'display_from_date': display_from_date,
        'display_to_date': display_to_date,
        'doctor_name': doctor_id,
        'doctors': doctor_list,
        'hospital': hospital,
        'stdesign': staff_design_id,
    }
    
    return render(request, 'discharge_register.html', context)


# ==================== DEATHS DURING ADMISSION PERIOD ====================
# @login_required
def deaths_during_admission(request):
    """Deaths During Admission - Shows patients who died during admission"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    # Get date range from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_name = request.GET.get('doctor', '')
    
    # Get death records from DeathRegister
    deaths = DeathRegister.objects.select_related('patient', 'created_by').all().order_by('-id')
    
    # Apply date filters (using death_datetime)
    if from_date:
        deaths = deaths.filter(death_datetime__date__gte=from_date)
    if to_date:
        deaths = deaths.filter(death_datetime__date__lte=to_date)
    
    # Apply doctor filter
    if doctor_name:
        deaths = deaths.filter(consulting_doctor_id=doctor_name)
    
    # Order by death_datetime descending
    deaths = deaths.order_by('-id')
    
    # Prepare data for template
    death_data = []
    for index, record in enumerate(deaths, start=1):
        # Get patient details
        if record.registration_type == 'registered' and record.patient:
            patient_name = record.patient.Patient_Name
            gender = record.patient.Gender
            age = record.patient.Age or 'N/A'
            ip_number = 'N/A'
            if ippatientadmission.objects.filter(MR_Number=record.patient,Admittedstatus=True):
                ip_number = ippatientadmission.objects.get(MR_Number=record.patient,Admittedstatus=True).ipnumber or 'Unregistered'
        else:
            patient_name = record.unregistered_name or 'N/A'
            gender = record.unregistered_gender or 'N/A'
            age = record.unregistered_age or 'N/A'
            ip_number = 'Unregistered'
        
        # Format gender for display
        gender_display = 'Male' if gender == 'Male' else 'Female' if gender == 'Female' else 'Others'
        
        # Format dates
        admission_datetime = record.admission_datetime.strftime('%d/%m/%Y %H:%M') if record.admission_datetime else 'N/A'
        death_datetime = record.death_datetime.strftime('%d/%m/%Y %H:%M') if record.death_datetime else 'N/A'
        
        death_data.append({
            'id': record.id,
            'sl_no': index,
            'ip_number': ip_number,
            'patient_name': patient_name,
            'gender_age': f"{gender_display} / {age}",
            'room': record.room or 'N/A',
            'admission_datetime': admission_datetime,
            'death_datetime': death_datetime,
            'consulting_doctor': record.consulting_doctor.Staff.Staff_firstname + ' ' + record.consulting_doctor.Staff.Staff_lastname if record.consulting_doctor and record.consulting_doctor.Staff else 'N/A',            'id': record.id,
            'registration_type': record.registration_type
        })
    
    # Get unique doctors for filter dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    context = {
        'death_data': death_data,
        'doctors': doctor_list,
        'from_date': from_date,
        'to_date': to_date,
        'doctor_name': doctor_name,
        'total_deaths': len(death_data),
        'stdesign': staff_design_id,
    }
    return render(request, 'death_during_admissionperiod.html', context)


def get_base_quantity(request):
    if request.method == 'GET':
        unit_id = request.GET.get('unit_id')
        
        if not unit_id:
            return JsonResponse({'error': 'Missing parameters'}, status=400)
        
        try:
            from .models import unitdt
            
            # Get the unit
            unit = unitdt.objects.get(pk=unit_id)
            unit_name = unit.unitname.upper() if unit.unitname else ''
            
            # Only return base_quantity if unit is STRP/STRIP
            if 'STRP' in unit_name or 'STRIP' in unit_name:
                base_quantity = unit.basequantity or 0
                return JsonResponse({
                    'success': True,
                    'base_quantity': base_quantity,
                    'unit_name': unit.unitname
                })
            else:
                return JsonResponse({
                    'success': True,
                    'base_quantity': 0,
                    'unit_name': unit.unitname,
                    'message': 'Not a STRIP unit'
                })
        except Exception as e:
            return JsonResponse({'error': str(e)}, status=500)
    
    return JsonResponse({'error': 'Method not allowed'}, status=405)

def get_unit_details(request):
    if request.method == 'GET':
        med_id = request.GET.get('med_id')
        batch_no = request.GET.get('batch_no')
        unit_name = request.GET.get('unit', '').upper()
        branch_id = request.session.get('branchid')
        
        if not med_id or not batch_no:
            return JsonResponse({'success': False, 'error': 'Missing parameters'}, status=400)
        
        try:
            # Get the medicine
            medicine = medicinemaster.objects.get(id=med_id)
            
            # Get stock details for this medicine and batch
            stock = Physicalstockdetails.objects.filter(
                itemnm=medicine,
                Batch_no=batch_no,
                stockbranch_id=branch_id,
                deleted=False
            ).first()
            
            if not stock:
                return JsonResponse({'success': False, 'error': 'Stock not found'}, status=404)
            
            # Check if the selected unit is STRIP/STRP
            is_strip = 'STRP' in unit_name or 'STRIP' in unit_name
            
            # Get base_quantity from unit master
            unit_obj = unitdt.objects.filter(unitname__iexact=unit_name).first()
            base_quantity = unit_obj.basequantity if unit_obj and is_strip else 1
            
            # Calculate base_rate if unit is STRIP
            base_rate = 0
            if is_strip and base_quantity > 0 and stock.Rate:
                base_rate = float(stock.Rate) / base_quantity
            
            # If selected unit is TAB or NOS, use base_rate
            rate_to_use = float(stock.Rate)
            if (unit_name == 'TAB' or unit_name == 'NOS') and base_rate > 0:
                rate_to_use = base_rate
            
            return JsonResponse({
                'success': True,
                'base_quantity': base_quantity,
                'base_rate': base_rate,
                'rate': rate_to_use,
                'tax': float(medicine.taxpercentage.taxrate) if medicine.taxpercentage else 0,
                'is_strip': is_strip
            })
            
        except Exception as e:
            return JsonResponse({'success': False, 'error': str(e)}, status=500)
    
    return JsonResponse({'success': False, 'error': 'Method not allowed'}, status=405)

def get_stock_details(request):
    """Get detailed stock information including base quantity and total base quantity"""
    med_id = request.GET.get('med_id')
    batch_no = request.GET.get('batchId')
    comp_id = request.GET.get('compid')
    supp_id = request.GET.get('selectedsupid')
    stock_branch = request.GET.get('stockbranch')
    
    if not all([med_id, batch_no, stock_branch]):
        return JsonResponse({'error': 'Missing required parameters'}, status=400)
    
    try:
        # Build the filter
        filter_kwargs = {
            'itemnm_id': med_id,
            'Batch_no': batch_no,
            'stockbranch_id': stock_branch,
            'deleted': False
        }
        
        # Add optional filters
        if supp_id:
            filter_kwargs['suppliernm_id'] = supp_id
        if comp_id:
            filter_kwargs['Comapany_name_id'] = comp_id
        
        # Get the stock item
        stock_item = Physicalstockdetails.objects.get(**filter_kwargs)
        
        # Extract tablets per strip from unit if applicable
        tablets_per_strip = 1
        if stock_item.unit:
            import re
            # Check if unit contains STRP (case insensitive)
            if 'STRP' in stock_item.unit.upper():
                match = re.search(r'(\d+)\s*\*\s*(\d+)\s*STRP', stock_item.unit, re.IGNORECASE)
                if match:
                    tablets_per_strip = int(match.group(2))
                else:
                    match = re.search(r'(\d+)\s*STRP', stock_item.unit, re.IGNORECASE)
                    if match:
                        tablets_per_strip = int(match.group(1))
        
        return JsonResponse({
            'quantity': stock_item.quantity or 0,
            'base_quantity': stock_item.base_quantity or tablets_per_strip,
            'total_base_quantity': stock_item.total_base_quantity or 0,
            'unit': stock_item.unit,
            'bsunit': stock_item.bsunit,
            'available_stock': stock_item.quantity,
            'stock_status': 'Available'
        })
        
    except Physicalstockdetails.DoesNotExist:
        return JsonResponse({
            'quantity': 0,
            'base_quantity': 0,
            'total_base_quantity': 0,
            'stock_status': 'Out Of Stock'
        })
    except Exception as e:
        return JsonResponse({
            'quantity': 0,
            'base_quantity': 0,
            'total_base_quantity': 0,
            'stock_status': 'Error',
            'error': str(e)
        })


def sales_return_report(request):
    """
    Simple Sales Return Report with day-wise totals and pagination
    """
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    bill_type = request.GET.get('bill_type', '')
    
    # Start with all credit notes
    credit_notes = CreditNoteMaster.objects.all()
    
    # Apply date filter
    if from_date and to_date:
        credit_notes = credit_notes.filter(creditnote_date__range=[from_date, to_date])
    elif from_date and not to_date:
        to_date = date.today().strftime('%Y-%m-%d')
        credit_notes = credit_notes.filter(creditnote_date__range=[from_date, to_date])
    elif not from_date and to_date:
        from_date = date.today().replace(day=1).strftime('%Y-%m-%d')
        credit_notes = credit_notes.filter(creditnote_date__range=[from_date, to_date])
    
    # Apply bill type filter
    if bill_type:
        if bill_type == 'Cash':
            credit_notes = credit_notes.filter(
                Q(invoicemaster__payementmode__icontains='Cash') |
                Q(invoicemaster__payementmode__icontains='cash')
            )
        elif bill_type == 'Credit':
            credit_notes = credit_notes.filter(
                Q(invoicemaster__payementmode__icontains='Credit') |
                Q(invoicemaster__payementmode__icontains='credit')
            )
    
    # Build grouped data by date and credit_no
    total_amount = 0
    day_totals = {}
    grouped_data = {}  # Group by credit_note_id to avoid duplicates
    
    for credit_note in credit_notes.order_by('creditnote_date', '-id'):
        items = CreditNoteChild.objects.filter(creditnote_master=credit_note)
        day_total = 0
        credit_note_total = 0
        
        date_str = credit_note.creditnote_date.strftime('%d/%m/%Y') if credit_note.creditnote_date else ''
        credit_no = credit_note.creditnote_number
        
        # Group by credit_note_id
        if credit_note.id not in grouped_data:
            grouped_data[credit_note.id] = {
                'date': credit_note.creditnote_date,
                'credit_no': credit_no,
                'credit_note_id': credit_note.id,
                'items': [],
                'total': 0
            }
        
        for item in items:
            amount = float(item.total or item.amount or 0)
            total_amount += amount
            day_total += amount
            credit_note_total += amount
            
            grouped_data[credit_note.id]['items'].append({
                'product_name': item.particulars or 'N/A',
                'batch': item.invoice_child.batchno if item.invoice_child else '',
                'quantity': item.quantity,
                'amount': amount
            })
        
        grouped_data[credit_note.id]['total'] = credit_note_total
        
        # Store day-wise total
        if date_str in day_totals:
            day_totals[date_str] += day_total
        else:
            day_totals[date_str] = day_total
    
    # Convert grouped_data dict to list
    grouped_list = list(grouped_data.values())
    
    # Sort by date (newest first)
    grouped_list.sort(key=lambda x: x['date'], reverse=True)
    
    # Get hospital details
    hospital = Hospitaldetails.objects.first()
    
    # Pagination for grouped data
    paginator = Paginator(grouped_list, 10)
    page = request.GET.get('page', 1)
    
    try:
        grouped_page = paginator.page(page)
    except PageNotAnInteger:
        grouped_page = paginator.page(1)
    except EmptyPage:
        grouped_page = paginator.page(paginator.num_pages)
    
    context = {
        'grouped_data': grouped_page,  # Paginated grouped data
        'all_grouped_data': grouped_list,  # All grouped data for print
        'total_amount': total_amount,
        'total_count': len(grouped_list),
        'from_date': from_date,
        'to_date': to_date,
        'bill_type': bill_type,
        'day_totals': day_totals,
        'hospital': hospital,
    }
    
    return render(request, 'salesreturnreport.html', context)


def purchase_statement_report(request):
    """
    Purchase Statement Report with pagination and print functionality
    Using PurchaseInvoice and PurchaseInvoiceItem models
    """
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    supplier_filter = request.GET.get('supplier', '')
    bill_type = request.GET.get('bill_type', '')
    
    # Start with all Purchase Invoices
    purchase_invoices = PurchaseInvoice.objects.all().select_related('supplier', 'branch')
    
    # Apply date filter - only if both dates are provided
    if from_date and to_date:
        purchase_invoices = purchase_invoices.filter(invoice_date__range=[from_date, to_date])
    elif from_date and not to_date:
        to_date = date.today().strftime('%Y-%m-%d')
        purchase_invoices = purchase_invoices.filter(invoice_date__range=[from_date, to_date])
    elif not from_date and to_date:
        from_date = date.today().replace(day=1).strftime('%Y-%m-%d')
        purchase_invoices = purchase_invoices.filter(invoice_date__range=[from_date, to_date])
    
    # Apply supplier filter
    if supplier_filter:
        purchase_invoices = purchase_invoices.filter(supplier_id=supplier_filter)
    
    # Build the purchase statement data
    purchase_data = []
    total_amount = 0
    total_qty = 0
    invoice_totals = {}
    suppliers_with_invoices = set()
    for invoice in purchase_invoices.order_by('invoice_date', '-id'):
        items = PurchaseInvoiceItem.objects.filter(invoice=invoice)
        invoice_total = 0
        invoice_qty = 0
        invoice_id = invoice.id
        if invoice.supplier:
            suppliers_with_invoices.add(invoice.supplier.id)
        for item in items:
            qty = float(item.quantity or 0)
            rate = float(item.unit_price or 0)
            amount = qty * rate
            free_qty = float(item.free_quantity or 0)
            
            purchase_data.append({
                'date': invoice.invoice_date,
                'invoice_no': invoice.invoice_number,
                'party': invoice.supplier.shopname if invoice.supplier else 'N/A',
                'product': item.medicine.itemnm if item.medicine else 'N/A',
                'batch': item.batch_no or '',
                'bill_no': invoice.supplier_bill_number or '',
                'qty': qty,
                'free_qty': free_qty,
                'rate': rate,
                'amount': amount,
                'invoice_id': invoice_id,
            })
            
            invoice_total += amount
            invoice_qty += qty
            total_amount += amount
            total_qty += qty
        
        # Store Invoice-wise total
        invoice_totals[invoice.invoice_number] = {
            'total': invoice_total,
            'qty': invoice_qty,
            'date': invoice.invoice_date,
            'invoice_id': invoice_id,
        }
    
    # Get all suppliers for filter dropdown
    suppliers = supplier.objects.filter(
        id__in=suppliers_with_invoices
    ).order_by('shopname')
    
    # Get hospital details from database
    hospital = Hospitaldetails.objects.first()
    
    # All data for print
    all_purchase_data = purchase_data.copy()
    
    # Pagination - 25 items per page
    paginator = Paginator(purchase_data, 10)
    page = request.GET.get('page', 1)
    
    try:
        purchase_data_page = paginator.page(page)
    except PageNotAnInteger:
        purchase_data_page = paginator.page(1)
    except EmptyPage:
        purchase_data_page = paginator.page(paginator.num_pages)
    
    context = {
        'purchase_data': purchase_data_page,
        'all_purchase_data': all_purchase_data,
        'total_amount': total_amount,
        'total_qty': total_qty,
        'total_count': len(purchase_data),
        'from_date': from_date,
        'to_date': to_date,
        'supplier_filter': supplier_filter,
        'bill_type': bill_type,
        'invoice_totals': invoice_totals,
        'hospital': hospital,
        'suppliers': suppliers,
    }
    
    return render(request, 'purchase_statement_report.html', context)


def sales_statement_report(request):
    """
    Sales Statement Report with pagination and print functionality
    Using newInvoiceMaster and newInvoiceChild models
    """
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    patient_filter = request.GET.get('patient', '')
    bill_type = request.GET.get('bill_type', '')
    search_term = request.GET.get('search', '')

    # Start with all Sales Invoices
    sales_invoices = newInvoiceMaster.objects.filter(restockstatus=True).select_related('branch', 'Mrno', 'preparedby')
    
    # Apply date filter - only if both dates are provided
    if from_date and to_date:
        sales_invoices = sales_invoices.filter(currentdate__range=[from_date, to_date])
    elif from_date and not to_date:
        to_date = date.today().strftime('%Y-%m-%d')
        sales_invoices = sales_invoices.filter(currentdate__range=[from_date, to_date])
    elif not from_date and to_date:
        from_date = date.today().replace(day=1).strftime('%Y-%m-%d')
        sales_invoices = sales_invoices.filter(currentdate__range=[from_date, to_date])

    # Apply patient filter
    if patient_filter:
        sales_invoices = sales_invoices.filter( Q(patientname__icontains=patient_filter) |
                    Q(Mrno__Patient_Name__icontains=patient_filter))

    if search_term:
        # Search in invoice fields
        invoice_matches = sales_invoices.filter(
            Q(Invoicenumber__icontains=search_term) |
            Q(patientname__icontains=search_term) |
            Q(Mrno__Patient_Name__icontains=search_term) |
            Q(Mrno__Medical_Record_Number__icontains=search_term) |
            Q(Mrno__contactno__icontains=search_term)
        )
    # Build the sales statement data
    sales_data = []
    total_amount = 0
    total_qty = 0
    invoice_totals = {}
    for invoice in sales_invoices.order_by('currentdate', '-id'):
        items = newInvoiceChild.objects.filter(invmasterid=invoice)
        invoice_total = 0
        invoice_qty = 0
        invoice_id = invoice.id
        # Get patient name
        patient_name = invoice.patientname or 'N/A'
        if invoice.Mrno:
            patient_name = invoice.Mrno.Patient_Name if invoice.Mrno.Patient_Name else patient_name
        for item in items:
            qty = float(item.quantity or 0)
            rate = float(item.amount or 0)
            amount = float(item.sutotal or 0)
            
            sales_data.append({
                'date': invoice.currentdate,
                'bill_no': invoice.Invoicenumber,
                'patient': patient_name,
                'product': item.particulars or 'N/A',
                'batch': item.batchno or '',
                'qty': qty,
                'rate': rate,
                'amount': amount,
                'is_discount': False,
                'discount_amount': 0,
                'invoice_id': invoice_id
            })
            
            invoice_total += amount
            invoice_qty += qty
            total_amount += amount
            total_qty += qty
        
        # Add discount/roundoff row if discount exists
        if invoice.discount and float(invoice.discount) > 0:
            discount_amount = float(invoice.discount)
            sales_data.append({
                'date': invoice.currentdate,
                'bill_no': invoice.Invoicenumber,
                'patient': patient_name,
                'product': f'Discount {invoice.discount}%',
                'batch': '',
                'qty': 0,
                'rate': 0,
                'amount': -discount_amount,
                'is_discount': True,
                'discount_amount': discount_amount,
                'invoice_id':invoice_id
            })
            invoice_total -= discount_amount
        
        # Store Invoice-wise total
        invoice_totals[invoice.Invoicenumber] = {
            'total': invoice_total,
            'qty': invoice_qty,
            'date': invoice.currentdate,
            'patient': patient_name,
            'invoice_id': invoice_id,
        }
    
    # Get all patients for filter dropdown
    
    
    # Get hospital details from database
    hospital = Hospitaldetails.objects.first()
    
    # All data for print
    all_sales_data = sales_data.copy()
    
    # Pagination - 25 items per page
    paginator = Paginator(sales_data, 25)
    page = request.GET.get('page', 1)
    
    try:
        sales_data_page = paginator.page(page)
    except PageNotAnInteger:
        sales_data_page = paginator.page(1)
    except EmptyPage:
        sales_data_page = paginator.page(paginator.num_pages)
    
    context = {
        'sales_data': sales_data_page,
        'all_sales_data': all_sales_data,
        'total_amount': total_amount,
        'total_qty': total_qty,
        'total_count': len(sales_data),
        'from_date': from_date,
        'to_date': to_date,
        'patient_filter': patient_filter,
        'bill_type': bill_type,
        'invoice_totals': invoice_totals,
        'hospital': hospital,
        'search_term': search_term,
        'patient_filter':patient_filter,
    }
    
    return render(request, 'sales_statement_report.html', context)


