def doctorwise_op_registration(request):
    """Doctor Wise OP Registration - Shows OP registrations by doctor"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    visit_type = request.GET.get('visit_type', '')
    
    # Get all doctors
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # Get appointments
    appointments = Appointments.objects.select_related('MR_Number', 'Doctor_Name', 'Branch')
    
    if from_date and to_date:
        appointments = appointments.filter(Appointment_date__range=[from_date, to_date])
    
    if doctor_id:
        appointments = appointments.filter(Doctor_Name_id=doctor_id)
    
    # Track first visit per patient (by date and id order)
    patient_first_visit = {}  # key: patient_id, value: first appointment id
    
    # First pass: Find the first appointment (by date and id) for each patient
    for appt in appointments.order_by('Appointment_date', 'id'):
        patient_id = appt.MR_Number_id
        if patient_id and patient_id not in patient_first_visit:
            patient_first_visit[patient_id] = appt.id
    
    # Build registration data
    reg_data = []
    total_reg_fees = 0
    total_cons_fees = 0
    total_count = 0
    
    for appt in appointments.order_by('-Appointment_date', '-id'):
        patient_id = appt.MR_Number_id
        
        # ✅ Get reg_Fee - Only for first visit, else 0
        reg_fees = 0
        if appt.MR_Number:
            # Check if this is the first visit for this patient (by appointment id)
            if patient_id in patient_first_visit and patient_first_visit[patient_id] == appt.id:
                reg_fees = float(appt.MR_Number.reg_Fee or 0)
            else:
                reg_fees = 0  # Subsequent visits - no registration fee
        
        # ✅ Get consultation fee from Appointment Fee field
        cons_fees = 0
        if appt.status:
            status_lower = appt.status.lower()
            # Consultation fee for consultation status
            if 'consultation' in status_lower or 'new' in status_lower:
                cons_fees = float(appt.Fee or 0)
            # Followup fee for followup status
            elif 'followup' in status_lower:
                cons_fees = float(appt.Fee or 0)
            # Revisit fee for revisit status
            elif 'revisit' in status_lower:
                cons_fees = float(appt.Fee or 0)
        
        reg_data.append({
            'sl_no': len(reg_data) + 1,
            'doctor_name': f"{appt.Doctor_Name.Staff_firstname} {appt.Doctor_Name.Staff_lastname}".strip() if appt.Doctor_Name else 'N/A',
            'op_number': appt.MR_Number.Medical_Record_Number if appt.MR_Number else '-',
            'date': appt.Appointment_date if appt.Appointment_date else '-',
            'token': appt.Tokenno,
            'patient_details': f"{appt.MR_Number.Patient_Name if appt.MR_Number else 'N/A'} ({appt.MR_Number.Gender if appt.MR_Number else 'N/A'}/{appt.MR_Number.Age if appt.MR_Number else '0'} Y)" if appt.MR_Number else 'N/A',
            'reg_fees': reg_fees,
            'cons_fees': cons_fees,
            'id': appt.id,
        })
        total_reg_fees += reg_fees
        total_cons_fees += cons_fees
        total_count += 1
    

    context = {
        'reg_data': reg_data,
        'total_count': total_count,
        'total_reg_fees': total_reg_fees,
        'total_cons_fees': total_cons_fees,
        'from_date': from_date,
        'to_date': to_date,
        'doctor_id': doctor_id,
        'visit_type': visit_type,
        'doctors': doctor_list,
        'hospital': Hospitaldetails.objects.first(),
        'stdesign': staff_design_id,
    }
    return render(request, 'doctorwise_opregisteration.html', context)


# ==================== DOCTOR WISE BILL ANALYSIS ====================
def doctorwise_bill_analysis(request):
    """Doctor Wise Bill Analysis - Shows bill analysis with chart and pagination"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    
    # Get all doctors for dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # Get selected doctor name
    selected_doctor_name = "All Doctors"
    if doctor_id:
        selected_doctor = Staffdetails.objects.filter(id=doctor_id).first()
        if selected_doctor:
            selected_doctor_name = f"{selected_doctor.Staff_firstname} {selected_doctor.Staff_lastname}".strip()
    
    # ============================================================
    # 1. APPOINTMENT INVOICES (appointmentinvoicemaster)
    # ============================================================
    appointment_invoices = appointmentinvoicemaster.objects.filter(
        cancelstatus=False,
    ).select_related('Mrno', 'branch')
    
    if from_date and to_date:
        appointment_invoices = appointmentinvoicemaster.objects.filter(cancelstatus=False,currentdate__range=[from_date,to_date])
    elif from_date and not to_date:
        appointment_invoices = appointmentinvoicemaster.objects.filter(cancelstatus=False,currentdate__range=[from_date,timezone.now().date()])

    if doctor_id:
        appointment_invoices = appointment_invoices.filter(
            Mrno__in=Appointments.objects.filter(Doctor_Name_id=doctor_id).values_list('MR_Number_id', flat=True)
        )
    
    # ============================================================
    # 2. TREATMENT INVOICES (treatmentinvoicemaster)
    # ============================================================
    treatment_invoices = treatmentinvoicemaster.objects.filter(
        cancelstatus=False,
    ).select_related('Mrno', 'branch')
    
    if from_date and to_date:
        treatment_invoices = treatmentinvoicemaster.objects.filter(
                cancelstatus=False,
                currentdate__range=[from_date, to_date]
            ).select_related('Mrno', 'branch')
    elif from_date and not to_date:
        treatment_invoices = treatmentinvoicemaster.objects.filter(
        cancelstatus=False,
        currentdate__range=[from_date, timezone.now().date()]
    ).select_related('Mrno', 'branch')
    if doctor_id:
        treatment_invoices = treatment_invoices.filter(
            Mrno__in=Appointments.objects.filter(Doctor_Name_id=doctor_id).values_list('MR_Number_id', flat=True)
        )
    
    # ============================================================
    # 3. PHARMACY INVOICES (newInvoiceMaster)
    # ============================================================
    pharmacy_invoices = newInvoiceMaster.objects.filter(
        restockstatus=True,
    ).select_related('Mrno', 'branch')
    if from_date and to_date:
        pharmacy_invoices = newInvoiceMaster.objects.filter(restockstatus=True,currentdate__range=[from_date,to_date])
    elif from_date and not to_date:
        pharmacy_invoices = newInvoiceMaster.objects.filter(restockstatus=True,currentdate__range=[from_date,timezone.now().today()])
    if doctor_id:
        pharmacy_invoices = pharmacy_invoices.filter(
            Mrno__in=Appointments.objects.filter(Doctor_Name_id=doctor_id).values_list('MR_Number_id', flat=True)
        )
    
    # ============================================================
    # 4. LAB INVOICES (LabInvoiceMaster)
    # ============================================================
    lab_invoices = LabInvoiceMaster.objects.filter(
        is_cancelled=False,
    ).select_related('patient')
    if from_date and to_date:
        lab_invoices = LabInvoiceMaster.objects.filter(
        is_cancelled=False,
        date__range=[from_date, to_date]
    ).select_related('patient')
    elif from_date and not to_date:
        lab_invoices = LabInvoiceMaster.objects.filter(
        is_cancelled=False,
        date__range=[from_date, timezone.now().today()]
    ).select_related('patient')
       
    if doctor_id:
        lab_invoices = lab_invoices.filter(
            patient__in=Appointments.objects.filter(Doctor_Name_id=doctor_id).values_list('MR_Number_id', flat=True)
        )
    
    # ============================================================
    # BUILD BILL ANALYSIS DATA
    # ============================================================
    bill_types = {}
    total_amount = 0
    bill_details = []
    
    # Process Appointment Invoices
    for inv in appointment_invoices:
        amount = float(inv.total or 0)
        bill_type = 'APPOINTMENT'
        bill_details.append({
            'id': inv.id,
            'bill_number': inv.treatmentInvoicenumber,
            'bill_type': bill_type,
            'patient_name': inv.patientname or (inv.Mrno.Patient_Name if inv.Mrno else 'N/A'),
            'amount': amount,
            'date': inv.currentdate,
        })
        bill_types[bill_type] = bill_types.get(bill_type, 0) + amount
        total_amount += amount
    
    # Process Treatment Invoices
    for inv in treatment_invoices:
        amount = float(inv.total or 0)
        bill_type = 'TREATMENT'
        bill_details.append({
            'id': inv.id,
            'bill_number': inv.treatmentInvoicenumber,
            'bill_type': bill_type,
            'patient_name': inv.patientname or (inv.Mrno.Patient_Name if inv.Mrno else 'N/A'),
            'amount': amount,
            'date': inv.currentdate,
        })
        bill_types[bill_type] = bill_types.get(bill_type, 0) + amount
        total_amount += amount
    
    # Process Pharmacy Invoices
    for inv in pharmacy_invoices:
        amount = float(inv.total or 0)
        bill_type = 'PHARMACY'
        bill_details.append({
            'id': inv.id,
            'bill_number': inv.Invoicenumber,
            'bill_type': bill_type,
            'patient_name': inv.patientname or (inv.Mrno.Patient_Name if inv.Mrno else 'N/A'),
            'amount': amount,
            'date': inv.currentdate
        })
        bill_types[bill_type] = bill_types.get(bill_type, 0) + amount
        total_amount += amount
    
    # Process Lab Invoices
    for inv in lab_invoices:
        amount = float(inv.total or 0)
        bill_type = 'LAB BILL'
        created_by = inv.created_by.Staff.Staff_firstname + ' ' + inv.created_by.Staff.Staff_lastname if inv.created_by and hasattr(inv.created_by, 'Staff') else 'N/A'
        bill_details.append({
            'id': inv.id,
            'bill_number': inv.invoiceno,
            'bill_type': bill_type,
            'patient_name': inv.patient.Patient_Name if inv.patient else 'N/A',
            'amount': amount,
            'date': inv.date,
            'created_by':created_by
        })
        bill_types[bill_type] = bill_types.get(bill_type, 0) + amount
        total_amount += amount
    # ============================================================
    # 5. CASUALITY INVOICES (CasualityInvoiceMaster)
    # ============================================================
    casuality_invoices = CasualityInvoiceMaster.objects.filter(
        is_cancelled=False,
    ).select_related('patient', 'branch', 'created_by')
    
    if from_date and to_date:
        casuality_invoices = casuality_invoices.filter(invoice_date__range=[from_date, to_date])
    elif from_date and not to_date:
        casuality_invoices = casuality_invoices.filter(invoice_date__gte=from_date)
    
    if doctor_id:
        casuality_invoices = casuality_invoices.filter(
            patient__in=Appointments.objects.filter(Doctor_Name_id=doctor_id).values_list('MR_Number_id', flat=True)
        )
    
    # Process Casuality Invoices
    for inv in casuality_invoices:
        amount = float(inv.total or 0)
        bill_type = 'CASUALITY'
        created_by = inv.created_by.Staff.Staff_firstname + ' ' + inv.created_by.Staff.Staff_lastname if inv.created_by and hasattr(inv.created_by, 'Staff') else 'N/A'
        
        # Get patient MR number
        if inv.patient_mr_no:
            op_number = inv.patient_mr_no
        elif inv.patient and inv.patient.Medical_Record_Number:
            op_number = inv.patient.Medical_Record_Number
        else:
            op_number = '-'
        
        bill_details.append({
            'id': inv.id,
            'bill_number': inv.invoice_no,
            'bill_type': bill_type,
            'patient_name': inv.patient_name or (inv.patient.Patient_Name if inv.patient else 'N/A'),
            'amount': amount,
            'date': inv.invoice_date,
            'created_by': created_by
        })
        bill_types[bill_type] = bill_types.get(bill_type, 0) + amount
        total_amount += amount
    # Sort bill details by date (newest first)
    bill_details.sort(key=lambda x: x['date'], reverse=True)
    
    # ============================================================
    # PAGINATION
    # ============================================================
    paginator = Paginator(bill_details, 25)
    page = request.GET.get('page', 1)
    try:
        bill_details_page = paginator.page(page)
    except (PageNotAnInteger, EmptyPage):
        bill_details_page = paginator.page(1)
    
    # ============================================================
    # PREPARE CHART DATA
    # ============================================================
    chart_labels = list(bill_types.keys())
    chart_data = list(bill_types.values())
    
    # Generate colors for chart
    colors = ['#dc3545', '#28a745', '#007bff', '#ffc107', '#6f42c1', '#fd7e14', '#20c997']
    chart_colors = colors[:len(chart_labels)]
    
    # Get hospital details
    hospital = Hospitaldetails.objects.first()
    
    context = {
        'bill_details': bill_details_page,
        'bill_types': bill_types,
        'total_amount': total_amount,
        'total_count': len(bill_details),
        'chart_labels': json.dumps(chart_labels),
        'chart_data': json.dumps(chart_data),
        'chart_colors': json.dumps(chart_colors),
        'selected_doctor': doctor_id,
        'selected_doctor_name': selected_doctor_name,
        'doctors': doctor_list,
        'from_date': from_date,
        'to_date': to_date,
        'hospital': hospital,
        'stdesign': staff_design_id,
    }
    return render(request, 'doctorwise_billanalysis.html', context)


