# ==================== OCCUPANCY LIST ====================
def occupancy_list(request):
    """Occupancy List - Shows doctor wise occupancy from ippatientroombooking"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # Get all doctors for dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # Get room bookings - All data for DataTable
    bookings = ippatientroombooking.objects.filter(
        bookingcancel=False,
        ipno__Admittedstatus=True
    ).select_related(
        'ipno', 
        'ipno__MR_Number', 
        'room_number', 
        'bed_number',
        'roomdt',
        'admitteddoctor', 
        'admitteddoctor__Staff',
        'admitteddoctor__Branch_Name'
    )
    
    # Apply date filter
    if from_date and to_date:
        bookings = bookings.filter(Admission_Date__range=[from_date, to_date])
    elif from_date:
        bookings = bookings.filter(Admission_Date__gte=from_date)
    elif to_date:
        bookings = bookings.filter(Admission_Date__lte=to_date)
    
    # Apply doctor filter
    if doctor_id:
        bookings = bookings.filter(admitteddoctor__Staff_id=doctor_id)
    
    # Build occupancy data
    occupancy_data = []
    sl_no = 0
    
    for booking in bookings.order_by('-Admission_Date'):
        sl_no += 1
        patient = booking.ipno.MR_Number if booking.ipno else None
        
        # ============================================================
        # FIX: Get room/ward details properly
        # ============================================================
        room_display = '-'
        accommodation_type = booking.accommodation_type or 'Room'
        floor_number = booking.floor_number or ''
        room_type = booking.room_type or ''
        
        # Check if it's a Room or Ward
        if accommodation_type == 'Room':
            # For Room - use room_number or roomdt
            if booking.room_number:
                room_display = booking.room_number.Roomno
            elif booking.roomdt:
                room_display = booking.roomdt.Roomno
            # Add room type if available
            if room_type and room_display != '-':
                room_display = f"{room_display} ({room_type})"
        else:
            # For Ward - use bed_number
            if booking.bed_number:
                bed_no = booking.bed_number.wardbedno
                # Get ward room number from room_number or roomdt
                ward_room = ''
                if booking.room_number:
                    ward_room = booking.room_number.Roomno
                elif booking.roomdt:
                    ward_room = booking.roomdt.Roomno
                
                if ward_room:
                    room_display = f"Ward {ward_room} - Bed {bed_no}"
                else:
                    room_display = f"Bed {bed_no}"
            elif booking.room_number:
                room_display = f"Ward {booking.room_number.Roomno}"
            elif booking.roomdt:
                room_display = f"Ward {booking.roomdt.Roomno}"
        
        # Add floor number if available
        if floor_number and room_display != '-':
            room_display = f"{room_display} (Floor {floor_number})"
        
        # Build patient details string
        patient_details = ""
        if patient:
            patient_details = f"{patient.Medical_Record_Number} {patient.Patient_Name} ({patient.Gender}/{patient.Age}/Y)"
            if patient.address:
                patient_details += f"<br>{patient.address}"
            if patient.contactno:
                patient_details += f"<br>PH : +91 {patient.contactno}"
        
        # Get doctor name
        doctor_name = "N/A"
        if booking.admitteddoctor and booking.admitteddoctor.Staff:
            doctor_name = f"{booking.admitteddoctor.Staff.Staff_firstname} {booking.admitteddoctor.Staff.Staff_lastname}".strip()
        
        occupancy_data.append({
            'id': booking.id,
            'sl_no': sl_no,
            'room': room_display,
            'patient_details': patient_details,
            'admission_date': booking.Admission_Date,
            'doctor': doctor_name,
            'patient_name': patient.Patient_Name if patient else 'N/A',
            'op_number': patient.Medical_Record_Number if patient else '-',
            'gender': patient.Gender if patient else 'N/A',
            'age': patient.Age if patient else '0',
            'address': patient.address if patient else '',
            'phone': patient.contactno if patient else '',
            'accommodation_type': accommodation_type,
            'floor_number': floor_number,
            'room_type': room_type,
        })
    
    # Get hospital details
    hospital = Hospitaldetails.objects.first()
    
    context = {
        'occupancy_data': occupancy_data,
        'total_count': len(occupancy_data),
        'from_date': from_date,
        'to_date': to_date,
        'doctor_id': doctor_id,
        'doctors': doctor_list,
        'hospital': hospital,
        'stdesign': staff_design_id,
    }
    return render(request, 'occupancy_list.html', context)

# ==================== DOCTOR'S OP/IP COLLECTION ====================

def doctors_op_ip_collection(request):
    """Doctor's OP/IP Collection Report"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    
    # ✅ No default dates - only use if both provided
    
    # Get all doctors for dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ============================================================
    # 1. GET OP APPOINTMENTS
    # ============================================================
    op_appointments = Appointments.objects.select_related('MR_Number', 'Doctor_Name')
    
    # ✅ Only apply date filter if both dates are provided
    if from_date and to_date:
        op_appointments = op_appointments.filter(Appointment_date__range=[from_date, to_date])
    
    if doctor_id:
        op_appointments = op_appointments.filter(Doctor_Name_id=doctor_id)
    
    # Group by doctor for OP
    doctor_collection = {}
    
    for appt in op_appointments:
        doc_id = appt.Doctor_Name_id
        doc_name = f"{appt.Doctor_Name.Staff_firstname} {appt.Doctor_Name.Staff_lastname}".strip() if appt.Doctor_Name else 'RMO'
        
        if doc_id not in doctor_collection:
            doctor_collection[doc_id] = {
                'doctor_id': doc_id,
                'name': doc_name,
                'op_count': 0,
                'reg_fees': 0,
                'cons_fees': 0,
                'ip_count': 0,
                'ip_amount': 0
            }
        
        doctor_collection[doc_id]['op_count'] += 1
        
        # ✅ Registration Fee: From Patient_details.reg_Fee
        reg_fee = 0
        if appt.MR_Number:
            reg_fee = float(appt.MR_Number.reg_Fee or 0)
        
        # ✅ Consultation Fee: From Appointment.Fee (only for consultation/followup/revisit)
        cons_fee = 0
        status_lower = (appt.status or "").lower()
        if status_lower:
            if 'consultation' in status_lower or 'followup' in status_lower or 'revisit' in status_lower:
                cons_fee = float(appt.Fee or 0)
        
        # Add to totals
        if reg_fee > 0:
            doctor_collection[doc_id]['reg_fees'] += reg_fee
        
        if cons_fee > 0:
            doctor_collection[doc_id]['cons_fees'] += cons_fee
    
    # ============================================================
    # 2. GET IP ADMISSIONS
    # ============================================================
    ip_admissions = ippatientadmission.objects.filter(Admittedstatus=True)
    
    # ✅ Only apply date filter if both dates are provided
    if from_date and to_date:
        ip_admissions = ip_admissions.filter(Current_Date__range=[from_date, to_date])
    
    for admission in ip_admissions:
        # Get doctor from room booking
        room_booking = ippatientroombooking.objects.filter(ipno=admission).first()
        if room_booking and room_booking.admitteddoctor:
            doc_id = room_booking.admitteddoctor.Staff_id
            if doc_id in doctor_collection:
                doctor_collection[doc_id]['ip_count'] += 1
                # Get IP bill amount
                ip_bill = IPBill.objects.filter(ip_admission=admission).first()
                if ip_bill:
                    doctor_collection[doc_id]['ip_amount'] += float(ip_bill.total_amount)
    
    # ============================================================
    # 3. CONVERT TO LIST FOR TEMPLATE
    # ============================================================
    collection_data = []
    total_op = 0
    total_reg = 0
    total_cons = 0
    total_ip = 0
    total_ip_amount = 0
    
    for idx, (doc_id, data) in enumerate(doctor_collection.items(), 1):
        total = data['reg_fees'] + data['cons_fees'] + data['ip_amount']
        collection_data.append({
            'id': doc_id,
            'sl_no': idx,
            'doctor_name': data['name'],
            'op_count': data['op_count'],
            'reg_fees': data['reg_fees'],
            'cons_fees': data['cons_fees'],
            'ip_count': data['ip_count'],
            'ip_amount': data['ip_amount'],
            'total': total
        })
        total_op += data['op_count']
        total_reg += data['reg_fees']
        total_cons += data['cons_fees']
        total_ip += data['ip_count']
        total_ip_amount += data['ip_amount']
    
    total_amount = total_reg + total_cons + total_ip_amount
    
    # Get hospital details
    hospital = Hospitaldetails.objects.first()
    
    context = {
        'collection_data': collection_data,
        'total_op': total_op,
        'total_reg': total_reg,
        'total_cons': total_cons,
        'total_ip': total_ip,
        'total_ip_amount': total_ip_amount,
        'total_amount': total_amount,
        'from_date': from_date,
        'to_date': to_date,
        'doctor_id': doctor_id,
        'doctors': doctor_list,
        'hospital': hospital,
        'stdesign': staff_design_id,
    }
    return render(request, 'doctors_op_ipcollection.html', context)


# ==================== DOCTOR WISE ADMISSION REGISTER ====================
def doctorwise_admission_register(request):
    """Doctor Wise Admission Register with Admitted/Discharged filter"""
    staff_design_id = request.session.get('loginstaffdesign')
    if not staff_design_id:
        return redirect('staff_login')
    
    # Get filter values from request
    from_date = request.GET.get('from_date', '')
    to_date = request.GET.get('to_date', '')
    doctor_id = request.GET.get('doctor', '')
    status_filter = request.GET.get('status', 'all')  # all, admitted, discharged
    
    # # Set default dates if not provided
    # if not from_date:
    #     from_date = date.today().replace(day=1).strftime('%Y-%m-%d')
    # if not to_date:
    #     to_date = date.today().strftime('%Y-%m-%d')
    
    # Get all doctors for dropdown
    doctors = Staffallocation.objects.filter(
        Designation_Name_id__in=[2, 3, 13],
        Status='Active'
    ).select_related('Staff').order_by('Staff__Staff_firstname')
    
    doctor_list = []
    for doc in doctors:
        doctor_list.append({
            'id': doc.Staff.id,
            'name': f"{doc.Staff.Staff_firstname} {doc.Staff.Staff_lastname}".strip()
        })
    
    # ============================================================
    # GET ALL ADMISSIONS
    # ============================================================
    admissions = ippatientadmission.objects.all().select_related('MR_Number')
    
    # Apply date filter
    if from_date and to_date:
        admissions = admissions.filter(Current_Date__range=[from_date, to_date])
    elif from_date:
        admissions = admissions.filter(Current_Date__gte=from_date)
    elif to_date:
        admissions = admissions.filter(Current_Date__lte=to_date)
    
    # Apply doctor filter
    if doctor_id:
        admissions = admissions.filter(
            ippatientroombooking__admitteddoctor__Staff_id=doctor_id
        )
    
    # ============================================================
    # COUNT ADMITTED AND DISCHARGED
    # ============================================================
    # Get all admission IDs that have a discharge record
    discharged_admission_ids = PatientDischarge.objects.filter(
        ipptno__in=admissions
    ).values_list('ipptno_id', flat=True)
    
    # Admitted = not discharged
    admitted_admissions = admissions.exclude(id__in=discharged_admission_ids)
    discharged_admissions = admissions.filter(id__in=discharged_admission_ids)
    
    admitted_count = admitted_admissions.count()
    discharged_count = discharged_admissions.count()
    total_count = admissions.count()
    
    # ============================================================
    # APPLY STATUS FILTER
    # ============================================================
    if status_filter == 'admitted':
        admissions = admitted_admissions
    elif status_filter == 'discharged':
        admissions = discharged_admissions
    
    # ============================================================
    # BUILD ADMISSION DATA
    # ============================================================
    admission_data = []
    sl_no = 0
    
    for admission in admissions.order_by('-Current_Date'):
        sl_no += 1
        room_booking = ippatientroombooking.objects.filter(ipno=admission).first()
        patient = admission.MR_Number
        
        # Check if discharged
        is_discharged = PatientDischarge.objects.filter(ipptno=admission).exists()
        status_label = 'Discharged' if is_discharged else 'Admitted'
        status_class = 'text-success' if not is_discharged else 'text-danger'
        
        # Get room/ward details
        room_display = '-'
        if room_booking:
            if room_booking.accommodation_type == 'Room':
                if room_booking.room_number:
                    room_display = room_booking.room_number.Roomno
                elif room_booking.roomdt:
                    room_display = room_booking.roomdt.Roomno
            else:  # Ward
                if room_booking.bed_number:
                    bed_no = room_booking.bed_number.wardbedno
                    ward_room = room_booking.room_number.Roomno if room_booking.room_number else ''
                    if ward_room:
                        room_display = f"Ward {ward_room} - Bed {bed_no}"
                    else:
                        room_display = f"Bed {bed_no}"
                elif room_booking.room_number:
                    room_display = f"Ward {room_booking.room_number.Roomno}"
                elif room_booking.roomdt:
                    room_display = f"Ward {room_booking.roomdt.Roomno}"
        
        # Get doctor name
        doctor_name = "N/A"
        if admission and admission.admitted_doctor and admission.admitted_doctor.Staff:
            doctor_name = f"{admission.admitted_doctor.Staff.Staff_firstname} {admission.admitted_doctor.Staff.Staff_lastname}".strip()
        
        admission_data.append({
            'id': admission.id, 
            'sl_no': sl_no,
            'date': admission.Current_Date,
            'ip_number': admission.ipnumber or 'N/A',
            'doctor': doctor_name,
            'patient_name': patient.Patient_Name if patient else 'N/A',
            'address': patient.address if patient else '',
            'gender': patient.Gender if patient else 'N/A',
            'age': patient.Age if patient else '0',
            'time': room_booking.admissiontime.strftime('%H:%M:%S') if room_booking and room_booking.admissiontime else '-',
            'room': room_display,
            'status': status_label,
            'status_class': status_class
        })
    
    # Get hospital details
    hospital = Hospitaldetails.objects.first()
    
    context = {
        'admission_data': admission_data,
        'total_count': total_count,
        'admitted_count': admitted_count,
        'discharged_count': discharged_count,
        'from_date': from_date,
        'to_date': to_date,
        'doctor_id': doctor_id,
        'status_filter': status_filter,
        'doctors': doctor_list,
        'hospital': hospital,
        'stdesign': staff_design_id,
    }
    return render(request, 'doctorwise_admission_register.html', context)

def birth_and_death_register(request):
    try:
        # Get doctors from Staffallocation where Designation is doctor
        # Option 1: Get staff with doctor designation
        doctor_allocations = Staffallocation.objects.filter(
            Designation_Name__Designation_Name__icontains='doctor'
        ).select_related('Staff')
        
        doctor_list = []
        for allocation in doctor_allocations:
            staff = allocation.Staff
            if staff and not staff.deleted:
                doctor_list.append({
                    'id': staff.id,
                    'name': f"{staff.Staff_firstname} {staff.Staff_lastname}".strip(),
                    'designation': allocation.Designation_Name.Designation_Name if allocation.Designation_Name else '',
                    'qualification': staff.Qualification or ''
                })
        
        # Remove duplicates by name (keep first occurrence)
        seen_names = set()
        unique_doctors = []
        for doctor in doctor_list:
            if doctor['name'] not in seen_names:
                seen_names.add(doctor['name'])
                unique_doctors.append(doctor)
        
        context = {
            'doctors': unique_doctors,
        }
        return render(request, 'birth_and_death_registration.html', context)
        
    except Exception as e:
        # If error, return empty list
        print(f"Error loading doctors: {e}")
        context = {
            'doctors': [],
        }
    return render(request, 'birth_and_death_registration.html', context)

def save_death_registration(request):
    """API endpoint to save death registration"""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request method'}, status=405)
    
    try:
        data = json.loads(request.body)
        reg_type = data.get('registrationType', 'registered')
        
        # Get staff
        staff_id = request.session.get('staffid')
        staff = Staffdetails.objects.filter(id=staff_id).first()
        
        # Handle photo upload
        photo_path = None
        photo_data = data.get('photoData')
        if photo_data:
            photo_path = save_base64_image(photo_data, 'death_reg_photos/')
        
        # Create Death Register record
        death_record = DeathRegister()
        
        if reg_type == 'registered':
            # Registered Patient
            patient_id = data.get('patientId')
            if not patient_id:
                return JsonResponse({'success': False, 'error': 'Patient ID is required for registered patient'}, status=400)
            
            patient = get_object_or_404(Patient_details, id=patient_id)
            death_record.patient = patient
            death_record.registration_type = 'registered'
            
            # Get patient details from DB
            death_record.unregistered_name = None
            death_record.unregistered_gender = None
            death_record.unregistered_address = None
            death_record.unregistered_phone = None
            
        else:
            # Unregistered Patient - create new patient first
            first_name = data.get('firstName', '')
            last_name = data.get('lastName', '')
            full_name = f"{first_name} {last_name}".strip()
            
            if not full_name:
                return JsonResponse({'success': False, 'error': 'Patient name is required'}, status=400)
            
            # Create new patient
            patient = Patient_details.objects.create(
                Patient_Name=full_name,
                Gender=data.get('gender', ''),
                contactno=data.get('phone', ''),
                address=data.get('address', ''),
                Date=timezone.now().date(),
                Entry_Date=timezone.now().strftime("%Y%m%d"),
                Age=data.get('age', '0'),
                Branch_Name_id=request.session.get('branchid')
            )
            
            death_record.patient = patient
            death_record.registration_type = 'unregistered'
            
            # Store unregistered details for reference
            death_record.unregistered_name = full_name
            death_record.unregistered_gender = data.get('gender', '')
            death_record.unregistered_age = data.get('age')
            death_record.unregistered_address = data.get('address', '')
            death_record.unregistered_phone = data.get('phone', '')
            
            # Additional unregistered fields
            death_record.registration_date = data.get('regDate') or timezone.now().date()
            death_record.visit_date = data.get('visitDate') or timezone.now().date()
            death_record.booking_number = data.get('bookingNumber', '')
            death_record.citizen_id = data.get('citizenId', '')
            death_record.uhid_no = data.get('uhidNo', '')
            death_record.customer_type = data.get('customerType', '')
            death_record.insurance_ref = data.get('insuranceRef', '')
            death_record.corporate_company = data.get('corporateCompany', '')
            death_record.staff_id = staff.id
            death_record.privileged_customer_id = data.get('privilegedCustomerId', '')
            death_record.aadhaar_number = data.get('aadhaarNumber', '')

        doctor_staff_id = data.get('doctor', '')
        consulting_doctor = None
        
        if doctor_staff_id:
            try:
                # Find the Staffallocation record for this staff member
                consulting_doctor = Staffallocation.objects.filter(
                    Staff_id=doctor_staff_id,
                    Status='Active'  # Only active staff
                ).first()
                
                if not consulting_doctor:
                    # Try without status filter
                    consulting_doctor = Staffallocation.objects.filter(
                        Staff_id=doctor_staff_id
                    ).first()
                
                if consulting_doctor:
                    death_record.consulting_doctor = consulting_doctor
                else:
                    # Log warning but continue (doctor not found in Staffallocation)
                    print(f"Warning: No Staffallocation found for staff_id: {doctor_staff_id}")
                    
            except Exception as e:
                print(f"Error finding consulting doctor: {e}")
        # Common death details
        death_record.room = data.get('room', '')
        death_record.admission_datetime = data.get('admissionDateTime') or None
        death_record.death_datetime = data.get('deathDateTime') or None
        death_record.photo = photo_path
        death_record.created_by = staff
        death_record.save()
        
        
        return JsonResponse({
            'success': True,
            'message': 'Death registration saved successfully',
            'record_id': death_record.id
        })
        
    except Patient_details.DoesNotExist:
        return JsonResponse({'success': False, 'error': 'Patient not found'}, status=404)
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


def save_birth_registration(request):
    """API endpoint to save birth registration"""
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Invalid request method'}, status=405)
    
    try:
        data = json.loads(request.body)
        
        # Get mother's MR Number/OP Number
        mother_mrno = data.get('motherMrNumber') or data.get('advancedMothersNumber')
        if not mother_mrno:
            return JsonResponse({'success': False, 'error': 'Mother\'s MR/OP number is required'}, status=400)
        
        # Find mother by MR Number or OP Number
        mother = Patient_details.objects.filter(
            Medical_Record_Number=mother_mrno
        ).first()
        
        if not mother:
            # Try searching by OP number if MR number not found
            mother = Patient_details.objects.filter(
                id=mother_mrno  # Try as ID
            ).first()
            
        if not mother:
            return JsonResponse({'success': False, 'error': 'Mother not found. Please register the mother first.'}, status=404)
        
        # Get staff
        staff_id = request.session.get('staffid')
        staff = Staffdetails.objects.filter(id=staff_id).first()
        
        today = datetime.now().strftime("%Y%m%d")
        
        # Get the latest birth record with child_op starting with today's date
        latest_birth = BirthRegister.objects.filter(
            child_op__startswith=f"BIRTH-{today}"
        ).order_by('-child_op').first()
        
        if latest_birth and latest_birth.child_op:
            try:
                # Extract sequence number
                parts = latest_birth.child_op.split('-')
                if len(parts) == 3:
                    sequence = int(parts[2]) + 1
                else:
                    sequence = 1
            except (ValueError, IndexError):
                sequence = 1
        else:
            sequence = 1
        
        # Format with leading zeros (4 digits)
        child_op = f"BIRTH-{today}-{str(sequence).zfill(4)}"
        # Handle photo upload
        photo_path = None
        photo_data = data.get('photoData')
        if photo_data:
            photo_path = save_base64_image(photo_data, 'birth_reg_photos/')
        
        # Create Birth Register record
        birth_record = BirthRegister(
            mother=mother,
            gender=data.get('gender', ''),
            date_time_of_birth=data.get('dateTimeOfBirth') or None,
            weight=data.get('weight', ''),
            blood_group=data.get('bloodGroup', ''),
            guardian_address=data.get('guardianAddress', ''),
            guardian_phone=data.get('guardianPhone', ''),
            special_instructions=data.get('specialInstructions', ''),
            file_location=data.get('fileLocation', ''),
            is_new_born=True,
            photo=photo_path,
            created_by=staff,
            child_op=child_op,
        )
        birth_record.save()
        
        return JsonResponse({
            'success': True,
            'message': 'Birth registration saved successfully',
            'record_id': birth_record.id,
            'child_op': child_op,
            'mother': {
                'name': mother.Patient_Name,
                'mr_number': mother.Medical_Record_Number,
            }
        })
        
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)}, status=500)


def search_patient(request):
    """Search patient by MR Number or Name for death registration"""
    query = request.GET.get('query', '').strip()
    if not query:
        return JsonResponse([], safe=False)
    
    patients = Patient_details.objects.filter(
        models.Q(Medical_Record_Number__icontains=query) |
        models.Q(Patient_Name__icontains=query)
    ).filter(deleted=False)[:10]
    
    results = []
    for patient in patients:
        results.append({
            'id': patient.id,
            'mr_no': patient.Medical_Record_Number,
            'name': patient.Patient_Name,
            'gender': patient.Gender,
            'room': getattr(patient, 'room', ''),
            'address': patient.address or '',
            'phone': patient.contactno or ''
        })
    
    return JsonResponse(results, safe=False)


def search_mother_by_mr(request):
    """Search mother by MR Number for birth registration"""
    query = request.GET.get('query', '').strip()
    if not query:
        return JsonResponse([], safe=False)
    
    # Search by MR Number
    patients = Patient_details.objects.filter(
        models.Q(Medical_Record_Number__icontains=query) |
        models.Q(Patient_Name__icontains=query)
    ).filter(deleted=False, Gender__in=['Female', 'Transgender'])[:10]
    
    results = []
    for patient in patients:
        results.append({
            'id': patient.id,
            'mr_no': patient.Medical_Record_Number,
            'name': patient.Patient_Name,
            'gender': patient.Gender,
            'phone': patient.contactno or '',
            'age': patient.Age or '0',
            'address': patient.address or ''
        })
    
    return JsonResponse(results, safe=False)


def save_base64_image(base64_string, upload_folder):
    """Save base64 image to storage and return path"""
    try:
        # Check if it's a data URL
        if ';base64,' in base64_string:
            format, imgstr = base64_string.split(';base64,')
            ext = format.split('/')[-1] if '/' in format else 'png'
        else:
            imgstr = base64_string
            ext = 'png'
        
        # Decode and save
        image_data = base64.b64decode(imgstr)
        filename = f"{upload_folder}{uuid.uuid4()}.{ext}"
        path = default_storage.save(filename, ContentFile(image_data))
        return path
    except Exception as e:
        print(f"Error saving image: {e}")
        return None

def birth_and_death_list(request):
    """View for birth and death registration list with DataTables"""
    try:
        # Get filter parameters from request
        birth_reg_type = request.GET.get('birth_reg_type', '')
        birth_date_from = request.GET.get('birth_date_from', '')
        birth_date_to = request.GET.get('birth_date_to', '')
        death_reg_type = request.GET.get('death_reg_type', '')
        death_date_from = request.GET.get('death_date_from', '')
        death_date_to = request.GET.get('death_date_to', '')
        active_tab = request.GET.get('tab', 'birth')
        
        # Get Birth Registrations with filters
        birth_queryset = BirthRegister.objects.select_related('mother', 'created_by').all()
        
        if birth_reg_type == 'registered':
            birth_queryset = birth_queryset.filter(mother__isnull=False)
        
        if birth_date_from:
            birth_queryset = birth_queryset.filter(created_at__date__gte=birth_date_from)
        if birth_date_to:
            birth_queryset = birth_queryset.filter(created_at__date__lte=birth_date_to)
        
        birth_queryset = birth_queryset.order_by('-created_at')
        
        # Prepare birth data
        birth_data = []
        for record in birth_queryset:
            birth_data.append({
                'id': record.id,
                'mother_name': record.mother.Patient_Name if record.mother else 'N/A',
                'mother_mr_no': record.mother.Medical_Record_Number if record.mother else 'N/A',
                'gender': record.gender or 'N/A',
                'date_time_of_birth': record.date_time_of_birth.strftime('%d-%m-%Y %H:%M') if record.date_time_of_birth else 'N/A',
                'weight': record.weight or 'N/A',
                'blood_group': record.blood_group or 'N/A',
                'guardian_phone': record.guardian_phone or 'N/A',
                'created_by': f"{record.created_by.Staff_firstname} {record.created_by.Staff_lastname}" if record.created_by else 'System',
                'created_at': record.created_at.strftime('%Y-%m-%d %H:%M'),
                'registration_type': 'Registered',
                'photo': record.photo.url if record.photo else None,
                'guardian_address': record.guardian_address or 'N/A',
                'special_instructions': record.special_instructions or 'N/A',
                'file_location': record.file_location or 'N/A'
            })
        
        # Get Death Registrations with filters
        death_queryset = DeathRegister.objects.select_related('patient', 'created_by', 'consulting_doctor').all().order_by('-id')
        
        if death_reg_type:
            death_queryset = death_queryset.filter(registration_type=death_reg_type)
        
        if death_date_from:
            death_queryset = death_queryset.filter(created_at__date__gte=death_date_from)
        if death_date_to:
            death_queryset = death_queryset.filter(created_at__date__lte=death_date_to)
        
        death_queryset = death_queryset.order_by('-created_at')
        
        # Prepare death data
        death_data = []
        for record in death_queryset:
            if record.registration_type == 'registered' and record.patient:
                patient_name = record.patient.Patient_Name
                patient_mr_no = record.patient.Medical_Record_Number
                gender = record.patient.Gender
            else:
                patient_name = record.unregistered_name or 'N/A'
                patient_mr_no = 'N/A'
                gender = record.unregistered_gender or 'N/A'
            
            # Get doctor name safely
            doctor_name = 'N/A'
            if record.consulting_doctor:
                try:
                    if hasattr(record.consulting_doctor, 'Staff') and record.consulting_doctor.Staff:
                        staff = record.consulting_doctor.Staff
                        doctor_name = f"{staff.Staff_firstname} {staff.Staff_lastname}".strip()
                    elif hasattr(record.consulting_doctor, 'staff_name'):
                        doctor_name = record.consulting_doctor.staff_name
                    else:
                        doctor_name = str(record.consulting_doctor)
                except:
                    doctor_name = 'N/A'
            
            death_data.append({
                'id': record.id,
                'patient_name': patient_name,
                'patient_mr_no': patient_mr_no,
                'gender': gender,
                'room': record.room or 'N/A',
                'admission_datetime': record.admission_datetime.strftime('%d-%m-%Y %H:%M') if record.admission_datetime else 'N/A',
                'death_datetime': record.death_datetime.strftime('%d-%m-%Y %H:%M') if record.death_datetime else 'N/A',
                'consulting_doctor': doctor_name,
                'registration_type': record.registration_type.title() if record.registration_type else 'N/A',
                'created_by': f"{record.created_by.Staff_firstname} {record.created_by.Staff_lastname}" if record.created_by else 'System',
                'created_at': record.created_at.strftime('%Y-%m-%d %H:%M'),
                'photo': record.photo.url if record.photo else None,
                'unregistered_address': record.unregistered_address or 'N/A',
                'unregistered_phone': record.unregistered_phone or 'N/A',
                'unregistered_age': record.unregistered_age or 'N/A',
                'aadhaar_number': record.aadhaar_number or 'N/A',
                'customer_type': record.customer_type or 'N/A'
            })
        
        # Calculate statistics
        total_births = BirthRegister.objects.count()
        total_deaths = DeathRegister.objects.count()
        registered_count = DeathRegister.objects.filter(registration_type='registered').count() + total_births
        unregistered_count = DeathRegister.objects.filter(registration_type='unregistered').count()
        
        context = {
            'birth_data': birth_data,
            'death_data': death_data,
            'total_births': total_births,
            'total_deaths': total_deaths,
            'registered_count': registered_count,
            'unregistered_count': unregistered_count,
            'birth_reg_type': birth_reg_type,
            'birth_date_from': birth_date_from,
            'birth_date_to': birth_date_to,
            'death_reg_type': death_reg_type,
            'death_date_from': death_date_from,
            'death_date_to': death_date_to,
            'active_tab': active_tab,
        }
        return render(request, 'birth_and_death_list.html', context)
        
    except Exception as e:
        print(f"Error in birth_and_death_list: {e}")
        import traceback
        traceback.print_exc()
        context = {
            'birth_data': [],
            'death_data': [],
            'total_births': 0,
            'total_deaths': 0,
            'registered_count': 0,
            'unregistered_count': 0,
            'active_tab': 'birth',
        }
        return render(request, 'birth_and_death_list.html', context)

def get_doctors_list():
    """Helper function to get doctors list"""
