def view_lab_results(request):
    """
    Single view to display lab results with search/filter and detail view
    Uses GET parameter 'master_id' to show detail view
    """
    # Check if we're viewing a specific result detail
    master_id = request.GET.get('master_id')
    
    if master_id:
        # ========== DETAIL VIEW ==========
        result_master = get_object_or_404(
            LabResultMaster.objects.select_related('patient', 'invoice', 'created_by', 'completed_by'),
            id=master_id,
            is_completed=True
        )
        
        # Get all result items
        result_items = casehistorylabresult.objects.filter(
            result_master=result_master
        ).select_related('labtest', 'patient', 'preparedby')
        
        # Group items by test group
        grouped_items = {}
        ungrouped_items = []
        
        for item in result_items:
            if item.labtest and item.labtest.group:
                group_name = item.labtest.group.groupname
                if group_name not in grouped_items:
                    grouped_items[group_name] = []
                grouped_items[group_name].append(item)
            else:
                ungrouped_items.append(item)
        
        # Calculate statistics
        total_tests = result_items.count()
        context = {
            'is_detail_view': True,
            'result_master': result_master,
            'result_items': result_items,
            'grouped_items': grouped_items,
            'ungrouped_items': ungrouped_items,
            'patient': result_master.patient,
            'invoice': result_master.invoice,
            'total_tests': total_tests,
            'completed_date': result_master.completed_date,
            'result_number': result_master.result_number,
        }
        return render(request, 'lab_result_view.html', context)
    
    else:
        # ========== LIST VIEW ==========
        # Get filter parameters
        search_query = request.GET.get('search', '').strip()
        patient_id = request.GET.get('patient_id', '')
        date_from = request.GET.get('date_from', '')
        date_to = request.GET.get('date_to', '')
        
        # Base queryset - get all completed result masters
        result_masters = LabResultMaster.objects.filter(
            is_completed=True
        ).select_related('patient', 'invoice', 'completed_by').order_by('-completed_date')
        
        # Filter by patient ID
        if patient_id:
            try:
                result_masters = result_masters.filter(patient_id=patient_id)
            except ValueError:
                pass
        
        # Filter by search query
        if search_query:
            result_masters = result_masters.filter(
                Q(patient__Patient_Name__icontains=search_query) |
                Q(patient__Medical_Record_Number__icontains=search_query) |
                Q(patient__contactno__icontains=search_query) |
                Q(result_number__icontains=search_query) |
                Q(invoice__invoiceno__icontains=search_query)
            )
        
        # Filter by date range
        if date_from:
            try:
                result_masters = result_masters.filter(completed_date__date__gte=date_from)
            except:
                pass
        
        if date_to:
            try:
                result_masters = result_masters.filter(completed_date__date__lte=date_to)
            except:
                pass
        
        # Get all patients for dropdown filter
        all_patients = Patient_details.objects.filter(
            id__in=LabResultMaster.objects.filter(
                is_completed=True
            ).values_list('patient_id', flat=True).distinct()
        ).order_by('Patient_Name')
        
        
        # Build results data
        results_data = []
        for master in result_masters:
            test_count = casehistorylabresult.objects.filter(
                result_master=master
            ).count()
            
            preview_tests = casehistorylabresult.objects.filter(
                result_master=master
            ).select_related('labtest')[:3]
            
            preview_test_names = [item.labtest.testname for item in preview_tests if item.labtest]
            
            results_data.append({
                'master': master,
                'patient': master.patient,
                'invoice': master.invoice,
                'result_number': master.result_number,
                'completed_date': master.completed_date,
                'invoice_no': master.invoice.invoiceno if master.invoice else 'N/A',
                'test_count': test_count,
                'preview_tests': preview_test_names,
                'created_by': master.created_by,
                'completed_by': master.completed_by,
            })
        
        context = {
            'is_detail_view': False,
            'results': results_data,
            'search_query': search_query,
            'patient_id': patient_id,
            'date_from': date_from,
            'date_to': date_to,
            'all_patients': all_patients,
            'total_results': result_masters.count(),
            'page_obj': result_masters,
        }
        return render(request, 'lab_result_view.html', context)


def edit_lab_result(request):
    """
    Single function to handle lab result editing using GET parameter
    Only allows editing of result_value and result status
    """
    # Get the result_id from GET parameters
    result_id = request.GET.get('result_id')
    
    if not result_id:
        messages.error(request, 'Result ID is required')
        return redirect('view_lab_results')
    
    # Get the result master
    result_master = get_object_or_404(
        LabResultMaster.objects.select_related('patient', 'invoice'),
        id=result_id,
        is_completed=True
    )
    
    # Get all result items
    result_items = casehistorylabresult.objects.filter(
        result_master=result_master
    ).select_related('labtest', 'patient')
    
    # Handle form submission
    if request.method == 'POST':
        # Handle AJAX single row update
        if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            try:
                rid = request.POST.get('result_id')
                result_value = request.POST.get('result_value')
                status = request.POST.get('result')
                
                if not rid:
                    return JsonResponse({'success': False, 'error': 'Result ID required'})
                
                lab_result = get_object_or_404(casehistorylabresult, id=rid)
                
                if result_value is not None:
                    lab_result.result_value = result_value
                if status is not None:
                    lab_result.result = status
                
                lab_result.save()
                
                return JsonResponse({
                    'success': True,
                    'message': 'Updated successfully'
                })
                
            except Exception as e:
                return JsonResponse({'success': False, 'error': str(e)})
        
        # Handle bulk form submission
        try:
            with transaction.atomic():
                # Get form data
                result_ids = request.POST.getlist('result_id[]')
                result_values = request.POST.getlist('result_value[]')
                statuses = request.POST.getlist('result[]')
                notes = request.POST.get('notes', '')
                
                # Update each result item
                for i, rid in enumerate(result_ids):
                    if not rid:
                        continue
                    
                    lab_result = get_object_or_404(casehistorylabresult, id=rid)
                    
                    if i < len(result_values):
                        lab_result.result_value = result_values[i]
                    if i < len(statuses):
                        lab_result.result = statuses[i]
                    
                    lab_result.save()
                
                # Update master notes
                if notes:
                    result_master.notes = notes
                    result_master.save()
                
                messages.success(request, 'Lab results updated successfully!')
                return redirect(f'view_lab_results')
                
        except Exception as e:
            messages.error(request, f'Error updating results: {str(e)}')
    
    # Group items by test group
    grouped_items = {}
    ungrouped_items = []
    
    for item in result_items:
        if item.labtest and item.labtest.group:
            group_name = item.labtest.group.groupname
            if group_name not in grouped_items:
                grouped_items[group_name] = []
            grouped_items[group_name].append(item)
        else:
            ungrouped_items.append(item)
    
    context = {
        'result_master': result_master,
        'result_items': result_items,
        'grouped_items': grouped_items,
        'ungrouped_items': ungrouped_items,
        'patient': result_master.patient,
        'invoice': result_master.invoice,
        'total_tests': result_items.count(),
        'result_number': result_master.result_number,
        'completed_date': result_master.completed_date,
        'result_id': result_id,
    }
    return render(request, 'lab_results_edit.html', context)


def asset_list(request):
    """
    Display all assets with datatable
    """
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    assets = Asset.objects.filter(deleted=False).select_related('branch', 'added_by')
    
    # Store permissions in session
    try:
        assetobj = get_object_or_404(menumanagement, id=idmngmnt)
        request.session['assetobjmngid'] = idmngmnt
        request.session['assetobjmngadd'] = assetobj.add
        request.session['assetobjmngview'] = assetobj.view
        request.session['assetobjmngedit'] = assetobj.edit
        request.session['assetobjmngdelete'] = assetobj.delete
    except Exception as e:
        messages.error(request, f'Error retrieving menu management details: {e}')
        return redirect('error_page')
    
    context = {
        'idmngmnt': idmngmnt,
        'assets': assets,
        'stdesign': stdesign,
        'assetadd': request.session.get('assetobjmngadd'),
        'assetview': request.session.get('assetobjmngview'),
        'assetedit': request.session.get('assetobjmngedit'),
        'assetdelete': request.session.get('assetobjmngdelete'),
    }
    return render(request, 'asset_list.html', context)


# ============================================
# ASSET ADD VIEW
# ============================================

def asset_add(request):
    """
    Add new asset
    """
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    if request.method == 'POST':
        asset_id = request.POST.get('asset_id')
        asset_name = request.POST.get('asset_name')
        description = request.POST.get('description')
        purchase_date = request.POST.get('purchase_date')
        manufacturer = request.POST.get('manufacturer')
        supplier = request.POST.get('supplier')
        branch_id = request.POST.get('branch')
        # department_id = request.POST.get('department')
        purchase_cost = request.POST.get('purchase_cost') or 0
        physical_location = request.POST.get('physical_location')
        status = request.POST.get('status', 'available')
        
        # Validation
        if not asset_id or not asset_name:
            messages.error(request, 'Asset ID and Asset Name are required!')
            return redirect(f"{reverse('asset_add')}?menumanagement_id={idmngmnt}")
        
        # Check for duplicate asset_id
        if Asset.objects.filter(asset_id=asset_id, deleted=False).exists():
            messages.error(request, f'Asset ID "{asset_id}" already exists!')
            return redirect(f"{reverse('asset_add')}?menumanagement_id={idmngmnt}")
        
        # Get staff (logged in user)
        staff = Staffallocation.objects.filter(id=request.session.get('loginstaff')).first()
        staff_details = staff.Staff if staff else None
        try:
            with transaction.atomic():
                # Create asset
                asset = Asset.objects.create(
                    asset_id=asset_id,
                    asset_name=asset_name,
                    description=description,
                    purchase_date=purchase_date if purchase_date else None,
                    manufacturer=manufacturer,
                    supplier=supplier,
                    branch_id=branch_id,
                    added_by=staff_details,
                    purchase_cost=purchase_cost if purchase_cost else 0,
                    physical_location=physical_location,
                    status=status
                )
                
                # Create audit log
                AssetAuditLog.objects.create(
                    asset=asset,
                    action='create',
                    staff=staff,
                    branch_id=branch_id,
                    notes=f"Asset '{asset.asset_name}' created"
                )
                
                messages.success(request, f'Asset "{asset.asset_name}" added successfully!')
                return redirect(f"{reverse('asset_list')}?menumanagement_id={idmngmnt}")
                
        except Exception as e:
            messages.error(request, f"An error occurred while saving: {str(e)}")
            return redirect('error_page')
    
    # GET request - show form
    branches = Branch.objects.filter(inactive=False)
    departments = Department.objects.filter(flag=True)
    
    context = {
        'idmngmnt': idmngmnt,
        'branches': branches,
        'departments': departments,
        'stdesign': stdesign,
        'assetadd': request.session.get('assetobjmngadd'),
    }
    return render(request, 'asset_add.html', context)


# ============================================
# ASSET EDIT VIEW (Using query parameter ?id=)
# ============================================

def asset_edit(request):
    """
    Edit existing asset using query parameter
    URL: /assets/edit/?id=1
    """
    asset_id_param = request.GET.get('id')
    
    if not asset_id_param:
        messages.error(request, 'Asset ID is required!')
        return redirect('asset_list')
    
    try:
        asset = Asset.objects.get(id=asset_id_param, deleted=False)
    except Asset.DoesNotExist:
        messages.error(request, 'Asset not found or has been deleted!')
        return redirect('asset_list')
    
    # Check if asset is disposed (not editable)
    if asset.status == 'disposed':
        messages.error(request, 'Disposed assets cannot be edited!')
        return redirect('asset_list')
    
    idmngmnt = request.session.get('assetobjmngid')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    if request.method == 'POST':
        # Get asset id from hidden field
        asset_id = request.POST.get('asset_id')
        try:
            asset = Asset.objects.get(id=asset_id, deleted=False)
        except Asset.DoesNotExist:
            messages.error(request, 'Asset not found!')
            return redirect('asset_list')
        
        # Get old values for audit
        old_values = {
            'asset_name': asset.asset_name,
            'description': asset.description,
            'purchase_date': str(asset.purchase_date) if asset.purchase_date else None,
            'manufacturer': asset.manufacturer,
            'supplier': asset.supplier,
            'branch': asset.branch_id,
            'status': asset.status,
            'physical_location': asset.physical_location,
            'purchase_cost': str(asset.purchase_cost)
        }
        
        # Update fields
        asset.asset_name = request.POST.get('asset_name')
        asset.description = request.POST.get('description')
        asset.purchase_date = request.POST.get('purchase_date') or None
        asset.manufacturer = request.POST.get('manufacturer')
        asset.supplier = request.POST.get('supplier')
        asset.branch_id = request.POST.get('branch')
        asset.status = request.POST.get('status', 'available')
        asset.physical_location = request.POST.get('physical_location')
        asset.purchase_cost = request.POST.get('purchase_cost') or 0
        
        # Save to trigger signals
        asset.save()
        
        # Get new values
        new_values = {
            'asset_name': asset.asset_name,
            'description': asset.description,
            'purchase_date': str(asset.purchase_date) if asset.purchase_date else None,
            'manufacturer': asset.manufacturer,
            'supplier': asset.supplier,
            'branch': asset.branch_id,
            'status': asset.status,
            'physical_location': asset.physical_location,
            'purchase_cost': str(asset.purchase_cost)
        }
        
        # Create audit log
        staff = Staffallocation.objects.filter(id=request.session.get('loginstaff')).first()
        AssetAuditLog.objects.create(
            asset=asset,
            action='update',
            staff=staff,
            branch=asset.branch,
            old_value=old_values,
            new_value=new_values,
            notes=f"Asset updated by {staff.Staff.Staff_firstname if staff else 'Unknown'}"
        )
        
        messages.success(request, f'Asset "{asset.asset_name}" updated successfully!')
        return redirect(f"{reverse('asset_list')}?menumanagement_id={idmngmnt}")
    
    # GET request - show edit form
    branches = Branch.objects.filter(inactive=False)
    departments = Department.objects.filter(flag=True)
    
    context = {
        'idmngmnt': idmngmnt,
        'asset': asset,
        'branches': branches,
        'departments': departments,
        'stdesign': request.session.get('loginstaffdesign'),
        'assetview': request.session.get('assetobjmngview'),
        'assetedit': request.session.get('assetobjmngedit'),
    }
    return render(request, 'asset_edit.html', context)


# ============================================
# ASSET DELETE VIEW (Soft delete)
# ============================================

def asset_delete(request):
    """
    Soft delete asset (dispose)
    URL: /assets/delete/?id=1
    """
    asset_id_param = request.GET.get('id')
    
    if not asset_id_param:
        messages.error(request, 'Asset ID is required!')
        return redirect('asset_list')
    
    try:
        asset = Asset.objects.get(id=asset_id_param, deleted=False)
    except Asset.DoesNotExist:
        messages.error(request, 'Asset not found or already deleted!')
        return redirect('asset_list')
    
    idmngmnt = request.session.get('assetobjmngid')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    if request.method == 'POST':
        asset_id = request.POST.get('asset_id')
        try:
            asset = Asset.objects.get(id=asset_id, deleted=False)
        except Asset.DoesNotExist:
            messages.error(request, 'Asset not found!')
            return redirect('asset_list')
        
        staff = Staffallocation.objects.filter(id=request.session.get('loginstaff')).first()
        reason = request.POST.get('reason', 'No reason provided')
        disposal_value = request.POST.get('disposal_value') or 0
        
        # Soft delete
        asset.deleted = True
        asset.deleted_date = timezone.now().date()
        asset.deleted_by = staff
        asset.status = 'disposed'
        asset.is_available = False
        asset.is_disposed = True
        asset.disposal_date = timezone.now().date()
        asset.disposal_reason = reason
        asset.disposal_value = disposal_value
        asset.save()
        
        # Create audit log
        AssetAuditLog.objects.create(
            asset=asset,
            action='dispose',
            staff=staff,
            branch=asset.branch,
            notes=f"Asset disposed. Reason: {reason}"
        )
        
        messages.success(request, f'Asset "{asset.asset_name}" disposed successfully!')
        return redirect(f"{reverse('asset_list')}?menumanagement_id={idmngmnt}")
    
    context = {
        'idmngmnt': idmngmnt,
        'asset': asset,
        'stdesign': request.session.get('loginstaffdesign'),
        'assetdelete': request.session.get('assetobjmngdelete'),
        'assetview': request.session.get('assetobjmngview'),
    }
    return render(request, 'asset_delete.html', context)


