def generate_transfer_number():
    """
    Generate unique transfer number
    Format: TRFYYYYMMDDXXXX
    """
    today = timezone.now().strftime("%Y%m%d")
    last_transfer = AssetTransfer.objects.filter(
        transfer_number__startswith=f"TRF{today}"
    ).order_by('-transfer_number').first()
    
    if last_transfer and last_transfer.transfer_number:
        try:
            last_number = int(last_transfer.transfer_number[-4:])
            new_number = last_number + 1
        except (ValueError, IndexError):
            new_number = 1
    else:
        new_number = 1
    
    return f"TRF{today}{new_number:04d}"

def asset_transfer(request):
    """
    Transfer asset to another branch/department
    URL: /assets/transfer/?id=1
    """
    asset_id_param = request.GET.get('id')
    
    if not asset_id_param:
        messages.error(request, 'Asset ID is required!')
        return redirect('asset_list')
    
    try:
        asset = Asset.objects.get(id=asset_id_param, deleted=False)
    except Asset.DoesNotExist:
        messages.error(request, 'Asset not found or has been deleted!')
        return redirect('asset_list')
    
    # Check if asset is available for transfer
    if asset.status == 'disposed':
        messages.error(request, 'Disposed assets cannot be transferred!')
        return redirect('asset_list')
    
    if asset.status == 'maintenance':
        messages.warning(request, 'Asset is under maintenance. Transfer may not be recommended.')
    
    idmngmnt = request.session.get('assetobjmngid')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
        
    if request.method == 'POST':
        asset_id = request.POST.get('asset_id')
        try:
            asset = Asset.objects.get(id=asset_id, deleted=False)
        except Asset.DoesNotExist:
            messages.error(request, 'Asset not found!')
            return redirect('asset_list')
        
        # Get fields from POST
        branch_id = request.POST.get('branch')  # Current branch (from)
        from_department_id = request.POST.get('from_department')
        to_department_id = request.POST.get('to_department')
        received_by = request.POST.get('received_by')
        transfer_date_str = request.POST.get('transfer_date')
        remarks = request.POST.get('remarks')
        
        # Validation
        if not branch_id:
            messages.error(request, 'Branch is required!')
            return redirect(f"{reverse('asset_transfer')}?id={asset.id}")
        
        if from_department_id and to_department_id and from_department_id == to_department_id:
            messages.error(request, 'From Department and To Department cannot be the same!')
            return redirect(f"{reverse('asset_transfer')}?id={asset.id}")
        # Convert transfer_date string to date object
        transfer_date = None
        if transfer_date_str:
            try:
                transfer_date = datetime.strptime(transfer_date_str, '%Y-%m-%d').date()
            except ValueError:
                messages.error(request, 'Invalid date format! Please use YYYY-MM-DD.')
                return redirect(f"{reverse('asset_transfer')}?id={asset.id}")
        
        # Validate that transfer date is not in the future
        if transfer_date and transfer_date > timezone.now().date():
            messages.error(request, 'Transfer date cannot be in the future!')
            return redirect(f"{reverse('asset_transfer')}?id={asset.id}")
        
        # Get staff allocation (for Staffallocation references)
        staff_allocation = Staffallocation.objects.filter(id=request.session.get('loginstaff')).first()
        
        try:
            with transaction.atomic():
                transfer_number = generate_transfer_number()
                # Create transfer record - using updated model fields
                transfer = AssetTransfer.objects.create(
                    asset=asset,
                    transfer_number=transfer_number,
                    branch_id=branch_id,  # Current branch where asset is
                    from_department_id=from_department_id,
                    to_department_id=to_department_id,
                    received_by=received_by,
                    transfer_date=transfer_date if transfer_date else timezone.now().date(),
                    transferred_by=staff_allocation,
                    remarks=remarks
                )
                
                # Update asset branch and status
                asset.branch_id = branch_id
                asset.status = 'transferred'
                asset.is_available = False
                asset.is_transferred = True
                asset.save()
                
                # Create audit log
                AssetAuditLog.objects.create(
                    asset=asset,
                    action='transfer',
                    staff=staff_allocation,
                    branch_id=branch_id,
                    notes=f"Asset transferred to branch: {transfer.branch.Branch_Name}"
                )
                
                messages.success(request, f'Asset "{asset.asset_name}" transferred successfully!')
                return redirect(f"{reverse('asset_list')}?menumanagement_id={idmngmnt}")
                
        except Exception as e:
            messages.error(request, f"Error during transfer: {str(e)}")
            return redirect('error_page')
    
    # GET request
    branches = Branch.objects.filter(inactive=False)
    departments = Department.objects.filter(flag=True)
    
    context = {
        'idmngmnt': idmngmnt,
        'asset': asset,
        'branches': branches,
        'departments': departments,
        'stdesign': request.session.get('loginstaffdesign'),
        'assetview': request.session.get('assetobjmngview'),
        'assetedit': request.session.get('assetobjmngedit'),
        'today': timezone.now().date(),
    }
    return render(request, 'asset_transfer.html', context)


