def asset_history(request):
    """
    View complete history of a specific asset
    URL: /assets/history/?id=1
    """
    asset_id_param = request.GET.get('id')
    
    if not asset_id_param:
        messages.error(request, 'Asset ID is required!')
        return redirect('asset_list')
    
    try:
        asset = Asset.objects.get(id=asset_id_param)
    except Asset.DoesNotExist:
        messages.error(request, 'Asset not found!')
        return redirect('asset_list')
    
    idmngmnt = request.session.get('assetobjmngid')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    # Get all audit logs
    audit_logs = AssetAuditLog.objects.filter(asset=asset).order_by('-action_date', '-action_time')
    
    # Get all transfers
    transfers = AssetTransfer.objects.filter(asset=asset).order_by('-transfer_date')
    
    # Get all maintenance records
    
    context = {
        'idmngmnt': idmngmnt,
        'asset': asset,
        'audit_logs': audit_logs,
        'transfers': transfers,
        'stdesign': request.session.get('loginstaffdesign'),
        'assetview': request.session.get('assetobjmngview'),
    }
    return render(request, 'asset_history.html', context)


# ============================================
# ASSET REPORT VIEW
# ============================================

def asset_report(request):
    """
    Asset report with filters
    """
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    assets = Asset.objects.filter(deleted=False).select_related('branch', 'added_by')
    
    # Filter by branch
    branch_id = request.GET.get('branch')
    if branch_id:
        assets = assets.filter(branch_id=branch_id)
    
    # Filter by status
    status = request.GET.get('status')
    if status:
        assets = assets.filter(status=status)
    
    # Filter by date range
    from_date = request.GET.get('from_date')
    to_date = request.GET.get('to_date')
    if from_date:
        assets = assets.filter(asset_added_date__gte=from_date)
    if to_date:
        assets = assets.filter(asset_added_date__lte=to_date)
    
    # Search
    search = request.GET.get('search')
    if search:
        assets = assets.filter(
            Q(asset_id__icontains=search) |
            Q(asset_name__icontains=search) |
            Q(manufacturer__icontains=search) |
            Q(supplier__icontains=search)
        )
    
    # Summary statistics
    total_assets = assets.count()
    total_value = assets.aggregate(Sum('purchase_cost'))['purchase_cost__sum'] or 0
    
    # Status counts
    status_counts = {
        'available': assets.filter(status='available').count(),
        'transferred': assets.filter(status='transferred').count(),
        'maintenance': assets.filter(status='maintenance').count(),
        'disposed': assets.filter(status='disposed').count(),
    }
    
    branches = Branch.objects.filter(inactive=False)
    
    context = {
        'idmngmnt': idmngmnt,
        'assets': assets,
        'branches': branches,
        'total_assets': total_assets,
        'total_value': total_value,
        'status_counts': status_counts,
        'selected_branch': branch_id,
        'selected_status': status,
        'from_date': from_date,
        'to_date': to_date,
        'search': search,
        'stdesign': stdesign,
        'assetview': request.session.get('assetobjmngview'),
    }
    return render(request, 'asset_report.html', context)

def asset_transfer_edit(request):
    """
    Edit existing asset transfer
    URL: /assets/transfer/edit/?id=1
    """
    transfer_id_param = request.GET.get('id')
    
    if not transfer_id_param:
        messages.error(request, 'Transfer ID is required!')
        return redirect('asset_transfer_list')
    
    try:
        transfer = AssetTransfer.objects.get(id=transfer_id_param)
    except AssetTransfer.DoesNotExist:
        messages.error(request, 'Transfer record not found!')
        return redirect('asset_transfer_list')
    
    # Check if transfer is editable
    if not transfer.is_editable:
        messages.error(request, 'This transfer record is locked and cannot be edited!')
        return redirect('asset_transfer_list')
    
    idmngmnt = request.session.get('assetobjmngid')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    if request.method == 'POST':
        # Get fields from POST
        branch_id = request.POST.get('branch')
        from_department_id = request.POST.get('from_department')
        to_department_id = request.POST.get('to_department')
        received_by = request.POST.get('received_by')
        transfer_date_str = request.POST.get('transfer_date')
        remarks = request.POST.get('remarks')
        
        if from_department_id and to_department_id and from_department_id == to_department_id:
            messages.error(request, 'From Department and To Department cannot be the same!')
            return redirect(f"{reverse('asset_transfer_edit')}?id={transfer.id}")
        # Validation
        if not branch_id:
            messages.error(request, 'Branch is required!')
            return redirect(f"{reverse('asset_transfer_edit')}?id={transfer.id}")
        
        # Convert transfer_date string to date object
        transfer_date = None
        if transfer_date_str:
            try:
                transfer_date = datetime.strptime(transfer_date_str, '%Y-%m-%d').date()
            except ValueError:
                messages.error(request, 'Invalid date format! Please use YYYY-MM-DD.')
                return redirect(f"{reverse('asset_transfer_edit')}?id={transfer.id}")
        
        # Validate that transfer date is not in the future
        if transfer_date and transfer_date > timezone.now().date():
            messages.error(request, 'Transfer date cannot be in the future!')
            return redirect(f"{reverse('asset_transfer_edit')}?id={transfer.id}")
        
        try:
            with transaction.atomic():
                # Get old values for audit
                old_values = {
                    'branch': transfer.branch_id,
                    'from_department': transfer.from_department_id,
                    'to_department': transfer.to_department_id,
                    'received_by': transfer.received_by,
                    'transfer_date': str(transfer.transfer_date),
                    'remarks': transfer.remarks
                }
                
                # Update transfer record
                transfer.branch_id = branch_id
                transfer.from_department_id = from_department_id
                transfer.to_department_id = to_department_id
                transfer.received_by = received_by
                transfer.transfer_date = transfer_date if transfer_date else timezone.now().date()
                transfer.remarks = remarks
                transfer.save()
                
                # Update asset branch
                asset = transfer.asset
                asset.branch_id = branch_id
                asset.save()
                
                # Create audit log
                staff_allocation = Staffallocation.objects.filter(id=request.session.get('loginstaff')).first()
                AssetAuditLog.objects.create(
                    asset=asset,
                    action='update',
                    staff=staff_allocation,
                    branch_id=branch_id,
                    old_value=old_values,
                    new_value={
                        'branch': branch_id,
                        'from_department': from_department_id,
                        'to_department': to_department_id,
                        'received_by': received_by,
                        'transfer_date': str(transfer.transfer_date),
                        'remarks': remarks
                    },
                    notes=f"Transfer record updated by {staff_allocation.Staff.Staff_firstname if staff_allocation else 'Unknown'}"
                )
                
                messages.success(request, f'Transfer record updated successfully!')
                return redirect(f"{reverse('asset_transfer_list')}?menumanagement_id={idmngmnt}")
                
        except Exception as e:
            messages.error(request, f"Error during update: {str(e)}")
            return redirect('error_page')
    
    # GET request
    branches = Branch.objects.filter(inactive=False)
    departments = Department.objects.filter(flag=True)
    
    context = {
        'idmngmnt': idmngmnt,
        'transfer': transfer,
        'branches': branches,
        'departments': departments,
        'stdesign': request.session.get('loginstaffdesign'),
        'assetview': request.session.get('assetobjmngview'),
        'assetedit': request.session.get('assetobjmngedit'),
        'today': timezone.now().date(),
    }
    return render(request, 'asset_transfer_edit.html', context)

def generate_gin_number():
    """
    Generate unique GIN number
    Format: GIN-YYYYMMDD-XXXX
    """
    today = timezone.now().strftime("%Y%m%d")
    last_gin = GoodsIssueNote.objects.filter(
        gin_number__startswith=f"GIN-{today}"
    ).order_by('-gin_number').first()
    
    if last_gin and last_gin.gin_number:
        try:
            last_number = int(last_gin.gin_number.split('-')[-1])
            new_number = last_number + 1
        except (ValueError, IndexError):
            new_number = 1
    else:
        new_number = 1
    
    return f"GIN-{today}-{new_number:04d}"


# ============================================
# STOCK CHECK HELPER FOR INVENTORY
# ============================================

def check_inventory_stock_availability(item_id, batch_no, branch_id, quantity, company_id=None, supplier_id=None):
    """
    Check if inventory stock is available for the given item, batch, branch and quantity
    Returns: (available, stock_details, message)
    
    Parameters:
    - item_id: ID of the inventory item
    - batch_no: Batch number
    - branch_id: Branch ID where stock is located
    - quantity: Quantity requested
    - company_id: (Optional) Company ID to filter stock
    - supplier_id: (Optional) Supplier ID to filter stock
    """
    try:
        # Build filter
        filters = {
            'itemnm_id': item_id,
            'Batch_no': batch_no,
            'stockbranch_id': branch_id,
            'deleted': False
        }
        
        # Add optional filters if provided
        if company_id:
            filters['Comapany_name_id'] = company_id
        if supplier_id:
            filters['suppliernm_id'] = supplier_id
        
        stock = Inventorystockdetails.objects.filter(**filters).first()
        
        if not stock:
            return False, None, f"Inventory stock not found for batch {batch_no}"
        
        if stock.qty < quantity:
            return False, stock, f"Insufficient stock. Available: {stock.qty}, Requested: {quantity}"
        
        return True, stock, "Stock available"
        
    except Exception as e:
        return False, None, f"Error checking stock: {str(e)}"

def check_inventory_stock(request):
    """
    AJAX endpoint to check inventory stock availability
    """
    item_id = request.GET.get('item_id')
    company_id = request.GET.get('company_id')
    supplier_id = request.GET.get('supplier_id')
    batch_no = request.GET.get('batch_no')
    quantity = int(request.GET.get('quantity', 0))
    branch_id = request.GET.get('branch_id')
    
    if not all([item_id, batch_no, branch_id]):
        return JsonResponse({
            'available': False,
            'message': 'Missing required parameters'
        }, status=400)
    
    try:
        # Build filter
        filters = {
            'itemnm_id': item_id,
            'Batch_no': batch_no,
            'stockbranch_id': branch_id,
            'deleted': False
        }
        
        if company_id:
            filters['Comapany_name_id'] = company_id
        if supplier_id:
            filters['suppliernm_id'] = supplier_id
        
        # First try with all filters
        stock = Inventorystockdetails.objects.filter(**filters).first()
        
        if not stock:
            # Try without company/supplier filters
            fallback_filters = {
                'itemnm_id': item_id,
                'Batch_no': batch_no,
                'stockbranch_id': branch_id,
                'deleted': False
            }
            fallback_stock = Inventorystockdetails.objects.filter(**fallback_filters).first()
            
            if fallback_stock:
                return JsonResponse({
                    'available': False,
                    'message': f'Stock exists but does not match selected company/supplier. Available: {fallback_stock.qty}',
                    'available_qty': fallback_stock.qty,
                    'stock_id': fallback_stock.id,
                    'batch_no': fallback_stock.Batch_no,
                    'company_id': fallback_stock.Comapany_name_id if fallback_stock.Comapany_name else None,
                    'company_name': fallback_stock.Comapany_name.Comapany_name if fallback_stock.Comapany_name else None,
                    'supplier_id': fallback_stock.suppliernm_id,
                    'supplier_name': fallback_stock.suppliernm.shopname if fallback_stock.suppliernm else None,
                    'unit_id': fallback_stock.unt_id,
                    'unit_name': fallback_stock.unt.unitname if fallback_stock.unt else None,
                    'rate': fallback_stock.Rate,
                    'mfg_date': fallback_stock.Manufacturer_date.strftime('%Y-%m-%d') if fallback_stock.Manufacturer_date else '',
                    'expiry_date': fallback_stock.Expiry_date.strftime('%Y-%m-%d') if fallback_stock.Expiry_date else '',
                })
            else:
                return JsonResponse({
                    'available': False,
                    'message': f'No stock found for batch {batch_no}',
                    'available_qty': 0
                })
        
        if stock.qty < quantity:
            return JsonResponse({
                'available': False,
                'message': f'Insufficient stock. Available: {stock.qty}, Requested: {quantity}',
                'available_qty': stock.qty,
                'stock_id': stock.id,
                'batch_no': stock.Batch_no,
                'company_id': stock.Comapany_name_id if stock.Comapany_name else None,
                'company_name': stock.Comapany_name.Comapany_name if stock.Comapany_name else None,
                'supplier_id': stock.suppliernm_id,
                'supplier_name': stock.suppliernm.shopname if stock.suppliernm else None,
                'unit_id': stock.unt_id,
                'unit_name': stock.unt.unitname if stock.unt else None,
                'rate': stock.Rate,
                'mfg_date': stock.Manufacturer_date.strftime('%Y-%m-%d') if stock.Manufacturer_date else '',
                'expiry_date': stock.Expiry_date.strftime('%Y-%m-%d') if stock.Expiry_date else '',
            })
        
        return JsonResponse({
            'available': True,
            'message': 'Stock available',
            'available_qty': stock.qty,
            'stock_id': stock.id,
            'batch_no': stock.Batch_no,
            'company_id': stock.Comapany_name_id if stock.Comapany_name else None,
            'company_name': stock.Comapany_name.Comapany_name if stock.Comapany_name else None,
            'supplier_id': stock.suppliernm_id,
            'supplier_name': stock.suppliernm.shopname if stock.suppliernm else None,
            'unit_id': stock.unt_id,
            'unit_name': stock.unt.unitname if stock.unt else None,
            'rate': stock.Rate,
            'mfg_date': stock.Manufacturer_date.strftime('%Y-%m-%d') if stock.Manufacturer_date else '',
            'expiry_date': stock.Expiry_date.strftime('%Y-%m-%d') if stock.Expiry_date else '',
        })
        
    except Exception as e:
        return JsonResponse({
            'available': False,
            'message': f'Error checking stock: {str(e)}'
        }, status=500)
    
# ============================================
# GOODS ISSUE NOTE CREATE VIEW
# ============================================

def inventory_issue_note_create(request):
    """
    Create Goods Issue Note using Inventory Stock
    """
    idmngmnt = request.GET.get('menumanagement_id')
    if not idmngmnt:
        messages.error(request, "Invalid Menu Management ID provided.")
        return redirect('error_page')
    
    stdesign = request.session.get('loginstaffdesign')
    if not stdesign:
        return redirect('staff_login')
    
    # Get staff branch
    staff_id = request.session.get('loginstaff')
    staff_allocation = Staffallocation.objects.filter(id=staff_id).first()
    branch_id = staff_allocation.Branch_Name_id if staff_allocation else None
    branch = Branch.objects.filter(id=branch_id).first() if branch_id else None
    
    if request.method == 'POST':
        try:
            with transaction.atomic():
                # Get form data
                gin_date = request.POST.get('gin_date')
                department_id = request.POST.get('department')
                staff_id_field = request.POST.get('staff')
                reference_no = request.POST.get('reference_no')
                remarks = request.POST.get('remarks')
                
                # Validation
                if not department_id:
                    messages.error(request, 'Department is required!')
                    return redirect(f"{reverse('inventory_issue_note_create')}?menumanagement_id={idmngmnt}")
                
                # Generate GIN number
                gin_number = generate_gin_number()
                
                # Create GIN Master
                gin = GoodsIssueNote.objects.create(
                    gin_number=gin_number,
                    gin_date=gin_date if gin_date else timezone.now().date(),
                    branch_id=branch_id,
                    department_id=department_id,
                    staff_id=staff_id_field if staff_id_field else None,
                    reference_no=reference_no,
                    remarks=remarks,
                    created_by=staff_allocation,
                    status='issued'
                )
                
                # ✅ FIX: Get item_count from POST
                item_count = int(request.POST.get('item_count', 0))
                total_quantity = 0
                total_amount = 0
                items_saved = 0
                
                for i in range(1, item_count + 1):
                    item_id = request.POST.get(f'item_id_{i}')
                    company_id = request.POST.get(f'company_{i}')
                    supplier_id = request.POST.get(f'supplier_{i}')
                    batch_no = request.POST.get(f'batch_no_{i}')
                    unit_id = request.POST.get(f'unit_{i}')
                    quantity = int(request.POST.get(f'quantity_{i}', 0))
                    rate = float(request.POST.get(f'rate_{i}', 0))
                    tax = float(request.POST.get(f'tax_{i}', 0))
                    mfg_date = request.POST.get(f'mfg_date_{i}')
                    expiry_date = request.POST.get(f'expiry_date_{i}')
                    
                    # Skip if no item or quantity is 0
                    if not item_id or quantity <= 0:
                        continue
                    
                    # Check inventory stock availability with company and supplier filters
                    available, stock, stock_msg = check_inventory_stock_availability(
                        item_id, batch_no, branch_id, quantity, company_id, supplier_id
                    )
                    
                    if not available:
                        item_name = inventorymaster.objects.get(id=item_id).itemnm
                        messages.error(request, f'Stock not available for {item_name}: {stock_msg}')
                        # Rollback will happen automatically due to transaction.atomic()
                        return redirect(f"{reverse('inventory_issue_note_create')}?menumanagement_id={idmngmnt}")
                    
                    # Create GIN item
                    gin_item = GoodsIssueNoteItem.objects.create(
                        gin=gin,
                        item_name_id=item_id,
                        company_id=company_id if company_id else None,
                        supplier_id=supplier_id if supplier_id else None,
                        inventory_stock=stock,
                        batch_no=batch_no,
                        unit_id=unit_id,
                        quantity=quantity,
                        rate=rate,
                        tax_percentage=tax,
                        manufacturer_date=mfg_date if mfg_date else None,
                        expiry_date=expiry_date if expiry_date else None,
                        total_amount=quantity * rate
                    )
                    
                    # Reduce inventory stock
                    stock.qty -= quantity
                    stock.lastupdatedate = timezone.now().date()
                    stock.save()
                    
                    # Log stock reduction
                    try:
                        StockAuditLog.objects.create(
                            stock=stock,
                            action="UPDATE",
                            staff_id=request.session.get('staffid'),
                            branch_id=branch_id,
                            store=stock.storenm,
                            item=stock.itemnm,
                            qty=quantity,
                            action_date=timezone.now().date(),
                            action_time=timezone.now().time(),
                            remarks=f"Stock issued via GIN {gin_number} to {gin.department.Department_Name}"
                        )
                    except Exception as log_error:
                        print(f"Stock audit log error: {log_error}")
                    
                    total_quantity += quantity
                    total_amount += quantity * rate
                    items_saved += 1
                
                # ✅ Check if any items were saved
                if items_saved == 0:
                    messages.error(request, 'No items were added to the GIN. Please add at least one item.')
                    # Delete the GIN master since no items were saved
                    gin.delete()
                    return redirect(f"{reverse('inventory_issue_note_create')}?menumanagement_id={idmngmnt}")
                
                messages.success(request, f'Goods Issue Note {gin_number} created successfully with {items_saved} item(s)!')
                return redirect(f"{reverse('inventory_issue_note_list')}?menumanagement_id={idmngmnt}")
                
        except Exception as e:
            messages.error(request, f"Error creating GIN: {str(e)}")
            return redirect(f"{reverse('inventory_issue_note_create')}?menumanagement_id={idmngmnt}")
    
    # GET request - Fetch all required data for dropdowns
    departments = Department.objects.filter(flag=True)
    staff_members = Staffdetails.objects.filter(deleted=False)
    
    # Fetch inventory items that have stock
    inventory_items = inventorymaster.objects.filter(
        id__in=Inventorystockdetails.objects.filter(
            stockbranch_id=branch_id,
            deleted=False,
            qty__gt=0
        ).values_list('itemnm_id', flat=True).distinct()
    ).order_by('itemnm')
    
    # Fetch inventory companies
    inventory_companies = InventoryCompany.objects.all().order_by('Comapany_name')
    
    # Fetch suppliers
    suppliers = supplier.objects.all().order_by('shopname')
    
    # Fetch units
    units = unitdt.objects.all().order_by('unitname')
    
    context = {
        'idmngmnt': idmngmnt,
        'departments': departments,
        'staff_members': staff_members,
        'branch': branch,
        'branch_id': branch_id,
        'stdesign': stdesign,
        'today': timezone.now().date(),
        'gin_number': generate_gin_number(),
        'items': inventory_items,
        'companies': inventory_companies,
        'suppliers': suppliers,
        'units': units,
    }
    return render(request, 'inventory_issue_note_create.html', context)

# ============================================
# AJAX: GET INVENTORY STOCK DETAILS FOR ITEM
# ============================================

def get_inventory_stock_details(request):
    """
    Get inventory stock details for a selected item with company/supplier info
    """
    item_id = request.GET.get('item_id')
    branch_id = request.GET.get('branch_id')
    
    if not item_id or not branch_id:
        return JsonResponse({'error': 'Missing parameters'}, status=400)
    
    try:
        # Get all inventory stock for this item at this branch
        stocks = Inventorystockdetails.objects.filter(
            itemnm_id=item_id,
            stockbranch_id=branch_id,
            deleted=False,
            qty__gt=0
        ).select_related('itemnm', 'unt', 'Comapany_name', 'suppliernm')
        
        if not stocks.exists():
            return JsonResponse({'error': 'No inventory stock available for this item'}, status=404)
        
        # Get inventory item details
        item = inventorymaster.objects.get(id=item_id)
        
        # Prepare batch data
        batches = []
        for stock in stocks:
            batches.append({
                'batch_no': stock.Batch_no,
                'stock_id': stock.id,
                'unit_id': stock.unt_id,
                'unit_name': stock.unt.unitname if stock.unt else 'N/A',
                'qty': stock.qty,
                'rate': float(stock.Rate) if stock.Rate else 0,
                'company_id': stock.Comapany_name_id,
                'company_name': stock.Comapany_name.Comapany_name if stock.Comapany_name else 'N/A',
                'supplier_id': stock.suppliernm_id,
                'supplier_name': stock.suppliernm.shopname if stock.suppliernm else 'N/A',
                'mfg_date': stock.Manufacturer_date.strftime('%Y-%m-%d') if stock.Manufacturer_date else '',
                'expiry_date': stock.Expiry_date.strftime('%Y-%m-%d') if stock.Expiry_date else '',
                'tax_percentage': float(item.taxpercentage.taxrate) if item.taxpercentage else 0,
            })
        
        return JsonResponse({
            'success': True,
            'item_name': item.itemnm,
            'hsncode': item.hsncode or '',
            'batches': batches
        })
        
    except inventorymaster.DoesNotExist:
        return JsonResponse({'error': 'Inventory item not found'}, status=404)
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)


# ============================================
# AJAX: SEARCH INVENTORY ITEMS
# ============================================

def search_inventory_items_for_gin(request):
    """
    Search inventory items for GIN
    """
    query = request.GET.get('q', '').strip()
    branch_id = request.GET.get('branch_id')
    
    if not query or not branch_id:
        return JsonResponse([], safe=False)
    
    try:
        # Get inventory items that have stock in the given branch
        items_with_stock = Inventorystockdetails.objects.filter(
            stockbranch_id=branch_id,
            deleted=False,
            qty__gt=0,
            itemnm__itemnm__icontains=query
        ).select_related('itemnm').values_list('itemnm_id', flat=True).distinct()
        
        items = inventorymaster.objects.filter(
            id__in=items_with_stock,
            itemnm__icontains=query
        )[:15]
        
        results = []
        for item in items:
            results.append({
                'id': item.id,
                'itemnm': item.itemnm,
                'hsncode': item.hsncode or '',
            })
        
        return JsonResponse(results, safe=False)
        
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)

def get_staff_by_department_ajax(request):
    """
    AJAX endpoint to fetch staff members based on department
    """
    if request.method != 'GET':
        return JsonResponse({'error': 'Method not allowed'}, status=405)
    department_id = request.GET.get('department_id')
    
    if not department_id:
        return JsonResponse({'error': 'Department ID is required'}, status=400)
    try:
        # Get staff members from Staffallocation
        staff_allocations = Staffallocation.objects.filter(
            Department_Name_id=department_id,
            Status='active'
        ).select_related('Staff')
        staff_list = []
        for allocation in staff_allocations:
            staff = allocation.Staff
            if staff and not staff.deleted:
                staff_list.append({
                    'id': staff.id,
                    'docid':allocation.id,  
                    'name': f"{staff.Staff_firstname} {staff.Staff_lastname}".strip()
                })
        return JsonResponse(staff_list, safe=False)
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)

