def add_appointment_status(request):
    menu_management_id = request.GET.get('menumanagement_id')
    
    if request.method == 'POST':
        status_name = request.POST.get('status_name')
        is_active = request.POST.get('is_active', '1')
        
        if status_name:
            # Check if status already exists
            if AppointmentStatus.objects.filter(status_name=status_name).exists():
                messages.error(request, 'Appointment status already exists!')
            else:
                visit_type_choices = AppointmentStatus.VISIT_TYPE_CHOICES
                status_exists_in_choices = False
                for choice in visit_type_choices:
                    if choice[0].lower() == status_name.lower():
                        status_exists_in_choices = True
                        break
                if not status_exists_in_choices:
                    messages.warning(request, f"Status '{status_name}' is not in the predefined visit type choices.")
                
                AppointmentStatus.objects.create(
                    status_name=status_name,
                    is_active=is_active
                )
                messages.success(request, 'Appointment status added successfully!')
                return redirect(f'/appointment-status-list/?menumanagement_id={menu_management_id}')
        else:
            messages.error(request, 'Please enter status name!')
    
    context = {
        'menu_management_id': menu_management_id,
    }
    return render(request, 'add_appointment_status.html', context)

