# ===============================
# EDIT APPOINTMENT STATUS
# ===============================
def edit_appointment_status(request):
    menu_management_id = request.GET.get('menumanagement_id')
    status_id = request.GET.get('ids')
    
    # Get the status object
    obj_edit_status = get_object_or_404(AppointmentStatus, id=status_id)
    
    if request.method == 'POST':
        status_id = request.POST.get('status_id')
        status_name = request.POST.get('status_name')
        is_active = request.POST.get('is_active')
        
        if status_name:
            # Check if another status with same name exists
            existing_status = AppointmentStatus.objects.filter(
                status_name__iexact=status_name
            ).exclude(id=status_id)
            
            if existing_status.exists():
                messages.error(request, 'Appointment status with this name already exists!')
            else:
                # Update the status
                obj_edit_status.status_name = status_name
                obj_edit_status.is_active = is_active
                obj_edit_status.save()
                messages.success(request, 'Appointment status updated successfully!')
                return redirect(f'/appointment-status-list/?menumanagement_id={menu_management_id}')
        else:
            messages.error(request, 'Please enter status name!')
    
    context = {
        'obj_edit_status': obj_edit_status,
        'menu_management_id': menu_management_id,
        'cmmgmntedit': '1',
        'cmmgmntview': '1',
    }
    return render(request, 'edit_appointment_status.html', context)

