def search_supplier(request):
    """
    Search suppliers by name, code, or contact - used in purchase invoice form
    """
    if request.method == 'GET' and 'term' in request.GET:
        search_term = request.GET.get('term', '').strip()
        if search_term:
            suppliers = supplier.objects.filter(
                Q(shopname__icontains=search_term) |
                Q(suppliercode__icontains=search_term) |
                Q(contactnumber__icontains=search_term)
            )[:10]
            
            data = [
                {
                    'id': supp.id,
                    'shopname': supp.shopname,
                    'name': supp.shopname,
                    'suppliercode': supp.suppliercode or '',
                    'contactnumber': supp.contactnumber or '',
                    'address': supp.address or '',
                    'email': supp.email or ''
                }
                for supp in suppliers
            ]
            return JsonResponse(data, safe=False)
    return JsonResponse([], safe=False)



def search_store(request):
    """
    Search stores by name - used in purchase invoice form
    """
    if request.method == 'GET' and 'term' in request.GET:
        search_term = request.GET.get('term', '').strip()
        if search_term:
            stores = storedetails.objects.filter(
                storename__icontains=search_term
            )[:10]
            
            data = [
                {
                    'id': store.id, 
                    'storename': store.storename,
                    'name': store.storename
                } 
                for store in stores
            ]
            return JsonResponse(data, safe=False)
    return JsonResponse([], safe=False)

def registration_fee_invoice(request):
    """Generate invoice for registration fee from Patient_details"""
    
    # Get patient ID from request
    patient_id = request.GET.get('patient_id')
    invoice_id = request.GET.get('invoice_id')
    
    # If viewing existing invoice
    if invoice_id:
        try:
            invoice = RegistrationFeeInvoice.objects.get(id=invoice_id)
            patient = invoice.patient
            objhospt = invoice.hospital or Hospitaldetails.objects.first()
            brname = invoice.branch
            
            
            # Convert total to words
            from num2words import num2words
            amount_in_words = num2words(float(invoice.registration_fee), to="currency", lang="en_IN").title()
            amount_in_words = amount_in_words.replace("euro", "Rupees").replace("cents", "Paise") + " Only"
            
            context = {
                'lsinvoice': invoice,
                'objhospt': objhospt,
                'brname': brname,
                'patient': patient,
                # 'doctor_name': doctor_name,
                'amount_in_words': amount_in_words,
                'registration_fee': float(invoice.registration_fee),
            }
            return render(request, 'registration_fee_invoice.html', context)
            
        except RegistrationFeeInvoice.DoesNotExist:
            messages.error(request, "Invoice not found.")
            return redirect('daily_transaction_report')
    
    # Create new invoice
    if not patient_id:
        messages.error(request, "Patient ID is required.")
        return redirect('daily_transaction_report')
    
    try:
        patient = Patient_details.objects.get(id=patient_id)
    except Patient_details.DoesNotExist:
        messages.error(request, "Patient not found.")
        return redirect('daily_transaction_report')
    
    # Check if patient has registration fee
    reg_fee = float(patient.reg_Fee) if patient.reg_Fee else 0
    if reg_fee <= 0:
        messages.error(request, "No registration fee found for this patient.")
        return redirect('daily_transaction_report')
    
    # Get hospital details
    objhospt = Hospitaldetails.objects.first()
    if not objhospt:
        messages.error(request, "Hospital details not found.")
        return redirect('daily_transaction_report')
    
    # Get branch details from patient
    brname = patient.Branch_Name
    if not brname:
        messages.error(request, "Branch details not found.")
        return redirect('daily_transaction_report')
    
    # Check if invoice already exists for this patient today
    existing_invoice = RegistrationFeeInvoice.objects.filter(
        patient=patient,
        invoice_date=date.today(),
        is_cancelled=False
    ).first()
    
    if existing_invoice:
        messages.warning(request, f"Registration fee invoice already exists: {existing_invoice.invoice_number}")
        return redirect(f"{reverse('registration_fee_invoice')}?invoice_id={existing_invoice.id}")
    
    # Generate invoice number
    today = date.today().strftime("%Y%m%d")
    last_invoice = RegistrationFeeInvoice.objects.filter(
        invoice_number__startswith=f"REG{today}"
    ).order_by('-id').first()
    
    if last_invoice and last_invoice.invoice_number:
        try:
            last_num = int(last_invoice.invoice_number[-4:])
            new_num = last_num + 1
        except (ValueError, IndexError):
            new_num = 1
    else:
        new_num = 1
    
    invoice_number = f"REG{today}{new_num:04d}"
    
    # Get staff (logged-in user)
    staff_id = request.session.get('staffid')
    staff_obj = None
    if staff_id:
        try:
            staff_obj = Staffdetails.objects.get(id=staff_id)
        except Staffdetails.DoesNotExist:
            pass
    
    # Get doctor name (if available from patient's appointments)
    doctor_name = "N/A"
    last_appointment = Appointments.objects.filter(
        MR_Number=patient
    ).order_by('-Appointment_date').first()
    
    if last_appointment and last_appointment.Doctor_Name:
        doctor_obj = last_appointment.Doctor_Name
        if hasattr(doctor_obj, 'Staff'):
            doctor_name = f"{doctor_obj.Staff.Staff_firstname} {doctor_obj.Staff.Staff_lastname}".strip()
        else:
            doctor_name = f"{doctor_obj.Staff_firstname} {doctor_obj.Staff_lastname}".strip()
    
    # Create invoice record using new model
    invoice = RegistrationFeeInvoice.objects.create(
        invoice_number=invoice_number,
        patient=patient,
        patient_name=patient.Patient_Name,
        patient_mr_no=patient.Medical_Record_Number or "N/A",
        patient_phone=patient.contactno,
        patient_address=getattr(patient, 'address', None),
        patient_age=patient.Age,
        patient_gender=patient.Gender,
        branch=brname,
        hospital=objhospt,
        registration_fee=reg_fee,
        tax_percentage=0,
        tax_amount=0,
        discount=0,
        payment_mode='Cash',
        payment_status='Paid',
        created_by=staff_obj,
        notes=f"Registration fee invoice for patient {patient.Patient_Name}"
    )
    
    # Convert total to words
    from num2words import num2words
    amount_in_words = num2words(reg_fee, to="currency", lang="en_IN")
    amount_in_words = amount_in_words
    
    context = {
        'lsinvoice': invoice,
        'objhospt': objhospt,
        'brname': brname,
        'patient': patient,
        'doctor_name': doctor_name,
        'amount_in_words': amount_in_words,
        'registration_fee': reg_fee,
    }
    
    return render(request, 'registration_fee_invoice.html', context)
    

def dotmatrixview(request):
        lsinvoice = newInvoiceMaster.objects.get(id=request.GET.get('ids'))  # fetch specific invoice
        chinvoice = newInvoiceChild.objects.filter(invmasterid=lsinvoice.id)
        
        stbtachid = request.session.get('branchid')
        st_id = request.session['loginstaff']
        staff_branch = Staffallocation.objects.get(id=st_id)
        staffn = staff_branch
        objhospt = Hospitaldetails.objects.first()
        today = date.today()
        todate = timezone.now().strftime("%d/%m/%y")

        stbtachid = request.session.get('branchid')
        br = Branch.objects.filter(id=stbtachid).first()

        branch_has_gst = bool(br and br.gstno and br.gstno.lower() != 'none')
        branch_is_composition = bool(br and br.compositiontax)

        # Reuse the same invoice number lookup as a5print
        current_year = today.year % 100
        next_year = (today.year + 1) % 100
        financial_year_prefix = f"INV{current_year:02d}/{next_year:02d}"

        # Aggregate GST breakup across all child lines (like the sample bill's
        # CGST% / SGST% / CGST / SGST rows under the item table)
        total_taxable = sum(float(i.taxableamount or 0) for i in chinvoice)
        total_cgst_amt = sum(float(i.cgstamount or 0) for i in chinvoice)
        total_sgst_amt = sum(float(i.sgstamount or 0) for i in chinvoice)
        # Pick the rate off the first line item (assumes a single slab bill,
        # same as the sample where every item shares one GST%)
        first_item = chinvoice.first()
        cgst_rate = first_item.cgst if first_item else "0"
        sgst_rate = first_item.sgst if first_item else "0"

        gross_amt = sum(float(i.amount or 0) for i in chinvoice)

        request.session['invoice_print_accessed'] = True

        context = {
        'lsinvoice': lsinvoice,
        'chinvoice': chinvoice,
        'staffn': staffn,
        'objhospt': objhospt,
        'today': today,
        'todate': todate,
        'br': br,
        'branch_has_gst': branch_has_gst,
        'branch_is_composition': branch_is_composition,
        'total_taxable': total_taxable,
        'total_cgst_amt': total_cgst_amt,
        'total_sgst_amt': total_sgst_amt,
        'cgst_rate': cgst_rate,
        'sgst_rate': sgst_rate,
        'gross_amt': gross_amt,
       }
        return render(request, "invdotmatrixprint.html", context)

